select set_config('request.jwt.claim.sub', '', false);


-- ---- 208. Oferta escalonada por fecha de carga: ranking, ventana, corte, recordatorio --
-- (usuario, 2026-11-15) Ruta propia de la prueba (Guadalajara 19 → Cuenca 16) para que el
-- ranking sea determinista: ningún otro dato de la suite toca esas provincias.
reset role;
select set_config('request.jwt.claim.sub', '', false);
-- Ventana abierta de par en par durante la prueba (se restaura al final): el CI corre a
-- cualquier hora y la ventana real de 5:00-23:00 la probamos aparte cerrándola a mano.
update parametros set valor = '0'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '24'::jsonb where clave = 'difusion_hora_fin';
-- «La bolsa va primero» (2026-11-16) se apaga durante esta prueba: aquí se mira el ranking,
-- la cadencia y el corte de los emails; la espera a la bolsa tiene su prueba aparte (248).
update parametros set valor = 'false'::jsonb where clave = 'bolsa_primero';
-- La mecánica se prueba con el arranque a 5 días y el corte a 3 horas (los valores con los
-- que se escribió la prueba); los de producción (3 días, sin corte) los mira la 249.
update parametros set valor = '5'::jsonb where clave = 'difusion_dias_antes';
update parametros set valor = '3'::jsonb where clave = 'difusion_horas_corte';
do $$ declare t_fav uuid; t_val uuid; t_sin uuid; t_lejos uuid; t_ruta uuid; t_colin uuid; t_par uuid; t_auto uuid; er uuid; ep uuid; begin
  -- Sede en la provincia del ORIGEN (Guadalajara, CP 19 + ES): entran en la difusión.
  insert into transportistas (razon_social, cif, nima, tags, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Favorito 208 SL', 'B20800001', 'NIMA-208A', array['Favorito'], 3, '19020', 'ES') returning id into t_fav;
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Valorado 208 SL', 'B20800002', 'NIMA-208B', 5, '19007', 'ES') returning id into t_val;
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Sin Email 208 SL', 'B20800003', 'NIMA-208C', 5, '19001', 'ES') returning id into t_sin;
  -- Sede en provincia COLINDANTE del origen (Madrid 28 toca Guadalajara 19): entra.
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Colindante 208 SL', 'B20800005', 'NIMA-208E', 4, '28010', 'ES') returning id into t_colin;
  -- HIZO ESA RUTA (envío entregado 19→16) con sede lejos (Barcelona): entra Y VA PRIMERO.
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Rutero 208 SL', 'B20800006', 'NIMA-208F', 2, '08020', 'ES') returning id into t_ruta;
  -- AUTÓNOMO (DNI, no CIF de sociedad), sede en el origen, valoración baja y sin rutas:
  -- aun así va EL PRIMERO de todos (usuario, 2026-11-15: la flota grande es la
  -- competencia; el autónomo, no).
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Auto Autonomo 208', '30208001P', 'NIMA-208H', 1, '19003', 'ES') returning id into t_auto;
  -- Hizo una ruta PARECIDA (Madrid 28 → Toledo 45, colindantes de 19 y de 16) con sede
  -- lejos (Barcelona): entra SOLO por eso, y ranquea el último antes de la antigüedad.
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Parecida 208 SL', 'B20800007', 'NIMA-208G', 4, '08030', 'ES') returning id into t_par;
  -- Activo, con email y bien valorado… pero con sede en OTRA provincia (Barcelona, que no
  -- toca ni 19 ni 16) y sin haber hecho la ruta ni una parecida: NO recibe nunca un email.
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Lejano 208 SL', 'B20800004', 'NIMA-208D', 5, '08010', 'ES') returning id into t_lejos;
  insert into contactos (transportista_id, nombre, email, funcion, es_principal)
    values (t_fav, 'Fani Favorita', 'fav.208@prueba.invalid', 'trafico', true),
           (t_val, 'Valen Valorado', 'val.208@prueba.invalid', 'trafico', true),
           (t_colin, 'Coli Colindante', 'colin.208@prueba.invalid', 'trafico', true),
           (t_ruta, 'Ruti Rutera', 'ruta.208@prueba.invalid', 'trafico', true),
           (t_par, 'Pare Parecida', 'par.208@prueba.invalid', 'trafico', true),
           (t_auto, 'Auto Autonomo', 'auto.208@prueba.invalid', 'trafico', true),
           (t_lejos, 'Lejo Lejano', 'lejos.208@prueba.invalid', 'trafico', true);
  -- El envío entregado que da la ruta hecha al rutero.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date)
    returning id into er;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (er, 1, 'carga', '19001', 'Guadalajara', 'ES'), (er, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set transportista_id = t_ruta, estado = 'entregado', entregado_en = now() - interval '20 days' where id = er;
  -- Y el envío entregado 28 → 45 que da la ruta parecida.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date)
    returning id into ep;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (ep, 1, 'carga', '28001', 'Madrid', 'ES'), (ep, 2, 'descarga', '45001', 'Toledo', 'ES');
  update envios set transportista_id = t_par, estado = 'entregado', entregado_en = now() - interval '30 days' where id = ep;
  perform set_config('prueba.t208p', t_par::text, false);
  perform set_config('prueba.t208a', t_auto::text, false);
  perform set_config('prueba.t208f', t_fav::text, false);
  perform set_config('prueba.t208v', t_val::text, false);
  perform set_config('prueba.t208l', t_lejos::text, false);
  perform set_config('prueba.t208c', t_colin::text, false);
  perform set_config('prueba.t208r', t_ruta::text, false);
end $$;
-- Cuatro envíos 19→16: E1 ranking (carga en 2 días), E2 agotamiento+recordatorio (2 días),
-- E3 corte (carga hoy a las 00:00), E4 dormida (carga en 10 días).
do $$ declare e uuid; n int; f date; begin
  for n in 1..4 loop
    f := case n when 3 then (now() at time zone 'Europe/Madrid')::date
                when 4 then (now() at time zone 'Europe/Madrid')::date + 10
                else (now() at time zone 'Europe/Madrid')::date + 2 end;
    perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
      values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, f) returning id into e;
    perform set_config('request.jwt.claim.sub', '', false);
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
      values (e, 1, 'carga', '19001', 'Guadalajara', 'ES'), (e, 2, 'descarga', '16001', 'Cuenca', 'ES');
    update envios set estado = 'programado' where id = e;
    perform set_config('prueba.e208' || n, e::text, false);
  end loop;
end $$;
-- Un cliente NO puede lanzarla.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare r jsonb; begin
  begin
    r := iniciar_difusion(current_setting('prueba.e2081')::uuid, 500);
    raise exception 'FALLO 208 · un cliente lanza la oferta escalonada';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
-- Dynamo la lanza: el PRIMER email sale al momento y es para el AUTÓNOMO.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e2081')::uuid; r jsonb; begin
  r := iniciar_difusion(e, 500);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 208 · no se lanza: %', r; end if;
  if iniciar_difusion(e, 500) ->> 'resultado' <> 'ya_activa' then
    raise exception 'FALLO 208 · se lanzan dos difusiones del mismo envío';
  end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e2081')::uuid; d record; begin
  select * into d from difusiones where envio_id = e and estado = 'activa';
  if d.contactados <> 1 then raise exception 'FALLO 208 · el primer paso no contacta a 1 (van %)', d.contactados; end if;
  if d.corte_en is null or d.carga_prevista_en is null then
    raise exception 'FALLO 208 · la difusión no guarda la hora de carga y el corte';
  end if;
  if not exists (select 1 from envio_ofertas o where o.envio_id = e and o.canal = 'email'
                   and o.transportista_id = current_setting('prueba.t208a')::uuid) then
    raise exception 'FALLO 208 · el primero no es el autónomo (manda sobre ruta y favorito)';
  end if;
  if not exists (select 1 from emails_enviados where clave = 'difusion:' || e || ':' || current_setting('prueba.t208a')) then
    raise exception 'FALLO 208 · el email del autónomo no queda encolado';
  end if;
  -- Antes de que pasen los minutos del tramo, la pasada del reloj NO manda otro…
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e) <> 1 then
    raise exception 'FALLO 208 · manda otro email sin esperar los minutos del tramo';
  end if;
  -- …con la VENTANA HORARIA cerrada tampoco, aunque el tiempo haya pasado de sobra…
  update parametros set valor = '0'::jsonb where clave = 'difusion_hora_fin';
  update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e) <> 1
     or (select estado from difusiones where envio_id = e) <> 'activa' then
    raise exception 'FALLO 208 · manda emails fuera de la ventana horaria (o la cierra)';
  end if;
  -- …y al abrirse la ventana, el SEGUNDO es quien hizo la ruta, y el TERCERO el de la
  -- ruta PARECIDA (probabilidad pura: la evidencia de ruta por delante del favorito).
  update parametros set valor = '24'::jsonb where clave = 'difusion_hora_fin';
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e) <> 2
     or not exists (select 1 from envio_ofertas o where o.envio_id = e
                      and o.transportista_id = current_setting('prueba.t208r')::uuid) then
    raise exception 'FALLO 208 · el segundo no es quien hizo la ruta';
  end if;
  update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e) <> 3
     or not exists (select 1 from envio_ofertas o where o.envio_id = e
                      and o.transportista_id = current_setting('prueba.t208p')::uuid) then
    raise exception 'FALLO 208 · el tercero no es el de la ruta parecida (debe ir antes que el favorito)';
  end if;
  if exists (select 1 from envio_ofertas o where o.envio_id = e and o.transportista_id is not null
               and not exists (select 1 from contactos c where c.transportista_id = o.transportista_id and c.email is not null)) then
    raise exception 'FALLO 208 · se oferta a un transportista sin email';
  end if;
  -- Con transportista asignado, PARA EN SECO: nadie más recibe nada.
  update envios set transportista_id = current_setting('prueba.t208v')::uuid where id = e;
  update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e;
  perform procesar_difusiones();
  select * into d from difusiones where envio_id = e;
  if d.estado <> 'aceptada' or d.contactados <> 3 then
    raise exception 'FALLO 208 · no para al asignarse transportista: % (%)', d.estado, d.contactados;
  end if;
  raise notice 'OK 208 · oferta escalonada a probabilidad pura: autónomo, luego la ruta hecha, luego la parecida (el favorito solo desempata); respeta tramo y ventana y para en seco al asignarse';
end $$;
-- E2: se agota al quedarse sin candidatos (el colindante entra; el de Barcelona sin ruta,
-- jamás) y avisa a Dynamo; después, RECORDATORIO diario a los contactados de otros días.
do $$ declare e2 uuid := current_setting('prueba.e2082')::uuid; d record; n int; v_hoy date; v_clave text; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if iniciar_difusion(e2, 400) ->> 'resultado' <> 'ok' then raise exception 'FALLO 208 · no se lanza la 2.ª'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  -- Vueltas del reloj hasta agotarse: 6 candidatos (autónomo, rutero, favorito,
  -- valorado, colindante y el de la ruta parecida).
  for n in 1..10 loop
    exit when (select estado from difusiones where envio_id = e2) <> 'activa';
    update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e2 and estado = 'activa';
    perform procesar_difusiones();
  end loop;
  -- Los números de la oferta, como en el resto de emails: coma decimal y «€» detrás.
  if exists (select 1 from emails_enviados where envio_id = e2 and tipo = 'difusion'
              and (asunto not like 'Carga disponible · % · 400,00 €' or position('<strong>400,00 € + IVA</strong>' in cuerpo_html) = 0
                   or position('>Aceptar carga</a>' in cuerpo_html) = 0
                   or cuerpo_html ~ '[0-9]\.[0-9]{2} (m|t|€)')) then
    raise exception 'FALLO 208 · la oferta por email no escribe el precio o las medidas con coma: %',
      (select asunto || ' · ' || cuerpo_html from emails_enviados where envio_id = e2 and tipo = 'difusion' limit 1);
  end if;
  select * into d from difusiones where envio_id = e2;
  if d.estado <> 'agotada' or d.contactados <> 6 then
    raise exception 'FALLO 208 · no se agota al quedarse sin candidatos: % (%)', d.estado, d.contactados;
  end if;
  if not exists (select 1 from envio_ofertas o where o.envio_id = e2 and o.transportista_id = current_setting('prueba.t208c')::uuid) then
    raise exception 'FALLO 208 · el de la provincia colindante no entra en la difusión';
  end if;
  if not exists (select 1 from envio_ofertas o where o.envio_id = e2 and o.transportista_id = current_setting('prueba.t208p')::uuid) then
    raise exception 'FALLO 208 · el de la ruta parecida (28→45 para un 19→16) no entra en la difusión';
  end if;
  if not exists (select 1 from avisos where envio_id = e2 and tipo = 'difusion_agotada' and para = 'dynamo') then
    raise exception 'FALLO 208 · agotada sin aviso de campana a Dynamo';
  end if;
  if not exists (select 1 from emails_enviados where clave = 'difusion_fin:' || d.id) then
    raise exception 'FALLO 208 · agotada sin email de aviso a Dynamo';
  end if;
  -- El de Barcelona sin ruta: NINGUNA oferta en NINGUNA difusión.
  if exists (select 1 from envio_ofertas o where o.transportista_id = current_setting('prueba.t208l')::uuid) then
    raise exception 'FALLO 208 · se contacta a un transportista de otra provincia sin la ruta hecha ni colindar';
  end if;
  raise notice 'OK 208b · se agota sin candidatos y avisa; el colindante y el de la ruta parecida entran y el de otra provincia sin ruta no entra nunca';
  -- RECORDATORIO: la oferta del rutero pasa a «de ayer» y casi caducada; el recordatorio
  -- diario la reabre hasta el corte y le manda «sigue disponible» (solo a él: los demás
  -- se contactaron hoy), una sola vez al día.
  v_hoy := (now() at time zone 'Europe/Madrid')::date;
  v_clave := 'difusion_rec:' || e2 || ':' || current_setting('prueba.t208r') || ':' || to_char(v_hoy, 'YYYYMMDD');
  -- (enviada_en y no creado_en: el sello de auditoría hace creado_en inmutable, y lo que
  -- mira el recordatorio es cuándo se le ESCRIBIÓ.)
  update envio_ofertas set enviada_en = now() - interval '1 day', caduca_en = now() + interval '1 minute'
   where envio_id = e2 and transportista_id = current_setting('prueba.t208r')::uuid;
  update difusiones set ultimo_recordatorio = null where envio_id = e2;
  update parametros set valor = '0'::jsonb where clave = 'difusion_recordatorio_hora';
  perform fn_difusion_recordatorios();
  if not exists (select 1 from emails_enviados where clave = v_clave and tipo = 'difusion_recordatorio') then
    raise exception 'FALLO 208 · el contactado de ayer no recibe el recordatorio diario';
  end if;
  if (select count(*) from emails_enviados where tipo = 'difusion_recordatorio' and envio_id = e2) <> 1 then
    raise exception 'FALLO 208 · el recordatorio se manda también a los contactados de hoy';
  end if;
  if exists (select 1 from emails_enviados where clave = v_clave
              and (asunto not like 'Sigue disponible · % · 400,00 €' or position('<strong>400,00 € + IVA</strong>' in cuerpo_html) = 0)) then
    raise exception 'FALLO 208 · el recordatorio no escribe el precio con coma: %', (select asunto from emails_enviados where clave = v_clave);
  end if;
  if (select caduca_en from envio_ofertas where envio_id = e2 and transportista_id = current_setting('prueba.t208r')::uuid)
     is distinct from d.corte_en then
    raise exception 'FALLO 208 · el recordatorio no reabre la oferta hasta el corte';
  end if;
  if (select ultimo_recordatorio from difusiones where envio_id = e2) <> v_hoy then
    raise exception 'FALLO 208 · no se apunta el día del recordatorio';
  end if;
  perform fn_difusion_recordatorios();
  if (select count(*) from emails_enviados where tipo = 'difusion_recordatorio' and envio_id = e2) <> 1 then
    raise exception 'FALLO 208 · el recordatorio se repite el mismo día';
  end if;
  raise notice 'OK 208c · recordatorio diario: reabre la oferta hasta el corte, solo a contactados de otros días y una vez al día';
end $$;
-- E3: CORTE. Con la carga hoy a las 00:00 estamos dentro del corte: no se lanza… salvo
-- forzarla (1 hora de margen). En el tramo urgente los emails salen EN LOTE (difusion_cadencia). Y al
-- llegar al corte, la difusión se cierra con aviso URGENTE.
do $$ declare e3 uuid := current_setting('prueba.e2083')::uuid; d record; r jsonb; begin
  -- Lote urgente de 3 SOLO para esta prueba: con el de producción (20) el primer paso
  -- contactaría a los 7 candidatos del montaje y agotaría la difusión en la misma
  -- llamada, y el cierre por corte de más abajo no tendría difusión activa que cerrar.
  update parametros set valor = '[{"hasta_horas":6,"minutos":1,"lote":3},{"hasta_horas":24,"minutos":1,"lote":3},{"hasta_horas":null,"minutos":3}]'::jsonb
   where clave = 'difusion_cadencia';
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := iniciar_difusion(e3, 400, 10::smallint, true, '00:00'::time);
  if r ->> 'resultado' <> 'dentro_del_corte' then
    raise exception 'FALLO 208 · dentro del corte se lanza sin avisar: %', r;
  end if;
  r := iniciar_difusion(e3, 400, 10::smallint, true, '00:00'::time, true);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 208 · forzada no se lanza: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  select * into d from difusiones where envio_id = e3 and estado = 'activa';
  if d.corte_en is null or d.corte_en < now() + interval '55 minutes' or d.corte_en > now() + interval '65 minutes' then
    raise exception 'FALLO 208 · la forzada no corre con 1 hora de margen: %', d.corte_en;
  end if;
  if d.contactados <> 3 then
    raise exception 'FALLO 208 · en el tramo urgente no salen en lote (de 3 en 3 en la prueba; van %)', d.contactados;
  end if;
  update difusiones set corte_en = now() - interval '1 second', ultimo_email_en = now() - interval '30 minutes' where envio_id = e3;
  perform procesar_difusiones();
  select * into d from difusiones where envio_id = e3;
  if d.estado <> 'agotada' or d.fin_motivo not like '%corte%' then
    raise exception 'FALLO 208 · al corte no se cierra: % (%)', d.estado, d.fin_motivo;
  end if;
  if not exists (select 1 from avisos where envio_id = e3 and tipo = 'difusion_corte' and para = 'dynamo') then
    raise exception 'FALLO 208 · corte sin aviso urgente a Dynamo';
  end if;
  if not exists (select 1 from emails_enviados where clave = 'difusion_fin:' || d.id) then
    raise exception 'FALLO 208 · corte sin email de aviso a Dynamo';
  end if;
  -- La cadencia real de producción, de vuelta (2026-11-16: 1 cada 3 min lejos · 8 cada 3 min el último día · 5 por minuto bajo 6 h · 10 por minuto bajo 3 h).
  update parametros set valor = '[{"hasta_horas":3,"minutos":1,"lote":10},{"hasta_horas":6,"minutos":1,"lote":5},{"hasta_horas":24,"minutos":3,"lote":8},{"hasta_horas":null,"minutos":3}]'::jsonb
   where clave = 'difusion_cadencia';
  raise notice 'OK 208d · dentro del corte no se lanza (forzada, 1 h y en lote) y al corte cierra con aviso urgente';
end $$;
-- E4: DORMIDA. Con la carga a 10 días, la difusión arranca pero no contacta a nadie hasta
-- el día del arranque (5 días antes); despierta al llegar, y el tope sigue mandando.
do $$ declare e4 uuid := current_setting('prueba.e2084')::uuid; d record; r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := iniciar_difusion(e4, 400);
  if r ->> 'resultado' <> 'ok' or r ->> 'empieza' is null then
    raise exception 'FALLO 208 · a 10 días no queda programada con su arranque: %', r;
  end if;
  perform set_config('request.jwt.claim.sub', '', false);
  select * into d from difusiones where envio_id = e4 and estado = 'activa';
  if d.empieza_en is null or d.empieza_en <= now() or d.contactados <> 0 then
    raise exception 'FALLO 208 · la dormida contacta antes del arranque (% · %)', d.empieza_en, d.contactados;
  end if;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e4) <> 0 then
    raise exception 'FALLO 208 · la pasada del reloj despierta la dormida antes de tiempo';
  end if;
  -- Llega el día del arranque: despierta; y el tope de contactados sigue valiendo.
  update difusiones set empieza_en = now() - interval '1 minute', max_contactados = 1 where envio_id = e4;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e4) <> 1 then
    raise exception 'FALLO 208 · al llegar el arranque no despierta';
  end if;
  update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e4;
  perform procesar_difusiones();
  select * into d from difusiones where envio_id = e4;
  if d.estado <> 'agotada' or d.fin_motivo not like 'Tope%' then
    raise exception 'FALLO 208 · el tope no corta la despierta: % (%)', d.estado, d.fin_motivo;
  end if;
  raise notice 'OK 208e · dormida hasta el arranque (días antes, parámetro), despierta al llegar y el tope sigue valiendo';
end $$;
-- Colindantes ENTRE PAÍSES (usuario, 2026-11-15): los pares fronterizos con Francia y
-- Portugal están, y la tabla entera es simétrica (todo par existe en los dos sentidos).
do $$ begin
  if not exists (select 1 from provincias_colindantes where pais_codigo_iso = 'ES' and cp2 = '17' and pais_colindante = 'FR' and colinda_con = '66')
  or not exists (select 1 from provincias_colindantes where pais_codigo_iso = 'FR' and cp2 = '66' and pais_colindante = 'ES' and colinda_con = '17')
  or not exists (select 1 from provincias_colindantes where pais_codigo_iso = 'ES' and cp2 = '21' and pais_colindante = 'PT' and colinda_con = '89')
  or not exists (select 1 from provincias_colindantes where pais_codigo_iso = 'PT' and cp2 = '77' and pais_colindante = 'ES' and colinda_con = '21')
  or not exists (select 1 from provincias_colindantes where pais_codigo_iso = 'ES' and cp2 = '20' and pais_colindante = 'FR' and colinda_con = '64') then
    raise exception 'FALLO 208 · faltan pares fronterizos ES-FR / ES-PT en provincias_colindantes';
  end if;
  if exists (select 1 from provincias_colindantes p
              where not exists (select 1 from provincias_colindantes q
                                 where q.pais_codigo_iso = p.pais_colindante and q.cp2 = p.colinda_con
                                   and q.pais_colindante = p.pais_codigo_iso and q.colinda_con = p.cp2)) then
    raise exception 'FALLO 208 · la tabla de colindantes no es simétrica';
  end if;
  if exists (select 1 from provincias_colindantes where pais_codigo_iso = pais_colindante and cp2 = colinda_con) then
    raise exception 'FALLO 208 · una zona no puede colindar consigo misma';
  end if;
  raise notice 'OK 208f · colindantes entre países: Girona↔66 (FR), Huelva↔Algarve (PT) y Gipuzkoa↔64 (FR); tabla simétrica y sin pares consigo misma';
end $$;
-- REANUDACIÓN (usuario, 2026-11-15): si el envío se queda sin transportista y sigue
-- programado, la difusión cerrada por esa asignación vuelve a arrancar sola donde se
-- quedó, revive las ofertas cerradas y avisa; una parada a mano nunca resucita.
do $$ declare e uuid := current_setting('prueba.e2081')::uuid; d record; begin
  -- Una oferta cerrada «porque otro se la quedó» (como hace la aceptación real).
  update envio_ofertas set estado = 'cerrada'
   where envio_id = e and transportista_id = current_setting('prueba.t208r')::uuid;
  update envios set transportista_id = null where id = e;
  select * into d from difusiones where envio_id = e order by creado_en desc limit 1;
  if d.estado <> 'activa' or d.fin_motivo is not null or d.terminada_en is not null then
    raise exception 'FALLO 208 · al quitar el transportista la difusión no se reanuda: %', d.estado;
  end if;
  if (select estado from envio_ofertas where envio_id = e and transportista_id = current_setting('prueba.t208r')::uuid) <> 'activa' then
    raise exception 'FALLO 208 · la oferta cerrada no revive al reanudarse';
  end if;
  if not exists (select 1 from avisos where envio_id = e and tipo = 'difusion_reanudada' and para = 'dynamo') then
    raise exception 'FALLO 208 · reanudada sin aviso de campana a Dynamo';
  end if;
  -- Y sigue contactando donde se quedó: el 4.º del ranking (el favorito).
  update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e) <> 4
     or not exists (select 1 from envio_ofertas o where o.envio_id = e
                      and o.transportista_id = current_setting('prueba.t208f')::uuid) then
    raise exception 'FALLO 208 · la reanudada no sigue contactando donde se quedó';
  end if;
  -- Parada A MANO: quitar el transportista no la resucita.
  update envios set transportista_id = current_setting('prueba.t208v')::uuid where id = e;
  perform procesar_difusiones();   -- la cierra como aceptada
  update difusiones set estado = 'parada', fin_motivo = 'Parada a mano por Dynamo.' where envio_id = e;
  update envios set transportista_id = null where id = e;
  if (select estado from difusiones where envio_id = e) <> 'parada' then
    raise exception 'FALLO 208 · una difusión parada a mano resucita sola al quitar el transportista';
  end if;
  raise notice 'OK 208g · sin transportista la difusión se reanuda sola (ofertas revividas y aviso); la parada a mano, nunca';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
-- TRAMPILLA POR HISTÓRICO (usuario, 2026-11-15): si el envío requiere plataforma
-- elevadora, solo entra en la difusión quien ya ENTREGÓ envíos que la requerían.
do $$ declare e5 uuid; ev uuid; d record; n int; begin
  -- t_val acredita la trampilla con un envío entregado que la requería.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, requiere_plataforma_elevadora)
    values (current_setting('prueba.cliente')::uuid, 8, 10, 500, 400, (now() at time zone 'Europe/Madrid')::date, true)
    returning id into ev;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (ev, 1, 'carga', '41001', 'Sevilla', 'ES'), (ev, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set transportista_id = current_setting('prueba.t208v')::uuid, estado = 'entregado',
         entregado_en = now() - interval '5 days' where id = ev;
  -- Envío 19→16 QUE REQUIERE trampilla: de toda la cuadrilla solo entra t_val.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, requiere_plataforma_elevadora)
    values (current_setting('prueba.cliente')::uuid, 8, 10, 500, 400, (now() at time zone 'Europe/Madrid')::date + 2, true)
    returning id into e5;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e5, 1, 'carga', '19001', 'Guadalajara', 'ES'), (e5, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set estado = 'programado' where id = e5;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if iniciar_difusion(e5, 300) ->> 'resultado' <> 'ok' then raise exception 'FALLO 208 · no se lanza la de trampilla'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  for n in 1..4 loop
    exit when (select estado from difusiones where envio_id = e5) <> 'activa';
    update difusiones set ultimo_email_en = now() - interval '30 minutes' where envio_id = e5 and estado = 'activa';
    perform procesar_difusiones();
  end loop;
  select * into d from difusiones where envio_id = e5;
  if d.estado <> 'agotada' or d.contactados <> 1
     or not exists (select 1 from envio_ofertas o where o.envio_id = e5 and o.transportista_id = current_setting('prueba.t208v')::uuid) then
    raise exception 'FALLO 208 · con trampilla requerida no entra solo quien la llevó: % (%)', d.estado, d.contactados;
  end if;
  if exists (select 1 from envio_ofertas o where o.envio_id = e5 and o.transportista_id = current_setting('prueba.t208a')::uuid) then
    raise exception 'FALLO 208 · un transportista sin trampilla acreditada entra en un envío que la requiere';
  end if;
  raise notice 'OK 208h · trampilla por histórico: solo entra quien ya entregó envíos que la requerían (ni el autónomo se cuela)';
end $$;
-- LA DIFUSIÓN SIGUE AL ENVÍO (usuario, 2026-11-15): mover la fecha recalcula arranque,
-- hora prevista y corte (vuelve a dormir), revive la agotada y alarga las ofertas vivas;
-- un cambio de ruta también revive la agotada.
do $$ declare e2 uuid := current_setting('prueba.e2082')::uuid; d record; begin
  update envios set fecha_carga_desde = (now() at time zone 'Europe/Madrid')::date + 9 where id = e2;
  select * into d from difusiones where envio_id = e2 order by creado_en desc limit 1;
  if d.estado <> 'activa' or d.fin_motivo is not null or d.empieza_en <= now() then
    raise exception 'FALLO 208 · al mover la fecha la difusión no se recalcula y duerme: % · %', d.estado, d.empieza_en;
  end if;
  if (d.carga_prevista_en at time zone 'Europe/Madrid')::date <> (now() at time zone 'Europe/Madrid')::date + 9
     or d.corte_en <> d.carga_prevista_en - interval '3 hours' then
    raise exception 'FALLO 208 · carga prevista o corte sin recalcular: % · %', d.carga_prevista_en, d.corte_en;
  end if;
  perform procesar_difusiones();
  if (select contactados from difusiones where envio_id = e2) <> 6 then
    raise exception 'FALLO 208 · la dormida recalculada contacta antes del nuevo arranque';
  end if;
  if (select min(caduca_en) from envio_ofertas where envio_id = e2 and canal = 'email' and estado = 'activa') < d.corte_en then
    raise exception 'FALLO 208 · las ofertas vivas no corren hasta el corte nuevo (los enlaces viejos caducarían)';
  end if;
  -- Y un cambio de RUTA revive una agotada, sin tocar su reloj.
  update difusiones set estado = 'agotada', fin_motivo = 'x', terminada_en = now() where envio_id = e2;
  perform registrar_hito(e2, 'ruta_cambiada', null, null, '{}'::jsonb, 'servidor');
  if (select estado from difusiones where envio_id = e2) <> 'activa' then
    raise exception 'FALLO 208 · el cambio de ruta no revive la difusión agotada';
  end if;
  raise notice 'OK 208i · la difusión sigue al envío: fecha movida recalcula y duerme, alarga los enlaces vivos; el cambio de ruta revive la agotada';
end $$;
-- Los parámetros vuelven a su valor real (5:30-23:30, medias horas con decimales).
update parametros set valor = '5.5'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '23.5'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = '9'::jsonb  where clave = 'difusion_recordatorio_hora';
update parametros set valor = 'true'::jsonb where clave = 'bolsa_primero';
update parametros set valor = '3'::jsonb where clave = 'difusion_dias_antes';
update parametros set valor = '0'::jsonb where clave = 'difusion_horas_corte';

-- ---- 209. Borrar transportistas: lógico, fuera de lista y ofertas; con envíos vivos no --
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare ta uuid; tb uuid; e uuid; begin
  insert into transportistas (razon_social, cif, nima, reparto_urbano)
    values ('Transp Borrable 209 SL', 'B20900001', 'NIMA-209A', true) returning id into ta;
  insert into transportistas (razon_social, cif, nima)
    values ('Transp Ocupado 209 SL', 'B20900002', 'NIMA-209B') returning id into tb;
  if not (select reparto_urbano from transportistas where id = ta) then
    raise exception 'FALLO 209 · reparto_urbano no se guarda';
  end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date)
    returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set transportista_id = tb where id = e;
  perform set_config('prueba.t209a', ta::text, false);
  perform set_config('prueba.t209b', tb::text, false);
  perform set_config('prueba.e209', e::text, false);
end $$;
-- Ni un cliente NI un empleado gestor borran transportistas: solo el Admin Master.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare r jsonb; begin
  begin
    r := borrar_transportista(current_setting('prueba.t209a')::uuid);
    raise exception 'FALLO 209 · un cliente borra transportistas';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_emp84'), false);
set role authenticated;
do $$ declare r jsonb; begin
  begin
    r := borrar_transportista(current_setting('prueba.t209a')::uuid);
    raise exception 'FALLO 209 · un empleado gestor borra transportistas (solo Admin Master)';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
-- El admin: con envíos vivos NO deja; sin ellos borra, caduca sus ofertas y lo esconde.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare ta uuid := current_setting('prueba.t209a')::uuid; tb uuid := current_setting('prueba.t209b')::uuid;
            e uuid := current_setting('prueba.e209')::uuid; e2 uuid; r jsonb; o uuid; begin
  r := borrar_transportista(tb);
  if r ->> 'resultado' <> 'con_envios_vivos' then
    raise exception 'FALLO 209 · se borra un transportista con envíos en marcha: %', r;
  end if;
  -- Un 2.º envío SIN transportista: para la oferta viva de ta y la prueba del disparador.
  select (crear_envio(
    jsonb_build_object('cliente_id', current_setting('prueba.cliente'), 'metros_lineales', 13.3,
                       'fecha_carga_desde', current_date + 5, 'importe_cliente', 900, 'importe_transportista', 700),
    jsonb_build_array(
      jsonb_build_object('tipo', 'carga',    'nombre_empresa', 'Carga 209b SL',   'direccion', 'C/ Uno 1', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
      jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Destino 209b SA', 'direccion', 'C/ Dos 2', 'codigo_postal', '28001', 'poblacion', 'Madrid'))
  )).id into e2;
  o := ofertar_envio(e2, ta, 'email', 500);
  r := borrar_transportista(ta);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 209 · no se borra: %', r; end if;
  if (select caduca_en from envio_ofertas where id = o) > now() then
    raise exception 'FALLO 209 · la oferta viva del borrado no se caduca';
  end if;
  if exists (select 1 from transportistas_pagina('Borrable 209') p
              where p.id = ta) then
    raise exception 'FALLO 209 · el borrado sigue saliendo en la lista';
  end if;
  if exists (select 1 from buscar_transportistas('Borrable 209') b where b.id = ta) then
    raise exception 'FALLO 209 · el borrado sigue saliendo en el buscador';
  end if;
  if not exists (select 1 from buscar_transportistas('zzz-nada', 12, ta) b where b.id = ta) then
    raise exception 'FALLO 209 · el ya asignado (p_incluir) no sale aunque esté borrado';
  end if;
  begin
    o := ofertar_envio(e2, ta, 'email', 500);
    raise exception 'FALLO 209 · se oferta a un transportista borrado';
  exception
    when insufficient_privilege then null;   -- lo corta el disparador de borrados
    when others then
      if sqlerrm like 'FALLO 209%' then raise; end if;   -- o el chequeo de «no activo»: también vale
  end;
  -- Y el disparador aguanta hasta un insert directo que se salte ofertar_envio.
  begin
    insert into envio_ofertas (envio_id, transportista_id, canal, precio_ofertado, banda_pct, pronto_pago, caduca_en)
    values (e2, ta, 'email', 500, 10, false, now() + interval '2 days');
    raise exception 'FALLO 209 · un insert directo oferta a un borrado';
  exception when insufficient_privilege then null; end;
  raise notice 'OK 209 · borrar transportistas: solo Admin Master, lógico, fuera de lista/buscador/ofertas (vivas caducadas); con envíos en marcha no deja; reparto_urbano en la ficha';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

