-- =====================================================================================
-- PRUEBA 213 · avisos de recogida/entrega a los sitios: solo con transportista, por
-- tramos sin repetirse, ventana horaria, cliente nombrado siempre (también con
-- discreción) y anulaciones
-- =====================================================================================
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid;
        hoy date := date '2027-03-01';  -- LUNES fijo: con los tramos en dias habiles la prueba es determinista cualquier dia que corra (encolar recibe p_hoy)
        s1 uuid; s2 uuid; e1 uuid; e2 uuid; e3 uuid; p1c uuid; p3d uuid; tr uuid; n int;
begin
  -- Ventanas abiertas de par en par: la prueba no depende de la hora a la que corra.
  update parametros set valor = '0'  where clave = 'aviso_parada_ventana_inicio';
  update parametros set valor = '24' where clave = 'aviso_parada_ventana_fin';
  update parametros set valor = '0'  where clave = 'aviso_parada_hora_mismo_dia';
  insert into transportistas (razon_social, cif) values ('Transp Avisos 213 SL', 'B21300001') returning id into tr;
  insert into sitios (nombre_empresa, cliente_id, emails_avisos) values ('Almacen Carga 213', cli, array['carga213@prueba.invalid']) returning id into s1;
  insert into sitios (nombre_empresa, cliente_id, emails_avisos) values ('Almacen Entrega 213', cli, array['entrega213@prueba.invalid']) returning id into s2;

  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde)
    values (cli, 13.30, 20, 900, hoy + 1) returning id into e1;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e1, 1, 'carga', '41001', 'Sevilla', 'ES', s1, 'Almacen Carga 213') returning id into p1c;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e1, 2, 'descarga', '28001', 'Madrid', 'ES', s2, 'Almacen Entrega 213');
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', fecha_entrega_estimada = hoy + 1 where id = e1;

  -- (a) SIN transportista: aunque cargue mañana, ni un aviso.
  perform encolar_avisos_paradas(hoy);
  if exists (select 1 from emails_enviados where clave like 'aviso_parada:' || e1 || ':%') then
    raise exception 'FALLO 213 · avisa sin transportista asignado';
  end if;

  -- (b) Con transportista: la víspera (d1), recogida Y entrega, UNA sola vez.
  update envios set transportista_id = tr where id = e1;
  perform encolar_avisos_paradas(hoy);
  perform encolar_avisos_paradas(hoy);
  select count(*) into n from emails_enviados where clave like 'aviso_parada:' || e1 || ':%';
  if n <> 2 then raise exception 'FALLO 213 · esperaba 2 avisos de víspera (recogida y entrega) y hay %', n; end if;
  if not exists (select 1 from emails_enviados
                  where clave = 'aviso_parada:' || e1 || ':' || p1c || ':d1:' || (hoy + 1)
                    and destinatario = 'carga213@prueba.invalid' and cuerpo_html like '%recoger mercancía%') then
    raise exception 'FALLO 213 · el aviso de recogida de la víspera no es el esperado';
  end if;

  -- (c) DISCRECIÓN comercial: se avisa IGUAL y se nombra IGUAL al cliente (criterio
  -- definitivo del usuario, 2026-11-13: la discreción protege la RUTA — que el aviso no
  -- lleva —, no al cliente que manda el camión). Y el aviso NUNCA lleva la otra punta
  -- del viaje: el de recogida no dice el destino ni el de entrega el origen.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, discrecion_comercial)
    values (cli, 13.30, 20, 900, hoy + 2, true) returning id into e2;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e2, 1, 'carga', '41001', 'Sevilla', 'ES', s1, 'Almacen Carga 213');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e2, 2, 'descarga', '28001', 'Madrid', 'ES', s2, 'Almacen Entrega 213');
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', transportista_id = tr, fecha_entrega_estimada = hoy + 2 where id = e2;
  perform encolar_avisos_paradas(hoy);
  select count(*) into n from emails_enviados where clave like 'aviso_parada:' || e2 || ':%';
  if n <> 2 then raise exception 'FALLO 213 · con discreción esperaba 2 avisos y hay %', n; end if;
  if exists (select 1 from emails_enviados x, clientes c
              where x.clave like 'aviso_parada:' || e2 || ':%' and c.id = cli
                and (x.asunto not like '%de parte de ' || c.razon_social || '%'
                  or x.cuerpo_html not like '%De parte de <strong>' || escapar_html(c.razon_social) || '%')) then
    raise exception 'FALLO 213 · el aviso (con discreción) debía nombrar al cliente en asunto y cuerpo';
  end if;
  if exists (select 1 from emails_enviados
              where clave like 'aviso_parada:' || e2 || ':%'
                and destinatario = 'carga213@prueba.invalid' and cuerpo_html like '%Madrid%') then
    raise exception 'FALLO 213 · el aviso de recogida revela el destino';
  end if;
  if not exists (select 1 from emails_enviados x, clientes c
                  where x.clave like 'aviso_parada:' || e1 || ':%' and c.id = cli
                    and x.cuerpo_html like '%De parte de <strong>' || escapar_html(c.razon_social) || '%') then
    raise exception 'FALLO 213 · sin discreción el aviso debía decir «de parte de» el cliente';
  end if;

  -- (d) VENTANA cerrada: el envío a 2 días espera; al abrirla, salen los d2.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde)
    values (cli, 13.30, 20, 900, hoy + 2) returning id into e3;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e3, 1, 'carga', '41001', 'Sevilla', 'ES', s1, 'Almacen Carga 213');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e3, 2, 'descarga', '28001', 'Madrid', 'ES', s2, 'Almacen Entrega 213');
  -- Tercera parada (otra entrega): es la que luego se QUITA — la ruta exige mínimo 2.
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e3, 3, 'descarga', '40001', 'Segovia', 'ES', s2, 'Almacen Entrega 213') returning id into p3d;
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', transportista_id = tr, fecha_entrega_estimada = hoy + 2 where id = e3;
  update parametros set valor = '23' where clave = 'aviso_parada_ventana_inicio';
  update parametros set valor = '23' where clave = 'aviso_parada_ventana_fin';
  perform encolar_avisos_paradas(hoy);
  if exists (select 1 from emails_enviados where clave like 'aviso_parada:' || e3 || ':%') then
    raise exception 'FALLO 213 · avisa fuera de la ventana horaria';
  end if;
  update parametros set valor = '0'  where clave = 'aviso_parada_ventana_inicio';
  update parametros set valor = '24' where clave = 'aviso_parada_ventana_fin';
  perform encolar_avisos_paradas(hoy);
  select count(*) into n from emails_enviados where clave like 'aviso_parada:' || e3 || ':%:d2:%';
  if n <> 3 then raise exception 'FALLO 213 · esperaba 3 avisos d2 al abrir la ventana y hay %', n; end if;

  -- (e) ENVÍO CANCELADO: anulación a los dos sitios avisados y sus pendientes en omitido.
  update envios set estado = 'cancelado' where id = e1;
  select count(*) into n from emails_enviados where clave like 'aviso_parada_cancelada:' || e1 || ':%';
  if n <> 2 then raise exception 'FALLO 213 · esperaba 2 anulaciones al cancelar y hay %', n; end if;
  if exists (select 1 from emails_enviados where clave like 'aviso_parada:' || e1 || ':%' and estado = 'pendiente') then
    raise exception 'FALLO 213 · los avisos del envío cancelado siguen pendientes';
  end if;

  -- (f) PARADA QUITADA de un envío vivo: anulación solo a ese sitio.
  delete from envio_paradas where id = p3d;
  if not exists (select 1 from emails_enviados where clave = 'aviso_parada_cancelada:' || e3 || ':' || p3d) then
    raise exception 'FALLO 213 · quitar una parada avisada no genera su anulación';
  end if;
  select count(*) into n from emails_enviados where clave like 'aviso_parada_cancelada:' || e3 || ':%';
  if n <> 1 then raise exception 'FALLO 213 · la anulación de parada quitada debía ser solo una y hay %', n; end if;

  -- (g) Anulación CON discreción: nombra al cliente igualmente.
  update envios set estado = 'cancelado' where id = e2;
  if exists (select 1 from emails_enviados x, clientes c
              where x.clave like 'aviso_parada_cancelada:' || e2 || ':%' and c.id = cli
                and x.cuerpo_html not like '%por parte de <strong>' || escapar_html(c.razon_social) || '%') then
    raise exception 'FALLO 213 · la anulación (con discreción) debía nombrar al cliente';
  end if;
  select count(*) into n from emails_enviados where clave like 'aviso_parada_cancelada:' || e2 || ':%';
  if n <> 2 then raise exception 'FALLO 213 · con discreción esperaba 2 anulaciones y hay %', n; end if;

  -- Los parámetros, como estaban.
  update parametros set valor = '10' where clave = 'aviso_parada_ventana_inicio';
  update parametros set valor = '16' where clave = 'aviso_parada_ventana_fin';
  update parametros set valor = '8'  where clave = 'aviso_parada_hora_mismo_dia';
  raise notice 'OK 213 · avisos a los sitios: solo con transportista, por tramos sin repetirse, ventana horaria, cliente nombrado siempre (también con discreción, que solo protege la ruta), y anulaciones al cancelar o quitar paradas';
end $$;

-- =====================================================================================
-- PRUEBA 214 · el día de carga ELEGIDO al asignar (fecha_carga_prevista) viaja en los
-- documentos públicos: orden_carga_json, cmr_publico y datos_cmr_por_token
-- =====================================================================================
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid;
        hoy date := (now() at time zone 'Europe/Madrid')::date;
        tr uuid; e1 uuid; tok uuid;
begin
  insert into transportistas (razon_social, cif) values ('Transp Fecha 214 SL', 'B21400001') returning id into tr;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 900, hoy + 1, hoy + 3) returning id into e1;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, nombre_empresa)
    values (e1, 1, 'carga', '41001', 'Sevilla', 'ES', 'Carga 214');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, nombre_empresa)
    values (e1, 2, 'descarga', '28001', 'Madrid', 'ES', 'Entrega 214');
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', transportista_id = tr,
         fecha_carga_prevista = hoy + 2, fecha_entrega_estimada = hoy + 4 where id = e1;

  if (orden_carga_json(e1)->'envio'->>'fecha_carga_prevista') is distinct from (hoy + 2)::text then
    raise exception 'FALLO 214 · orden_carga_json no lleva el día de carga elegido';
  end if;
  select token into tok from cmr_enlaces where envio_id = e1 and not revocado limit 1;
  if tok is null then insert into cmr_enlaces (envio_id) values (e1) returning token into tok; end if;
  if (cmr_publico(tok)->>'fecha_carga') is distinct from (hoy + 2)::text then
    raise exception 'FALLO 214 · cmr_publico no enseña el día elegido en fecha_carga';
  end if;
  if (datos_cmr_por_token(tok)->'envio'->>'fecha_carga_prevista') is distinct from (hoy + 2)::text then
    raise exception 'FALLO 214 · datos_cmr_por_token no lleva el día de carga elegido';
  end if;
  raise notice 'OK 214 · el día de carga elegido al asignar sale en la orden por enlace, la página de firmas y el PDF del e-CMR';
end $$;

-- =====================================================================================
-- PRUEBA 215 · copia cliente de la orden: orden_carga_json lleva los dos importes y el
-- bloque del cliente, y datos_orden_por_cmr solo suelta la economía de su clave
-- =====================================================================================
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid;
        hoy date := (now() at time zone 'Europe/Madrid')::date;
        tr uuid; e1 uuid; tok uuid; j jsonb;
begin
  insert into transportistas (razon_social, cif) values ('Transp Copia 215 SL', 'B21500001') returning id into tr;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 950, hoy + 1, hoy + 3) returning id into e1;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, nombre_empresa)
    values (e1, 1, 'carga', '41001', 'Sevilla', 'ES', 'Carga 215');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, nombre_empresa)
    values (e1, 2, 'descarga', '28001', 'Madrid', 'ES', 'Entrega 215');
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', transportista_id = tr, importe_transportista = 700, iva_pct = 21 where id = e1;

  j := orden_carga_json(e1);
  if (j->'envio'->>'importe_cliente')::numeric is distinct from 950
     or (j->'envio'->>'iva_pct')::numeric is distinct from 21
     or (j->'envio'->>'importe_transportista')::numeric is distinct from 700
     or (j->'cliente'->>'razon_social') is null then
    raise exception 'FALLO 215 · orden_carga_json no lleva los dos importes o el bloque del cliente';
  end if;

  select token into tok from cmr_enlaces where envio_id = e1 and not revocado limit 1;
  if tok is null then insert into cmr_enlaces (envio_id) values (e1) returning token into tok; end if;
  -- Sin clave (o con una ajena): ninguna economía y ningún id.
  j := datos_orden_por_cmr(tok);
  if j->'envio' ? 'importe_transportista' or j->'envio' ? 'importe_cliente' or j ? 'cliente'
     or j ? 'transportista_id' or j ? 'cliente_id' or (j->>'clave_rol') is not null then
    raise exception 'FALLO 215 · sin clave, datos_orden_por_cmr suelta economía o ids';
  end if;
  j := datos_orden_por_cmr(tok, e1);   -- una clave ajena (el propio id del envío) no abre nada
  if j->'envio' ? 'importe_transportista' or j->'envio' ? 'importe_cliente' or (j->>'clave_rol') is not null then
    raise exception 'FALLO 215 · una clave ajena abre economía en datos_orden_por_cmr';
  end if;
  -- Con la clave del transportista: su importe sí; el del cliente, no.
  j := datos_orden_por_cmr(tok, tr);
  if (j->'envio'->>'importe_transportista')::numeric is distinct from 700
     or j->'envio' ? 'importe_cliente' or j ? 'cliente' or (j->>'clave_rol') is distinct from 'transportista' then
    raise exception 'FALLO 215 · con la clave del transportista no sale (solo) su importe';
  end if;
  -- Con la clave del cliente: su importe con IVA y su bloque; el del transportista, no.
  j := datos_orden_por_cmr(tok, cli);
  if (j->'envio'->>'importe_cliente')::numeric is distinct from 950
     or (j->'envio'->>'iva_pct')::numeric is distinct from 21
     or (j->'cliente'->>'razon_social') is null
     or j->'envio' ? 'importe_transportista' or j ? 'porteador' or j ? 'pronto_pago'
     or j->'envio' ? 'plazo_pago_transportista' or (j->>'clave_rol') is distinct from 'cliente' then
    raise exception 'FALLO 215 · con la clave del cliente no sale (solo) su importe con IVA, o se cuela el porteador';
  end if;
  raise notice 'OK 215 · copia cliente: los dos importes viajan en el JSON interno y la clave decide qué economía suelta el enlace público';
end $$;

-- =====================================================================================
-- PRUEBA 216 · el tarifador vuelve a contar consultas de precio (registrar_consulta_precio)
-- =====================================================================================
do $$
declare u_cli uuid := current_setting('prueba.u_cli')::uuid; n0 int; n1 int; j jsonb;
begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  select count(*) into n0 from consultas_precio where usuario_id = u_cli;
  perform registrar_consulta_precio();
  select count(*) into n1 from consultas_precio where usuario_id = u_cli;
  if n1 <> n0 + 1 then raise exception 'FALLO 216 · la consulta del cliente no se registra'; end if;
  if (select origen from consultas_precio where usuario_id = u_cli order by cuando desc, id desc limit 1) <> 'tarifador' then
    raise exception 'FALLO 216 · la consulta no queda con origen tarifador';
  end if;
  j := mi_autosuspension();
  if coalesce((j->'consultas'->>'hoy')::int, 0) < 1 then
    raise exception 'FALLO 216 · mi_autosuspension no cuenta la consulta del tarifador: %', j;
  end if;
  -- El equipo de Dynamo no cuenta: la función no registra nada.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  select count(*) into n0 from consultas_precio;
  perform registrar_consulta_precio();
  select count(*) into n1 from consultas_precio;
  if n1 <> n0 then raise exception 'FALLO 216 · una consulta del equipo de Dynamo se ha registrado'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 216 · el tarifador registra la consulta del cliente (y del equipo no), y mi_autosuspension la cuenta';
end $$;

-- =====================================================================================
-- PRUEBA 217 · regla 4 ESTRICTA (en el límite no suspende; por encima sí) y email al
-- buzón de Dynamo en cada suspensión automática
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare b uuid := current_setting('prueba.u_cli_b')::uuid;
        cli_b uuid; e uuid; i int; pct_antes jsonb;
begin
  select id into cli_b from clientes where cif = 'B44444444';
  -- La suspensión del cliente A en la prueba 95 (barrido) tuvo que encolar su email.
  if not exists (select 1 from emails_enviados where tipo = 'cuenta_suspendida'
                   and clave like 'cuenta_suspendida:' || current_setting('prueba.u_cli') || ':%') then
    raise exception 'FALLO 217 · la suspensión automática no encola el email al buzón de Dynamo';
  end if;
  -- Límite al 20 % para reproducir el caso del usuario (1 de 5 = 20 % NO debe suspender).
  select valor into pct_antes from parametros where clave = 'autosuspension_cancel_pct';
  update parametros set valor = '20' where clave = 'autosuspension_cancel_pct';
  update usuarios set autosuspension_desde_en = now(), estado = 'activa' where id = b;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  for i in 1..5 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
      values (cli_b, 13.30, 20, 1000, 800, current_date) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28001', 'Madrid', 'ES');
    update envios set estado = 'programado' where id = e;
    if i = 1 then
      update envios set transportista_id = current_setting('prueba.transp')::uuid where id = e;
      update envios set estado = 'cancelado' where id = e;
    end if;
  end loop;
  perform set_config('request.jwt.claim.sub', '', false);
  -- 1 de 5 = 20 % con límite 20 %: EN el límite, ni en la lista ni suspendida (antes caía).
  if exists (select 1 from autosuspension_motivos(b) where motivo like 'Regla 4%') then
    raise exception 'FALLO 217 · la regla 4 suspende AL LLEGAR al límite (1 de 5 con 20 %%)';
  end if;
  if (select estado from usuarios where id = b) <> 'activa' then
    raise exception 'FALLO 217 · la cuenta cayó suspendida en el límite exacto';
  end if;
  -- Una cancelación más (2 de 5 = 40 %): ahora sí, y al momento llega su email a Dynamo.
  select x.id into e from envios x where x.cliente_id = cli_b and x.estado = 'programado' and x.creado_por = b order by x.creado_en desc limit 1;
  update envios set transportista_id = current_setting('prueba.transp')::uuid where id = e;
  -- La cancela EL USUARIO (con su jwt): el hito lleva su quien y la regla 4 la cuenta.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  update envios set estado = 'cancelado' where id = e;
  perform set_config('request.jwt.claim.sub', '', false);
  perform autosuspension_revisar(b);
  if (select estado from usuarios where id = b) <> 'suspendida'
     or (select suspension_motivo from usuarios where id = b) not like 'Automática (al momento) · Regla 4%' then
    raise exception 'FALLO 217 · por encima del límite no suspende al momento: %', (select suspension_motivo from usuarios where id = b);
  end if;
  if not exists (select 1 from emails_enviados where tipo = 'cuenta_suspendida'
                   and clave like 'cuenta_suspendida:' || b || ':%') then
    raise exception 'FALLO 217 · la suspensión al momento no encola el email al buzón de Dynamo';
  end if;
  -- Se deja todo como estaba: cuenta activa y límite anterior.
  update usuarios set estado = 'activa' where id = b;
  update parametros set valor = pct_antes where clave = 'autosuspension_cancel_pct';
  raise notice 'OK 217 · regla 4 estricta (en el límite no, por encima sí) y email a Dynamo en cada suspensión automática';
end $$;

-- =====================================================================================
-- PRUEBA 218 · lista de bloqueo de altas: email y dominio, defensa en el alta y bloqueo
-- opcional al anonimizar
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare uid uuid; n int;
begin
  -- El Admin Master bloquea una dirección y un dominio entero.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  insert into bloqueos_alta (tipo, valor, motivo) values ('email', 'molesto@acme.prueba', 'prueba 218');
  insert into bloqueos_alta (tipo, valor, motivo) values ('dominio', 'spamcorp.prueba', 'prueba 218');
  reset role;
  -- Un cliente ni ve la lista ni puede escribir en ella (RLS).
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  select count(*) into n from bloqueos_alta;
  if n <> 0 then raise exception 'FALLO 218 · un cliente ve la lista de bloqueo'; end if;
  begin
    insert into bloqueos_alta (tipo, valor) values ('email', 'colado@porcliente.prueba');
    raise exception 'FALLO 218 · un cliente ha podido bloquear un alta';
  exception when insufficient_privilege then null; end;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);
  -- alta_bloqueada: la dirección exacta (da igual mayúsculas), cualquier buzón del
  -- dominio bloqueado, y nada más.
  if not alta_bloqueada('molesto@acme.prueba') then raise exception 'FALLO 218 · la dirección bloqueada no se detecta'; end if;
  if not alta_bloqueada('  MOLESTO@ACME.PRUEBA ') then raise exception 'FALLO 218 · el bloqueo distingue mayúsculas o espacios'; end if;
  if alta_bloqueada('otro@acme.prueba') then raise exception 'FALLO 218 · bloquear una dirección bloquea a sus compañeros de dominio'; end if;
  if not alta_bloqueada('cualquiera@spamcorp.prueba') then raise exception 'FALLO 218 · el dominio bloqueado no se detecta'; end if;
  if alta_bloqueada('cualquiera@otraempresa.prueba') then raise exception 'FALLO 218 · se bloquea un dominio que no está en la lista'; end if;
  -- Defensa en el propio alta: aunque se esquive la web, la cuenta no se crea.
  begin
    insert into auth.users (email) values ('nuevo@spamcorp.prueba');
    raise exception 'FALLO 218 · un email de dominio bloqueado ha podido darse de alta';
  exception when insufficient_privilege then null; end;
  if exists (select 1 from usuarios where email = 'nuevo@spamcorp.prueba') then
    raise exception 'FALLO 218 · el perfil del alta bloqueada se ha creado igualmente';
  end if;
  -- Anonimizar con las dos opciones: el email real y su dominio quedan bloqueados.
  insert into auth.users (email) values ('borrame@bloqueo218.prueba') returning id into uid;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if (select j->>'resultado' from anonimizar_usuario(uid, true, true) j) <> 'ok' then
    raise exception 'FALLO 218 · anonimizar con bloqueo no devuelve ok';
  end if;
  perform set_config('request.jwt.claim.sub', '', false);
  if not alta_bloqueada('borrame@bloqueo218.prueba') or not alta_bloqueada('otronuevo@bloqueo218.prueba') then
    raise exception 'FALLO 218 · anonimizar con bloqueo no apunta el email o el dominio en la lista';
  end if;
  if (select email from usuarios where id = uid) not like '%@anonimo.invalid' then
    raise exception 'FALLO 218 · la cuenta anonimizada conserva su email';
  end if;
  -- Se deja la lista limpia para no estorbar a otras pasadas.
  delete from bloqueos_alta where motivo = 'prueba 218' or valor like '%bloqueo218.prueba';
  raise notice 'OK 218 · lista de bloqueo de altas: email y dominio, defensa en el alta y bloqueo al anonimizar';
end $$;

-- =====================================================================================
-- PRUEBA 219 · cambiar el email de acceso: un email vetado se rechaza en la base de
-- datos, uno libre se sincroniza al perfil y los usos del usuario no se reinician
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare b uuid := current_setting('prueba.u_cli_b')::uuid;
        v_antes text; v_consultas int; v_desde timestamptz;
begin
  select email into v_antes from usuarios where id = b;
  select count(*) into v_consultas from consultas_precio where usuario_id = b;
  select autosuspension_desde_en into v_desde from usuarios where id = b;
  insert into bloqueos_alta (tipo, valor, motivo) values ('email', 'nuevo219@vetado.prueba', 'prueba 219');
  -- A un email de la lista de bloqueo NO se puede cambiar, ni llamando al acceso directo.
  begin
    update auth.users set email = 'nuevo219@vetado.prueba' where id = b;
    raise exception 'FALLO 219 · se ha podido cambiar el email a uno vetado';
  exception when insufficient_privilege then null; end;
  if (select email from usuarios where id = b) <> v_antes then
    raise exception 'FALLO 219 · el cambio rechazado ha tocado el perfil igualmente';
  end if;
  -- A uno libre sí, y el perfil se sincroniza solo.
  update auth.users set email = 'nuevo219@libre.prueba' where id = b;
  if (select email from usuarios where id = b) <> 'nuevo219@libre.prueba' then
    raise exception 'FALLO 219 · el email nuevo no se ha sincronizado al perfil';
  end if;
  -- Y los usos NO se reinician: mismas consultas y misma fecha de arranque del contador.
  if (select count(*) from consultas_precio where usuario_id = b) <> v_consultas
     or (select autosuspension_desde_en from usuarios where id = b) is distinct from v_desde then
    raise exception 'FALLO 219 · cambiar el email ha reiniciado los usos del usuario';
  end if;
  -- Se deja todo como estaba.
  update auth.users set email = v_antes where id = b;
  delete from bloqueos_alta where motivo = 'prueba 219';
  raise notice 'OK 219 · el cambio de email respeta la lista de bloqueo, sincroniza el perfil y no reinicia los usos';
end $$;

-- =====================================================================================
-- PRUEBA 220 · el CMR digital es solo de Dynamo: un envío MANUAL no se puede firmar ni
-- anotar reservas aunque se llame a las funciones públicas con su token
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid;
        op uuid; e uuid; tok uuid; par uuid; r jsonb; i0 int; ruta text;
begin
  -- El envío manual se crea como lo hace la web (crear_envio_manual exige el jwt del cliente).
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into operadores (cliente_id, razon_social, cif) values (cli, 'Transportes Guardia 220', 'B22000220') returning id into op;
  select s.id into e from crear_envio_manual(
    jsonb_build_object('operador_id', op, 'metros_lineales', 5, 'fecha_carga_desde', current_date, 'precio_acordado_operador', 300),
    jsonb_build_array(
      jsonb_build_object('tipo', 'carga',    'nombre_empresa', 'Nave 220', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
      jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Destino 220', 'codigo_postal', '28001', 'poblacion', 'Madrid'))) s;
  perform set_config('request.jwt.claim.sub', '', false);
  select id into par from envio_paradas where envio_id = e and tipo = 'carga' limit 1;
  -- crear_envio_manual ya deja su enlace vivo (uno por envío): se usa ese.
  select token into tok from cmr_enlaces where envio_id = e and not revocado limit 1;
  if tok is null then raise exception 'FALLO 220 · el envío manual no tiene enlace de CMR'; end if;
  -- El trazo subido de verdad en la carpeta del enlace (como exige la firma): la llamada
  -- pasa todas las validaciones y solo la frena el cerrojo del disparador.
  ruta := 'cmr/' || tok || '/' || gen_random_uuid() || '.png';
  insert into storage.objects (bucket_id, name) values ('documentos', ruta);
  -- Firmar: rechazado y sin dejar nada.
  begin
    r := firmar_cmr_publico(tok, par, 'remitente', 'Prueba Manual', '12345678Z', 'ES', true, null, ruta, '127.0.0.1'::inet, 'prueba', repeat('a', 64));
    raise exception 'FALLO 220 · un envío manual se ha podido firmar en digital: %', r;
  exception when insufficient_privilege then null; end;
  if exists (select 1 from firmas_cmr where envio_id = e) then
    raise exception 'FALLO 220 · la firma del envío manual se ha guardado igualmente';
  end if;
  -- Reservas: rechazadas, y la incidencia de la misma llamada se deshace con el rechazo.
  select count(*) into i0 from incidencias;
  begin
    r := anotar_reservas_cmr_publico(tok, par, 'remitente', 'Reserva de prueba 220');
    raise exception 'FALLO 220 · un envío manual ha podido anotar reservas: %', r;
  exception when insufficient_privilege then null; end;
  if (select count(*) from incidencias) <> i0 or exists (select 1 from cmr_reservas where envio_id = e) then
    raise exception 'FALLO 220 · la reserva del manual ha dejado rastro (incidencia o reserva)';
  end if;
  -- La hoja pública se sigue pudiendo LEER (para el aviso y el PDF imprimible).
  r := cmr_publico(tok);
  if r ->> 'resultado' <> 'ok' or not coalesce((r ->> 'manual')::boolean, false) then
    raise exception 'FALLO 220 · la lectura pública del manual ha dejado de funcionar: %', r;
  end if;
  raise notice 'OK 220 · el CMR digital es solo de Dynamo: el manual ni firma ni reserva, pero se sigue leyendo';
end $$;

-- =====================================================================================
-- PRUEBA 221 · suspensión en dos niveles: «suspendida» entra y LEE pero no escribe
-- (solo lectura); «suspendida_total» ni lee; reactivada, todo vuelve
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  update usuarios set estado = 'suspendida', suspension_motivo = 'Prueba 221'
   where id = current_setting('prueba.u_cli')::uuid;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare n int; begin
  -- SOLO LECTURA: sus ayudantes de RLS responden y ve sus envíos…
  if cliente_del_usuario() is null then raise exception 'FALLO 221 · la cuenta suspendida no puede ni leer (cliente_del_usuario nulo)'; end if;
  select count(*) into n from mis_envios();
  if n = 0 then raise exception 'FALLO 221 · la cuenta suspendida no ve sus envíos'; end if;
  -- …pero NO escribe: el cerrojo central corta cualquier escritura (RLS la dejaría pasar).
  begin
    insert into sitios (nombre_empresa, cliente_id) values ('Nave suspendida 221', cliente_del_usuario());
    raise exception 'FALLO 221 · una cuenta suspendida ha podido crear un sitio';
  exception when insufficient_privilege then null; end;
  begin
    update envios set referencia_cliente = 'PED-221' where creado_por = auth.uid() and estado = 'programado';
    if found then raise exception 'FALLO 221 · una cuenta suspendida ha podido editar un envío'; end if;
  exception when insufficient_privilege then null; end;
  raise notice 'OK 221a · suspendida = solo lectura: lee lo suyo y toda escritura se corta';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  update usuarios set estado = 'suspendida_total' where id = current_setting('prueba.u_cli')::uuid;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare n int; begin
  -- TOTAL: ni lectura (la web además la expulsa de la sesión).
  if cliente_del_usuario() is not null then raise exception 'FALLO 221 · la suspensión total sigue leyendo'; end if;
  select count(*) into n from mis_envios();
  if n <> 0 then raise exception 'FALLO 221 · la suspensión total ve envíos'; end if;
  raise notice 'OK 221b · suspendida_total: ni lectura';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare n int; begin
  update usuarios set estado = 'activa', suspension_motivo = null where id = current_setting('prueba.u_cli')::uuid;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  select count(*) into n from mis_envios();
  if n = 0 then raise exception 'FALLO 221 · reactivada no recupera sus envíos'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 221 · suspensión en dos niveles: solo lectura / total, y la reactivación lo devuelve todo';
end $$;

-- =====================================================================================
-- PRUEBA 222 · el camión del envío manual se pone y cambia en cualquier momento
-- =====================================================================================
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; r jsonb; v record; begin
  -- El manual de la prueba 220 (del cliente de u_cli), sin matrícula todavía.
  select x.id into e from envios x where x.es_manual and x.operador_id in (select id from operadores where razon_social = 'Transportes Guardia 220') limit 1;
  if e is null then raise exception 'FALLO 222 · no está el envío manual de la 220'; end if;
  -- Su dueño lo rellena…
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  r := poner_camion_mi_envio_manual(e, ' 1234 bcd ', '', 'Juan Conductor', '+34 600 111 222');
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 222 · el dueño no puede poner el camión: %', r; end if;
  select matricula_camion, matricula_remolque, conductor_nombre, conductor_telefono into v from envios where id = e;
  if v.matricula_camion <> '1234 BCD' or v.matricula_remolque is not null
     or v.conductor_nombre <> 'Juan Conductor' or v.conductor_telefono <> '+34600111222' then
    raise exception 'FALLO 222 · los datos no se guardan normalizados: %', v;
  end if;
  -- …lo cambia después (y el remolque entra ahora)…
  r := poner_camion_mi_envio_manual(e, '5678CDF', 'r9999zz', 'Ana Conductora', null);
  if r ->> 'resultado' <> 'ok' or (select matricula_remolque from envios where id = e) <> 'R9999ZZ' then
    raise exception 'FALLO 222 · no se puede cambiar después: %', r;
  end if;
  if (select conductor_telefono from envios where id = e) is not null then
    raise exception 'FALLO 222 · vacío no quita el teléfono';
  end if;
  -- …y la orden de transporte lo recoge.
  if (select datos_orden_manual(e)::text) !~ '5678CDF' then
    raise exception 'FALLO 222 · la orden del manual no recoge la matrícula nueva';
  end if;
  perform set_config('request.jwt.claim.sub', '', false);
  -- Otro cliente, no; un envío de Dynamo, tampoco.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  begin
    r := poner_camion_mi_envio_manual(e, '0000XXX', null, null, null);
    raise exception 'FALLO 222 · otro cliente ha podido cambiar el camión ajeno';
  exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  r := poner_camion_mi_envio_manual(current_setting('prueba.envio')::uuid, '0000XXX', null, null, null);
  if r ->> 'resultado' <> 'solo_manuales' then raise exception 'FALLO 222 · un envío de Dynamo acepta el camión manual: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 222 · el camión del envío manual se pone y cambia en cualquier momento (dueño o Dynamo; normalizado; la orden lo recoge)';
end $$;

-- ---- 223. Panel de modificaciones del DeCA (Resolución 5-jun-2026, apdo. quinto) ------
-- El DeCA se EMITE al ponerse las primeras matrículas (usuario, 2026-11-15): el panel
-- empieza por esa 1.ª asignación de matrículas («primera») y sigue con lo posterior — el
-- cambio de matrícula, la retirada y la reasignación —; el transportista asignado ANTES de
-- las matrículas es el documento original y no sale.
-- Cada cambio va en su propia transacción para que los hitos tengan horas distintas.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t1 uuid; t2 uuid; begin
  insert into transportistas (razon_social, cif, nima) values ('Transp 223A SL', 'B22300001', 'NIMA-223A') returning id into t1;
  insert into transportistas (razon_social, cif, nima) values ('Transp 223B SL', 'B22300002', 'NIMA-223B') returning id into t2;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3)
    returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('prueba.e223', e::text, false);
  perform set_config('prueba.t223a', t1::text, false);
  perform set_config('prueba.t223b', t2::text, false);
end $$;
-- El transportista, antes de las matrículas (no cuenta); las 1.as matrículas = emisión…
update envios set transportista_id = current_setting('prueba.t223a')::uuid where id = current_setting('prueba.e223')::uuid;
update envios set matricula_camion = '1111AAA' where id = current_setting('prueba.e223')::uuid;
-- …y MODIFICARLO (cuenta): cambio de matrícula, retirada y reasignación.
update envios set matricula_camion = '2222BBB', matricula_remolque = 'R3333CCC' where id = current_setting('prueba.e223')::uuid;
update envios set transportista_id = null where id = current_setting('prueba.e223')::uuid;
update envios set transportista_id = current_setting('prueba.t223b')::uuid where id = current_setting('prueba.e223')::uuid;
do $$ declare e uuid := current_setting('prueba.e223')::uuid; m jsonb; begin
  m := fn_modificaciones_deca(e);
  if jsonb_array_length(m) <> 4 then raise exception 'FALLO 223 · esperaba 4 entradas y hay %: %', jsonb_array_length(m), m; end if;
  if m -> 0 ->> 'hito' <> 'matricula_asignada' or (m -> 0 ->> 'primera')::boolean is not true or m -> 0 ->> 'detalle' <> '1111AAA' then
    raise exception 'FALLO 223 · el panel no empieza por la 1.ª asignación de matrículas (la emisión): %', m;
  end if;
  if m -> 1 ->> 'hito' <> 'matricula_asignada' or (m -> 1 ->> 'primera')::boolean is not false or m -> 1 ->> 'detalle' <> '2222BBB / R3333CCC'
     or m -> 1 ->> 'antes' <> '1111AAA' then
    raise exception 'FALLO 223 · el cambio de matrícula no sale bien: %', m -> 1;
  end if;
  if m -> 2 ->> 'hito' <> 'transportista_quitado' or m -> 3 ->> 'hito' <> 'transportista_asignado' or (m -> 3 ->> 'primera')::boolean is not false then
    raise exception 'FALLO 223 · faltan la retirada y la reasignación: %', m;
  end if;
  if exists (select 1 from jsonb_array_elements(m) x where x ->> 'cuando' !~ '^[0-9]{2}/[0-9]{2}/[0-9]{4} [0-9]{2}:[0-9]{2}$') then
    raise exception 'FALLO 223 · la fecha no va formateada a la española: %', m;
  end if;
  if orden_carga_json(e) -> 'modificaciones' is null or jsonb_array_length(orden_carga_json(e) -> 'modificaciones') <> 4 then
    raise exception 'FALLO 223 · orden_carga_json no lleva el panel de modificaciones';
  end if;
end $$;
-- El envoltorio respeta permisos: el cliente no lo lee; Dynamo sí.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  begin
    perform modificaciones_deca(current_setting('prueba.e223')::uuid);
    raise exception 'FALLO 223 · un cliente lee las modificaciones del DeCA de un envío ajeno';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ begin
  if jsonb_array_length(modificaciones_deca(current_setting('prueba.e223')::uuid)) <> 4 then
    raise exception 'FALLO 223 · Dynamo no lee las modificaciones del DeCA';
  end if;
  raise notice 'OK 223 · panel del DeCA: se emite con las 1.as matrículas (lo anterior no sale), matrícula cambiada con su dato anterior, retirada y reasignación, fecha a la española, en orden_carga_json y con permisos';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 224. Emails a Dynamo: envío aceptado y alta online pendiente de aceptar ----------
-- (a) Un conocido acepta al precio ofertado → email 'envio_aceptado' con el enlace a la
--     ficha. (b) Un desconocido (alta online sin verificar) deja la carga pendiente →
--     email 'alta_pendiente' con sus datos y el enlace «Revisar y aceptar». (c) La
--     contraoferta de un conocido NO manda el email de alta (solo campana).
do $$ declare c uuid := current_setting('prueba.cliente')::uuid; t uuid := current_setting('prueba.transp')::uuid;
              e1 uuid; e2 uuid; e3 uuid; o uuid; r jsonb; res1 uuid; res2 uuid; res3 uuid;
              t_alta uuid; v_cuerpo text; begin
  -- (a) aceptación directa de un conocido, por el flujo real.
  insert into envios (cliente_id, metros_lineales, importe_cliente, importe_transportista)
    values (c, 6, 700, 560) returning id into e1;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e1, 1, 'carga', '41001', 'Sevilla');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e1, 2, 'descarga', '46001', 'Valencia');
  update envios set estado = 'programado' where id = e1;
  o := ofertar_envio(e1, t, 'email', 560, 10::smallint);
  r := reservar_envio_publico((select token from envio_ofertas where id = o));
  res1 := (r->>'reserva_id')::uuid;
  r := aceptar_reserva(res1, t, null, 560);
  if r->>'resultado' <> 'aceptada' then raise exception 'FALLO 224 · la aceptacion directa no sale: %', r; end if;
  select cuerpo_html into v_cuerpo from emails_enviados
   where clave = 'envio_aceptado:' || res1 and tipo = 'envio_aceptado' and envio_id = e1 and destinatario = email_dynamo();
  if v_cuerpo is null then raise exception 'FALLO 224 · aceptar no deja el email envio_aceptado a Dynamo'; end if;
  if v_cuerpo not like '%/panel/envios?ver=%' or v_cuerpo not like '%Sevilla%' or v_cuerpo not like '%Valencia%' then
    raise exception 'FALLO 224 · al email de aceptado le faltan el enlace o la ruta: %', v_cuerpo;
  end if;
  if (select asunto from emails_enviados where clave = 'envio_aceptado:' || res1) not like '%aceptado%' then
    raise exception 'FALLO 224 · el asunto del email de aceptado no dice aceptado';
  end if;

  -- (b) alta online sin verificar → pendiente_revision deja el email con el enlace.
  insert into transportistas (razon_social, cif, estado_operativo, tags)
    values ('Alta Online 224 SL', 'B22400224', 'no_ofertar', array['alta_online']) returning id into t_alta;
  insert into contactos (transportista_id, nombre, funcion, telefono, email, es_principal)
    values (t_alta, 'Nuria Prueba', 'trafico', '+34600224224', 'nuria224@prueba.invalid', true);
  insert into envios (cliente_id, metros_lineales, importe_cliente, importe_transportista)
    values (c, 6, 700, 560) returning id into e2;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e2, 1, 'carga', '19001', 'Guadalajara');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e2, 2, 'descarga', '16001', 'Cuenca');
  update envios set estado = 'programado' where id = e2;
  insert into envio_reservas (envio_id, hasta) values (e2, now() + interval '30 min') returning id into res2;
  update envio_reservas set estado = 'pendiente_revision', transportista_id = t_alta, precio_propuesto = 560 where id = res2;
  select cuerpo_html into v_cuerpo from emails_enviados
   where clave = 'alta_pendiente:' || res2 and tipo = 'alta_pendiente' and envio_id = e2 and destinatario = email_dynamo();
  if v_cuerpo is null then raise exception 'FALLO 224 · el alta online pendiente no deja el email alta_pendiente'; end if;
  if v_cuerpo not like '%Revisar y aceptar%' or v_cuerpo not like '%B22400224%'
     or v_cuerpo not like '%/panel/envios?ver=%' or v_cuerpo not like '%nuria224@prueba.invalid%' then
    raise exception 'FALLO 224 · al email del alta le faltan el enlace, el CIF o el contacto: %', v_cuerpo;
  end if;
  if (select asunto from emails_enviados where clave = 'alta_pendiente:' || res2) not like 'PENDIENTE%' then
    raise exception 'FALLO 224 · el asunto del alta pendiente no empieza por PENDIENTE';
  end if;
  -- (b2) Dynamo aprueba el alta → el envío queda asignado y llega TAMBIÉN el email de
  -- «envío aceptado» (en ese instante el transportista ya es conocido).
  r := resolver_contraoferta(res2, true);
  if r->>'resultado' <> 'aceptada' or (select transportista_id from envios where id = e2) <> t_alta then
    raise exception 'FALLO 224 · aprobar el alta no asigna el envio: %', r;
  end if;
  select cuerpo_html into v_cuerpo from emails_enviados
   where clave = 'envio_aceptado:' || res2 and tipo = 'envio_aceptado' and envio_id = e2 and destinatario = email_dynamo();
  if v_cuerpo is null then raise exception 'FALLO 224 · aprobar el alta no deja el email envio_aceptado'; end if;
  if v_cuerpo not like '%aprobación en la revisión%' or v_cuerpo not like '%Alta Online 224 SL%' then
    raise exception 'FALLO 224 · al email de aceptado tras aprobar le falta la línea de aprobación o el transportista: %', v_cuerpo;
  end if;

  -- (c) contraoferta de un conocido (ya verificado): campana sí, email de alta NO.
  insert into envios (cliente_id, metros_lineales, importe_cliente, importe_transportista)
    values (c, 6, 700, 500) returning id into e3;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e3, 1, 'carga', '41001', 'Sevilla');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion) values (e3, 2, 'descarga', '46001', 'Valencia');
  update envios set estado = 'programado' where id = e3;
  o := ofertar_envio(e3, t, 'email', 500, 30::smallint);
  r := reservar_envio_publico((select token from envio_ofertas where id = o));
  res3 := (r->>'reserva_id')::uuid;
  r := aceptar_reserva(res3, t, null, 620);
  if r->>'resultado' <> 'pendiente_revision' then raise exception 'FALLO 224 · la contraoferta del conocido no queda pendiente: %', r; end if;
  if exists (select 1 from emails_enviados where clave = 'alta_pendiente:' || res3) then
    raise exception 'FALLO 224 · la contraoferta de un conocido no debe mandar el email de alta pendiente';
  end if;
  raise notice 'OK 224 · emails a Dynamo: aceptado con enlace y ruta, alta online con CIF y contacto, y la contraoferta de un conocido sin email de alta';
end $$;

-- ---- 225. Avisos a sitios en DÍAS HÁBILES: la víspera de un lunes es el viernes -------
-- La cuenta pura de tramos (tramo_aviso_parada) con fechas fijas de calendario:
-- fin de semana, festivo nacional en medio (Inmaculada, 8-dic-2026, martes) y el
-- mismo día, que sale siempre. Fechas verificadas: 19/20/21-nov-2026 = jue/vie/sáb,
-- 23-nov lunes; 4-dic viernes, 7-dic lunes, 9-dic miércoles.
do $$ begin
  if tramo_aviso_parada(date '2026-11-20', date '2026-11-23') is distinct from 'd1' then
    raise exception 'FALLO 225 · la víspera de un lunes debía ser el viernes (d1)';
  end if;
  if tramo_aviso_parada(date '2026-11-19', date '2026-11-23') is distinct from 'd2' then
    raise exception 'FALLO 225 · dos días hábiles antes de un lunes debía ser el jueves (d2)';
  end if;
  if tramo_aviso_parada(date '2026-11-21', date '2026-11-23') is not null
     or tramo_aviso_parada(date '2026-11-22', date '2026-11-23') is not null then
    raise exception 'FALLO 225 · en sábado o domingo no debía salir ningún aviso anticipado';
  end if;
  if tramo_aviso_parada(date '2026-12-07', date '2026-12-09') is distinct from 'd1' then
    raise exception 'FALLO 225 · con la Inmaculada (8-dic) en medio, la víspera hábil del miércoles debía ser el lunes (d1)';
  end if;
  if tramo_aviso_parada(date '2026-12-04', date '2026-12-09') is distinct from 'd2' then
    raise exception 'FALLO 225 · con el festivo en medio, el viernes debía ser dos días hábiles antes (d2)';
  end if;
  if tramo_aviso_parada(date '2026-12-08', date '2026-12-09') is not null then
    raise exception 'FALLO 225 · en festivo nacional no debía salir ningún aviso anticipado';
  end if;
  if tramo_aviso_parada(date '2026-12-08', date '2026-12-08') is distinct from 'd0'
     or tramo_aviso_parada(date '2026-11-22', date '2026-11-22') is distinct from 'd0' then
    raise exception 'FALLO 225 · el aviso del MISMO día debía salir aunque sea festivo o domingo (d0)';
  end if;
  if tramo_aviso_parada(date '2026-11-17', date '2026-11-23') is not null then
    raise exception 'FALLO 225 · a tres días hábiles vista no toca ningún tramo todavía';
  end if;
  raise notice 'OK 225 · avisos a sitios en días hábiles: víspera de lunes = viernes, festivos saltados, nada en finde/festivo y el mismo día siempre';
end $$;

-- ---- 226. Festivos autonómicos y locales en los avisos a sitios -----------------------
-- La tabla provincia→comunidad está completa y los festivos con comunidad (y población)
-- solo cuentan para los sitios a los que les tocan. Fechas fijas de 2027: 1-mar lunes,
-- 2-mar martes, 3-mar miércoles, 9-mar martes, 10-mar miércoles.
do $$ declare n int; begin
  select count(*) into n from provincias_comunidades where pais_codigo_iso = 'ES';
  if n <> 52 then raise exception 'FALLO 226 · la tabla provincia-comunidad debe tener 52 filas y tiene %', n; end if;
  select count(distinct comunidad_iso) into n from provincias_comunidades;
  if n <> 19 then raise exception 'FALLO 226 · deben salir 19 comunidades y ciudades autónomas y salen %', n; end if;
  if comunidad_de('ES', '41703') is distinct from 'ES-AN'
     or comunidad_de('ES', '08040') is distinct from 'ES-CT'
     or comunidad_de('ES', '28001') is distinct from 'ES-MD'
     or comunidad_de('PT', '1000-100') is not null then
    raise exception 'FALLO 226 · comunidad_de no resuelve bien el CP';
  end if;

  -- Festivo AUTONÓMICO de prueba en Andalucía el martes 2-mar-2027.
  insert into festivos (fecha, nombre, region, repetir) values (date '2027-03-02', 'Festivo autonómico de prueba 226', 'ES-AN', 'no');
  -- Para un sitio de Sevilla (CP 41) la víspera hábil del miércoles 3 es el LUNES 1…
  if tramo_aviso_parada(date '2027-03-01', date '2027-03-03', 'ES', '41001', 'Sevilla') is distinct from 'd1' then
    raise exception 'FALLO 226 · con el festivo andaluz en medio, la víspera del sitio sevillano debía ser el lunes';
  end if;
  -- …y el martes festivo no le sale ningún aviso; a un sitio valenciano, sí (es su víspera).
  if tramo_aviso_parada(date '2027-03-02', date '2027-03-03', 'ES', '41001', 'Sevilla') is not null then
    raise exception 'FALLO 226 · el sitio andaluz recibe aviso en su festivo autonómico';
  end if;
  if tramo_aviso_parada(date '2027-03-02', date '2027-03-03', 'ES', '46001', 'Valencia') is distinct from 'd1' then
    raise exception 'FALLO 226 · el festivo andaluz no debía afectar a un sitio valenciano';
  end if;
  -- Sin CP (no se sabe el sitio) solo cuentan los nacionales: el martes es hábil.
  if tramo_aviso_parada(date '2027-03-02', date '2027-03-03', 'ES') is distinct from 'd1' then
    raise exception 'FALLO 226 · sin CP deberían contar solo los festivos nacionales';
  end if;

  -- Festivo LOCAL de prueba en Sevilla capital el martes 9-mar-2027.
  insert into festivos (fecha, nombre, region, poblacion, repetir) values (date '2027-03-09', 'Fiesta local de prueba 226', 'ES-AN', 'Sevilla', 'no');
  if tramo_aviso_parada(date '2027-03-09', date '2027-03-10', 'ES', '41001', 'Sevilla') is not null then
    raise exception 'FALLO 226 · el sitio de Sevilla capital recibe aviso en su fiesta local';
  end if;
  if tramo_aviso_parada(date '2027-03-09', date '2027-03-10', 'ES', '41703', 'Dos Hermanas') is distinct from 'd1' then
    raise exception 'FALLO 226 · la fiesta local de Sevilla no debía afectar a Dos Hermanas';
  end if;

  delete from festivos where nombre in ('Festivo autonómico de prueba 226', 'Fiesta local de prueba 226');
  raise notice 'OK 226 · provincia→comunidad completa (52/19) y los festivos autonómicos y locales solo afectan a los avisos de sus sitios';
end $$;

-- ---- 227. Festivos nacionales europeos sembrados y perpetuos --------------------------
-- Los 11 países de servicio con sus fijos (cada año) y sus móviles de Pascua.
-- Fechas verificadas: 14-jul-2026 martes · 11-nov-2026 miércoles · Pascua 2027 = 28-mar
-- (lunes de Pascua 29-mar, lunes).
do $$ declare n int; begin
  select count(*) into n from festivos where pais_codigo_iso <> 'ES' and region is null and poblacion is null;
  if n <> 120 then raise exception 'FALLO 227 · esperaba 120 festivos europeos sembrados y hay %', n; end if;
  if (select count(*) from festivos where pais_codigo_iso = 'DE') <> 9
     or (select count(*) from festivos where pais_codigo_iso = 'PL') <> 13
     or (select count(*) from festivos where pais_codigo_iso = 'CZ') <> 13 then
    raise exception 'FALLO 227 · el reparto por país no cuadra (DE %, PL %, CZ %)',
      (select count(*) from festivos where pais_codigo_iso = 'DE'),
      (select count(*) from festivos where pais_codigo_iso = 'PL'),
      (select count(*) from festivos where pais_codigo_iso = 'CZ');
  end if;
  -- Fijo: el 14 de julio (martes) es festivo en Francia y laborable en España.
  if es_dia_habil(date '2026-07-14', 'FR') or not es_dia_habil(date '2026-07-14', 'ES') then
    raise exception 'FALLO 227 · el 14 de julio debía parar Francia y no España';
  end if;
  -- Fijo compartido: el 11 de noviembre (miércoles) para a Francia, Bélgica y Polonia.
  if es_dia_habil(date '2026-11-11', 'FR') or es_dia_habil(date '2026-11-11', 'BE')
     or es_dia_habil(date '2026-11-11', 'PL') or not es_dia_habil(date '2026-11-11', 'ES') then
    raise exception 'FALLO 227 · el 11 de noviembre debía parar FR/BE/PL y no España';
  end if;
  -- Móvil de Pascua PERPETUO: el lunes de Pascua de 2027 (29-mar) para a DE/FR/PL/IT
  -- y no a España (que no lo tiene). Se calcula solo: no hay ninguna fila con esa fecha.
  if es_dia_habil(date '2027-03-29', 'DE') or es_dia_habil(date '2027-03-29', 'FR')
     or es_dia_habil(date '2027-03-29', 'PL') or es_dia_habil(date '2027-03-29', 'IT')
     or not es_dia_habil(date '2027-03-29', 'ES') then
    raise exception 'FALLO 227 · el lunes de Pascua 2027 debía parar DE/FR/PL/IT y no España';
  end if;
  -- Y el aviso a un sitio alemán lo respeta: carga el martes 30-mar-2027. Para el sitio
  -- DE el viernes 26 es Viernes Santo y el lunes 29 lunes de Pascua, así que su víspera
  -- hábil es el JUEVES 25; la de un sitio español es el lunes 29 (en España es laborable).
  if tramo_aviso_parada(date '2027-03-25', date '2027-03-30', 'DE') is distinct from 'd1'
     or tramo_aviso_parada(date '2027-03-26', date '2027-03-30', 'DE') is not null
     or tramo_aviso_parada(date '2027-03-29', date '2027-03-30', 'DE') is not null
     or tramo_aviso_parada(date '2027-03-29', date '2027-03-30', 'ES') is distinct from 'd1' then
    raise exception 'FALLO 227 · la víspera del sitio alemán no salta la Semana Santa alemana';
  end if;
  raise notice 'OK 227 · festivos europeos: 120 sembrados (11 países), fijos perpetuos y Pascua recalculándose sola, y los avisos del sitio extranjero los respetan';
end $$;

-- ---- 228. Proforma vinculada al envío pagado, en el concepto del pedido de venta ------
-- Pagado por transferencia: el concepto del porte lleva «PROFORMA PRO-GX… · PAGADA VÍA
-- TRANSFERENCIA · FECHA · IMPORTE» (el total con IVA que se cobró). Sin pagar: «porte» a
-- secas. Y un cliente no lee la proforma de otro.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
update parametros set valor = 'true' where clave = 'pago_previo_activo';
do $$ declare c uuid; e1 uuid; e2 uuid; v_con text; v_gx text; v_tot numeric; begin
  insert into clientes (razon_social, cif) values ('Cliente Proforma 228 SL', 'B22800228') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista)
    values (c, 13.30, 20, 500, 400) returning id into e1;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e1, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e1, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e1;
  if (select estado_pago_previo from envios where id = e1) <> 'pendiente' then
    raise exception 'FALLO 228 · el primer envío de un cliente sin crédito debía pedir pago previo';
  end if;
  -- Los pedidos (venta y compra a la vez) nacen al tener transportista (2026-11-20).
  alter table envios disable trigger user;
  update envios set transportista_id = current_setting('prueba.transp')::uuid where id = e1;
  alter table envios enable trigger user;
  -- Sin pagar todavía: el concepto es el porte a secas.
  select "Concepto" into v_con from v_holded_pedido_venta
   where "Num Pedido (referencia_gx_carga)" = (select referencia_gx from envios where id = e1);
  if v_con is distinct from 'porte' then raise exception 'FALLO 228 · sin pagar el concepto debía ser «porte» y es %', v_con; end if;

  -- Pagado por transferencia el 10/11/2026 a media mañana (hora de Madrid).
  perform set_config('request.jwt.claim.role', 'service_role', true);
  update envios set estado_pago_previo = 'pagado', pago_metodo = 'transferencia',
                    pagado_en = timestamptz '2026-11-10 10:30:00+01' where id = e1;
  perform set_config('request.jwt.claim.role', '', true);
  select referencia_gx into v_gx from envios where id = e1;
  select total into v_tot from pago_envio_importes(e1);
  select "Concepto" into v_con from v_holded_pedido_venta where "Num Pedido (referencia_gx_carga)" = v_gx;
  if v_con is distinct from 'porte · PROFORMA PRO-' || v_gx || ' · PAGADA VÍA TRANSFERENCIA · FECHA 10/11/2026 · IMPORTE ' || euros_texto(v_tot) then
    raise exception 'FALLO 228 · el concepto del pedido pagado no lleva la proforma bien: %', v_con;
  end if;

  -- Pagado con tarjeta: lo dice el método.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista)
    values (c, 13.30, 20, 500, 400) returning id into e2;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e2, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e2, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e2;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  update envios set estado_pago_previo = 'pagado', pago_metodo = 'stripe', pagado_en = now() where id = e2;
  perform set_config('request.jwt.claim.role', '', true);
  if proforma_pagada_texto(e2) not like 'PROFORMA PRO-% · PAGADA VÍA STRIPE (TARJETA) · FECHA % · IMPORTE %' then
    raise exception 'FALLO 228 · el pago con tarjeta no sale como STRIPE (TARJETA): %', proforma_pagada_texto(e2);
  end if;
  perform set_config('prueba.e228', e1::text, false);
end $$;
update parametros set valor = 'false' where clave = 'pago_previo_activo';
-- Un cliente (otra empresa) no lee la proforma de este envío.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  if proforma_pagada_texto(current_setting('prueba.e228')::uuid) is not null then
    raise exception 'FALLO 228 · un cliente lee la proforma pagada de otra empresa';
  end if;
  raise notice 'OK 228 · proforma vinculada: el concepto del pedido de venta lleva la proforma pagada (transferencia o tarjeta, fecha e importe), sin pagar va «porte» y otro cliente no la ve';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 229. Panel del DeCA: lo que se asigna DESPUÉS de emitirse sale con fecha y hora ---
-- Sin matrículas no hay emisión ni panel. El transportista asignado antes no sale; la 1.ª
-- asignación de matrículas ES la emisión («primera») y el cambio posterior sale como
-- cambio. Cada paso en su propia transacción.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t uuid; begin
  insert into transportistas (razon_social, cif, nima) values ('Transp 229 SL', 'B22900229', 'NIMA-229') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3)
    returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('prueba.e229', e::text, false);
  perform set_config('prueba.t229', t::text, false);
end $$;
update envios set transportista_id = current_setting('prueba.t229')::uuid where id = current_setting('prueba.e229')::uuid;
do $$ begin
  if jsonb_array_length(fn_modificaciones_deca(current_setting('prueba.e229')::uuid)) <> 0 then
    raise exception 'FALLO 229 · sin matrículas (sin emitir) el panel no va vacío: %', fn_modificaciones_deca(current_setting('prueba.e229')::uuid);
  end if;
end $$;
update envios set matricula_camion = '1234GDF', matricula_remolque = 'R2143ERA' where id = current_setting('prueba.e229')::uuid;
update envios set matricula_camion = '5555KKK' where id = current_setting('prueba.e229')::uuid;
do $$ declare m jsonb := fn_modificaciones_deca(current_setting('prueba.e229')::uuid); begin
  if jsonb_array_length(m) <> 2 then raise exception 'FALLO 229 · esperaba 2 entradas (emisión y cambio) y hay %: %', jsonb_array_length(m), m; end if;
  if m -> 0 ->> 'hito' <> 'matricula_asignada' or (m -> 0 ->> 'primera')::boolean is not true or m -> 0 ->> 'detalle' <> '1234GDF / R2143ERA' then
    raise exception 'FALLO 229 · la 1.ª asignación de matrículas (la emisión) no abre el panel: %', m -> 0;
  end if;
  if m -> 1 ->> 'hito' <> 'matricula_asignada' or (m -> 1 ->> 'primera')::boolean is not false or m -> 1 ->> 'detalle' <> '5555KKK / R2143ERA' then
    raise exception 'FALLO 229 · el cambio posterior de matrículas no sale como cambio: %', m -> 1;
  end if;
  raise notice 'OK 229 · panel del DeCA: sin matrículas va vacío; se emite con las 1.as matrículas (el transportista de antes no sale) y el cambio posterior sale como cambio';
end $$;

-- ---- 232. DeCA (apdo. quinto.1): dato anterior «no válido», motivo y fecha/mercancía ----
-- Sobre el envío de la 229: el cambio de matrículas lleva las ANTERIORES; los cambios de
-- mercancía y de fecha hechos tras la emisión quedan en el panel con antes y después; el
-- motivo anotado justo después se pega al ÚLTIMO cambio (no a uno anterior). Solo Dynamo
-- anota motivos.
update envios set toneladas = 18 where id = current_setting('prueba.e229')::uuid;
update envios set fecha_carga_desde = fecha_carga_desde + 1, fecha_carga_hasta = coalesce(fecha_carga_hasta, fecha_carga_desde) + 1
 where id = current_setting('prueba.e229')::uuid;
insert into deca_motivos (envio_id, motivo) values (current_setting('prueba.e229')::uuid, 'El cargador retrasa la mercancía');
do $$ declare m jsonb := fn_modificaciones_deca(current_setting('prueba.e229')::uuid); x jsonb; f jsonb; begin
  if m -> 1 ->> 'antes' is distinct from '1234GDF / R2143ERA' then
    raise exception 'FALLO 232 · el cambio de matrículas no lleva las anteriores: %', m -> 1;
  end if;
  if m -> 0 ->> 'antes' is not null then raise exception 'FALLO 232 · la primera asignación no tiene dato anterior: %', m -> 0; end if;
  select e into x from jsonb_array_elements(m) e where e ->> 'hito' = 'mercancia_cambiada';
  if x is null or x ->> 'antes' <> '20 Tn · 13,3 m' or x ->> 'detalle' <> '18 Tn · 13,3 m' or x ->> 'motivo' is not null then
    raise exception 'FALLO 232 · el cambio de mercancía no sale con antes/después (o se le pega un motivo ajeno): %', x;
  end if;
  select e into f from jsonb_array_elements(m) e where e ->> 'hito' = 'fecha_carga_cambiada';
  if f is null or f ->> 'antes' is null or f ->> 'detalle' is null or f ->> 'motivo' is distinct from 'El cargador retrasa la mercancía' then
    raise exception 'FALLO 232 · el cambio de fecha no sale con antes/después y su motivo: %', f;
  end if;
  if (select count(*) from jsonb_array_elements(m) e where e ->> 'en' is null) > 0 then raise exception 'FALLO 232 · falta la fecha ISO de algún cambio'; end if;
end $$;
-- Antes de emitirse no se apunta nada de fecha ni mercancía (es el documento original).
do $$ declare e uuid; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 4) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set toneladas = 12 where id = e;
  if exists (select 1 from envio_hitos where envio_id = e and hito in ('mercancia_cambiada', 'fecha_carga_cambiada')) then
    raise exception 'FALLO 232 · apunta cambios de un envío sin DeCA emitido';
  end if;
  perform set_config('prueba.e232', e::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform anotar_motivo_deca(current_setting('prueba.e229')::uuid, 'Motivo del cliente'); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 232 · un cliente anota motivos del DeCA'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ begin
  if not anotar_motivo_deca(current_setting('prueba.e229')::uuid, 'Avería de la tractora') then raise exception 'FALLO 232 · Dynamo no puede anotar el motivo'; end if;
  if anotar_motivo_deca(current_setting('prueba.e229')::uuid, '  ') then raise exception 'FALLO 232 · anota un motivo vacío'; end if;
  raise notice 'OK 232 · DeCA (apdo. quinto.1): cada cambio con el dato anterior (no válido) y su motivo; fecha y mercancía tras la emisión quedan; antes de emitir, no; solo Dynamo anota motivos';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 233. El CMR digital a cada sitio: el mismo día a las 7:00 y 1 h antes ---------------
-- Martes fijo con hora fijada (p_ahora): a las 7:05 sale el del mismo día con el enlace
-- de la hoja de firmas; 50 min antes de la hora prevista de la recogida, el «h1» con el
-- enlace y la hora; firmada la casilla del sitio, otro envío igual ya no recibe el h1.
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid; dia date := date '2027-03-02';
        s1 uuid; s2 uuid; e uuid; pc uuid; tr uuid; v_hora timestamptz; ini int; fin int; hmd int; c text;
begin
  select valor::int into ini from parametros where clave = 'aviso_parada_ventana_inicio';
  select valor::int into fin from parametros where clave = 'aviso_parada_ventana_fin';
  select valor::int into hmd from parametros where clave = 'aviso_parada_hora_mismo_dia';
  update parametros set valor = '7' where clave = 'aviso_parada_hora_mismo_dia';
  insert into transportistas (razon_social, cif) values ('Transp Avisos 233 SL', 'B23300001') returning id into tr;
  insert into sitios (nombre_empresa, cliente_id, emails_avisos) values ('Almacen Carga 233', cli, array['carga233@prueba.invalid']) returning id into s1;
  insert into sitios (nombre_empresa, cliente_id, emails_avisos) values ('Almacen Entrega 233', cli, array['entrega233@prueba.invalid']) returning id into s2;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde)
    values (cli, 13.30, 20, 900, dia) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES', s1, 'Almacen Carga 233') returning id into pc;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, sitio_id, nombre_empresa)
    values (e, 2, 'descarga', '28001', 'Madrid', 'ES', s2, 'Almacen Entrega 233');
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado', fecha_entrega_estimada = dia + 1, transportista_id = tr,
                    importe_transportista = 700, fecha_carga_prevista = dia, matricula_camion = '2330ABC' where id = e;
  select x.hora into v_hora from seguimiento_calcular(e) x where x.parada_id = pc and x.estado = 'cargando';
  if v_hora is null then raise exception 'FALLO 233 · sin hora prevista para la recogida'; end if;
  if v_hora - interval '60 minutes' <= (dia + time '07:00') at time zone 'Europe/Madrid' then
    raise exception 'FALLO 233 · la recogida prevista (%) es demasiado temprana para probar el aviso de 1 h antes', v_hora;
  end if;
  -- 6:50: aún nada del mismo día.
  perform encolar_avisos_paradas(dia, (dia + time '06:50') at time zone 'Europe/Madrid');
  if exists (select 1 from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':d0:' || dia) then
    raise exception 'FALLO 233 · el del mismo día sale antes de las 7:00';
  end if;
  -- 7:05: el del mismo día, con el enlace de la hoja de firmas; todavía no el de 1 h antes.
  perform encolar_avisos_paradas(dia, (dia + time '07:05') at time zone 'Europe/Madrid');
  select cuerpo_html into c from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':d0:' || dia and estado = 'pendiente';
  if c is null or c not like '%/cmr/%' or c not like '%CMR digital%' then
    raise exception 'FALLO 233 · el aviso de las 7:00 no lleva el enlace del CMR: %', left(coalesce(c, '(no hay)'), 200);
  end if;
  if exists (select 1 from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':h1:' || dia) then
    raise exception 'FALLO 233 · el de 1 h antes sale a primera hora';
  end if;
  -- 50 min antes de la hora prevista: el h1, con el enlace y la hora.
  perform encolar_avisos_paradas(dia, v_hora - interval '50 minutes');
  select cuerpo_html into c from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':h1:' || dia;
  if c is null or c not like '%/cmr/%' or c not like '%hacia las ' || to_char(v_hora at time zone 'Europe/Madrid', 'HH24:MI') || '%' then
    raise exception 'FALLO 233 · no sale el aviso de 1 h antes con enlace y hora: %', left(coalesce(c, '(no hay)'), 200);
  end if;
  -- Con la casilla del sitio ya firmada, no hay aviso de 1 h antes (se borra para repetir).
  delete from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':h1:' || dia;
  insert into firmas_cmr (envio_id, parada_id, rol, nombre, documento, documento_pais, firmado_en, firma_storage_ruta)
    values (e, pc, 'remitente', 'Firmante 233', '12345678Z', 'ES', now(), 'cmr/prueba233/x.png');
  perform encolar_avisos_paradas(dia, v_hora - interval '50 minutes');
  if exists (select 1 from emails_enviados where clave = 'aviso_parada:' || e || ':' || pc || ':h1:' || dia) then
    raise exception 'FALLO 233 · manda el aviso de 1 h antes con la casilla ya firmada';
  end if;
  update parametros set valor = to_jsonb(hmd) where clave = 'aviso_parada_hora_mismo_dia';
  raise notice 'OK 233 · CMR digital a cada sitio: el mismo día desde las 7:00 y 1 h antes de su hora prevista, con el enlace; no con la casilla firmada';
end $$;

-- ---- 234. Semirremolque obligatorio en tráiler y motivo según el momento ----------------
-- Tráiler (no pide plataforma): la cabecera no puede poner solo la tractora (falta_remolque)
-- salvo que declare «rígido»; con tractora sola puesta por otra vía, nadie firma
-- (sin_matriculas) hasta que esté el semirremolque. El panel del DeCA marca 'iniciado' en
-- lo que se cambia con el camión ya cargando.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; e2 uuid; t uuid; begin
  insert into transportistas (razon_social, cif) values ('Transp 234 SL', 'B23400234') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e2;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES'),
           (e2, 1, 'carga', '41001', 'Sevilla', 'ES'), (e2, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado', transportista_id = t where id in (e, e2);
  perform set_config('prueba.e234', e::text, false);
  perform set_config('prueba.e234b', e2::text, false);
end $$;
do $$ declare e uuid := current_setting('prueba.e234')::uuid; e2 uuid := current_setting('prueba.e234b')::uuid; tok uuid; tok2 uuid; r jsonb; d uuid; begin
  select token into tok from cmr_enlaces where envio_id = e and not revocado;
  select token into tok2 from cmr_enlaces where envio_id = e2 and not revocado;
  if not envio_necesita_remolque(e) then raise exception 'FALLO 234 · un tráiler no pide semirremolque'; end if;
  -- (a) Cabecera con solo la tractora: rechazada y sin guardar nada.
  r := firmar_cmr_publico(tok, null, 'transportista', 'Pepe', 'X1234567L', 'ES', true, null, 'cmr/' || tok || '/a.png', null, null, null,
                          p_matricula_camion => '2340AAA');
  if r ->> 'resultado' <> 'falta_remolque' then raise exception 'FALLO 234 · la cabecera pone la tractora sin semirremolque: %', r; end if;
  if (select matricula_camion from envios where id = e) is not null then raise exception 'FALLO 234 · guarda la tractora aunque rechaza'; end if;
  -- (b) Declarando «rígido» pasa (se queda en el trazo, que aquí no existe) y ya no lo pide.
  r := firmar_cmr_publico(tok, null, 'transportista', 'Pepe', 'X1234567L', 'ES', true, null, 'cmr/' || tok || '/a.png', null, null, null,
                          p_matricula_camion => '2340AAA', p_camion_rigido => true);
  if r ->> 'resultado' <> 'falta_trazo' then raise exception 'FALLO 234 · el rígido declarado no pasa el control de matrículas: %', r; end if;
  if envio_necesita_remolque(e) or (select v.tipo from vehiculos v join envios x on x.vehiculo_camion_id = v.id where x.id = e) <> 'rigido' then
    raise exception 'FALLO 234 · el camión declarado rígido no queda como rígido';
  end if;
  -- (c) Tractora sola puesta por otra vía en un tráiler: nadie firma hasta el semirremolque.
  update envios set matricula_camion = '2340BBB' where id = e2;
  select id into d from envio_paradas where envio_id = e2 and tipo = 'descarga';
  r := firmar_cmr_publico(tok2, d, 'destinatario', 'Rosa', '12345678Z', 'ES', true, null, 'cmr/' || tok2 || '/b.png', null, null, null);
  if r ->> 'resultado' <> 'sin_matriculas' then raise exception 'FALLO 234 · se firma un tráiler sin semirremolque: %', r; end if;
  if (cmr_publico(tok2) ->> 'necesita_remolque')::boolean is not true then raise exception 'FALLO 234 · la página de firma no sabe que falta el semirremolque'; end if;
  if (orden_carga_json(e2) -> 'envio' ->> 'necesita_remolque')::boolean is not true then raise exception 'FALLO 234 · el PDF no sabe que falta el semirremolque'; end if;
end $$;
update envios set estado = 'hacia_la_carga' where id = current_setting('prueba.e234b')::uuid;
update envios set estado = 'cargando', parada_actual = 1 where id = current_setting('prueba.e234b')::uuid;
update envios set matricula_remolque = 'R2340BBB' where id = current_setting('prueba.e234b')::uuid;
do $$ declare e2 uuid := current_setting('prueba.e234b')::uuid; tok2 uuid; r jsonb; d uuid; m jsonb; x jsonb; begin
  select token into tok2 from cmr_enlaces where envio_id = e2 and not revocado;
  select id into d from envio_paradas where envio_id = e2 and tipo = 'descarga';
  r := firmar_cmr_publico(tok2, d, 'destinatario', 'Rosa', '12345678Z', 'ES', true, null, 'cmr/' || tok2 || '/b.png', null, null, null);
  if r ->> 'resultado' <> 'falta_trazo' then raise exception 'FALLO 234 · con las dos matrículas sigue sin dejar firmar: %', r; end if;
  -- (d) 'iniciado' lo dicen las FIRMAS, no el seguimiento: el semirremolque se puso con el
  -- envío ya «cargando» pero sin ninguna firma → no es iniciado.
  m := fn_modificaciones_deca(e2);
  select y into x from jsonb_array_elements(m) y where y ->> 'detalle' = '2340BBB / R2340BBB';
  if x is null or (x ->> 'iniciado')::boolean is not false or x ->> 'antes' <> '2340BBB' then
    raise exception 'FALLO 234 · un cambio sin firmas previas sale como iniciado (el seguimiento no cuenta): %', m;
  end if;
  insert into firmas_cmr (envio_id, parada_id, rol, nombre, documento, documento_pais, firma_storage_ruta)
    values (e2, (select id from envio_paradas where envio_id = e2 and tipo = 'carga'), 'remitente', 'Carga 234', '12345678Z', 'ES', 'cmr/prueba234/x.png');
end $$;
update envios set matricula_camion = '2340CCC' where id = current_setting('prueba.e234b')::uuid;
do $$ declare m jsonb := fn_modificaciones_deca(current_setting('prueba.e234b')::uuid); x jsonb; begin
  select y into x from jsonb_array_elements(m) y where y ->> 'detalle' = '2340CCC / R2340BBB';
  if x is null or (x ->> 'iniciado')::boolean is not true then
    raise exception 'FALLO 234 · el cambio hecho después de una firma no sale como iniciado: %', m;
  end if;
  select y into x from jsonb_array_elements(m) y where y ->> 'detalle' = '2340BBB / R2340BBB';
  if (x ->> 'iniciado')::boolean is not false then raise exception 'FALLO 234 · la firma posterior marca como iniciado un cambio anterior: %', m; end if;
  raise notice 'OK 234 · tráiler = dos matrículas: la cabecera no pone solo la tractora (salvo rígido declarado), nadie firma sin semirremolque, la página y el PDF lo saben; el panel marca «iniciado» solo lo cambiado después de una firma (el seguimiento no cuenta)';
end $$;

-- ---- 235. Faltan matrículas a la hora de cargar: se AVISA, no se bloquea ------------------
-- (El bloqueo de 20261115350000 se deshizo el mismo día por decisión del usuario.) Envío
-- con transportista y sin matrículas, ya pasada su hora: el automático AVANZA igual y deja
-- UN aviso urgente a Dynamo; a mano también se puede marcar «cargando».
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; e2 uuid; t uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; n int; begin
  insert into transportistas (razon_social, cif) values ('Transp 235 SL', 'B23500235') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, hoy + 2) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, hoy + 2) returning id into e2;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES'),
           (e2, 1, 'carga', '41001', 'Sevilla', 'ES'), (e2, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado', transportista_id = t where id in (e, e2);
  -- Como si hubiera tenido que cargar hace 3 días: toda su ruta prevista ya ha pasado.
  update envios set fecha_carga_desde = hoy - 3, fecha_carga_hasta = hoy - 3, fecha_carga_prevista = hoy - 3 where id = e;
  perform set_config('prueba.e235b', e2::text, false);
  perform seguimiento_aplicar(e, false);
  perform seguimiento_aplicar(e, false);
  if (select estado from envios where id = e) in ('programado', 'hacia_la_carga') then
    raise exception 'FALLO 235 · sin matrículas el automático se queda parado (ya no debe bloquear): %', (select estado from envios where id = e);
  end if;
  select count(*) into n from avisos where envio_id = e and tipo = 'sin_matriculas_al_cargar';
  if n <> 1 then raise exception 'FALLO 235 · esperaba 1 aviso a Dynamo y hay %', n; end if;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r jsonb; begin
  r := marcar_etapa_envio(current_setting('prueba.e235b')::uuid, 2::smallint);
  if not (r ->> 'ok')::boolean then raise exception 'FALLO 235 · a mano no deja marcar «cargando» sin matrículas (ya no debe bloquear): %', r; end if;
  raise notice 'OK 235 · faltan matrículas a la hora de cargar: el seguimiento avanza igual (por reloj y a mano) y Dynamo recibe un aviso urgente, una sola vez';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 236. Tres avisos de matrículas al transportista: víspera hábil, antes y a la hora -----
-- Carga el martes 02/03/2027, con transportista y sin matrículas. Lunes 15:50 → nada; lunes
-- 16:05 → víspera (una vez); 100 min antes de su hora → «antes»; a su hora → «URGENTE».
-- Asignado a última hora (el «antes» salió a 20 min de la hora) → sin urgente. Con las
-- matrículas completas, ninguno.
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid; dia date := date '2027-03-02'; lunes date := date '2027-03-01';
        e uuid; e2 uuid; e3 uuid; tr uuid; v_hora timestamptz; n int; x record;
begin
  insert into transportistas (razon_social, cif) values ('Transp Matrículas 236 SL', 'B23600236') returning id into tr;
  insert into contactos (transportista_id, nombre, email, es_principal) values (tr, 'Tráfico 236', 'trafico236@prueba.invalid', true);
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde) values (cli, 13.30, 20, 900, 700, dia) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde) values (cli, 13.30, 20, 900, 700, dia) returning id into e2;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde) values (cli, 13.30, 20, 900, 700, dia) returning id into e3;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select y, 1, 'carga', '41001', 'Sevilla', 'ES' from unnest(array[e, e2, e3]) y;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select y, 2, 'descarga', '28001', 'Madrid', 'ES' from unnest(array[e, e2, e3]) y;
  update envios set estado = 'programado', transportista_id = tr, fecha_carga_prevista = dia where id in (e, e2, e3);
  update envios set matricula_camion = '2360AAA', matricula_remolque = 'R2360AAA' where id = e3;   -- completo: nunca recibe nada
  select c.hora into v_hora from seguimiento_calcular(e) c
   where c.parada_id = (select id from envio_paradas where envio_id = e and orden = 1) and c.estado = 'cargando';
  v_hora := coalesce(v_hora, (dia + time '08:00') at time zone 'Europe/Madrid');

  -- Lunes 15:50: todavía nada.
  perform encolar_avisos_operativos((lunes + time '15:50') at time zone 'Europe/Madrid');
  if exists (select 1 from emails_enviados where envio_id in (e, e2, e3) and tipo = 'matriculas') then
    raise exception 'FALLO 236 · pide matrículas la víspera antes de su hora';
  end if;
  -- Lunes 16:05: el de la víspera, una sola vez, al contacto del transportista.
  perform encolar_avisos_operativos((lunes + time '16:05') at time zone 'Europe/Madrid');
  perform encolar_avisos_operativos((lunes + time '16:20') at time zone 'Europe/Madrid');
  select count(*) into n from emails_enviados where clave = 'matriculas:vispera:' || e || ':' || dia and destinatario = 'trafico236@prueba.invalid' and estado = 'pendiente';
  if n <> 1 then raise exception 'FALLO 236 · esperaba 1 aviso de víspera y hay %', n; end if;
  if exists (select 1 from emails_enviados where envio_id = e3 and tipo = 'matriculas') then
    raise exception 'FALLO 236 · pide matrículas a un envío que ya las tiene';
  end if;
  -- 100 min antes de su hora: el «antes» (clave de siempre).
  perform encolar_avisos_operativos(v_hora - interval '100 minutes');
  if not exists (select 1 from emails_enviados where clave = 'matriculas:' || e) then raise exception 'FALLO 236 · no sale el aviso de antes de la carga'; end if;
  if exists (select 1 from emails_enviados where clave = 'matriculas:hora:' || e || ':' || dia) then raise exception 'FALLO 236 · el urgente sale antes de la hora'; end if;
  -- A su hora: el urgente (el «antes» salió con margen: se le pone su fecha de envío real de la prueba).
  update emails_enviados set creado_en = v_hora - interval '100 minutes' where clave in ('matriculas:' || e, 'matriculas:' || e2);
  update emails_enviados set creado_en = v_hora - interval '20 minutes' where clave = 'matriculas:' || e2;   -- e2: asignado a última hora
  perform encolar_avisos_operativos(v_hora + interval '5 minutes');
  perform encolar_avisos_operativos(v_hora + interval '15 minutes');
  select * into x from emails_enviados where clave = 'matriculas:hora:' || e || ':' || dia;
  if x.id is null or x.asunto not like 'URGENTE%' or x.cuerpo_html not like '%/cmr/%' then
    raise exception 'FALLO 236 · no sale el aviso urgente a la hora de carga, con su enlace: %', x.asunto;
  end if;
  if exists (select 1 from emails_enviados where clave = 'matriculas:hora:' || e2 || ':' || dia) then
    raise exception 'FALLO 236 · manda el urgente aunque el anterior salió a 20 min de la hora';
  end if;
  select count(*) into n from emails_enviados where envio_id = e and tipo = 'matriculas';
  if n <> 3 then raise exception 'FALLO 236 · esperaba 3 avisos de matrículas en total y hay %', n; end if;
  -- Solo falta el semirremolque: el texto lo dice.
  delete from emails_enviados where envio_id = e2 and tipo = 'matriculas';
  update envios set matricula_camion = '2360BBB' where id = e2;
  perform encolar_avisos_operativos(v_hora - interval '100 minutes');
  if not exists (select 1 from emails_enviados where clave = 'matriculas:' || e2 and cuerpo_html like '%semirremolque%' and cuerpo_html not like '%tractora%') then
    raise exception 'FALLO 236 · con la tractora puesta el aviso no pide solo el semirremolque';
  end if;
  raise notice 'OK 236 · matrículas al transportista: víspera hábil desde las 16:00, antes de la carga y urgente a la hora, cada uno una vez; sin urgente si el anterior fue a última hora; nada si están completas';
end $$;

-- ---- 230. Nadie firma sin matrículas: solo la cabecera, que las pone ----------------
-- Con transportista y sin matrículas, el destinatario NO firma (sin_matriculas); la firma
-- de cabecera del transportista sin matrículas tampoco (faltan_matriculas).
do $$ declare e uuid := current_setting('prueba.e229')::uuid; tok uuid; r jsonb; begin
  update envios set matricula_camion = null, matricula_remolque = null where id = e;
  select token into tok from cmr_enlaces where envio_id = e and not revocado limit 1;
  r := firmar_cmr_publico(tok, (select id from envio_paradas where envio_id = e and tipo = 'descarga'), 'destinatario',
                          'Rosa', '12345678Z', 'ES', true, null, 'cmr/' || tok || '/x.png', null, null, null);
  if r ->> 'resultado' <> 'sin_matriculas' then raise exception 'FALLO 230 · el destinatario firma sin matrículas: %', r; end if;
  r := firmar_cmr_publico(tok, null, 'transportista', 'Pepe', 'X1234567L', 'ES', true, null, 'cmr/' || tok || '/y.png', null, null, null);
  if r ->> 'resultado' <> 'faltan_matriculas' then raise exception 'FALLO 230 · la cabecera firma sin poner matrículas: %', r; end if;
  raise notice 'OK 230 · sin matrículas solo se puede firmar la cabecera, y poniéndolas';
end $$;

-- ---- 231. Nunca precio 0: sin precio no se asigna transportista; el cliente nunca a 0 -------
reset role;
do $$ declare e uuid; t uuid := current_setting('prueba.transp')::uuid; r jsonb; ok boolean; begin
  select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false) into strict e;
  set local role authenticated;
  select (crear_envio(
    jsonb_build_object('cliente_id', current_setting('prueba.cliente'), 'metros_lineales', 13.3,
                       'fecha_carga_desde', current_date + 15, 'fecha_carga_hasta', current_date + 15, 'importe_cliente', 900),
    jsonb_build_array(jsonb_build_object('tipo', 'carga', 'nombre_empresa', 'A231', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
                      jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'B231', 'codigo_postal', '28001', 'poblacion', 'Madrid')))).id into e;
  r := asignar_transportista(e, t);
  if r ->> 'resultado' <> 'falta_precio' then raise exception 'FALLO 231 · asigna sin precio: %', r; end if;
  r := asignar_transportista(e, t, 0);
  if r ->> 'resultado' <> 'falta_precio' then raise exception 'FALLO 231 · asigna a 0 €: %', r; end if;
  if (select transportista_id from envios where id = e) is not null then raise exception 'FALLO 231 · quedó asignado sin precio'; end if;
  -- Por la tabla tampoco: transportista sin precio, ni precio del cliente a 0.
  ok := false;
  begin update envios set transportista_id = t where id = e; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 231 · la tabla deja un transportista sin precio'; end if;
  ok := false;
  begin update envios set importe_cliente = 0 where id = e; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 231 · la tabla deja el precio del cliente a 0'; end if;
  r := asignar_transportista(e, t, 650);
  if r ->> 'resultado' <> 'asignado' then raise exception 'FALLO 231 · no asigna con precio: %', r; end if;
  ok := false;
  begin update envios set importe_transportista = 0 where id = e; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 231 · deja bajar a 0 el precio del transportista asignado'; end if;
  raise notice 'OK 231 · nunca precio 0: sin precio (o a 0) no se asigna transportista, ni por la tabla; el precio del cliente nunca queda a 0';
end $$;

-- ---- 237. Archivo de copias del DeCA: se guardan solas y no se tocan en un año -------------
-- Tipo deca_copia: lo guarda Dynamo (o el servidor) con su huella; nunca visible para el
-- cliente ni para el transportista; una sola por versión; durante un año no se quita, no se
-- cambia y no se borra; pasado el año, sí. El borrado de datos de prueba suelta el candado.
reset role;
do $$ declare e uuid; t uuid := current_setting('prueba.transp')::uuid; d uuid; d2 uuid; ok boolean; n int; h text := repeat('a', 64); begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  select (crear_envio(
    jsonb_build_object('cliente_id', current_setting('prueba.cliente'), 'metros_lineales', 13.3,
                       'fecha_carga_desde', current_date + 16, 'fecha_carga_hasta', current_date + 16, 'importe_cliente', 900),
    jsonb_build_array(jsonb_build_object('tipo', 'carga', 'nombre_empresa', 'A237', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
                      jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'B237', 'codigo_postal', '28001', 'poblacion', 'Madrid')))).id into e;
  if asignar_transportista(e, t, 650) ->> 'resultado' <> 'asignado' then raise exception 'FALLO 237 · no asigna el envío de la prueba'; end if;
  -- Dynamo guarda una copia: nunca queda visible para el cliente, aunque se pida.
  insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, sha256, tamano_bytes, visible_cliente)
  values (e, 'deca_copia', 'envios/' || e || '/deca/a/DeCA-X-aaaaaaaaaaaa.pdf', 'DeCA-X-aaaaaaaaaaaa.pdf', h, 1000, true) returning id into d;
  if (select visible_cliente from documentos where id = d) then raise exception 'FALLO 237 · la copia queda visible para el cliente'; end if;
  -- Sin huella no es una copia válida.
  ok := false;
  begin
    insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, tamano_bytes)
    values (e, 'deca_copia', 'envios/' || e || '/deca/b/DeCA-X-bbbbbbbbbbbb.pdf', 'DeCA-X-bbbbbbbbbbbb.pdf', 1000);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · admite una copia sin huella'; end if;
  -- La misma versión no se guarda dos veces.
  ok := false;
  begin
    insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, sha256, tamano_bytes)
    values (e, 'deca_copia', 'envios/' || e || '/deca/c/DeCA-X-aaaaaaaaaaaa.pdf', 'DeCA-X-aaaaaaaaaaaa.pdf', h, 1000);
  exception when unique_violation then ok := true; end;
  if not ok then raise exception 'FALLO 237 · guarda dos veces la misma versión'; end if;
  -- Ni quitarla, ni enseñársela al cliente, ni cambiarle nada.
  ok := false;
  begin update documentos set borrado = true, borrado_en = now() where id = d; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · deja quitar una copia archivada'; end if;
  ok := false;
  begin update documentos set visible_cliente = true where id = d; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · deja enseñar la copia al cliente'; end if;
  -- Otro documento no se convierte en copia archivada.
  insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo) values (e, 'adjunto', 'envios/' || e || '/x/nota.pdf', 'nota.pdf') returning id into d2;
  ok := false;
  begin update documentos set tipo = 'deca_copia' where id = d2; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · un adjunto se convierte en copia archivada'; end if;
  -- El transportista del envío: ni las ve ni las guarda.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
  select count(*) into n from documentos where tipo = 'deca_copia';
  if n <> 0 then raise exception 'FALLO 237 · el transportista ve las copias archivadas (%)', n; end if;
  ok := false;
  begin
    insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, sha256, tamano_bytes)
    values (e, 'deca_copia', 'u/' || current_setting('prueba.u_transp') || '/DeCA-falsa.pdf', 'DeCA-falsa.pdf', h, 1000);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · el transportista guarda una copia archivada'; end if;
  -- El cliente del envío tampoco las ve.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  select count(*) into n from documentos where tipo = 'deca_copia';
  if n <> 0 then raise exception 'FALLO 237 · el cliente ve las copias archivadas (%)', n; end if;
  perform set_config('prueba.e237', e::text, false);
  perform set_config('prueba.d237', d::text, false);
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e237')::uuid; d uuid := current_setting('prueba.d237')::uuid; v uuid; ok boolean; n int; h text := repeat('b', 64); begin
  -- Ni siquiera el servidor la borra o la cambia antes del año…
  ok := false;
  begin delete from documentos where id = d; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · deja borrar una copia archivada'; end if;
  ok := false;
  begin update documentos set sha256 = h where id = d; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 237 · deja cambiar la huella de una copia archivada'; end if;
  -- …pasado el año, sí. (La fecha de alta la pone siempre el servidor: para la prueba se
  -- usa el modo migración, el único que deja traer una fecha antigua.)
  perform set_config('dynamo.migracion', 'on', true);
  insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, sha256, tamano_bytes, creado_en)
  values (e, 'deca_copia', 'envios/' || e || '/deca/v/DeCA-X-vieja.pdf', 'DeCA-X-vieja.pdf', h, 1000, now() - interval '400 days') returning id into v;
  perform set_config('dynamo.migracion', 'off', true);
  update documentos set borrado = true, borrado_en = now() where id = v;
  if not (select borrado from documentos where id = v) then raise exception 'FALLO 237 · pasado el año no deja quitar la copia'; end if;
  -- El borrado de datos de prueba suelta y vuelve a poner el candado.
  select count(*) into n from regexp_matches(
    (select pg_get_functiondef(p.oid) from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = 'public' and p.proname = 'borrar_datos_de_prueba'),
    'trigger tg_documentos_deca_copia', 'g');
  if n <> 2 then raise exception 'FALLO 237 · borrar_datos_de_prueba no suelta y repone el candado de las copias (%)', n; end if;
  raise notice 'OK 237 · copias archivadas del DeCA: las guarda Dynamo o el servidor con su huella, una por versión, ocultas a cliente y transportista; en un año ni se quitan, ni se cambian, ni se borran';
end $$;

-- ---- 238. DeCA y CMR, dos documentos: el email del DeCA existe y nada dice «CMR / DeCA» ------
reset role;
do $$ declare n int; f text; begin
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html, estado)
  values ('deca:prueba238:aaaaaaaaaaaa', 'deca', 'trafico@prueba.invalid', 'DeCA · envío #X', '<p>x</p>', 'pendiente');
  delete from emails_enviados where clave = 'deca:prueba238:aaaaaaaaaaaa';
  select count(*), min(p.proname) into n, f from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.prosrc like '%CMR / DeCA%';
  if n <> 0 then raise exception 'FALLO 238 · quedan % funciones que dicen «CMR / DeCA» (p. ej. %)', n, f; end if;
  select count(*) into n from parametros where descripcion like '%CMR / DeCA%';
  if n <> 0 then raise exception 'FALLO 238 · quedan % parámetros que dicen «CMR / DeCA»', n; end if;
  if pg_get_functiondef('public.fn_documentos_deca_copia()'::regprocedure) not like '%copias archivadas del DeCA%' then
    raise exception 'FALLO 238 · el candado de las copias no habla del DeCA';
  end if;
  raise notice 'OK 238 · DeCA y CMR separados: el email del DeCA tiene su tipo, las copias archivadas son del DeCA y ningún aviso dice ya «CMR / DeCA»';
end $$;

-- ---- 239. Historial de envíos (DeCA, CMR y orden): lo compartido a mano queda apuntado -------
reset role;
do $$ declare e uuid := current_setting('prueba.e237')::uuid; ok boolean; n int; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  if not anotar_compartido_envio(e, 'deca', 'whatsapp') then raise exception 'FALLO 239 · Dynamo no apunta que compartió el DeCA'; end if;
  if not anotar_compartido_envio(e, 'cmr', 'copiar') then raise exception 'FALLO 239 · Dynamo no apunta que compartió el CMR'; end if;
  if not anotar_compartido_envio(e, 'orden_cliente', 'whatsapp') then raise exception 'FALLO 239 · Dynamo no apunta que compartió la orden del cliente'; end if;
  if anotar_compartido_envio(e, 'deca', 'fax') then raise exception 'FALLO 239 · apunta una vía que no existe'; end if;
  if anotar_compartido_envio(e, 'factura', 'sms') then raise exception 'FALLO 239 · apunta un documento que no existe'; end if;
  select count(*) into n from envio_compartidos where envio_id = e and documento = 'deca' and via = 'whatsapp' and creado_por = current_setting('prueba.u_admin')::uuid;
  if n <> 1 then raise exception 'FALLO 239 · el apunte no queda con su documento, su vía y su autor (%)', n; end if;
  if (select count(*) from envio_compartidos where envio_id = e) <> 3 then raise exception 'FALLO 239 · no quedan los tres apuntes'; end if;
  -- Por la tabla, nada: solo entra por la función.
  ok := false;
  begin insert into envio_compartidos (envio_id, documento, via) values (e, 'deca', 'sms'); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 239 · se escribe en el historial por la tabla'; end if;
  -- Ni el transportista ni el cliente apuntan ni lo leen.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
  ok := false;
  begin perform anotar_compartido_envio(e, 'deca', 'sms'); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 239 · el transportista apunta en el historial de envíos'; end if;
  if (select count(*) from envio_compartidos) <> 0 then raise exception 'FALLO 239 · el transportista lee el historial de envíos'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  if (select count(*) from envio_compartidos) <> 0 then raise exception 'FALLO 239 · el cliente lee el historial de envíos'; end if;
  raise notice 'OK 239 · historial de envíos (DeCA, CMR y orden): lo compartido a mano queda apuntado con su documento, su vía y su autor; solo Dynamo lo apunta y lo lee';
end $$;
reset role;

-- ---- 240. Alta pendiente: sube y ve los documentos de SU alta (y nada más) --------------------
-- Quien se acaba de registrar (pendiente de verificación) tiene que poder adelantar la hoja
-- del CIF y su DNI; no puede colgar documentos a otro usuario ni de otro tipo.
reset role;
insert into auth.users (email, raw_user_meta_data) values ('alta240@prueba.es', '{"nombre":"Alta Doscientos Cuarenta"}');
do $$ declare u uuid; n int; ok boolean; begin
  select id into u from usuarios where email = 'alta240@prueba.es';
  if (select estado from usuarios where id = u) <> 'pendiente_verificacion' then raise exception 'FALLO 240 · el alta no nace pendiente de verificación'; end if;
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  insert into documentos (tipo, usuario_id, storage_ruta, nombre_archivo) values ('hoja_cif', u, 'u/' || u || '/a/hoja-cif.pdf', 'hoja-cif.pdf');
  insert into documentos (tipo, usuario_id, storage_ruta, nombre_archivo) values ('dni', u, 'u/' || u || '/b/dni.jpg', 'dni.jpg');
  select count(*) into n from documentos where usuario_id = u;
  if n <> 2 then raise exception 'FALLO 240 · quien tiene el alta pendiente no ve sus documentos (%)', n; end if;
  ok := false;
  begin
    insert into documentos (tipo, usuario_id, storage_ruta, nombre_archivo)
    values ('dni', current_setting('prueba.u_cli')::uuid, 'u/' || u || '/c/dni.jpg', 'dni.jpg');
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 240 · cuelga un documento en el alta de otro usuario'; end if;
  ok := false;
  begin
    insert into documentos (tipo, usuario_id, storage_ruta, nombre_archivo) values ('albaran', u, 'u/' || u || '/d/albaran.pdf', 'albaran.pdf');
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 240 · sube a su alta un tipo de documento que no es del alta'; end if;
  if (select count(*) from documentos where usuario_id is distinct from u) <> 0 then raise exception 'FALLO 240 · ve documentos que no son de su alta'; end if;
  raise notice 'OK 240 · alta pendiente: sube y ve la hoja del CIF y el DNI de su propia alta, y nada más';
end $$;
reset role;

-- ---- 241. Alta pendiente: busca su empresa por CIF (solo «está / no está», con tope) -----
-- Quien tiene el alta pendiente sabe si su CIF es ya de un cliente, sin ver ningún dato
-- del cliente; no puede sondear (5 CIF distintos al día) y nadie más usa la búsqueda.
reset role;
insert into auth.users (email, raw_user_meta_data) values ('alta241@prueba.es', '{"nombre":"Alta Doscientos Cuarenta y Uno"}');
do $$ declare u uuid; v_cif text; r text; ok boolean; i int; begin
  select id into u from usuarios where email = 'alta241@prueba.es';
  select cif into v_cif from clientes where cif ~ '^[A-Z0-9]{6,20}$' order by creado_en limit 1;
  if v_cif is null then raise exception 'FALLO 241 · no hay ningún cliente con CIF para la prueba'; end if;
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  r := buscar_empresa_de_mi_alta(lower(left(v_cif, 2)) || '-' || substr(v_cif, 3, 3) || '.' || substr(v_cif, 6));
  if r <> 'encontrado' then raise exception 'FALLO 241 · no encuentra un CIF que ya es cliente (con guiones y minúsculas): %', r; end if;
  r := buscar_empresa_de_mi_alta('ZZ24100000');
  if r <> 'no_encontrado' then raise exception 'FALLO 241 · da por cliente un CIF que no lo es: %', r; end if;
  if buscar_empresa_de_mi_alta('¿?') <> 'no_valido' or buscar_empresa_de_mi_alta(null) <> 'no_valido' then
    raise exception 'FALLO 241 · acepta como CIF algo que no lo es';
  end if;
  if (select count(*) from clientes) <> 0 then raise exception 'FALLO 241 · quien tiene el alta pendiente ve clientes'; end if;
  if (select count(*) from alta_busquedas_cif) <> 0 then raise exception 'FALLO 241 · quien tiene el alta pendiente lee las búsquedas'; end if;
  ok := false;
  begin insert into alta_busquedas_cif (usuario_id, cif, encontrado) values (u, 'ZZ24199999', false);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 241 · se apunta búsquedas a mano, sin pasar por la función'; end if;
  -- Tope: van 2 CIF distintos; 3 más llegan a 5 y el sexto ya no se contesta.
  for i in 1..3 loop
    if buscar_empresa_de_mi_alta('ZZ2410000' || i) <> 'no_encontrado' then raise exception 'FALLO 241 · la búsqueda % debía contestarse', i; end if;
  end loop;
  if buscar_empresa_de_mi_alta('ZZ24100009') <> 'tope' then raise exception 'FALLO 241 · deja sondear más de 5 CIF distintos al día'; end if;
  if buscar_empresa_de_mi_alta(v_cif) <> 'encontrado' then raise exception 'FALLO 241 · con el tope alcanzado no deja repetir un CIF ya buscado'; end if;
  reset role;
  if (select count(*) from alta_busquedas_cif where usuario_id = u) <> 6 or (select count(*) from alta_busquedas_cif where usuario_id = u and encontrado) <> 2 then
    raise exception 'FALLO 241 · las búsquedas no quedan apuntadas como deben';
  end if;
  -- Una cuenta ya activa no busca.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  ok := false;
  begin perform buscar_empresa_de_mi_alta(v_cif); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 241 · una cuenta activa usa la búsqueda de empresa del alta'; end if;
  reset role;
  if has_function_privilege('anon', 'public.buscar_empresa_de_mi_alta(text)', 'execute') then
    raise exception 'FALLO 241 · la búsqueda de empresa del alta se puede llamar sin sesión';
  end if;
  raise notice 'OK 241 · alta pendiente: busca su empresa por CIF, solo sabe si está o no, con tope de 5 CIF al día';
end $$;
reset role;

-- ---- 242. Borrar un alta pendiente: solo el administrador y solo si sigue pendiente --------
reset role;
insert into auth.users (email, raw_user_meta_data) values ('alta242@prueba.es', '{"nombre":"Alta Doscientos Cuarenta y Dos"}');
do $$ declare u uuid; adm uuid; r jsonb; ok boolean; begin
  select id into u from usuarios where email = 'alta242@prueba.es';
  select id into adm from usuarios where rol = 'admin' and estado = 'activa' order by creado_en limit 1;
  if adm is null then raise exception 'FALLO 242 · no hay administrador para la prueba'; end if;
  -- El alta sube un documento y busca su empresa.
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  insert into documentos (tipo, usuario_id, storage_ruta, nombre_archivo) values ('dni', u, 'u/' || u || '/a/dni.jpg', 'dni.jpg');
  perform buscar_empresa_de_mi_alta('ZZ24200000');
  -- Ella misma no se borra, ni borra a nadie.
  ok := false;
  begin perform borrar_alta_pendiente(u); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 242 · quien tiene el alta pendiente borra altas'; end if;
  reset role;
  -- Un cliente activo tampoco.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  ok := false;
  begin perform borrar_alta_pendiente(u); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 242 · un cliente borra altas'; end if;
  reset role;
  -- El administrador: no puede borrar una cuenta activa…
  perform set_config('request.jwt.claim.sub', adm::text, false);
  set local role authenticated;
  ok := false;
  begin perform borrar_alta_pendiente(current_setting('prueba.u_cli')::uuid); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 242 · se borra una cuenta ya activa'; end if;
  -- … y sí el alta pendiente, con todo lo suyo.
  r := borrar_alta_pendiente(u);
  reset role;
  if r ->> 'email' <> 'alta242@prueba.es' or jsonb_array_length(r -> 'rutas') <> 1 then raise exception 'FALLO 242 · no devuelve el email y los ficheros del alta: %', r; end if;
  if exists (select 1 from usuarios where id = u) or exists (select 1 from auth.users where id = u)
     or exists (select 1 from documentos where usuario_id = u) or exists (select 1 from alta_busquedas_cif where usuario_id = u) then
    raise exception 'FALLO 242 · quedan restos del alta borrada';
  end if;
  if not exists (select 1 from auditoria where tabla = 'usuarios' and registro_id = u::text and accion = 'baja' and quien = adm and cambios ->> 'email' = 'alta242@prueba.es') then
    raise exception 'FALLO 242 · el borrado del alta no queda en la auditoría con su autor';
  end if;
  if not exists (select 1 from usuarios where id = current_setting('prueba.u_cli')::uuid) then raise exception 'FALLO 242 · ha desaparecido la cuenta activa'; end if;
  -- El email queda libre: se puede registrar otra vez.
  insert into auth.users (email, raw_user_meta_data) values ('alta242@prueba.es', '{"nombre":"Otra vez"}');
  if (select estado from usuarios where email = 'alta242@prueba.es') <> 'pendiente_verificacion' then raise exception 'FALLO 242 · el email no queda libre para registrarse de nuevo'; end if;
  if has_function_privilege('anon', 'public.borrar_alta_pendiente(uuid)', 'execute') then raise exception 'FALLO 242 · borrar altas se puede llamar sin sesión'; end if;
  raise notice 'OK 242 · borrar un alta pendiente: solo el administrador, solo si sigue pendiente; se van sus documentos y el email queda libre';
end $$;
reset role;

-- ---- 243. Al confirmar un alta sale el email «tu cuenta ya está activa» con el enlace ------
reset role;
insert into auth.users (email, raw_user_meta_data) values ('alta243@prueba.es', '{"nombre":"Marta Doscientos Cuarenta y Tres"}');
do $$ declare u uuid; c uuid; v_cuerpo text; n int; begin
  select id into u from usuarios where email = 'alta243@prueba.es';
  select id into c from clientes order by creado_en limit 1;
  if exists (select 1 from emails_enviados where clave = 'cuenta_activada:' || u) then raise exception 'FALLO 243 · el email de cuenta activa sale antes de confirmar el alta'; end if;
  update usuarios set cliente_id = c, estado = 'activa' where id = u;
  select cuerpo_html into v_cuerpo from emails_enviados
   where clave = 'cuenta_activada:' || u and tipo = 'cuenta_activada' and destinatario = 'alta243@prueba.es';
  if v_cuerpo is null then raise exception 'FALLO 243 · confirmar el alta no deja el email al usuario'; end if;
  if v_cuerpo not like '%/panel/entrar%' or v_cuerpo not like '%Hola Marta:%' or v_cuerpo not like '%alta243@prueba.es%'
     or v_cuerpo not like '%' || escapar_html((select razon_social from clientes where id = c)) || '%' then
    raise exception 'FALLO 243 · al email de cuenta activa le falta el enlace para entrar, el nombre, el email o la empresa: %', v_cuerpo;
  end if;
  -- Suspender y reactivar después no repite el de ALTA (sale el de reactivada: prueba 244).
  update usuarios set estado = 'suspendida' where id = u;
  update usuarios set estado = 'activa' where id = u;
  select count(*) into n from emails_enviados where tipo = 'cuenta_activada' and destinatario = 'alta243@prueba.es';
  if n <> 1 then raise exception 'FALLO 243 · el email de cuenta activa se repite (%)', n; end if;
  raise notice 'OK 243 · confirmar un alta encola el email «tu cuenta ya está activa» con el enlace para entrar, una sola vez';
end $$;
reset role;

-- ---- 244. Cada reactivación de una cuenta suspendida manda el email «vuelve a estar activa» ----
reset role;
do $$ declare u uuid; n0 int; n int; v_cuerpo text; begin
  select id into u from usuarios where email = 'alta243@prueba.es';
  select count(*) into n0 from emails_enviados where tipo = 'cuenta_reactivada' and destinatario = 'alta243@prueba.es';
  if n0 <> 1 then raise exception 'FALLO 244 · la reactivación de la prueba 243 debía dejar un email (%)', n0; end if;
  -- Suspensión de solo lectura → activa.
  update usuarios set estado = 'suspendida' where id = u;
  if (select count(*) from emails_enviados where tipo = 'cuenta_reactivada' and destinatario = 'alta243@prueba.es') <> n0 then
    raise exception 'FALLO 244 · suspender manda el email de reactivada';
  end if;
  update usuarios set estado = 'activa' where id = u;
  -- Suspensión total → activa.
  update usuarios set estado = 'suspendida_total' where id = u;
  update usuarios set estado = 'activa' where id = u;
  select count(*) into n from emails_enviados where tipo = 'cuenta_reactivada' and destinatario = 'alta243@prueba.es';
  if n <> n0 + 2 then raise exception 'FALLO 244 · cada reactivación debía dejar su email (había %, hay %)', n0, n; end if;
  select cuerpo_html into v_cuerpo from emails_enviados
   where tipo = 'cuenta_reactivada' and destinatario = 'alta243@prueba.es' order by creado_en desc, clave desc limit 1;
  if v_cuerpo not like '%/panel/entrar%' or v_cuerpo not like '%reactivado tu cuenta%' or v_cuerpo not like '%Hola Marta:%' then
    raise exception 'FALLO 244 · al email de cuenta reactivada le falta el enlace para entrar o el texto: %', v_cuerpo;
  end if;
  if (select count(*) from emails_enviados where tipo = 'cuenta_activada' and destinatario = 'alta243@prueba.es') <> 1 then
    raise exception 'FALLO 244 · reactivar repite el email de alta';
  end if;
  raise notice 'OK 244 · cada reactivación de una cuenta suspendida encola el email «vuelve a estar activa» con el enlace para entrar';
end $$;
reset role;

-- ---- 245. Cambiar el email de acceso avisa a la dirección antigua y a la nueva ------------
reset role;
do $$ declare u uuid; v_a text; v_n text; n int; begin
  select id into u from usuarios where email = 'alta243@prueba.es';
  -- El cambio entra por el acceso (auth.users), como lo hace la plataforma; el perfil se sincroniza solo.
  update auth.users set email = 'nuevo245@prueba.es' where id = u;
  if (select email from usuarios where id = u) <> 'nuevo245@prueba.es' then raise exception 'FALLO 245 · el perfil no sigue al cambio de email'; end if;
  select cuerpo_html into v_a from emails_enviados where tipo = 'cambio_email' and destinatario = 'alta243@prueba.es' and clave like 'cambio_email:' || u || ':%:antiguo';
  select cuerpo_html into v_n from emails_enviados where tipo = 'cambio_email' and destinatario = 'nuevo245@prueba.es' and clave like 'cambio_email:' || u || ':%:nuevo';
  if v_a is null or v_n is null then raise exception 'FALLO 245 · cambiar el email no avisa a las dos direcciones (antigua %, nueva %)', v_a is not null, v_n is not null; end if;
  if v_a not like '%nuevo245@prueba.es%' or v_a not like '%ya no sirve para entrar%' or v_a not like '%No lo has pedido%' or v_a like '%/panel/entrar%' then
    raise exception 'FALLO 245 · el aviso a la dirección antigua no es el que debe: %', v_a;
  end if;
  if v_n not like '%/panel/entrar%' or v_n not like '%contraseña de siempre%' or v_n not like '%alta243@prueba.es%' then
    raise exception 'FALLO 245 · el aviso a la dirección nueva no trae el enlace para entrar o el texto: %', v_n;
  end if;
  -- Cambiar solo mayúsculas no es un cambio; anonimizar no avisa a nadie nuevo.
  select count(*) into n from emails_enviados where tipo = 'cambio_email';
  update usuarios set email = 'Nuevo245@prueba.es' where id = u;
  update usuarios set email = 'eliminado-245@anonimo.invalid' where id = u;
  if (select count(*) from emails_enviados where tipo = 'cambio_email') <> n then raise exception 'FALLO 245 · sale aviso de cambio de email al cambiar mayúsculas o al anonimizar'; end if;
  raise notice 'OK 245 · cambiar el email de acceso avisa a la dirección antigua y a la nueva (con el enlace para entrar); anonimizar no';
end $$;
reset role;

-- ---- 246. Un email pendiente de más de 24 horas ya no se manda (queda omitido) -------------
reset role;
do $$ declare v_viejo uuid; v_nuevo uuid; begin
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html)
    values ('prueba246:nuevo', 'cuenta_activada', 'nuevo246@prueba.es', 'Reciente', '<p>x</p>') returning id into v_nuevo;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html)
    values ('prueba246:viejo', 'cuenta_activada', 'viejo246@prueba.es', 'Viejo', '<p>x</p>') returning id into v_viejo;
  alter table emails_enviados disable trigger user;
  update emails_enviados set creado_en = now() - interval '25 hours' where id = v_viejo;
  alter table emails_enviados enable trigger user;
  if (select creado_en from emails_enviados where id = v_viejo) > now() - interval '24 hours' then raise exception 'FALLO 246 · no se ha podido preparar el email viejo'; end if;
  perform enviar_emails_pendientes();
  if (select estado from emails_enviados where id = v_viejo) <> 'omitido' or (select error from emails_enviados where id = v_viejo) not like '%24 horas%' then
    raise exception 'FALLO 246 · un email pendiente de hace 25 horas no queda omitido';
  end if;
  if (select estado from emails_enviados where id = v_nuevo) = 'omitido' then raise exception 'FALLO 246 · se omite un email reciente'; end if;
  raise notice 'OK 246 · un email que lleva más de 24 horas pendiente ya no se manda: queda omitido con su motivo';
end $$;
reset role;

-- ---- 247. La cola de emails: cada minuto, sin repetir y sin adelantarse al servidor web -----
reset role;
do $$ declare v_src text; begin
  select prosrc into v_src from pg_proc where oid = 'public.enviar_emails_pendientes()'::regprocedure;
  if v_src not like '%for update skip locked%' then raise exception 'FALLO 247 · dos pasadas a la vez podrían mandar el mismo email (falta skip locked)'; end if;
  -- Desde 2026-11-20 los emails esperan su plazo (enviar_desde) y los del servidor web los manda él; la cola solo los recoge
  -- si siguen sin salir (a los 2 minutos; desde 2026-11-25, con el plazo a 60 s, a los 15 segundos).
  if v_src not like '%x.enviar_desde <= now()%' or v_src not like '%x.via = ''bd'' or x.enviar_desde < now() - interval ''15 seconds''%' then
    raise exception 'FALLO 247 · la cola podría adelantarse al plazo de los emails o al servidor web'; end if;
  if v_src not like '%24 hours%' then raise exception 'FALLO 247 · se ha perdido la caducidad de 24 horas'; end if;
  if has_function_privilege('authenticated', 'public.enviar_emails_pendientes()', 'execute') then raise exception 'FALLO 247 · cualquiera con sesión puede lanzar la cola de emails'; end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if not exists (select 1 from cron.job where jobname = 'dynamo-emails-enviar' and schedule in ('* * * * *', '10 seconds')) then
      raise exception 'FALLO 247 · falta la tarea que manda la cola cada minuto';
    end if;
  end if;
  raise notice 'OK 247 · la cola de emails sale cada minuto, sin repetir entre pasadas y con 15 s de margen para el servidor web';
end $$;
reset role;

-- ---- 248. La bolsa va primero: ventana de 12 días, márgenes y arranque de los emails --------
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = '0'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '24'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = '0'::jsonb  where clave = 'bolsa_espera_minutos';
update parametros set valor = 'true'::jsonb where clave = 'bolsa_primero';
do $$ declare e uuid; gx text; hoy date := (now() at time zone 'Europe/Madrid')::date; r jsonb; t uuid; begin
  -- Un transportista de la provincia del origen, con email: el candidato de la oferta.
  insert into transportistas (razon_social, cif, nima, valoracion_dynamo, codigo_postal, pais_codigo_iso)
    values ('Transp Bolsa 248 SL', 'B24800001', 'NIMA-248A', 5, '19005', 'ES') returning id into t;
  insert into contactos (transportista_id, nombre, email, funcion, es_principal)
    values (t, 'Berta Bolsa', 'bolsa.248@prueba.invalid', 'trafico', true);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, hoy + 20) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '19001', 'Guadalajara', 'ES'), (e, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set estado = 'programado' where id = e;
  select referencia_gx into gx from envios where id = e;
  perform set_config('prueba.e248', e::text, false);

  -- (a) El fichero de la bolsa: a 20 días no sale; a 12 sí.
  if exists (select 1 from v_wtransnet where "REF." = gx) then raise exception 'FALLO 248 · un envío a 20 días sale ya en el fichero de la bolsa'; end if;
  update envios set fecha_carga_desde = hoy + 12 where id = e;
  if not exists (select 1 from v_wtransnet where "REF." = gx) then raise exception 'FALLO 248 · a 12 días de la carga el envío no entra en el fichero de la bolsa'; end if;

  -- (b) Los márgenes de los emails según lo que falte al publicar.
  if fn_difusion_bolsa(e) ->> 'espera' <> 'bolsa' then raise exception 'FALLO 248 · sin publicar en la bolsa los emails no esperan: %', fn_difusion_bolsa(e); end if;
  update envios set publicado_en_bolsa_en = now() where id = e;
  r := fn_difusion_bolsa(e);
  if r ->> 'espera' <> 'margen' or (r ->> 'minutos')::int <> 180 then raise exception 'FALLO 248 · a 3 días o más el margen debía ser de 180 minutos: %', r; end if;
  update envios set publicado_en_bolsa_en = now() - interval '181 minutes' where id = e;
  if fn_difusion_bolsa(e) ->> 'espera' is not null then raise exception 'FALLO 248 · pasado el margen los emails siguen esperando: %', fn_difusion_bolsa(e); end if;
  update envios set fecha_carga_desde = hoy + 2, publicado_en_bolsa_en = now() where id = e;
  if (fn_difusion_bolsa(e) ->> 'minutos')::int <> 120 then raise exception 'FALLO 248 · a 2 días el margen debía ser de 120 minutos: %', fn_difusion_bolsa(e); end if;
  update envios set fecha_carga_desde = hoy + 1, publicado_en_bolsa_en = now() where id = e;
  if (fn_difusion_bolsa(e) ->> 'minutos')::int <> 15 then raise exception 'FALLO 248 · con la carga mañana el margen debía ser de 15 minutos: %', fn_difusion_bolsa(e); end if;
  update envios set fecha_carga_desde = hoy, publicado_en_bolsa_en = now() where id = e;
  if (fn_difusion_bolsa(e) ->> 'minutos')::int <> 5 then raise exception 'FALLO 248 · con la carga hoy el margen debía ser de 5 minutos: %', fn_difusion_bolsa(e); end if;
  -- Red de seguridad: carga mañana y sin publicar → los emails salen igual.
  update envios set fecha_carga_desde = hoy + 1, publicado_en_bolsa_en = null where id = e;
  r := fn_difusion_bolsa(e);
  if r ->> 'espera' is not null or (r ->> 'sin_bolsa')::boolean is not true then raise exception 'FALLO 248 · con la carga mañana y sin publicar, los emails debían salir igual: %', r; end if;
  -- Interruptor apagado: los emails no miran la bolsa.
  update envios set fecha_carga_desde = hoy + 3 where id = e;
  update parametros set valor = 'false'::jsonb where clave = 'bolsa_primero';
  if fn_difusion_bolsa(e) ->> 'espera' is not null then raise exception 'FALLO 248 · con «bolsa primero» apagado los emails siguen esperando'; end if;
  update parametros set valor = 'true'::jsonb where clave = 'bolsa_primero';
end $$;
-- (c) La oferta escalonada: lanzada sin publicar en la bolsa, no contacta a nadie y avisa.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e248')::uuid; r jsonb; begin
  r := iniciar_difusion(e, 500);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 248 · no se lanza la oferta escalonada: %', r; end if;
  if difusion_espera_bolsa(e) ->> 'espera' <> 'bolsa' then raise exception 'FALLO 248 · Dynamo no ve que los emails esperan a la bolsa'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  if difusion_espera_bolsa(current_setting('prueba.e248')::uuid) ->> 'espera' is not null then raise exception 'FALLO 248 · un cliente ve si su envío está en la bolsa'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e248')::uuid; d uuid; n int; begin
  select id into d from difusiones where envio_id = e and estado = 'activa';
  perform fn_difusion_paso(d); perform fn_difusion_paso(d);
  if (select contactados from difusiones where id = d) <> 0 then raise exception 'FALLO 248 · sin publicar en la bolsa ya salen emails a los transportistas'; end if;
  select count(*) into n from avisos where tipo = 'bolsa_pendiente' and envio_id = e;
  if n <> 1 then raise exception 'FALLO 248 · el aviso de «sube a la bolsa» debía salir una sola vez (%)', n; end if;
  -- Publicado, pero dentro del margen de 3 horas: sigue esperando.
  update envios set publicado_en_bolsa_en = now() - interval '60 minutes' where id = e;
  perform fn_difusion_paso(d);
  if (select contactados from difusiones where id = d) <> 0 then raise exception 'FALLO 248 · dentro del margen de la bolsa ya salen emails'; end if;
  -- Pasado el margen: sale el primero.
  update envios set publicado_en_bolsa_en = now() - interval '181 minutes' where id = e;
  perform fn_difusion_paso(d);
  if (select contactados from difusiones where id = d) < 1 then
    raise exception 'FALLO 248 · pasado el margen de la bolsa no sale el primer email (estado %, motivo %)',
      (select estado from difusiones where id = d), (select fin_motivo from difusiones where id = d);
  end if;
  -- Una oferta que ya ha contactado a alguien no se vuelve a parar por la bolsa.
  update envios set publicado_en_bolsa_en = now() where id = e;
  if (select estado from difusiones where id = d) <> 'activa' then raise exception 'FALLO 248 · volver a publicar para la oferta en marcha'; end if;

  -- (d) Con transportista: deja de constar como publicado y Dynamo recibe aviso de retirarlo.
  update envios set transportista_id = (select id from transportistas where cif = 'B24800001'), estado_asignacion = 'confirmada',
                    fecha_carga_prevista = fecha_carga_desde where id = e;
  if (select publicado_en_bolsa_en from envios where id = e) is not null then raise exception 'FALLO 248 · con transportista sigue constando como publicado en la bolsa'; end if;
  if not exists (select 1 from avisos where tipo = 'bolsa_retirar' and envio_id = e) then raise exception 'FALLO 248 · falta el aviso de retirar el envío de la bolsa'; end if;
  raise notice 'OK 248 · la bolsa va primero: fichero a 12 días, márgenes 180/120/15/5, los emails esperan a la bolsa y se retira al asignar';
end $$;
update parametros set valor = '5.5'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '23.5'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = '3'::jsonb where clave = 'bolsa_espera_minutos';
reset role;

-- ---- 249. Oferta escalonada: 3 días antes, sin corte, ritmos nuevos; cola sin .invalid ------
reset role;
do $$ declare m int; l int; v_ok uuid; v_inv uuid; v_src text; begin
  if (parametro('difusion_dias_antes'))::text::int <> 3 then raise exception 'FALLO 249 · los emails no empiezan 3 días antes'; end if;
  if (parametro('difusion_horas_corte'))::text::int <> 0 then raise exception 'FALLO 249 · sigue habiendo corte horas antes de la carga'; end if;
  if (parametro('difusion_max_contactados'))::text::int <> 1000 then raise exception 'FALLO 249 · el tope de contactados no es 1000'; end if;
  select minutos, lote into m, l from fn_difusion_cadencia(2);   if (m, l) <> (1, 10) then raise exception 'FALLO 249 · a 2 h: % min, lote %', m, l; end if;
  select minutos, lote into m, l from fn_difusion_cadencia(5);   if (m, l) <> (1, 5)  then raise exception 'FALLO 249 · a 5 h: % min, lote %', m, l; end if;
  select minutos, lote into m, l from fn_difusion_cadencia(20);  if (m, l) <> (3, 8)  then raise exception 'FALLO 249 · a 20 h: % min, lote %', m, l; end if;
  select minutos, lote into m, l from fn_difusion_cadencia(60);  if (m, l) <> (3, 1)  then raise exception 'FALLO 249 · a 60 h: % min, lote %', m, l; end if;
  -- La cola: las direcciones de prueba quedan omitidas; las reales, no.
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html)
    values ('prueba249:real', 'cuenta_activada', 'real249@prueba.es', 'Real', '<p>x</p>') returning id into v_ok;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html)
    values ('prueba249:invalid', 'difusion', 'Trafico <trafico.249@prueba.invalid>', 'De prueba', '<p>x</p>') returning id into v_inv;
  perform enviar_emails_pendientes();
  if (select estado from emails_enviados where id = v_inv) <> 'omitido' then raise exception 'FALLO 249 · un email a una dirección .invalid no queda omitido'; end if;
  if (select estado from emails_enviados where id = v_ok) = 'omitido' then raise exception 'FALLO 249 · se omite un email a una dirección real'; end if;
  select prosrc into v_src from pg_proc where oid = 'public.enviar_emails_pendientes()'::regprocedure;
  if v_src not like '%limit 100 for update skip locked%' then raise exception 'FALLO 249 · la cola no manda 100 por pasada'; end if;
  raise notice 'OK 249 · oferta desde 3 días antes, sin corte, 10/5 por minuto y 8 cada 3 min; la cola manda 100 por pasada y omite las direcciones .invalid';
end $$;
reset role;

-- ---- 250. La oferta escalonada sigue hasta el CIERRE del primer sitio de carga -------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = '0'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '24'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = 'false'::jsonb where clave = 'bolsa_primero';
do $$ declare e uuid; e2 uuid; s uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; f date; f2 date; begin
  -- Un día laborable a más de 3 días (así la oferta nace dormida y no manda nada): el lunes de dentro de dos semanas.
  f := hoy + (8 - extract(isodow from hoy)::int) + 7;
  -- Un sitio que ese día abre de 08:00 a 14:00 y de 15:30 a 19:30.
  insert into sitios (nombre_empresa, cliente_id) values ('Almacen 250', current_setting('prueba.cliente')::uuid) returning id into s;
  delete from sitio_horarios where sitio_id = s;
  insert into sitio_horarios (sitio_id, dia_semana, abre, cierra) values (s, 1, '08:00', '14:00'), (s, 1, '15:30', '19:30'), (s, 2, '08:00', '13:00');
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, f) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, sitio_id, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', s, '19001', 'Guadalajara', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set estado = 'programado' where id = e;
  if fn_difusion_hora_limite(e, f) <> time '19:30' then raise exception 'FALLO 250 · la hora límite no es el cierre del sitio de carga: %', fn_difusion_hora_limite(e, f); end if;
  if fn_difusion_hora_limite(e, f + 2) <> time '18:00' then raise exception 'FALLO 250 · sin horario ese día no se usa la hora por defecto (18:00): %', fn_difusion_hora_limite(e, f + 2); end if;
  perform set_config('prueba.e250', e::text, false);
  perform set_config('prueba.f250', f::text, false);
  -- Otro igual, para la hora indicada a mano.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, f) returning id into e2;
  insert into envio_paradas (envio_id, orden, tipo, sitio_id, codigo_postal, poblacion, pais_codigo_iso)
    values (e2, 1, 'carga', s, '19001', 'Guadalajara', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e2, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set estado = 'programado' where id = e2;
  perform set_config('prueba.e250b', e2::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r jsonb; begin
  r := iniciar_difusion(current_setting('prueba.e250')::uuid, 500);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 250 · no se lanza: %', r; end if;
  r := iniciar_difusion(current_setting('prueba.e250b')::uuid, 500, 10::smallint, true, '11:00'::time);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 250 · no se lanza la de hora a mano: %', r; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e250')::uuid; e2 uuid := current_setting('prueba.e250b')::uuid; f date := current_setting('prueba.f250')::date; d record; begin
  select * into d from difusiones where envio_id = e and estado = 'activa';
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> (f + time '19:30') or d.corte_en <> d.carga_prevista_en or d.hora_manual is not null then
    raise exception 'FALLO 250 · la oferta no corre hasta el cierre del sitio (19:30): % · corte %', d.carga_prevista_en at time zone 'Europe/Madrid', d.corte_en at time zone 'Europe/Madrid';
  end if;
  -- Al mover la fecha al martes (cierra a las 13:00), la hora límite sigue al sitio.
  update envios set fecha_carga_desde = f + 1 where id = e;
  select * into d from difusiones where envio_id = e order by creado_en desc limit 1;
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> (f + 1 + time '13:00') then
    raise exception 'FALLO 250 · al mover la fecha no toma el cierre del nuevo día: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  -- La hora indicada a mano manda, también al mover la fecha.
  select * into d from difusiones where envio_id = e2 and estado = 'activa';
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> (f + time '11:00') or d.hora_manual <> time '11:00' then
    raise exception 'FALLO 250 · la hora indicada por Dynamo no manda: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  update envios set fecha_carga_desde = f + 1 where id = e2;
  select * into d from difusiones where envio_id = e2 order by creado_en desc limit 1;
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> (f + 1 + time '11:00') then
    raise exception 'FALLO 250 · al mover la fecha se pierde la hora indicada por Dynamo: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  raise notice 'OK 250 · la oferta escalonada sigue hasta el cierre del primer sitio de carga (o la hora que indique Dynamo), también al mover la fecha';
end $$;
update parametros set valor = '5.5'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '23.5'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = 'true'::jsonb where clave = 'bolsa_primero';
reset role;

-- ---- 251. Con ventana de carga, la oferta sigue hasta el cierre del ÚLTIMO día -------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = '0'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '24'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = 'false'::jsonb where clave = 'bolsa_primero';
do $$ declare e uuid; s uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; lun date; begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;   -- el lunes de dentro de dos semanas
  insert into sitios (nombre_empresa, cliente_id) values ('Almacen 251', current_setting('prueba.cliente')::uuid) returning id into s;
  delete from sitio_horarios where sitio_id = s;
  insert into sitio_horarios (sitio_id, dia_semana, abre, cierra) values (s, 1, '08:00', '18:00'), (s, 2, '08:00', '18:00'), (s, 3, '08:00', '15:00');
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, lun, lun + 2) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, sitio_id, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', s, '19001', 'Guadalajara', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 2, 'descarga', '16001', 'Cuenca', 'ES');
  update envios set estado = 'programado' where id = e;
  -- La función sola: lunes a miércoles → miércoles 15:00; lunes a jueves (jueves no abre) → miércoles 15:00;
  -- sin ventana → lunes 18:00; hora a mano → esa hora del último día; sin horario ningún día → último día 18:00.
  if (fn_difusion_limite(e, lun, lun + 2, null) at time zone 'Europe/Madrid') <> lun + 2 + time '15:00' then raise exception 'FALLO 251 · con ventana de lunes a miércoles el límite no es el cierre del miércoles'; end if;
  if (fn_difusion_limite(e, lun, lun + 3, null) at time zone 'Europe/Madrid') <> lun + 2 + time '15:00' then raise exception 'FALLO 251 · si el último día no abre, el límite debía ser el último día que abre'; end if;
  if (fn_difusion_limite(e, lun, null, null) at time zone 'Europe/Madrid') <> lun + time '18:00' then raise exception 'FALLO 251 · sin ventana el límite no es el cierre de ese día'; end if;
  if (fn_difusion_limite(e, lun, lun + 2, '11:00') at time zone 'Europe/Madrid') <> lun + 2 + time '11:00' then raise exception 'FALLO 251 · la hora a mano no cae en el último día de la ventana'; end if;
  if (fn_difusion_limite(e, lun + 5, lun + 6, null) at time zone 'Europe/Madrid') <> lun + 6 + time '18:00' then raise exception 'FALLO 251 · sin horario en toda la ventana no se usa el último día a la hora por defecto'; end if;
  perform set_config('prueba.e251', e::text, false);
  perform set_config('prueba.l251', lun::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r jsonb; begin
  r := iniciar_difusion(current_setting('prueba.e251')::uuid, 500);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 251 · no se lanza: %', r; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e251')::uuid; lun date := current_setting('prueba.l251')::date; d record; begin
  select * into d from difusiones where envio_id = e and estado = 'activa';
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> lun + 2 + time '15:00' or d.corte_en <> d.carga_prevista_en then
    raise exception 'FALLO 251 · la oferta lanzada no corre hasta el cierre del último día: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  -- El arranque sigue contando desde el PRIMER día (3 días antes del lunes).
  if (d.empieza_en at time zone 'Europe/Madrid')::date <> lun - 3 then raise exception 'FALLO 251 · el arranque no cuenta desde el primer día de la ventana: %', d.empieza_en at time zone 'Europe/Madrid'; end if;
  -- Acortar solo el final de la ventana (lunes a martes) recoloca el límite.
  update envios set fecha_carga_hasta = lun + 1 where id = e;
  select * into d from difusiones where envio_id = e order by creado_en desc limit 1;
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> lun + 1 + time '18:00' then
    raise exception 'FALLO 251 · al cambiar solo el final de la ventana el límite no se recoloca: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  raise notice 'OK 251 · con ventana de carga la oferta sigue hasta el cierre del último día que abre el sitio; el arranque cuenta desde el primero';
end $$;
update parametros set valor = '5.5'::jsonb  where clave = 'difusion_hora_inicio';
update parametros set valor = '23.5'::jsonb where clave = 'difusion_hora_fin';
update parametros set valor = 'true'::jsonb where clave = 'bolsa_primero';
reset role;

-- ---- 252. Firma en papel que completa el CMR digital (CMR bis) -----------------------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; pc uuid; pd uuid; doc uuid; otro uuid; begin
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 1) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '19001', 'Guadalajara', 'ES') returning id into pc;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '16001', 'Cuenca', 'ES') returning id into pd;
  update envios set estado = 'programado' where id = e;
  insert into documentos (tipo, envio_id, storage_ruta, nombre_archivo) values ('cmr_firmado', e, 'envios/' || e || '/x/cmr-bis.jpg', 'cmr-bis.jpg') returning id into doc;
  insert into documentos (tipo, envio_id, storage_ruta, nombre_archivo) values ('adjunto', e, 'envios/' || e || '/y/otra.jpg', 'otra.jpg') returning id into otro;
  perform set_config('prueba.e252', e::text, false); perform set_config('prueba.pd252', pd::text, false);
  perform set_config('prueba.doc252', doc::text, false); perform set_config('prueba.otro252', otro::text, false);
end $$;
-- Un cliente no registra firmas en papel.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform registrar_firma_papel(current_setting('prueba.e252')::uuid, current_setting('prueba.pd252')::uuid, 'Pepe', '12345678Z', 'ES', current_setting('prueba.doc252')::uuid);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 252 · un cliente registra una firma en papel'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e252')::uuid; pd uuid := current_setting('prueba.pd252')::uuid;
        doc uuid := current_setting('prueba.doc252')::uuid; r jsonb; begin
  -- Sin matrícula del camión, como en la firma digital, no se firma.
  r := registrar_firma_papel(e, pd, 'Pepe Destino', '12345678Z', 'ES', doc);
  if r ->> 'resultado' <> 'sin_matriculas' then raise exception 'FALLO 252 · se registra una firma en papel sin matrícula: %', r; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
update envios set matricula_camion = '2520ABC', matricula_remolque = 'R2520AB' where id = current_setting('prueba.e252')::uuid;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e252')::uuid; pd uuid := current_setting('prueba.pd252')::uuid;
        doc uuid := current_setting('prueba.doc252')::uuid; r jsonb; n int; begin
  -- Sin el documento escaneado (o con uno que no es un CMR firmado ni un albarán) no se registra.
  r := registrar_firma_papel(e, pd, 'Pepe Destino', '12345678Z', 'ES', current_setting('prueba.otro252')::uuid);
  if r ->> 'resultado' <> 'falta_documento' then raise exception 'FALLO 252 · vale cualquier adjunto como CMR en papel: %', r; end if;
  r := registrar_firma_papel(e, pd, '  ', '12345678Z', 'ES', doc);
  if r ->> 'resultado' <> 'faltan_datos' then raise exception 'FALLO 252 · se registra sin el nombre de quien firmó: %', r; end if;
  r := registrar_firma_papel(e, pd, 'Pepe Destino', '12.345.678-z', 'ES', doc);
  if r ->> 'resultado' <> 'ok' or r ->> 'rol' <> 'destinatario' then raise exception 'FALLO 252 · no se registra la firma en papel de la entrega: %', r; end if;
  if registrar_firma_papel(e, pd, 'Otra Vez', '12345678Z', 'ES', doc) ->> 'resultado' <> 'ya_firmada' then raise exception 'FALLO 252 · la misma parada se firma dos veces'; end if;
  select count(*) into n from firmas_envio(e) f where f.en_papel and f.rol = 'destinatario' and f.documento = '12345678Z' and f.documento_validado;
  if n <> 1 then raise exception 'FALLO 252 · la firma en papel no sale marcada en la lista de firmas del envío (%)', n; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e252')::uuid; ok boolean := false; j jsonb; begin
  -- Es una firma más del registro: no se cambia ni se borra.
  begin update firmas_cmr set nombre = 'Cambiado' where envio_id = e; exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 252 · una firma en papel registrada se puede cambiar'; end if;
  -- Una firma digital no puede marcarse «en papel» sin documento, ni al revés.
  ok := false;
  begin insert into firmas_cmr (envio_id, parada_id, rol, nombre, documento, firma_storage_ruta, en_papel)
        values (e, null, 'transportista', 'Tina', '00000000T', 'cmr/x/y.png', true);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 252 · se guarda una firma «en papel» sin su documento escaneado'; end if;
  -- El enlace público del CMR la trae marcada.
  select datos_cmr_por_token((select token from cmr_enlaces where envio_id = e and not revocado order by creado_en desc limit 1)) into j;
  if j is null or not exists (select 1 from jsonb_array_elements(j -> 'firmas') f where (f ->> 'en_papel')::boolean and f ->> 'rol' = 'destinatario') then
    raise exception 'FALLO 252 · el CMR público no marca la firma en papel: %', j -> 'firmas';
  end if;
  raise notice 'OK 252 · firma en papel (CMR bis): solo Dynamo, con el documento escaneado y con matrícula; completa el CMR digital, sale marcada y no se toca';
end $$;
reset role;

-- ---- 253. Nombre del remitente de los emails: «Dynamotrans.com» -----------------------------
do $$ declare n int; begin
  select count(*) into n from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.prosrc like '%''Dynamo <%';
  if n <> 0 then raise exception 'FALLO 253 · quedan % funciones que mandan emails con el remitente «Dynamo»', n; end if;
  select count(*) into n from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname = 'enviar_emails_pendientes' and p.prosrc like '%''Dynamotrans.com''), parametro(''dynamo_email'')%';
  if n <> 1 then raise exception 'FALLO 253 · la cola de emails no sale con el remitente «Dynamotrans.com»'; end if;
  raise notice 'OK 253 · los emails de la cola salen con el nombre de remitente «Dynamotrans.com»';
end $$;

-- ---- 254. La oferta escalonada sigue a la ruta: otro primer sitio de carga, otra hora límite --
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e251')::uuid; lun date := current_setting('prueba.l251')::date; s uuid; d record; begin
  -- Viene de la 251: ventana de lunes a martes, límite el martes a las 18:00.
  select * into d from difusiones where envio_id = e and estado = 'activa';
  if d.id is null or (d.carga_prevista_en at time zone 'Europe/Madrid') <> lun + 1 + time '18:00' then raise exception 'FALLO 254 · la oferta de partida no es la esperada'; end if;
  insert into sitios (nombre_empresa, cliente_id) values ('Almacen 254', current_setting('prueba.cliente')::uuid) returning id into s;
  delete from sitio_horarios where sitio_id = s;
  insert into sitio_horarios (sitio_id, dia_semana, abre, cierra) values (s, 1, '07:00', '14:00'), (s, 2, '07:00', '13:00');
  update envio_paradas set sitio_id = s where envio_id = e and tipo = 'carga';
  select * into d from difusiones where id = d.id;
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> lun + 1 + time '13:00' or d.corte_en <> d.carga_prevista_en then
    raise exception 'FALLO 254 · al cambiar el sitio de carga la hora límite no pasa al cierre del sitio nuevo: %', d.carga_prevista_en at time zone 'Europe/Madrid';
  end if;
  -- Con la hora puesta a mano por Dynamo, la ruta no la mueve.
  update difusiones set hora_manual = '11:00', carga_prevista_en = (lun + 1 + time '11:00') at time zone 'Europe/Madrid' where id = d.id;
  update envio_paradas set sitio_id = null where envio_id = e and tipo = 'carga';
  select * into d from difusiones where id = d.id;
  if (d.carga_prevista_en at time zone 'Europe/Madrid') <> lun + 1 + time '11:00' then raise exception 'FALLO 254 · la ruta mueve una hora límite puesta a mano'; end if;
  raise notice 'OK 254 · al cambiar la ruta, la oferta toma el cierre del nuevo primer sitio de carga; la hora a mano no se toca';
end $$;

-- ---- 255. Indicaciones del sitio: un solo campo (sin «info de mercancía por defecto») -------
do $$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'sitios' and column_name = 'mercancia_defecto') then
    raise exception 'FALLO 255 · el sitio sigue teniendo el campo de mercancía por defecto aparte';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'sitios' and column_name = 'anotaciones') then
    raise exception 'FALLO 255 · el sitio se ha quedado sin sus indicaciones';
  end if;
  raise notice 'OK 255 · el sitio tiene un solo campo de texto fijo: sus indicaciones';
end $$;

-- ---- 256. Emails al cliente sobre su envío: creado, víspera (solo con transportista), matrículas, modificado y cancelado ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; m uuid; r record; n int; cli uuid := current_setting('prueba.cliente')::uuid;
  adm uuid := current_setting('prueba.u_admin')::uuid; v_cli text; v_adm text;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;   -- el lunes de dentro de dos semanas
  select email into v_cli from usuarios where id = current_setting('prueba.u_cli')::uuid;
  select email into v_adm from usuarios where id = adm;
  -- Lo crea DYNAMO para el cliente: el email va al usuario del cliente, no a quien lo creó.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1, adm) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  if exists (select 1 from emails_enviados where clave = 'envio_creado:' || e) then raise exception 'FALLO 256 · el email sale con el envío aún sin confirmar'; end if;
  update envios set estado = 'programado' where id = e;
  select * into r from emails_enviados where clave = 'envio_creado:' || e;
  if r.id is null or r.tipo <> 'envio_creado' or r.estado <> 'pendiente' then raise exception 'FALLO 256 · al confirmar el envío no se encola el email «Envío creado»'; end if;
  if position('buscamos el camión' in r.cuerpo_html) > 0 or position('Tu envío ya está <strong>creado</strong>.</p>' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 256 · el email «Envío creado» no lleva el texto corto: %', r.cuerpo_html;
  end if;
  if position(v_cli in r.destinatario) = 0 or position(v_adm in r.destinatario) > 0 then raise exception 'FALLO 256 · el email no va al usuario del cliente: %', r.destinatario; end if;
  if r.asunto not like 'Envío creado · envío #% (Sevilla → Coslada)' then raise exception 'FALLO 256 · asunto: %', r.asunto; end if;
  if position('900,00' in r.cuerpo_html) = 0 or position('13,30 metros' in r.cuerpo_html) = 0 or position('/panel/envios?ver=' || e in r.cuerpo_html) = 0 then
    raise exception 'FALLO 256 · al email le falta el precio, la mercancía o el enlace a la ficha: %', r.cuerpo_html;
  end if;
  -- Una sola vez por envío.
  perform registrar_hito(e, 'confirmado');
  select count(*) into n from emails_enviados where envio_id = e and tipo = 'envio_creado';
  if n <> 1 then raise exception 'FALLO 256 · el email «Envío creado» se repite (%)', n; end if;
  if position('Recogida' in r.cuerpo_html) = 0 or position('Asignando transporte.' in r.cuerpo_html) = 0 or position('Transporte:' in r.cuerpo_html) > position('Precio:' in r.cuerpo_html) then raise exception 'FALLO 256 · al email le falta el detalle del envío (ruta y transporte): %', r.cuerpo_html; end if;
  -- SIN transportista no hay recordatorio de la víspera, aunque tenga fecha.
  perform encolar_avisos_operativos(((lun - 1) + time '17:30') at time zone 'Europe/Madrid');
  if exists (select 1 from emails_enviados where clave = 'vispera:' || e || ':' || lun) then raise exception 'FALLO 256 · sale la víspera de un envío sin transportista'; end if;
  -- Se asigna transportista CON matrículas en la misma operación: no sale el email de
  -- matrículas (van en el de «Transporte confirmado», que manda la web).
  update envios set transportista_id = current_setting('prueba.transp')::uuid, matricula_camion = '1234BBB', fecha_carga_prevista = lun where id = e;
  if exists (select 1 from emails_enviados where envio_id = e and tipo = 'envio_matriculas') then raise exception 'FALLO 256 · sale el email de matrículas cuando se pusieron al asignar el transportista'; end if;
  -- Ya con transportista, la víspera va a los mismos destinatarios: al cliente, aunque el envío lo creara Dynamo.
  perform encolar_avisos_operativos(((lun - 1) + time '17:30') at time zone 'Europe/Madrid');
  select * into r from emails_enviados where clave = 'vispera:' || e || ':' || lun;
  if r.id is null or position(v_cli in r.destinatario) = 0 then raise exception 'FALLO 256 · la víspera no va al usuario del cliente: %', r.destinatario; end if;
  -- Cambian las matrículas después: ahora sí, un email (y otro si vuelven a cambiar).
  update envios set matricula_camion = '5678CCC', matricula_remolque = 'R1234BBB' where id = e;
  select * into r from emails_enviados where envio_id = e and tipo = 'envio_matriculas';
  if r.id is null or r.asunto not like 'Matrículas cambiadas · envío #%' or position('5678CCC' in r.cuerpo_html) = 0 or position('R1234BBB' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 256 · no sale el email de matrículas al cambiarlas con el transportista ya asignado: %', r.asunto;
  end if;
  -- MODIFICADO: dos cambios en la misma operación van en UN email, con el antes y el ahora.
  update envios set toneladas = 22 where id = e;
  update envios set importe_cliente = 950 where id = e;
  select count(*) into n from emails_enviados where envio_id = e and tipo = 'envio_modificado';
  if n <> 1 then raise exception 'FALLO 256 · dos cambios seguidos deben ir en un solo email de modificado (%)', n; end if;
  select * into r from emails_enviados where envio_id = e and tipo = 'envio_modificado';
  if position('20,00 toneladas' in r.cuerpo_html) = 0 or position('22,00 toneladas' in r.cuerpo_html) = 0
     or position('900,00' in r.cuerpo_html) = 0 or position('950,00' in r.cuerpo_html) = 0 or position('Camión 5678CCC' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 256 · el email de modificado no trae el antes y el ahora de la mercancía y del precio, o el detalle al día: %', r.cuerpo_html;
  end if;
  if (select count(*) from regexp_matches(r.cuerpo_html, '<!--detalle-->', 'g')) <> 1 or (select count(*) from regexp_matches(r.cuerpo_html, 'Datos del envío', 'g')) <> 1 then
    raise exception 'FALLO 256 · el email de modificado repite el detalle al juntar cambios: %', r.cuerpo_html;
  end if;
  -- CANCELADO: un email, con el motivo que se anota después.
  update envios set estado = 'cancelado' where id = e;
  perform registrar_hito(e, 'incidencia', null, null, jsonb_build_object('motivo_cancelacion', 'El cliente ya no tiene la mercancía', 'por', 'dynamo'));
  select * into r from emails_enviados where envio_id = e and tipo = 'envio_cancelado';
  if r.id is null or r.asunto not like 'Envío cancelado · envío #%' or position('El cliente ya no tiene la mercancía' in r.cuerpo_html) = 0 or position(v_cli in r.destinatario) = 0 then
    raise exception 'FALLO 256 · no sale el email de cancelado con su motivo: % · %', r.asunto, r.cuerpo_html;
  end if;
  -- En un envío de gestión directa (el cliente con su transportista) no sale.
  insert into operadores (cliente_id, razon_social, cif) values (cli, 'Operador 256 SL', 'B25600256') returning id into m;
  insert into envios (cliente_id, metros_lineales, operador_id, precio_acordado_operador, fecha_carga_desde) values (cli, 13.30, m, 500, lun) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  if exists (select 1 from emails_enviados where clave = 'envio_creado:' || e) then raise exception 'FALLO 256 · el email sale en un envío de gestión directa'; end if;
  raise notice 'OK 256 · emails al cliente: creado (con detalle), víspera solo con transportista, matrículas si llegan después, modificado con antes y ahora en un solo email, cancelado con motivo; no en gestión directa';
end $$;

-- ---- 257. Email «Envío reactivado» al deshacer una cancelación ya comunicada --------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; cli uuid := current_setting('prueba.cliente')::uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; lun date; begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 14;   -- un lunes a más de dos semanas: cancelar no cuesta
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, creado_por)
    values (cli, 13.30, 20, 900, 700, lun, current_setting('prueba.u_admin')::uuid) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('prueba.e257', e::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e257')::uuid; begin
  -- Cancelado y deshecho al momento (por error): el cliente no debe recibir nada.
  perform cancelar_envio(e, 'Error al cancelar');
  perform deshacer_cancelacion(e);
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e257')::uuid; begin
  if (select count(*) from emails_enviados where envio_id = e and tipo = 'envio_cancelado' and estado = 'omitido') <> 1 then
    raise exception 'FALLO 257 · al deshacer al momento, el email de cancelado sin mandar no se anula';
  end if;
  if exists (select 1 from emails_enviados where envio_id = e and tipo = 'envio_reactivado') then
    raise exception 'FALLO 257 · sale «reactivado» cuando la cancelación no se llegó a comunicar';
  end if;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ begin perform cancelar_envio(current_setting('prueba.e257')::uuid, 'Ahora sí'); end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e257')::uuid; n int; begin
  -- La segunda cancelación (en el mismo minuto) tiene su propio email, y ese «ya ha salido».
  update emails_enviados set estado = 'enviado', enviado_en = now() where envio_id = e and tipo = 'envio_cancelado' and estado = 'pendiente';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'FALLO 257 · volver a cancelar en el mismo minuto no encola su email de cancelado (%)', n; end if;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ begin perform deshacer_cancelacion(current_setting('prueba.e257')::uuid); end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e257')::uuid; r record; v_cli text; begin
  select email into v_cli from usuarios where id = current_setting('prueba.u_cli')::uuid;
  select * into r from emails_enviados where envio_id = e and tipo = 'envio_reactivado';
  if r.id is null or r.estado <> 'pendiente' or r.asunto not like 'Envío reactivado · envío #% (Sevilla → Coslada)'
     or position(v_cli in r.destinatario) = 0 or position('Datos del envío' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 257 · al deshacer una cancelación ya comunicada no sale «Envío reactivado» al cliente: % · %', r.asunto, r.destinatario;
  end if;
  raise notice 'OK 257 · envío reactivado: email al cliente al deshacer una cancelación ya comunicada; si no se llegó a comunicar, se anula el de cancelado y no sale ninguno';
end $$;

-- ---- 258. Emails de crédito al cliente: cambios de la línea y avisos de uso, sin importes ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid; uc uuid; v_cli text := 'credito258@cliente.prueba'; r record; n int; u record;
  e uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  -- Un cliente nuevo, con su usuario, para que no arrastre avisos de otras pruebas.
  insert into clientes (razon_social, cif) values ('Cliente Crédito 258 SL', 'B25800258') returning id into cli;
  insert into auth.users (email) values (v_cli) returning id into uc;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = cli where id = uc;
  update clientes set riesgo_cesce_euros = null, riesgo_manual_euros = null, exento_pago_previo_primer_envio = true where id = cli;
  if exists (select 1 from emails_enviados where clave like 'credito_%:' || cli || ':%') then raise exception 'FALLO 258 · avisa de crédito a un cliente que nunca lo ha tenido'; end if;
  -- Sin crédito → CESCE concede: «concedida», nombrando a CESCE y sin importes.
  update clientes set riesgo_cesce_euros = 1000000 where id = cli;
  select * into r from emails_enviados where clave like 'credito_cambio:' || cli || ':%' order by clave desc limit 1;
  if r.id is null or r.asunto <> 'Línea de crédito concedida · Dynamo' or r.destinatario <> v_cli or position('CESCE' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 258 · al conceder crédito CESCE no sale «línea concedida» al cliente: %', r.asunto;
  end if;
  if position('1000000' in r.cuerpo_html) > 0 or position('1.000.000' in r.cuerpo_html) > 0 then raise exception 'FALLO 258 · el email de crédito enseña el importe del límite'; end if;
  update clientes set riesgo_cesce_euros = 2000000 where id = cli;
  if (select asunto from emails_enviados where clave like 'credito_cambio:' || cli || ':%' order by clave desc limit 1) <> 'Línea de crédito ampliada · Dynamo' then
    raise exception 'FALLO 258 · al subir el límite no sale «línea ampliada»';
  end if;
  -- Un envío a crédito confirmado, para que haya uso.
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (cli, 13.30, 20, 1000, 800, lun) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  select * into u from credito_uso_cliente(cli);
  if coalesce(u.usado, 0) <> 1210 then raise exception 'FALLO 258 · el uso de la línea no cuenta el envío confirmado con su IVA: %', u; end if;
  if exists (select 1 from emails_enviados where clave like 'credito_aviso:' || cli || ':%') then raise exception 'FALLO 258 · avisa de uso con la línea casi sin tocar (%)', u.pct; end if;
  -- El crédito MANUAL de Dynamo manda: lo baja hasta dejar el uso al 90 % → «reducida» + «cerca del límite».
  update clientes set riesgo_manual_euros = round(u.usado / 0.9, 2) where id = cli;
  select * into r from emails_enviados where clave like 'credito_cambio:' || cli || ':%' order by clave desc limit 1;
  if r.asunto <> 'Línea de crédito reducida · Dynamo' or position('CESCE' in r.cuerpo_html) > 0 then raise exception 'FALLO 258 · al bajar el límite con crédito manual: % (no debe nombrar a CESCE)', r.asunto; end if;
  select * into r from emails_enviados where clave like 'credito_aviso:' || cli || ':%';
  if r.id is null or r.asunto not like 'Estás cerca del límite%' or r.destinatario <> v_cli or position('facturas pendientes' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 258 · al 90 %% de uso no sale «cerca del límite»: %', r.asunto;
  end if;
  -- Repetir la revisión no repite el aviso.
  perform credito_revisar_uso(cli);
  select count(*) into n from emails_enviados where clave like 'credito_aviso:' || cli || ':%';
  if n <> 1 then raise exception 'FALLO 258 · el aviso de uso se repite (%)', n; end if;
  -- Por debajo de lo usado → «límite alcanzado», y el de «cerca» sin mandar se anula.
  update clientes set riesgo_manual_euros = round(u.usado / 2, 2) where id = cli;
  select * into r from emails_enviados where clave like 'credito_aviso:' || cli || ':alcanzado:%';
  if r.id is null or r.estado <> 'pendiente' or r.asunto not like 'Has alcanzado el límite%' or position('liquides las facturas pendientes' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 258 · con el límite superado no sale «límite alcanzado»: %', r.asunto;
  end if;
  -- Y dice lo que pasa de verdad: lo que no quepa se paga por adelantado (ya no «es posible que»).
  if position('se pagarán por adelantado' in r.cuerpo_html) = 0 or position('es posible que' in r.cuerpo_html) > 0 then
    raise exception 'FALLO 258 · el email de «límite alcanzado» no dice que lo que no quepa se paga por adelantado';
  end if;
  if (select estado from emails_enviados where clave like 'credito_aviso:' || cli || ':cerca:%') <> 'omitido' then
    raise exception 'FALLO 258 · el aviso de «cerca» pendiente no se anula al llegar el de «alcanzado»';
  end if;
  -- Retirada: sin manual y con CESCE a 0.
  update clientes set riesgo_manual_euros = null, riesgo_cesce_euros = 0 where id = cli;
  if (select asunto from emails_enviados where clave like 'credito_cambio:' || cli || ':%' order by clave desc limit 1) <> 'Línea de crédito retirada · Dynamo' then
    raise exception 'FALLO 258 · al quitar el crédito no sale «línea retirada»';
  end if;
  select count(*) into n from emails_enviados where clave like 'credito_cambio:' || cli || ':%';
  update clientes set riesgo_cesce_euros = null where id = cli;   -- de 0 a sin clasificar: sigue sin crédito, no es noticia
  if (select count(*) from emails_enviados where clave like 'credito_cambio:' || cli || ':%') <> n then raise exception 'FALLO 258 · avisa de un cambio entre «sin crédito» y «sin clasificar»'; end if;
  -- Apagados en Parámetros, no sale ninguno.
  update parametros set valor = 'false'::jsonb where clave = 'credito_emails_activo';
  update clientes set riesgo_cesce_euros = 500000 where id = cli;
  if (select count(*) from emails_enviados where clave like 'credito_cambio:' || cli || ':%') <> n then raise exception 'FALLO 258 · con los emails de crédito apagados sigue saliendo'; end if;
  update parametros set valor = 'true'::jsonb where clave = 'credito_emails_activo';
  raise notice 'OK 258 · emails de crédito: concedida, ampliada, reducida y retirada (CESCE o manual), cerca del límite y límite alcanzado, sin importes, sin repetir y apagables';
end $$;

-- ---- 259. El cliente modifica su envío entero (ruta, mercancía, fechas y precio) mientras no tenga transportista ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false' where clave = 'pago_previo_activo';
do $$ declare e uuid; f uuid; g uuid; h uuid; i uuid; begin
  -- e: libre y publicado en bolsa · f: con transportista · g: pagado por adelantado · h: carga hoy (pasada la hora límite de cancelar)
  -- i: con un transportista asignándose ahora (reserva en curso)
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 6, 5, 600, sumar_dias_habiles(current_date, 4), sumar_dias_habiles(current_date, 5)) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 6, 5, 600, sumar_dias_habiles(current_date, 4), sumar_dias_habiles(current_date, 5)) returning id into f;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 6, 5, 600, sumar_dias_habiles(current_date, 4), sumar_dias_habiles(current_date, 5)) returning id into g;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 6, 5, 600, current_date, current_date) returning id into h;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (current_setting('prueba.cliente')::uuid, 6, 5, 600, sumar_dias_habiles(current_date, 4), sumar_dias_habiles(current_date, 5)) returning id into i;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, nombre_empresa)
    select x, o, t, cp, p, n from unnest(array[e, f, g, h, i]) x,
      (values (1, 'carga', '41001', 'Sevilla', 'Nave Sevilla'), (2, 'descarga', '46001', 'Valencia', 'Nave Valencia')) v(o, t, cp, p, n);
  perform set_config('request.jwt.claim.sub', '', false);
  update envios set estado = 'programado' where id in (e, f, g, h, i);
  insert into envio_reservas (envio_id, hasta, transportista_id) values (i, now() + interval '3 minutes', current_setting('prueba.transp')::uuid);
  perform set_config('prueba.i259', i::text, false);
  update envios set transportista_id = current_setting('prueba.transp')::uuid where id = f;
  update envios set estado_pago_previo = 'pagado', pago_metodo = 'transferencia', pagado_en = now() where id = g;
  update envios set publicado_en_bolsa_en = now() where id = e;
  perform set_config('prueba.e259', e::text, false); perform set_config('prueba.f259', f::text, false);
  perform set_config('prueba.g259', g::text, false); perform set_config('prueba.h259', h::text, false);
  perform set_config('prueba.p259', (select id::text from envio_paradas where envio_id = e and orden = 1), false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e259')::uuid; r jsonb; d jsonb; ok boolean; x record; ruta jsonb; tot numeric; begin
  -- Ruta nueva (la recogida sigue, la entrega cambia), más metros y el precio que da el
  -- tarifador (desde el 2026-11-23 la base de datos no admite otro); la fecha no se toca.
  ruta := jsonb_build_array(jsonb_build_object('id', current_setting('prueba.p259')),
         jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Nave Getafe', 'poblacion', 'Getafe', 'codigo_postal', '28901'));
  d := prueba.con_precio(jsonb_build_object('fecha_carga_desde', sumar_dias_habiles(current_date, 4), 'fecha_carga_hasta', sumar_dias_habiles(current_date, 5),
                          'metros_lineales', 8, 'toneladas', 10, 'referencia_cliente', 'PED-259'), ruta, e);
  r := modificar_envio_cliente(e, d, ruta);
  if r->>'resultado' <> 'modificado' or (r->>'precio_antes')::numeric <> 600 or (r->>'precio_ahora')::numeric <> (d ->> 'importe_cliente')::numeric then
    raise exception 'FALLO 259 · el cliente no puede modificar su envío sin transportista: %', r;
  end if;
  perform set_config('prueba.precio259a', d ->> 'importe_cliente', false);
  -- Cambiar la fecha con tiempo: vale, con las reglas de un envío nuevo.
  d := prueba.con_precio(d || jsonb_build_object('fecha_carga_desde', sumar_dias_habiles(current_date, 8), 'fecha_carga_hasta', sumar_dias_habiles(current_date, 9)), null, e);
  perform set_config('prueba.precio259', d ->> 'importe_cliente', false);
  perform modificar_envio_cliente(e, d, null);
  -- Una fecha que ya no llega al corte no entra.
  ok := false;
  begin perform modificar_envio_cliente(e, d || jsonb_build_object('fecha_carga_desde', current_date - 1, 'fecha_carga_hasta', current_date - 1), null);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 259 · el cliente pone una fecha de carga pasada al modificar'; end if;
  -- Con transportista: no.
  ok := false;
  begin perform modificar_envio_cliente(current_setting('prueba.f259')::uuid, d, null);
  exception when others then ok := sqlerrm like '%transportista asignado%'; end;
  if not ok then raise exception 'FALLO 259 · el cliente modifica un envío con transportista asignado'; end if;
  -- Pagado por adelantado (600 € + 21 % = 726 €) y el precio SUBE al del tarifador (más de
  -- 700 €): lo pagado queda a cuenta y falta la diferencia; el envío vuelve a pendiente de pago.
  d := prueba.con_precio(jsonb_build_object('fecha_carga_desde', sumar_dias_habiles(current_date, 4), 'fecha_carga_hasta', sumar_dias_habiles(current_date, 5),
                          'metros_lineales', 6, 'toneladas', 5, 'referencia_cliente', 'PED-G'), null, current_setting('prueba.g259')::uuid);
  tot := round((d ->> 'importe_cliente')::numeric * 1.21, 2);
  if tot <= 726 then raise exception 'FALLO 259 · la prueba necesita que el precio suba (tarifador: %)', d ->> 'importe_cliente'; end if;
  perform set_config('prueba.total259', tot::text, false);
  r := modificar_envio_cliente(current_setting('prueba.g259')::uuid, d, null);
  if (r->>'falta_pagar')::numeric <> tot - 726 or (r->>'pagado_de_mas')::numeric <> 0 then
    raise exception 'FALLO 259 · pagado y el precio sube: no calcula bien la diferencia que falta: %', r;
  end if;
  select * into x from pagos_envio(current_setting('prueba.g259')::uuid);
  if x.estado_pago_previo <> 'pendiente' or x.a_cuenta <> 726 or x.pendiente <> tot - 726 or x.total <> tot or x.pago_limite is not null then
    raise exception 'FALLO 259 · pagado y el precio sube: el envío no queda pendiente por la diferencia (sin hora límite): %', x;
  end if;
  -- Un transportista asignándose ahora mismo: ni modificar ni cancelar.
  if not mi_envio_asignandose(current_setting('prueba.i259')::uuid) or mi_envio_asignandose(e) then
    raise exception 'FALLO 259 · la ficha no distingue el envío con un transportista asignándose';
  end if;
  ok := false;
  begin perform modificar_envio_cliente(current_setting('prueba.i259')::uuid, d, null);
  exception when others then ok := sqlerrm like '%se está asignando%'; end;
  if not ok then raise exception 'FALLO 259 · el cliente modifica un envío con un transportista asignándose'; end if;
  ok := false;
  begin perform cancelar_mi_envio(current_setting('prueba.i259')::uuid, 'ya no lo quiero');
  exception when others then ok := sqlerrm like '%se está asignando%'; end;
  if not ok then raise exception 'FALLO 259 · el cliente cancela un envío con un transportista asignándose'; end if;
  -- Pasada la hora límite de cancelar: sin transportista es como un envío nuevo, también la
  -- fecha (usuario, 2026-11-16: «si cancelar no tenía coste, modificar tampoco»).
  d := prueba.con_precio(jsonb_build_object('fecha_carga_desde', current_date, 'fecha_carga_hasta', current_date, 'metros_lineales', 7, 'toneladas', 5),
                         null, current_setting('prueba.h259')::uuid);
  perform modificar_envio_cliente(current_setting('prueba.h259')::uuid, d, null);
  -- A una fecha fija dentro de 60 días (con su suplemento de fecha fija).
  d := prueba.con_precio(d || jsonb_build_object('fecha_carga_desde', sumar_dias_habiles(current_date, 60), 'fecha_carga_hasta', sumar_dias_habiles(current_date, 60)),
                         null, current_setting('prueba.h259')::uuid);
  perform set_config('prueba.precio259h', d ->> 'importe_cliente', false);
  perform modificar_envio_cliente(current_setting('prueba.h259')::uuid, d, null);
  -- La función interna de la ruta no se puede llamar desde fuera.
  ok := false;
  begin perform ruta_envio_reemplazar(e, '[]'::jsonb); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 259 · un cliente llama a la función interna que cambia la ruta'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
-- (g queda pagado del todo más abajo, con la tarjeta.) Pagado y el precio BAJA: sigue
-- pagado y Dynamo recibe el aviso de lo pagado de más. Se prueba con h, que se da por pagado.
update envios set estado_pago_previo = 'pagado', pago_metodo = 'transferencia', pagado_en = now() where id = current_setting('prueba.h259')::uuid;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare r jsonb; d jsonb; sobra numeric; begin
  -- h está con fecha fija y pasa a una ventana de 1 a 4 días el mismo día: sin el suplemento
  -- de fecha fija el precio baja, y sobra la diferencia (con IVA).
  d := prueba.con_precio(jsonb_build_object('fecha_carga_desde', sumar_dias_habiles(current_date, 60),
         'fecha_carga_hasta', sumar_dias_habiles(current_date, 63), 'metros_lineales', 7, 'toneladas', 5), null, current_setting('prueba.h259')::uuid);
  sobra := round(current_setting('prueba.precio259h')::numeric * 1.21, 2) - round((d ->> 'importe_cliente')::numeric * 1.21, 2);
  if sobra <= 0 then raise exception 'FALLO 259 · la prueba necesita que el precio baje (% → %)', current_setting('prueba.precio259h'), d ->> 'importe_cliente'; end if;
  r := modificar_envio_cliente(current_setting('prueba.h259')::uuid, d, null);
  if (r->>'pagado_de_mas')::numeric <> sobra or (r->>'falta_pagar')::numeric <> 0 then
    raise exception 'FALLO 259 · pagado y el precio baja: no calcula lo pagado de más: %', r;
  end if;
  if (select estado_pago_previo from pagos_envio(current_setting('prueba.h259')::uuid)) <> 'pagado' then
    raise exception 'FALLO 259 · pagado y el precio baja: deja de estar pagado';
  end if;
end $$;
-- Un cliente de OTRA empresa no toca este envío.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
do $$ declare ok boolean := false; begin
  begin perform modificar_envio_cliente(current_setting('prueba.e259')::uuid, jsonb_build_object('importe_cliente', 1, 'fecha_carga_desde', current_date), null);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 259 · un cliente modifica el envío de otro'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e259')::uuid; a record; x record; begin
  select importe_cliente, metros_lineales, referencia_cliente, fecha_carga_desde into x from envios where id = e;
  if x.importe_cliente <> current_setting('prueba.precio259')::numeric or x.metros_lineales <> 8 or x.referencia_cliente <> 'PED-259' then
    raise exception 'FALLO 259 · la modificación no guarda precio, mercancía o referencia: %', x;
  end if;
  if x.fecha_carga_desde <> sumar_dias_habiles(current_date, 8) then raise exception 'FALLO 259 · el cliente no puede cambiar la fecha con tiempo'; end if;
  if (select poblacion from envio_paradas where envio_id = e and orden = 2) <> 'Getafe'
     or (select id from envio_paradas where envio_id = e and orden = 1) <> current_setting('prueba.p259')::uuid then
    raise exception 'FALLO 259 · la ruta nueva no queda guardada (o pierde la parada que seguía)';
  end if;
  if (select referencia_cliente from envios where id = current_setting('prueba.g259')::uuid) is distinct from 'PED-G' then
    raise exception 'FALLO 259 · con el envío pagado no guarda la modificación';
  end if;
  -- Con la diferencia sin pagar no se oferta, publica ni asigna; y no se anula solo.
  begin
    update envios set publicado_en_bolsa_en = now() where id = current_setting('prueba.g259')::uuid;
    raise exception 'FALLO 259 · se publica un envío al que le falta pagar la diferencia';
  exception when insufficient_privilege then null; end;
  update envios set pago_pendiente_en = now() - interval '30 days' where id = current_setting('prueba.g259')::uuid;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = current_setting('prueba.g259')::uuid) <> 'programado' then
    raise exception 'FALLO 259 · se anula por falta de pago un envío ya pagado en parte';
  end if;
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'envio_modificado_cliente' and nivel = 'urgente'
                    and envio_id = current_setting('prueba.g259')::uuid
                    and texto like '%le faltan ' || euros_texto(current_setting('prueba.total259')::numeric - 726) || '%') then
    raise exception 'FALLO 259 · Dynamo no se entera de que falta pagar la diferencia';
  end if;
  -- La tarjeta cobra SOLO la diferencia, no el total.
  if (pago_envio_stripe(current_setting('prueba.g259')::uuid, 'pi_259a', (current_setting('prueba.total259')::numeric * 100)::int))->>'resultado' <> 'importe_distinto' then
    raise exception 'FALLO 259 · la tarjeta acepta el total de un envío ya pagado en parte';
  end if;
  update envios set stripe_cobro_sin_aplicar = null where id = current_setting('prueba.g259')::uuid;
  x := null;
  select pago_envio_stripe(current_setting('prueba.g259')::uuid, 'pi_259b', ((current_setting('prueba.total259')::numeric - 726) * 100)::int) as r into x;
  if x.r->>'resultado' <> 'ok' or (select estado_pago_previo from envios where id = current_setting('prueba.g259')::uuid) <> 'pagado' then
    raise exception 'FALLO 259 · pagar la diferencia con tarjeta no deja el envío pagado: % · %', x.r, (select estado_pago_previo from envios where id = current_setting('prueba.g259')::uuid);
  end if;
  if (select metros_lineales from envios where id = current_setting('prueba.h259')::uuid) <> 7
     or (select fecha_carga_desde from envios where id = current_setting('prueba.h259')::uuid) <> sumar_dias_habiles(current_date, 60) then
    raise exception 'FALLO 259 · sin transportista y pasada la hora límite, no deja cambiar la mercancía o la fecha';
  end if;
  -- Dynamo se entera, con el antes → ahora del precio; y como estaba en la bolsa, se le dice.
  select * into a from avisos where para = 'dynamo' and tipo = 'envio_modificado_cliente' and envio_id = e order by creado_en, id limit 1;
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'envio_modificado_cliente' and envio_id = e
                    and texto like '%ruta nueva%' and texto like '%600,00 € → ' || euros_texto(current_setting('prueba.precio259a')::numeric) || '%' and texto like '%en la bolsa%') then
    raise exception 'FALLO 259 · Dynamo no recibe el aviso del envío modificado por el cliente: %', a.texto;
  end if;
  -- El cliente recibe su email «Envío modificado».
  if not exists (select 1 from emails_enviados where tipo = 'envio_modificado' and envio_id = e) then
    raise exception 'FALLO 259 · el cliente no recibe el email del envío modificado';
  end if;
  raise notice 'OK 259 · el cliente modifica su envío entero sin transportista (ruta, mercancía, fechas y precio); también la fecha pasada la hora límite de cancelar; pagado y sube: paga solo la diferencia y no sigue hasta pagarla; con transportista (o con uno asignándose), no';
end $$;

-- ---- 260. Crédito insuficiente: el envío que no cabe en el crédito que queda se paga por adelantado ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'true' where clave = 'pago_previo_activo';
do $$ declare cli uuid; uc uuid; a uuid; b uuid; c uuid; d uuid; r jsonb; x record;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  insert into clientes (razon_social, cif) values ('Cliente Crédito 260 SL', 'B26000260') returning id into cli;
  insert into auth.users (email) values ('credito260@cliente.prueba') returning id into uc;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = cli where id = uc;
  -- CESCE da 5.000 € pero Dynamo lo limita a mano a 1.000 €: manda el manual.
  update clientes set riesgo_cesce_euros = 5000, riesgo_manual_euros = 1000, exento_pago_previo_primer_envio = true where id = cli;
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 1000 then raise exception 'FALLO 260 · el crédito manual de Dynamo no manda sobre el de CESCE'; end if;
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  -- a: 600 € (726 € con IVA). Cabe en 1.000 €: va a crédito.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 600, lun) returning id into a;
  -- b: 400 € (484 €). Quedan 274 €: NO cabe → pendiente de pago.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 400, lun) returning id into b;
  -- c: 200 € (242 €). Cabe (726 + 242 = 968): a crédito. El pendiente (b) no gasta crédito.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 200, lun) returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 400, lun) returning id into d;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select e, o, t, cp, p, 'ES' from unnest(array[a, b, c, d]) e,
      (values (1, 'carga', '41001', 'Sevilla'), (2, 'descarga', '28821', 'Coslada')) v(o, t, cp, p);
  update envios set estado = 'programado' where id = a;
  if (select estado_pago_previo from envios where id = a) <> 'no_requerido' then raise exception 'FALLO 260 · un envío que cabe en el crédito se manda a pago por adelantado'; end if;
  update envios set estado = 'programado' where id = b;
  select estado_pago_previo, pago_motivo into x from envios where id = b;
  if x.estado_pago_previo <> 'pendiente' or x.pago_motivo not like 'Crédito insuficiente%' then
    raise exception 'FALLO 260 · un envío que NO cabe en el crédito que queda va a crédito igualmente: %', x;
  end if;
  if x.pago_motivo ~ '[0-9]' then raise exception 'FALLO 260 · el motivo del pago enseña importes de crédito: %', x.pago_motivo; end if;
  update envios set estado = 'programado' where id = c;
  if (select estado_pago_previo from envios where id = c) <> 'no_requerido' then raise exception 'FALLO 260 · el envío pendiente de pago gasta crédito (el siguiente que cabe no entra)'; end if;
  -- Apagado en Parámetros: con crédito concedido no se pide pago por pasarse.
  update parametros set valor = 'false'::jsonb where clave = 'credito_limite_exige_pago';
  update envios set estado = 'programado' where id = d;
  if (select estado_pago_previo from envios where id = d) <> 'no_requerido' then raise exception 'FALLO 260 · con la regla apagada sigue pidiendo pago por pasarse del crédito'; end if;
  update parametros set valor = 'true'::jsonb where clave = 'credito_limite_exige_pago';
  update envios set estado = 'cancelado' where id = d;
  -- Al MODIFICAR: c iba a crédito con 200 €; el cliente lo sube (al precio del tarifador) y ya no cabe → pendiente de pago.
  perform set_config('request.jwt.claim.sub', uc::text, false);
  -- (El precio, el del tarifador: más de 600 €, que tampoco caben en los 274 € que quedan.)
  r := modificar_envio_cliente(c, prueba.con_precio(jsonb_build_object('fecha_carga_desde', lun, 'fecha_carga_hasta', lun, 'metros_lineales', 6, 'toneladas', 5), null, c), null);
  perform set_config('request.jwt.claim.sub', '', false);
  select estado_pago_previo, pago_motivo into x from envios where id = c;
  if x.estado_pago_previo <> 'pendiente' or x.pago_motivo not like 'Crédito insuficiente%' then
    raise exception 'FALLO 260 · al subir el precio modificando, el envío que ya no cabe sigue a crédito: %', x;
  end if;
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'envio_a_pago_previo' and envio_id = c) then
    raise exception 'FALLO 260 · Dynamo no se entera de que el envío modificado pasa a pago por adelantado';
  end if;
  -- Con el manual VACÍO vuelve a mandar CESCE (5.000 €): un envío de 400 € cabe de sobra.
  update clientes set riesgo_manual_euros = null where id = cli;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 400, lun) returning id into d;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (d, 1, 'carga', '41001', 'Sevilla', 'ES'), (d, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = d;
  if (select estado_pago_previo from envios where id = d) <> 'no_requerido' then raise exception 'FALLO 260 · con el manual vacío no manda el crédito de CESCE'; end if;
  -- Con el manual a 0, es 0: SIN crédito aunque CESCE dé 5.000 € → el envío se paga por adelantado.
  update clientes set riesgo_manual_euros = 0 where id = cli;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 100, lun) returning id into d;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (d, 1, 'carga', '41001', 'Sevilla', 'ES'), (d, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = d;
  if (select estado_pago_previo from envios where id = d) <> 'pendiente' then raise exception 'FALLO 260 · con el manual a 0 el cliente sigue cargando a crédito de CESCE'; end if;
  if (select pago_motivo from envios where id = d) <> 'Sin crédito: crédito de Dynamo a 0,00 €' then raise exception 'FALLO 260 · el motivo no dice que el 0 lo ha puesto Dynamo: %', (select pago_motivo from envios where id = d); end if;
  raise notice 'OK 260 · crédito insuficiente: el envío que no cabe en lo que queda (también al subir el precio modificando) se paga por adelantado; el manual de Dynamo manda siempre sobre CESCE (0 = sin crédito, vacío = CESCE); sin importes en el motivo; apagable';
end $$;
update parametros set valor = 'false' where clave = 'pago_previo_activo';

-- ---- 261. Al conceder o subir el crédito, los envíos pendientes de pago que ya caben pasan a crédito solos ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'true' where clave = 'pago_previo_activo';
do $$ declare cli uuid; a uuid; b uuid; c uuid; x record; n int;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  -- Cliente SIN crédito (sin clasificar): sus envíos nacen pendientes de pago.
  insert into clientes (razon_social, cif) values ('Cliente Crédito 261 SL', 'B26100261') returning id into cli;
  update clientes set riesgo_cesce_euros = null, riesgo_manual_euros = null, exento_pago_previo_primer_envio = true where id = cli;
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 300, lun) returning id into a;        -- 363 €
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 900, lun + 1) returning id into b;    -- 1.089 €
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 100, lun + 2) returning id into c;    -- 121 €
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select e, o, t, cp, p, 'ES' from unnest(array[a, b, c]) e, (values (1, 'carga', '41001', 'Sevilla'), (2, 'descarga', '28821', 'Coslada')) v(o, t, cp, p);
  update envios set estado = 'programado' where id in (a, b, c);
  if (select count(*) from envios where id in (a, b, c) and estado_pago_previo = 'pendiente' and pago_motivo like 'Sin crédito%') <> 3 then
    raise exception 'FALLO 261 · los envíos de un cliente sin crédito no nacen pendientes de pago';
  end if;
  -- c lo pidió cobrar por adelantado Dynamo a mano: ese no se libera solo.
  update envios set pago_motivo = 'Pedido por Dynamo' where id = c;
  -- Dynamo le pone 1.000 € de crédito: a (363 €) cabe y pasa a crédito; b (1.089 €) no cabe y sigue pendiente.
  update clientes set riesgo_manual_euros = 1000 where id = cli;
  select estado_pago_previo, pago_exento_motivo into x from envios where id = a;
  if x.estado_pago_previo <> 'exento' or x.pago_exento_motivo not like 'Crédito disponible%' then
    raise exception 'FALLO 261 · al concederle crédito, el envío pendiente que ya cabe sigue pidiendo el pago: %', x;
  end if;
  select estado_pago_previo, pago_motivo into x from envios where id = b;
  if x.estado_pago_previo <> 'pendiente' or x.pago_motivo not like 'Crédito insuficiente%' then
    raise exception 'FALLO 261 · el envío que no cabe en el crédito nuevo no queda pendiente con el motivo al día: %', x;
  end if;
  if (select estado_pago_previo from envios where id = c) <> 'pendiente' then raise exception 'FALLO 261 · libera solo un envío que Dynamo pidió cobrar por adelantado'; end if;
  select count(*) into n from avisos where para = 'dynamo' and tipo = 'credito_libera_pagos' and titulo like '1 envío pasa a crédito%Cliente Crédito 261%';
  if n <> 1 then raise exception 'FALLO 261 · Dynamo no recibe (una vez) el aviso de los envíos que pasan a crédito: %', n; end if;
  -- El aviso lleva al ENVÍO (no a la ficha del cliente; usuario, 2026-11-17).
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'credito_libera_pagos' and titulo like '%Cliente Crédito 261%' and enlace = '/panel/envios?ver=' || a) then
    raise exception 'FALLO 261 · el aviso de «pasa a crédito» no lleva a la ficha del envío: %', (select enlace from avisos where tipo = 'credito_libera_pagos' and titulo like '%Cliente Crédito 261%' limit 1);
  end if;
  if not exists (select 1 from avisos where para = 'cliente' and cliente_id = cli and tipo = 'exento' and envio_id = a) then
    raise exception 'FALLO 261 · el cliente no recibe el aviso de que ya no hace falta pagar por adelantado';
  end if;
  -- Bajarle el crédito a 500 €: el envío liberado (363 €) sigue cabiendo, así que sigue a crédito.
  update clientes set riesgo_manual_euros = 500 where id = cli;
  if (select estado_pago_previo from envios where id = a) <> 'exento' then raise exception 'FALLO 261 · bajar el crédito vuelve a pedir el pago de un envío que sigue cabiendo'; end if;
  -- Se lo amplían (CESCE manda al quedar el manual vacío): ahora b también cabe.
  update clientes set riesgo_manual_euros = null, riesgo_cesce_euros = 5000 where id = cli;
  if (select estado_pago_previo from envios where id = b) <> 'exento' then raise exception 'FALLO 261 · al ampliar el crédito no pasa a crédito el envío que ya cabe'; end if;
  if (select estado_pago_previo from envios where id = c) <> 'pendiente' then raise exception 'FALLO 261 · al ampliar el crédito libera el envío pedido por Dynamo'; end if;
  raise notice 'OK 261 · al conceder o ampliar el crédito, los envíos pendientes de pago por falta de crédito que ya caben pasan a crédito solos (del que carga antes al que carga después), con aviso a Dynamo y al cliente; los pedidos por Dynamo, no';
end $$;
update parametros set valor = 'false' where clave = 'pago_previo_activo';

-- ---- 262. El factor del cliente va dentro del precio; el envío guarda la tarifa original y su factor ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false' where clave = 'pago_previo_activo';
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; begin
  update clientes set factor_tarifa_pct = -7, factor_fijado_a_mano = true where id = cli;
  perform set_config('prueba.otro262', (select id::text from clientes where id <> cli limit 1), false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; e uuid; ok boolean := false;
  paradas jsonb := jsonb_build_array(
    jsonb_build_object('tipo', 'carga',    'nombre_empresa', 'Nave 262', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
    jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Destino 262', 'codigo_postal', '28001', 'poblacion', 'Madrid'));
begin
  -- El asistente pregunta qué factor toca: el del cliente (solo el suyo).
  if factor_tarifa_envio(cli) <> -7 then raise exception 'FALLO 262 · el cliente no obtiene su factor para calcular el precio: %', factor_tarifa_envio(cli); end if;
  begin perform factor_tarifa_envio(current_setting('prueba.otro262')::uuid);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 262 · un cliente consulta el factor de otra empresa'; end if;
  -- Crea su envío: tarifa 780 € (grupaje con la ventana corta), con su −7 % le sale a 730 €
  -- (725,40 a la decena). La tarifa sin el factor la pone la base de datos, no la pantalla.
  select s.id into e from crear_envio_cliente(jsonb_build_object('importe_cliente', 730, 'importe_tarifa', 1,
    'fecha_carga_desde', sumar_dias_habiles(primera_fecha_carga(false), 3), 'fecha_carga_hasta', sumar_dias_habiles(primera_fecha_carga(false), 4),
    'metros_lineales', 6, 'toneladas', 5), paradas) s;
  if e is null then raise exception 'FALLO 262 · el cliente no puede crear el envío'; end if;
  perform set_config('prueba.e262', e::text, false);
  -- Él no ve ni el factor ni la tarifa original: solo su precio.
  if exists (select 1 from mis_envios() m where m.id = e and (to_jsonb(m) ? 'importe_tarifa' or to_jsonb(m) ? 'factor_tarifa_pct')) then
    raise exception 'FALLO 262 · el cliente ve el factor o la tarifa original de su envío';
  end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; e uuid := current_setting('prueba.e262')::uuid; x record; begin
  select importe_cliente, importe_tarifa, factor_tarifa_pct into x from envios where id = e;
  if x.importe_cliente <> 730 or x.importe_tarifa is distinct from 780 or x.factor_tarifa_pct is distinct from -7 then
    raise exception 'FALLO 262 · el envío no guarda la tarifa original y el factor aplicado: %', x;
  end if;
  -- Al cliente se le acaba el descuento…
  update clientes set factor_tarifa_pct = 0 where id = cli;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; e uuid := current_setting('prueba.e262')::uuid; d jsonb; begin
  -- …pero su envío conserva el suyo: al modificarlo, el asistente sigue calculando con −7 %.
  if factor_tarifa_envio(cli) <> 0 or factor_tarifa_envio(cli, e) <> -7 then
    raise exception 'FALLO 262 · al modificar, el envío no conserva su factor (cliente %, envío %)', factor_tarifa_envio(cli), factor_tarifa_envio(cli, e);
  end if;
  -- Ahora con residuos (NIMA, +50 €): tarifa 830 €, con el −7 % del envío 770 € (771,90).
  select jsonb_build_object('importe_cliente', 770, 'importe_tarifa', 1, 'fecha_carga_desde', m.fecha_carga_desde, 'fecha_carga_hasta', m.fecha_carga_hasta,
                            'metros_lineales', 8, 'toneladas', 6, 'requiere_nima', true) into d from mis_envios() m where m.id = e;
  perform modificar_envio_cliente(e, d, null);
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; e uuid := current_setting('prueba.e262')::uuid; x record; g uuid; begin
  select importe_cliente, importe_tarifa, factor_tarifa_pct into x from envios where id = e;
  if x.importe_cliente <> 770 or x.importe_tarifa is distinct from 830 or x.factor_tarifa_pct is distinct from -7 then
    raise exception 'FALLO 262 · al modificar no se guarda la tarifa nueva con el factor del envío: %', x;
  end if;
  -- Dynamo pone el precio a mano: ese precio ya no lleva el factor.
  update envios set importe_cliente = 800, precio_fijado_a_mano = true where id = e;
  if (select factor_tarifa_pct from envios where id = e) is not null then raise exception 'FALLO 262 · un precio puesto a mano sigue marcado con el factor'; end if;
  -- Un envío sin precio de tarifa (creado por otra vía) no lleva factor.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde)
    values (cli, 6, 5, 600, sumar_dias_habiles(current_date, 4)) returning id into g;
  if (select factor_tarifa_pct from envios where id = g) is not null then raise exception 'FALLO 262 · un envío sin tarifa anotada lleva factor'; end if;
  -- Y uno con tarifa pero precio que no cuadra con tarifa × factor, tampoco (el cliente va ahora a 0 %).
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_tarifa, fecha_carga_desde)
    values (cli, 6, 5, 600, 1000, sumar_dias_habiles(current_date, 4)) returning id into g;
  if (select factor_tarifa_pct from envios where id = g) is not null then raise exception 'FALLO 262 · un precio que no sale de la tarifa lleva factor'; end if;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_tarifa, fecha_carga_desde)
    values (cli, 6, 5, 1000, 1000, sumar_dias_habiles(current_date, 4)) returning id into g;
  if (select factor_tarifa_pct from envios where id = g) is distinct from 0 then raise exception 'FALLO 262 · un envío a tarifa (factor 0 %%) no queda anotado con 0'; end if;
  update clientes set factor_fijado_a_mano = false where id = cli;
  raise notice 'OK 262 · el factor del cliente va dentro del precio: el envío guarda la tarifa original y su factor, lo conserva al modificarse aunque al cliente se le acabe el descuento, y no lo lleva un precio puesto a mano; el cliente no ve ni el factor ni la tarifa, ni consulta el de otra empresa';
end $$;

-- ---- 263. El crédito y los envíos, al día en los dos sentidos: al bajar, lo que no cabe pasa a pendiente; cada hora, lo que ya cabe pasa a crédito ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'true' where clave = 'pago_previo_activo';
do $$ declare cli uuid; a uuid; b uuid; d uuid; t uuid; x record; n int;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  -- Cliente con 3.000 € de crédito: sus cuatro envíos (363 + 1.089 + 121 + 363 = 1.936 €) van a crédito.
  insert into clientes (razon_social, cif) values ('Cliente Crédito 263 SL', 'B26300263') returning id into cli;
  update clientes set riesgo_cesce_euros = null, riesgo_manual_euros = 3000, exento_pago_previo_primer_envio = true where id = cli;
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 300, lun) returning id into a;        -- 363 €
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 900, lun + 1) returning id into b;    -- 1.089 €
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 100, lun + 2) returning id into d;    -- 121 €
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 300, lun + 3) returning id into t;    -- 363 €, con transportista
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select e, o, tp, cp, p, 'ES' from unnest(array[a, b, d, t]) e, (values (1, 'carga', '41001', 'Sevilla'), (2, 'descarga', '28821', 'Coslada')) v(o, tp, cp, p);
  update envios set estado = 'programado' where id in (a, b, d, t);
  if (select count(*) from envios where id in (a, b, d, t) and estado_pago_previo = 'no_requerido') <> 4 then
    raise exception 'FALLO 263 · los envíos de un cliente con crédito de sobra no nacen a crédito';
  end if;
  update envios set transportista_id = current_setting('prueba.transp')::uuid where id = t;

  -- LE BAJAN EL CRÉDITO A 1.500 €. El del transportista (363 €) no se toca y cuenta. Del que carga
  -- antes al que carga después: a (363) cabe → 726; b (1.089) ya no cabe → pendiente; d (121) cabe → 847.
  update clientes set riesgo_manual_euros = 1500 where id = cli;
  if (select estado_pago_previo from envios where id = a) <> 'no_requerido' or (select estado_pago_previo from envios where id = d) <> 'no_requerido' then
    raise exception 'FALLO 263 · al bajar el crédito pasan a pendiente envíos que siguen cabiendo';
  end if;
  select estado_pago_previo, pago_motivo into x from envios where id = b;
  if x.estado_pago_previo <> 'pendiente' or x.pago_motivo not like 'Crédito insuficiente%' then
    raise exception 'FALLO 263 · al bajar el crédito, el envío que ya no cabe sigue a crédito: %', x;
  end if;
  if (select estado_pago_previo from envios where id = t) <> 'no_requerido' then raise exception 'FALLO 263 · se mueve un envío con transportista asignado'; end if;
  select count(*) into n from avisos where para = 'dynamo' and tipo = 'credito_retira_envios' and titulo like '1 envío pasa a pendiente de pago%Cliente Crédito 263%';
  if n <> 1 then raise exception 'FALLO 263 · Dynamo no recibe (una vez) el aviso de los envíos que pasan a pendiente de pago: %', n; end if;
  -- El aviso lleva al ENVÍO (no a la ficha del cliente; usuario, 2026-11-17).
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'credito_retira_envios' and titulo like '%Cliente Crédito 263%' and enlace = '/panel/envios?ver=' || b) then
    raise exception 'FALLO 263 · el aviso de «pasa a pendiente de pago» no lleva a la ficha del envío: %', (select enlace from avisos where tipo = 'credito_retira_envios' and titulo like '%Cliente Crédito 263%' limit 1);
  end if;
  if exists (select 1 from avisos where tipo in ('credito_retira_envios', 'credito_libera_pagos') and enlace like '/panel/clientes%') then
    raise exception 'FALLO 263 · queda algún aviso de crédito que abre la ficha del cliente en vez de los envíos';
  end if;
  if not exists (select 1 from avisos where para = 'cliente' and cliente_id = cli and tipo = 'pago_requerido' and envio_id = b) then
    raise exception 'FALLO 263 · el cliente no recibe el aviso de que su envío pasa a pago por adelantado';
  end if;

  -- SE LIBERA CRÉDITO SIN TOCAR LA LÍNEA (se cancelan a y d): b ya cabe (363 + 1.089 = 1.452 €), pero
  -- nadie ha cambiado el crédito… lo recoge el repaso de cada hora.
  update envios set estado = 'cancelado' where id in (a, d);
  if (select estado_pago_previo from envios where id = b) <> 'pendiente' then raise exception 'FALLO 263 · la prueba no está bien montada: b ya no está pendiente'; end if;
  n := credito_repasar_pendientes();
  select estado_pago_previo, pago_exento_motivo into x from envios where id = b;
  if x.estado_pago_previo <> 'exento' or x.pago_exento_motivo not like 'Crédito disponible:%' then
    raise exception 'FALLO 263 · el repaso de cada hora no pasa a crédito el envío que ya cabe: % (liberados %)', x, n;
  end if;

  -- LE QUITAN EL CRÉDITO (0 a mano): b, que se había liberado solo, vuelve a pendiente; el del transportista, no.
  update clientes set riesgo_manual_euros = 0 where id = cli;
  select estado_pago_previo, pago_motivo into x from envios where id = b;
  if x.estado_pago_previo <> 'pendiente' or x.pago_motivo not like 'Sin crédito%' then
    raise exception 'FALLO 263 · al quitarle el crédito, el envío sin transportista sigue a crédito: %', x;
  end if;
  if (select estado_pago_previo from envios where id = t) <> 'no_requerido' then raise exception 'FALLO 263 · al quitar el crédito se mueve un envío con transportista'; end if;
  -- Y uno que Dynamo pasó «sin pago previo» a mano tampoco se toca al bajar el crédito.
  update clientes set riesgo_manual_euros = 3000 where id = cli;
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_exento_motivo = null where id = b;
  update envios set estado_pago_previo = 'exento', pago_exento_motivo = 'Cliente de confianza' where id = b;
  update clientes set riesgo_manual_euros = 0 where id = cli;
  if (select estado_pago_previo from envios where id = b) <> 'exento' then raise exception 'FALLO 263 · al quitar el crédito se vuelve a cobrar un envío que Dynamo pasó sin pago previo a mano'; end if;
  raise notice 'OK 263 · el crédito y los envíos, al día en los dos sentidos: al bajar o quitar el crédito, los envíos a crédito sin transportista que ya no caben pasan a pendiente de pago (del que carga antes al que carga después, con aviso a Dynamo y al cliente); el repaso de cada hora pasa a crédito los pendientes que ya caben; con transportista o exentos a mano, no se tocan';
end $$;
update parametros set valor = 'false' where clave = 'pago_previo_activo';

-- ---- 264. La pestaña «Programados» no enseña los pendientes de pago: cada envío vivo, en una sola pestaña ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid; a uuid; b uuid; begin
  insert into clientes (razon_social, cif) values ('Cliente Pestañas 264 SL', 'B26400264') returning id into cli;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 300, sumar_dias_habiles(current_date, 4)) returning id into a;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 300, sumar_dias_habiles(current_date, 4)) returning id into b;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    select e, o, tp, cp, p, 'ES' from unnest(array[a, b]) e, (values (1, 'carga', '41001', 'Sevilla'), (2, 'descarga', '28821', 'Coslada')) v(o, tp, cp, p);
  update envios set estado = 'programado' where id in (a, b);
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo' where id = b;   -- b espera el pago; a va a crédito
  perform set_config('prueba.cli264', cli::text, false); perform set_config('prueba.a264', a::text, false); perform set_config('prueba.b264', b::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare cli uuid := current_setting('prueba.cli264')::uuid; a uuid := current_setting('prueba.a264')::uuid; b uuid := current_setting('prueba.b264')::uuid; begin
  if (select total from envios_pestanas(cli, null) where pestana = 'programada') <> 1 or (select total from envios_pestanas(cli, null) where pestana = 'sin-pagar') <> 1
     or (select total from envios_pestanas(cli, null) where pestana = 'todas') <> 2 then
    raise exception 'FALLO 264 · los contadores no reparten bien: programada %, sin pagar %', (select total from envios_pestanas(cli, null) where pestana = 'programada'), (select total from envios_pestanas(cli, null) where pestana = 'sin-pagar');
  end if;
  if (select array_agg(id) from envios_pagina('programada', 1, 20, cli)) is distinct from array[a] then raise exception 'FALLO 264 · «Programados» enseña un envío pendiente de pago (o no enseña el que va a crédito)'; end if;
  if (select array_agg(id) from envios_pagina('sin-pagar', 1, 20, cli)) is distinct from array[b] then raise exception 'FALLO 264 · «Pendientes de pago» no enseña el envío que espera el pago'; end if;
  raise notice 'OK 264 · cada envío vivo sale en una sola pestaña: «Pendientes de pago» si espera el pago, «Programados» si no';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 265. Logo de la empresa del cliente, y el cliente quita sus logos (y solo los suyos) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; o uuid; begin
  insert into operadores (cliente_id, razon_social) values (cli, 'Transportes Propios 265') returning id into o;
  perform set_config('prueba.o265', o::text, false);
  perform set_config('prueba.otro265', (select id::text from clientes where id <> cli limit 1), false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; yo text := current_setting('prueba.u_cli'); o uuid := current_setting('prueba.o265')::uuid;
  l uuid; lo uuid; ok boolean; begin
  -- Sube el logo de SU empresa y el de uno de sus transportistas.
  insert into documentos (tipo, cliente_id, storage_bucket, storage_ruta, nombre_archivo)
    values ('logo', cli, 'documentos', 'u/' || yo || '/265a/logo.png', 'logo.png') returning id into l;
  insert into documentos (tipo, operador_id, storage_bucket, storage_ruta, nombre_archivo)
    values ('logo', o, 'documentos', 'u/' || yo || '/265b/logo.png', 'logo.png') returning id into lo;
  if mi_logo_empresa() is distinct from l then raise exception 'FALLO 265 · el cliente no obtiene el logo de su empresa'; end if;
  -- No puede colgarle un logo a otra empresa: ni directamente…
  ok := false;
  begin insert into documentos (tipo, cliente_id, storage_bucket, storage_ruta, nombre_archivo)
          values ('logo', current_setting('prueba.otro265')::uuid, 'documentos', 'u/' || yo || '/265c/logo.png', 'logo.png');
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 265 · un cliente sube el logo de OTRA empresa'; end if;
  -- …ni escondido en la subida del logo de un transportista suyo.
  ok := false;
  begin insert into documentos (tipo, operador_id, cliente_id, storage_bucket, storage_ruta, nombre_archivo)
          values ('logo', o, current_setting('prueba.otro265')::uuid, 'documentos', 'u/' || yo || '/265d/logo.png', 'logo.png');
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 265 · un cliente cuelga un documento a otra empresa a través del logo de su transportista'; end if;
  -- Ni otro tipo de documento a nombre de su empresa.
  ok := false;
  begin insert into documentos (tipo, cliente_id, storage_bucket, storage_ruta, nombre_archivo)
          values ('otro', cli, 'documentos', 'u/' || yo || '/265e/x.pdf', 'x.pdf');
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 265 · un cliente sube a nombre de su empresa algo que no es un logo'; end if;
  perform set_config('prueba.l265', l::text, false); perform set_config('prueba.lo265', lo::text, false);
end $$;
-- Otra empresa: ni lo ve ni lo quita.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
do $$ declare ok boolean := false; begin
  if exists (select 1 from documentos where id in (current_setting('prueba.l265')::uuid, current_setting('prueba.lo265')::uuid)) then
    raise exception 'FALLO 265 · otra empresa ve el logo de un cliente o de su transportista';
  end if;
  begin perform quitar_logo(current_setting('prueba.l265')::uuid);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 265 · otra empresa quita el logo de un cliente'; end if;
end $$;
-- El dueño quita los dos (antes: «Solo el equipo de Dynamo quita documentos»).
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
do $$ begin
  perform quitar_logo(current_setting('prueba.lo265')::uuid);
  perform quitar_logo(current_setting('prueba.l265')::uuid);
  if mi_logo_empresa() is not null then raise exception 'FALLO 265 · tras quitarlo, la empresa sigue teniendo logo'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  if (select count(*) from documentos where id in (current_setting('prueba.l265')::uuid, current_setting('prueba.lo265')::uuid) and borrado) <> 2 then
    raise exception 'FALLO 265 · el cliente no puede quitar sus logos (el de su empresa y el de su transportista)';
  end if;
  raise notice 'OK 265 · el cliente sube y quita el logo de su empresa y los de sus transportistas propios; no puede colgar documentos a otra empresa, y otra empresa ni los ve ni los quita';
end $$;

-- ---- 266. El envío con transportista propio se modifica entero y libremente, sin avisar a nadie; el contador del menú no cuenta dos veces ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false' where clave = 'pago_previo_activo';
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; o1 uuid := current_setting('prueba.o265')::uuid; o2 uuid; ox uuid; e uuid; d uuid; begin
  insert into operadores (cliente_id, razon_social) values (cli, 'Otro Transportista 266') returning id into o2;
  insert into operadores (cliente_id, razon_social) values (current_setting('prueba.otro265')::uuid, 'Transportista Ajeno 266') returning id into ox;
  -- e: con su transportista (manual) · d: de Dynamo
  insert into envios (cliente_id, operador_id, metros_lineales, toneladas, fecha_carga_desde, fecha_carga_hasta)
    values (cli, o1, 6, 5, sumar_dias_habiles(current_date, 4), sumar_dias_habiles(current_date, 4)) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde)
    values (cli, 6, 5, 600, sumar_dias_habiles(current_date, 4)) returning id into d;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, nombre_empresa)
    select x, o, t, cp, p, n from unnest(array[e, d]) x,
      (values (1, 'carga', '41001', 'Sevilla', 'Nave Sevilla'), (2, 'descarga', '46001', 'Valencia', 'Nave Valencia')) v(o, t, cp, p, n);
  update envios set estado = 'programado' where id in (e, d);
  perform set_config('prueba.e266', e::text, false); perform set_config('prueba.d266', d::text, false);
  perform set_config('prueba.o266', o2::text, false); perform set_config('prueba.ox266', ox::text, false);
  perform set_config('prueba.p266', (select id::text from envio_paradas where envio_id = e and orden = 1), false);
  perform set_config('prueba.n266', (select count(*)::text from emails_enviados), false);
  perform set_config('prueba.a266', (select count(*)::text from avisos), false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e266')::uuid; dt jsonb; ok boolean; n1 bigint; begin
  dt := jsonb_build_object('operador_id', current_setting('prueba.o266'), 'precio_acordado_operador', 450,
          'fecha_carga_desde', sumar_dias_habiles(current_date, 9), 'fecha_carga_hasta', sumar_dias_habiles(current_date, 10),
          'metros_lineales', 9, 'toneladas', 12, 'referencia_cliente', 'PED-266');
  perform modificar_mi_envio_manual(e, dt, jsonb_build_array(jsonb_build_object('id', current_setting('prueba.p266')),
    jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Nave Getafe', 'poblacion', 'Getafe', 'codigo_postal', '28901')));
  -- Ya en marcha también se puede tocar (todo menos la ruta, que solo se cambia antes de cargar).
  perform marcar_mi_envio_manual(e, 'en_ruta');
  perform modificar_mi_envio_manual(e, dt || jsonb_build_object('metros_lineales', 9.5), null);
  -- Solo el precio, desde la ficha.
  perform mi_envio_manual_precio(e, 480);
  -- Con un transportista que no es suyo, no.
  ok := false;
  begin perform modificar_mi_envio_manual(e, dt || jsonb_build_object('operador_id', current_setting('prueba.ox266')), null);
  exception when others then ok := sqlerrm like '%tus transportistas%'; end;
  if not ok then raise exception 'FALLO 266 · el cliente pone en su envío el transportista de otra empresa'; end if;
  -- Un envío de Dynamo no se modifica por esta puerta (tiene sus reglas).
  ok := false;
  begin perform modificar_mi_envio_manual(current_setting('prueba.d266')::uuid, dt, null);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 266 · un envío de Dynamo se modifica por la puerta de los envíos propios'; end if;
  ok := false;
  begin perform mi_envio_manual_precio(current_setting('prueba.d266')::uuid, 10);
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 266 · se anota un precio acordado en un envío de Dynamo'; end if;
end $$;
-- Otra empresa no lo toca.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
do $$ declare ok boolean := false; begin
  begin perform mi_envio_manual_precio(current_setting('prueba.e266')::uuid, 1);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 266 · otra empresa cambia el precio de un envío ajeno'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e266')::uuid; x record; begin
  select operador_id, precio_acordado_operador, fecha_carga_desde, metros_lineales, referencia_cliente, estado into x from envios where id = e;
  if x.operador_id <> current_setting('prueba.o266')::uuid or x.precio_acordado_operador <> 480 or x.fecha_carga_desde <> sumar_dias_habiles(current_date, 9)
     or x.metros_lineales <> 9.5 or x.referencia_cliente <> 'PED-266' or x.estado <> 'en_ruta' then
    raise exception 'FALLO 266 · el envío propio no queda como lo ha dejado el cliente: %', x;
  end if;
  if (select poblacion from envio_paradas where envio_id = e and orden = 2) <> 'Getafe' then raise exception 'FALLO 266 · la ruta nueva del envío propio no se guarda'; end if;
  -- Dynamo no interviene: ni un email ni un aviso por todo lo anterior.
  if (select count(*) from emails_enviados) <> current_setting('prueba.n266')::bigint then raise exception 'FALLO 266 · modificar un envío propio manda emails'; end if;
  if (select count(*) from avisos) <> current_setting('prueba.a266')::bigint then raise exception 'FALLO 266 · modificar un envío propio genera avisos'; end if;
end $$;
-- El contador del menú: un envío pendiente de pago no cuenta como «sin transportista».
do $$ begin
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo' where id = current_setting('prueba.d266')::uuid;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin perform set_config('prueba.c266', cuenta_mis_envios_sin_asignar()::text, false); end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  update envios set estado_pago_previo = 'exento', pago_exento_motivo = 'Prueba 266' where id = current_setting('prueba.d266')::uuid;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  if cuenta_mis_envios_sin_asignar() <> current_setting('prueba.c266')::bigint + 1 then
    raise exception 'FALLO 266 · el contador de «sin transportista» del cliente cuenta también los pendientes de pago (antes %, ahora %)', current_setting('prueba.c266'), cuenta_mis_envios_sin_asignar();
  end if;
  raise notice 'OK 266 · el cliente modifica entero su envío con transportista propio (ruta, fechas, mercancía, transportista y precio), también en marcha, sin emails ni avisos; no puede poner un transportista ajeno ni tocar así un envío de Dynamo; y el contador del menú no cuenta el pendiente de pago como «sin transportista»';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 267. Sin incidencias en los envíos con transportista propio (Dynamo no interviene) ----
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare i uuid; begin
  begin
    insert into incidencias (envio_id, tipo_id, titulo, detalle)
    values (current_setting('prueba.e266')::uuid, (select id from tipos_incidencia limit 1), 'Retraso', 'Mi transportista llega tarde');
    raise exception 'FALLO 267 · el cliente abre una incidencia en un envío con su propio transportista';
  exception when insufficient_privilege then null;
  end;
  -- En un envío de Dynamo, como siempre.
  insert into incidencias (envio_id, tipo_id, titulo, detalle)
  values (current_setting('prueba.d266')::uuid, (select id from tipos_incidencia limit 1), 'Retraso', 'El camión no ha llegado')
  returning id into i;
  if i is null then raise exception 'FALLO 267 · el cliente ya no puede abrir incidencias en sus envíos de Dynamo'; end if;
  raise notice 'OK 267 · el cliente no abre incidencias en los envíos con su propio transportista, y sí en los de Dynamo';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 268. Emails al transportista asignado (cancelado, retirado, modificado; nunca con precios) y precio a mano: solo Dynamo modifica ----
do $$ declare e uuid; g uuid; t uuid; t2 uuid; r record; n int; cli uuid := current_setting('prueba.cliente')::uuid;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into transportistas (razon_social, cif) values ('Transportes 268 SL', 'B26800001') returning id into t;
  insert into contactos (transportista_id, funcion, email) values (t, 'trafico', 'trafico268@t.prueba');
  insert into transportistas (razon_social, cif) values ('Sin Email 268 SL', 'B26800002') returning id into t2;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 913, 707, lun, lun + 1) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  -- Sin transportista, los cambios no avisan a ninguno; asignarlo tampoco es «un cambio».
  update envios set toneladas = 21 where id = e;
  update envios set transportista_id = t where id = e;
  if exists (select 1 from emails_enviados where envio_id = e and tipo like 'transportista_%') then
    raise exception 'FALLO 268 · sale un email de cambios al transportista sin estar asignado o al asignarlo';
  end if;
  -- MODIFICADO: mercancía y fecha, en un solo email; sin precios.
  update envios set toneladas = 23 where id = e;
  update envios set fecha_carga_desde = lun + 1, fecha_carga_hasta = lun + 2 where id = e;
  update envios set importe_transportista = 650, importe_cliente = 950 where id = e;   -- el precio no se manda
  select count(*) into n from emails_enviados where envio_id = e and tipo = 'transportista_modificado';
  if n <> 1 then raise exception 'FALLO 268 · los cambios al transportista no van en un solo email (%)', n; end if;
  select * into r from emails_enviados where envio_id = e and tipo = 'transportista_modificado';
  if r.destinatario <> 'trafico268@t.prueba' or r.estado <> 'pendiente' or r.asunto not like 'Envío modificado · envío #% (Sevilla → Coslada)' then
    raise exception 'FALLO 268 · el email de cambios no va al contacto de tráfico del transportista: % · % · %', r.destinatario, r.estado, r.asunto;
  end if;
  if position('Mercancía' in r.cuerpo_html) = 0 or position('Fecha de carga:</strong> antes' in r.cuerpo_html) = 0 or position('te llamamos' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 268 · al email de cambios le falta la mercancía, la fecha o el aviso del precio: %', r.cuerpo_html;
  end if;
  if r.cuerpo_html ~ '(913|950|707|650),00' or position('Precio' in r.cuerpo_html) > 0 or position('€' in r.cuerpo_html) > 0 then
    raise exception 'FALLO 268 · el email al transportista lleva precios: %', r.cuerpo_html;
  end if;
  -- RETIRADO: se pasa a otro (sin email en su ficha: queda como fallo para avisar a mano).
  update envios set transportista_id = t2 where id = e;
  select * into r from emails_enviados where envio_id = e and tipo = 'transportista_retirado';
  if r.id is null or r.destinatario <> 'trafico268@t.prueba' or position('ya no está asignado a tu empresa' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 268 · al transportista al que se le retira el envío no le llega el email';
  end if;
  -- CANCELADO: al que lo tiene asignado ahora.
  update envios set estado = 'cancelado' where id = e;
  select * into r from emails_enviados where envio_id = e and tipo = 'transportista_cancelado';
  if r.id is null or r.estado <> 'error' or r.destinatario <> '—' or position('no hay que realizar este transporte' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 268 · el email de cancelado al transportista sin email no queda registrado como fallo: %', r;
  end if;
  -- Un envío con transportista PROPIO del cliente no avisa a nadie (Dynamo no interviene): ya lo cubre la 266.

  -- PRECIO A MANO: el envío solo lo modifica Dynamo.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, creado_por)
    values (cli, 6, 5, 600, sumar_dias_habiles(current_date, 6), current_setting('prueba.u_cli')::uuid) returning id into g;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (g, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (g, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = g;
  update envios set importe_cliente = 555, precio_fijado_a_mano = true where id = g;
  perform set_config('prueba.g268', g::text, false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare g uuid := current_setting('prueba.g268')::uuid; begin
  if not (select precio_a_mano from mi_cambio_envio(g)) then raise exception 'FALLO 268 · la ficha del cliente no sabe que el precio es a mano'; end if;
  begin
    perform modificar_envio_cliente(g, jsonb_build_object('importe_cliente', 500, 'fecha_carga_desde', sumar_dias_habiles(current_date, 6),
      'fecha_carga_hasta', sumar_dias_habiles(current_date, 6), 'metros_lineales', 6, 'toneladas', 5), null);
    raise exception 'FALLO 268 · el cliente modifica un envío con el precio fijado a mano por Dynamo';
  exception when others then
    if sqlerrm not like '%precio acordado con Dynamo%' then raise; end if;
  end;
  raise notice 'OK 268 · el transportista asignado recibe email si su envío se modifica (un solo email, sin precios), se le retira o se cancela; y un envío con precio a mano solo lo modifica Dynamo';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 269. Código de aceptación de carga: 6 cifras al azar, caduca, no lo ve el cliente y la casilla tiene tope ----
do $$ declare e uuid; g uuid; m uuid; t uuid; c text; c2 text; c3 text; cli uuid := current_setting('prueba.cliente')::uuid;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into transportistas (razon_social, cif) values ('Transportes 269 SL', 'B26900001') returning id into t;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 913, 707, lun, lun + 1) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 6, 5, 600, 450, lun, lun + 1) returning id into g;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (g, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (g, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = g;
  select codigo_aceptacion into c from envios where id = e;
  select codigo_aceptacion into c2 from envios where id = g;
  if c !~ '^[1-9][0-9]{5}$' or c2 !~ '^[1-9][0-9]{5}$' or c = c2 then
    raise exception 'FALLO 269 · el envío no nace con un código de aceptación propio de 6 cifras: % · %', c, c2;
  end if;
  -- Lo tienen los envíos de Dynamo sin terminar, y nadie más; sin repetir.
  if exists (select 1 from envios where codigo_aceptacion is null and not coalesce(es_manual, false) and estado::text not in ('entregado', 'cancelado'))
     or exists (select 1 from envios where codigo_aceptacion is not null and (coalesce(es_manual, false) or estado::text in ('entregado', 'cancelado')))
     or (select count(codigo_aceptacion) from envios) <> (select count(distinct codigo_aceptacion) from envios) then
    raise exception 'FALLO 269 · hay envíos vivos sin código de aceptación (%), terminados o de transportista propio con código (%), o códigos repetidos · ejemplo: %',
      (select count(*) from envios where codigo_aceptacion is null and not coalesce(es_manual, false) and estado::text not in ('entregado', 'cancelado')),
      (select count(*) from envios where codigo_aceptacion is not null and (coalesce(es_manual, false) or estado::text in ('entregado', 'cancelado'))),
      (select jsonb_build_object('estado', estado, 'manual', es_manual, 'codigo', codigo_aceptacion, 'transportista', transportista_id is not null, 'operador', operador_id is not null, 'creado', creado_en, 'modificado', modificado_en)
         from envios where (codigo_aceptacion is null) = (not coalesce(es_manual, false) and estado::text not in ('entregado', 'cancelado')) limit 1);
  end if;
  -- No se cambia a mano.
  update envios set codigo_aceptacion = '482913' where id = e;
  if (select codigo_aceptacion from envios where id = e) <> c then raise exception 'FALLO 269 · el código de aceptación se deja cambiar a mano'; end if;
  -- Otro envío para ver la caducidad: al cancelarse, el código se borra.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 4, 3, 500, 350, lun, lun + 1) returning id into m;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (m, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (m, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = m;
  select codigo_aceptacion into c3 from envios where id = m;
  update envios set estado = 'cancelado' where id = m;
  if c3 is null or (select codigo_aceptacion from envios where id = m) is not null then
    raise exception 'FALLO 269 · al cancelarse el envío su código de aceptación no se borra';
  end if;
  perform set_config('prueba.e269', e::text, false);
  perform set_config('prueba.t269', t::text, false);
  perform set_config('prueba.c269', c, false);
  perform set_config('prueba.c269b', c2, false);
  perform set_config('prueba.c269m', c3, false);
  perform set_config('prueba.gx269', (select referencia_gx from envios where id = e), false);
  perform set_config('prueba.tk269', (select token_publico::text from envios where id = e), false);
end $$;
-- El cliente no lo ve: ni en la tabla ni en la lista de sus envíos.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  if exists (select 1 from envios where codigo_aceptacion is not null) then raise exception 'FALLO 269 · el cliente lee el código de aceptación en la tabla de envíos'; end if;
  if exists (select 1 from mis_envios() m where to_jsonb(m) ? 'codigo_aceptacion') then raise exception 'FALLO 269 · la lista de envíos del cliente trae el código de aceptación'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
-- La casilla pública.
set role anon;
do $$ declare r jsonb; c text := current_setting('prueba.c269'); begin
  -- Da igual con espacios o guiones.
  r := carga_por_codigo(' ' || substr(c, 1, 3) || ' - ' || substr(c, 4) || ' ', '10.26.9.1');
  if r ->> 'resultado' <> 'ok' or r ->> 'token' <> current_setting('prueba.tk269') then
    raise exception 'FALLO 269 · el código de aceptación no lleva al enlace de su carga: %', r;
  end if;
  -- Y ese enlace (el propio del envío, no el de una oferta) abre la carga: antes daba error.
  r := oferta_publica(current_setting('prueba.tk269')::uuid);
  if r ->> 'resultado' <> 'ok' or not (r ->> 'disponible')::boolean or (r ->> 'precio')::numeric <> 707 then
    raise exception 'FALLO 269 · el enlace propio del envío no abre su carga: %', r;
  end if;
  -- El número de envío (GX) no abre nada: el cliente lo conoce.
  r := carga_por_codigo(current_setting('prueba.gx269'), '10.26.9.1');
  if r ->> 'resultado' <> 'codigo_incorrecto' or r ? 'token' then raise exception 'FALLO 269 · el número de envío abre la carga: %', r; end if;
  -- El código de un envío cancelado ya no abre nada, pero se sabe de qué era: «no disponible».
  r := carga_por_codigo(current_setting('prueba.c269m'), '10.26.9.3');
  if r ->> 'resultado' <> 'no_disponible' or r ? 'token' then raise exception 'FALLO 269 · el código de un envío cancelado no responde «no disponible»: %', r; end if;
end $$;
reset role;
-- Con la carga ya tomada el código sigue en la ficha y dice la razón: «no disponible»; uno
-- inventado, «código incorrecto». Ninguno de los dos trae enlace.
update envios set transportista_id = current_setting('prueba.t269')::uuid where id = current_setting('prueba.e269')::uuid;
do $$ begin
  if (select codigo_aceptacion from envios where id = current_setting('prueba.e269')::uuid) <> current_setting('prueba.c269') then
    raise exception 'FALLO 269 · al asignar transportista cambia o se pierde el código de aceptación';
  end if;
end $$;
set role anon;
do $$ declare r jsonb; r2 jsonb; begin
  r := carga_por_codigo(current_setting('prueba.c269'), '10.26.9.1');
  r2 := carga_por_codigo('999998', '10.26.9.1');
  if r ->> 'resultado' <> 'no_disponible' or r2 ->> 'resultado' <> 'codigo_incorrecto' or r ? 'token' or r2 ? 'token' then
    raise exception 'FALLO 269 · la casilla no distingue una carga ya tomada de un código mal escrito: % · %', r, r2;
  end if;
end $$;
reset role;
-- El transportista se cae: la carga vuelve a estar libre con un código NUEVO; el viejo no vuelve a servir.
update envios set transportista_id = null where id = current_setting('prueba.e269')::uuid;
-- (Al quitar el transportista se va también su precio: Dynamo lo vuelve a poner para ofrecerla.)
update envios set importe_transportista = 707 where id = current_setting('prueba.e269')::uuid;
do $$ declare c text; begin
  select codigo_aceptacion into c from envios where id = current_setting('prueba.e269')::uuid;
  if c is null or c !~ '^[1-9][0-9]{5}$' or c = current_setting('prueba.c269') then
    raise exception 'FALLO 269 · al quedarse sin transportista el envío no estrena código de aceptación: %', c;
  end if;
  perform set_config('prueba.c269n', c, false);
  if (select count(*) from codigos_carga_retirados where codigo in (current_setting('prueba.c269'), current_setting('prueba.c269m'))) <> 2 then
    raise exception 'FALLO 269 · los códigos que dejan de usarse (envío cancelado, transportista que se cae) no quedan apuntados';
  end if;
end $$;
set role anon;
do $$ declare r jsonb; i int; begin
  if carga_por_codigo(current_setting('prueba.c269'), '10.26.9.4') ->> 'resultado' <> 'no_disponible' then
    raise exception 'FALLO 269 · el código antiguo vuelve a abrir la carga al quedar libre, o no se reconoce como retirado';
  end if;
  -- La lista de códigos retirados no la lee nadie de fuera.
  if exists (select 1 from codigos_carga_retirados) then raise exception 'FALLO 269 · cualquiera lee los códigos retirados'; end if;
  r := carga_por_codigo(current_setting('prueba.c269n'), '10.26.9.4');
  if r ->> 'resultado' <> 'ok' or r ->> 'token' <> current_setting('prueba.tk269') then
    raise exception 'FALLO 269 · el código nuevo no abre la carga que ha quedado libre: %', r;
  end if;
  -- TOPE: tras los fallos de la hora, esa conexión espera aunque el código sea bueno…
  for i in 1 .. 12 loop
    r := carga_por_codigo((999900 + i)::text, '10.26.9.1');
    exit when r ->> 'resultado' = 'tope';
  end loop;
  if r ->> 'resultado' <> 'tope' or carga_por_codigo(current_setting('prueba.c269b'), '10.26.9.1') ->> 'resultado' <> 'tope' then
    raise exception 'FALLO 269 · la casilla del código no tiene tope de fallos: %', r;
  end if;
  -- …y otra conexión sigue entrando.
  if carga_por_codigo(current_setting('prueba.c269b'), '10.26.9.2') ->> 'resultado' <> 'ok' then
    raise exception 'FALLO 269 · el tope de una conexión bloquea a las demás';
  end if;
  raise notice 'OK 269 · código de aceptación de 6 cifras: al azar y único, no se cambia a mano, el cliente no lo ve, la casilla lleva a la carga y no acepta el número de envío, dice si el código está mal escrito o si la carga ya no está disponible (también de una cancelada y del código antiguo), tiene tope de fallos, se renueva si el envío se queda sin transportista y se borra al cancelarse';
end $$;
reset role;


-- ---- 270. Registro de clientes en la web: abierto o cerrado desde Parámetros ----
do $$ declare u uuid; begin
  if not registro_clientes_abierto() then raise exception 'FALLO 270 · el registro de clientes no nace abierto'; end if;
  update parametros set valor = 'false'::jsonb where clave = 'registro_clientes_abierto';
  if registro_clientes_abierto() then raise exception 'FALLO 270 · el interruptor del registro no se lee'; end if;
  -- Cerrado: un alta por su cuenta no entra, ni saltándose la web…
  begin
    insert into auth.users (email, raw_user_meta_data) values ('nuevo270@cliente.prueba', '{"tipo_usuario":"cliente","nombre":"Nuevo Doscientos Setenta"}');
    raise exception 'FALLO 270 · con el registro cerrado se crea una cuenta nueva de cliente';
  exception when others then
    if sqlerrm not like '%registro_cerrado%' then raise; end if;
  end;
  -- …ni inventándose quién la ha pedido…
  begin
    insert into auth.users (email, raw_user_meta_data) values ('nuevo270b@cliente.prueba', jsonb_build_object('nombre', 'Otro', 'anadido_por', gen_random_uuid()));
    raise exception 'FALLO 270 · con el registro cerrado vale un «añadido por» inventado';
  exception when others then
    if sqlerrm not like '%registro_cerrado%' then raise; end if;
  end;
  -- …pero sí la que pide un usuario activo (Dynamo desde Usuarios, o un compañero de empresa).
  insert into auth.users (email, raw_user_meta_data)
    values ('invitado270@cliente.prueba', jsonb_build_object('nombre', 'Invitado Doscientos Setenta', 'anadido_por', current_setting('prueba.u_admin')))
    returning id into u;
  if not exists (select 1 from usuarios where id = u) then raise exception 'FALLO 270 · con el registro cerrado no entra el usuario que da de alta Dynamo'; end if;
  update parametros set valor = 'true'::jsonb where clave = 'registro_clientes_abierto';
  -- Abierto otra vez: el alta por su cuenta vuelve a entrar (pendiente de verificar).
  insert into auth.users (email, raw_user_meta_data) values ('nuevo270@cliente.prueba', '{"tipo_usuario":"cliente","nombre":"Nuevo Doscientos Setenta"}') returning id into u;
  if (select estado from usuarios where id = u) <> 'pendiente_verificacion' then raise exception 'FALLO 270 · con el registro abierto el alta no queda pendiente de verificar'; end if;
end $$;
set role anon;
do $$ begin
  if not registro_clientes_abierto() then raise exception 'FALLO 270 · la página de registro (sin sesión) no puede leer si el registro está abierto'; end if;
  raise notice 'OK 270 · registro de clientes: nace abierto; cerrado no entra ningún alta por su cuenta (tampoco saltándose la web), sí la que pide un usuario activo; y se reabre';
end $$;
reset role;

-- ---- 271. Bloqueo automático del crédito a quien paga tarde ----
do $$ declare cli uuid; cli2 uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; r text; e jsonb; begin
  insert into clientes (razon_social, cif, riesgo_cesce_euros, riesgo_manual_euros) values ('Paga Tarde 271 SL', 'B27100271', 20000, 8000) returning id into cli;
  insert into clientes (razon_social, cif, riesgo_cesce_euros) values ('Buen Cliente 271 SL', 'B27100272', 30000) returning id into cli2;
  -- APAGADO (como nace): tres facturas tardías no bloquean a nadie.
  insert into facturas_cliente (cliente_id, numero, fecha_emision, fecha_cobro) values (cli, 'F-1', hoy - 300, hoy - 200), (cli, 'F-2', hoy - 250, hoy - 160), (cli, 'F-3', hoy - 200, hoy - 110);
  if (select riesgo_manual_euros from clientes where id = cli) <> 8000 or exists (select 1 from clientes_pagos where cliente_id = cli and bloqueado_en is not null) then
    raise exception 'FALLO 271 · con el bloqueo apagado se le quita el crédito a un cliente';
  end if;
  update parametros set valor = 'true'::jsonb where clave = 'pago_tarde_activo';
  -- Con dos tardías de las últimas tres (se toleran 2) sigue con su crédito…
  insert into facturas_cliente (cliente_id, numero, fecha_emision, fecha_cobro) values (cli, 'F-4', hoy - 100, hoy - 60);
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 8000 then raise exception 'FALLO 271 · se bloquea con las tardías toleradas'; end if;
  -- …y a la tercera (una factura SIN cobrar pasado el plazo también cuenta) se queda a cero.
  update facturas_cliente set fecha_cobro = null where cliente_id = cli and numero = 'F-2';
  update facturas_cliente set fecha_emision = hoy - 90, fecha_cobro = null where cliente_id = cli and numero = 'F-4';
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 0 then
    raise exception 'FALLO 271 · con tres facturas tardías no se bloquea el crédito: %', fn_credito_pagos_estado(cli);
  end if;
  if (select credito_manual_antes from clientes_pagos where cliente_id = cli) <> 8000 or (select bloqueado_en from clientes_pagos where cliente_id = cli) is null then
    raise exception 'FALLO 271 · el bloqueo no guarda el crédito que tenía el cliente';
  end if;
  if not exists (select 1 from avisos where tipo = 'credito_bloqueado_pagos' and titulo like '%Paga Tarde 271 SL')
     or not exists (select 1 from emails_enviados where tipo = 'credito_bloqueo' and destinatario = email_dynamo() and cuerpo_html like '%F-4%sin cobrar%') then
    raise exception 'FALLO 271 · el bloqueo no avisa a Dynamo (campana y email con las facturas)';
  end if;
  -- Al cobrar lo vencido no se le devuelve solo: aviso a Dynamo, una vez.
  update facturas_cliente set fecha_cobro = hoy where cliente_id = cli and fecha_cobro is null;
  update facturas_cliente set importe = 100 where cliente_id = cli and numero = 'F-4';
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 0 or (select count(*) from avisos where tipo = 'credito_pagos_al_dia' and titulo like '%Paga Tarde 271 SL') <> 1 then
    raise exception 'FALLO 271 · al ponerse al día se le devuelve solo el crédito, o no se avisa una sola vez';
  end if;
  -- REGLA PROPIA: al buen cliente se le dan 150 días y se le toleran 3; con la general ya estaría bloqueado.
  insert into clientes_pagos (cliente_id, dias_max, facturas_toleradas) values (cli2, 150, 3);
  insert into facturas_cliente (cliente_id, numero, fecha_emision, fecha_cobro) values (cli2, 'G-1', hoy - 300, hoy - 180), (cli2, 'G-2', hoy - 250, hoy - 130), (cli2, 'G-3', hoy - 200, hoy - 80), (cli2, 'G-4', hoy - 120, null);
  if (select riesgo_efectivo_euros from clientes where id = cli2) <> 30000 then
    raise exception 'FALLO 271 · la regla propia del cliente no manda sobre la general: %', fn_credito_pagos_estado(cli2);
  end if;
  e := fn_credito_pagos_estado(cli2);
  if (e ->> 'dias_max')::int <> 150 or (e ->> 'toleradas')::int <> 3 or (e ->> 'miradas')::int <> 4 or not (e ->> 'regla_propia')::boolean then
    raise exception 'FALLO 271 · el estado no refleja la regla propia: %', e;
  end if;
  -- Una factura marcada «no cuenta» (abono, en disputa) no suma.
  insert into facturas_cliente (cliente_id, numero, fecha_emision, no_cuenta) values (cli2, 'G-5', hoy - 400, true);
  if (select riesgo_efectivo_euros from clientes where id = cli2) <> 30000 then raise exception 'FALLO 271 · una factura que no cuenta bloquea el crédito'; end if;
  perform set_config('prueba.cli271', cli::text, false);
end $$;
-- Solo el Admin Master ve y toca todo esto; ni el cliente ni nadie sin sesión.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  if exists (select 1 from facturas_cliente) or exists (select 1 from clientes_pagos) then raise exception 'FALLO 271 · un cliente lee las facturas o las reglas de pago'; end if;
  begin
    perform credito_pagos_estado(current_setting('prueba.cli271')::uuid);
    raise exception 'FALLO 271 · un cliente consulta el estado de pagos';
  exception when insufficient_privilege then null; end;
  begin
    perform credito_desbloquear(current_setting('prueba.cli271')::uuid);
    raise exception 'FALLO 271 · un cliente se devuelve el crédito';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
-- El Admin le devuelve el crédito: vuelve el que tenía y las tardías de hoy no lo bloquean otra vez.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare cli uuid := current_setting('prueba.cli271')::uuid; r jsonb; begin
  if (credito_pagos_estado(cli) ->> 'tardias')::int < 3 then raise exception 'FALLO 271 · el Admin no ve las facturas tardías'; end if;
  r := credito_desbloquear(cli);
  if r ->> 'resultado' <> 'ok' or (select riesgo_manual_euros from clientes where id = cli) <> 8000 then
    raise exception 'FALLO 271 · al devolver el crédito no vuelve el que tenía: %', r;
  end if;
  update facturas_cliente set importe = 200 where cliente_id = cli and numero = 'F-4';   -- cualquier cambio vuelve a revisar
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 8000 then raise exception 'FALLO 271 · tras devolverle el crédito, las mismas facturas lo bloquean otra vez'; end if;
  -- Otra tardía NUEVA sí lo vuelve a bloquear.
  insert into facturas_cliente (cliente_id, numero, fecha_emision) values (cli, 'F-5', (now() at time zone 'Europe/Madrid')::date - 75);
  if (select riesgo_efectivo_euros from clientes where id = cli) <> 0 then raise exception 'FALLO 271 · una factura tardía nueva no vuelve a bloquear el crédito'; end if;
  raise notice 'OK 271 · pagos tardíos: apagado no bloquea; encendido bloquea a la factura que pasa de las toleradas (también sin cobrar), guarda el crédito y avisa a Dynamo; no lo devuelve solo; manda la regla propia del cliente; solo el Admin lo ve y lo devuelve, y hace falta otra tardía nueva para bloquear de nuevo';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false'::jsonb where clave = 'pago_tarde_activo';

-- ---- 272. Resumen mensual a los sitios: un email por dirección, sin la ruta, con sus exclusiones y su baja ----
do $$ declare cli uuid; cli2 uuid; cli3 uuid; s1 uuid; s1b uuid; s2 uuid; s2b uuid; s3 uuid; s4 uuid; e uuid; i int; n int; r record; tk uuid;
  mes date := (date_trunc('month', (now() at time zone 'Europe/Madrid')::date) - interval '1 month')::date;
begin
  insert into clientes (razon_social, cif) values ('Remite 272 SL', 'B27200272') returning id into cli;
  insert into clientes (razon_social, cif) values ('Otro Remite 272 SL', 'B27200273') returning id into cli2;
  insert into clientes (razon_social, cif, discrecion_comercial) values ('Discreto 272 SL', 'B27200274', true) returning id into cli3;
  insert into contactos (cliente_id, funcion, email) values (cli, 'trafico', 'logistica@remite272.prueba');
  -- El mismo almacén de destino, en la agenda de dos clientes (y con la dirección escrita distinta).
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli, 'Almacén Destino 272', 'Calle Uno 1', '28821', 'Coslada', 'ES', array['recepcion@destino272.prueba']) returning id into s1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli2, 'Almacen Destino 272', 'C/ Uno 1', '28821', 'Coslada', 'ES', array['recepcion@destino272.prueba']) returning id into s1b;
  -- La nave del propio cliente (dominio de correo de su empresa): no recibe nada.
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli, 'Nave Remite 272', 'Calle Dos 2', '41001', 'Sevilla', 'ES', array['nave@remite272.prueba']) returning id into s2;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli2, 'Origen Otro 272', 'Calle Tres 3', '41001', 'Sevilla', 'ES', '{}') returning id into s2b;
  -- Del cliente con discreción comercial: su destino TAMBIÉN recibe el resumen (2026-11-20: el
  -- resumen no dice de parte de qué cliente, así que la discreción no lo impide).
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli3, 'Origen Discreto 272', 'Calle Cuatro 4', '41001', 'Sevilla', 'ES', '{}') returning id into s3;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, emails_avisos)
    values (cli3, 'Destino Discreto 272', 'Calle Cinco 5', '08001', 'Barcelona', 'ES', array['almacen@discreto-destino272.prueba']) returning id into s4;
  for i in 1 .. 3 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
      values (case i when 1 then cli when 2 then cli2 else cli3 end, 6, 5, 600, 450, mes + 5) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, sitio_id, nombre_empresa, codigo_postal, poblacion, pais_codigo_iso, realizado_en)
      values (e, 1, 'carga', case i when 1 then s2 when 2 then s2b else s3 end, 'Origen', '41001', 'Sevilla', 'ES', (mes + 5 * i)::timestamptz + interval '10 hours');
    insert into envio_paradas (envio_id, orden, tipo, sitio_id, nombre_empresa, codigo_postal, poblacion, pais_codigo_iso, realizado_en)
      values (e, 2, 'descarga', case i when 1 then s1 when 2 then s1b else s4 end, 'Destino', '28821', 'Coslada', 'ES', (mes + 5 * i + 1)::timestamptz + interval '9 hours');
    alter table envios disable trigger user;
    update envios set estado = 'entregado', entregado_en = (mes + 5 * i + 1)::timestamptz, codigo_aceptacion = null where id = e;
    alter table envios enable trigger user;
  end loop;
  -- APAGADO (como nace): no prepara nada.
  if encolar_resumen_sitios() <> 0 or exists (select 1 from emails_enviados where tipo = 'resumen_sitio') then
    raise exception 'FALLO 272 · con el resumen apagado se preparan emails';
  end if;
  n := encolar_resumen_sitios(null, true);
  select * into r from emails_enviados where tipo = 'resumen_sitio' and destinatario = 'recepcion@destino272.prueba';
  if r.id is null or (select count(*) from emails_enviados where tipo = 'resumen_sitio' and destinatario like '%272.prueba') <> 2
     or not exists (select 1 from emails_enviados where tipo = 'resumen_sitio' and destinatario = 'almacen@discreto-destino272.prueba') then
    raise exception 'FALLO 272 · el almacén que está en la agenda de dos clientes no recibe un solo resumen (%): %', n,
      (select string_agg(destinatario, ' | ') from emails_enviados where tipo = 'resumen_sitio');
  end if;
  if position('Entrega' in r.cuerpo_html) = 0 or position('/baja/' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 272 · al resumen le falta el tipo o el enlace de baja: %', r.cuerpo_html;
  end if;
  -- Nunca el otro extremo de la ruta ni el nombre del cliente.
  if position('Sevilla' in r.cuerpo_html) > 0 or position('Origen' in r.cuerpo_html) > 0 or position('Remite 272' in r.cuerpo_html) > 0
     or position('de parte de' in r.cuerpo_html) > 0
     or position('Discreto 272 SL' in (select cuerpo_html from emails_enviados where destinatario = 'almacen@discreto-destino272.prueba')) > 0 then
    raise exception 'FALLO 272 · el resumen enseña el origen de la ruta o el cliente: %', r.cuerpo_html;
  end if;
  -- Una vez por dirección y mes.
  if encolar_resumen_sitios(null, true) <> 0 then raise exception 'FALLO 272 · el resumen del mismo mes se prepara dos veces'; end if;
  select token into tk from resumen_destinatarios where email = 'recepcion@destino272.prueba';
  perform set_config('prueba.tk272', tk::text, false);
end $$;
-- LA BAJA, sin sesión: consultar no da de baja; confirmar sí, y lo que esperaba ya no sale.
set role anon;
do $$ declare tk uuid := current_setting('prueba.tk272')::uuid; begin
  if baja_resumen_sitio(tk) ->> 'resultado' <> 'pendiente' or baja_resumen_sitio(tk) ->> 'resultado' <> 'pendiente' then raise exception 'FALLO 272 · abrir el enlace de baja ya da de baja'; end if;
  if baja_resumen_sitio(tk, true) ->> 'resultado' <> 'ok' or baja_resumen_sitio(tk, true) ->> 'resultado' <> 'ya_de_baja' then raise exception 'FALLO 272 · la baja no se confirma'; end if;
  if baja_resumen_sitio(gen_random_uuid(), true) ->> 'resultado' <> 'enlace_no_valido' then raise exception 'FALLO 272 · un enlace de baja inventado vale'; end if;
end $$;
reset role;
do $$ begin
  if (select estado from emails_enviados where tipo = 'resumen_sitio' and destinatario = 'recepcion@destino272.prueba') <> 'omitido' then
    raise exception 'FALLO 272 · tras la baja, el resumen pendiente sigue saliendo';
  end if;
  -- Dado de baja: el mes siguiente ya no se le prepara.
  delete from emails_enviados where tipo = 'resumen_sitio';
  perform encolar_resumen_sitios(null, true);
  if exists (select 1 from emails_enviados where tipo = 'resumen_sitio' and destinatario = 'recepcion@destino272.prueba') then
    raise exception 'FALLO 272 · se prepara el resumen a una dirección dada de baja'; end if;
  raise notice 'OK 272 · resumen mensual a los sitios: apagado no sale; un solo email por dirección; sin el cliente ni el otro extremo de la ruta (y con discreción comercial también sale); sin la nave del propio cliente; una vez al mes; y la baja funciona';
end $$;


-- ---- 273. «Recibe los avisos» de los contactos del cliente, por rol ----
do $$ declare e uuid := current_setting('prueba.e269')::uuid; cli uuid; l text; d text; antes text; pend text; begin
  select cliente_id into cli from envios where id = e;
  antes := emails_cliente_envio(e);
  insert into contactos (cliente_id, nombre, funcion, email, recibe_avisos) values
    (cli, 'Logística con avisos', 'trafico', 'Log273@Contacto.prueba', true),
    (cli, 'Logística sin avisos', 'trafico', 'logno273@contacto.prueba', false),
    (cli, 'Contabilidad con avisos', 'contabilidad', 'conta273@contacto.prueba', true),
    (cli, 'Contabilidad sin avisos', 'contabilidad', 'contano273@contacto.prueba', false),
    (cli, 'General con avisos', 'general', 'gen273@contacto.prueba', true);
  -- Emails de los ENVÍOS: los de antes más Logística con avisos; nadie más.
  l := emails_cliente_envio(e);
  if position('log273@contacto.prueba' in l) = 0 or l ~ '(logno273|conta273|contano273|gen273)' then
    raise exception 'FALLO 273 · los emails del envío no van a Logística con avisos (o van a quien no toca): %', l;
  end if;
  if exists (select 1 from unnest(string_to_array(antes, ',')) x where position(lower(btrim(x)) in l) = 0) then
    raise exception 'FALLO 273 · al añadir los contactos se pierde algún destinatario de antes: % → %', antes, l;
  end if;
  if (select count(*) from unnest(string_to_array(l, ',')) x) <> (select count(distinct x) from unnest(string_to_array(l, ',')) x) then
    raise exception 'FALLO 273 · hay direcciones repetidas en los emails del envío: %', l;
  end if;
  -- Emails de PAGOS Y CRÉDITO: Contabilidad con avisos; Logística no.
  d := emails_del_cliente(cli);
  if position('conta273@contacto.prueba' in coalesce(d, '')) = 0 or d ~ '(contano273|log273|logno273|gen273)' then
    raise exception 'FALLO 273 · los emails de crédito no van a Contabilidad con avisos (o van a quien no toca): %', d;
  end if;
  -- «Envío creado» PENDIENTE DE PAGO: va además a Contabilidad. (Se prueba y se deshace.)
  begin
    alter table envios disable trigger user;
    update envios set estado_pago_previo = 'pendiente' where id = e;
    alter table envios enable trigger user;
    perform fn_email_envio_cliente(e, 'prueba273:' || e, 'envio_creado', 'Envío creado', '<p>prueba</p>');
    select destinatario into pend from emails_enviados where clave = 'prueba273:' || e;
    raise exception 'deshacer273';
  exception when others then
    if sqlerrm <> 'deshacer273' then raise; end if;
  end;
  if pend is null or position('conta273@contacto.prueba' in pend) = 0 or position('log273@contacto.prueba' in pend) = 0 or pend ~ '(contano273|logno273|gen273)' then
    raise exception 'FALLO 273 · el «envío creado» pendiente de pago no va a Logística y a Contabilidad: %', pend;
  end if;
  -- Sin pago pendiente, el «envío creado» no va a Contabilidad.
  perform fn_email_envio_cliente(e, 'prueba273b:' || e, 'envio_creado', 'Envío creado', '<p>prueba</p>');
  select destinatario into pend from emails_enviados where clave = 'prueba273b:' || e;
  if pend is not null and position('conta273' in pend) > 0 then
    raise exception 'FALLO 273 · un «envío creado» sin pago pendiente va a Contabilidad: %', pend;
  end if;
  delete from emails_enviados where clave like 'prueba273%';
  delete from contactos where cliente_id = cli and email ilike '%273@contacto.prueba';
  if emails_cliente_envio(e) is distinct from fn_unir_emails(antes) then raise exception 'FALLO 273 · al quitar los contactos no vuelve la lista de antes'; end if;
  raise notice 'OK 273 · «Recibe los avisos» de los contactos del cliente: Logística recibe los emails de los envíos, Contabilidad los de crédito y el «envío creado» pendiente de pago; sin el interruptor, o con otro rol, nada; sin direcciones repetidas';
end $$;
-- Nadie de fuera lee esas listas.
set role anon;
do $$ begin
  begin perform emails_cliente_envio(gen_random_uuid()); raise exception 'FALLO 273 · cualquiera lee a quién se escribe de un envío';
  exception when insufficient_privilege then null; end;
  begin perform emails_contactos_cliente(gen_random_uuid(), 'trafico'); raise exception 'FALLO 273 · cualquiera lee los contactos con avisos de un cliente';
  exception when insufficient_privilege then null; end;
  begin perform emails_contabilidad_envio(gen_random_uuid()); raise exception 'FALLO 273 · cualquiera lee los contactos de contabilidad de un envío';
  exception when insufficient_privilege then null; end;
end $$;
reset role;


-- ---- 274. «Editar empresa» del cliente: ve su sector y cambia solo SUS contactos ----
do $$ declare u uuid; cli uuid; sec text; begin
  -- Un usuario de cliente con la cuenta activa (el de otras pruebas puede haber cambiado de estado).
  select id, cliente_id into u, cli from usuarios where rol = 'cliente' and estado = 'activa' and cliente_id is not null order by creado_en limit 1;
  if u is null then raise exception 'FALLO 274 · no hay ningún usuario de cliente activo para la prueba'; end if;
  select s into sec from jsonb_array_elements_text(parametro('sectores_cliente')) s limit 1;
  update clientes set sector = sec where id = cli;
  perform set_config('prueba.u274', u::text, false);
  perform set_config('prueba.sec274', sec, false);
  perform set_config('prueba.cli274', cli::text, false);
  perform set_config('prueba.otro274', (select id::text from clientes where id <> cli order by creado_en limit 1), false);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u274'), false);
set role authenticated;
do $$ declare c uuid; begin
  if mi_empresa_sector() is distinct from current_setting('prueba.sec274') then raise exception 'FALLO 274 · el cliente no lee el sector de su empresa: %', mi_empresa_sector(); end if;
  -- Sus contactos: los crea, los cambia y los borra él.
  insert into contactos (cliente_id, nombre, funcion, email, recibe_avisos) values (current_setting('prueba.cli274')::uuid, 'Contacto 274', 'trafico', 'c274@contacto.prueba', true) returning id into c;
  update contactos set funcion = 'contabilidad', recibe_avisos = false where id = c;
  if not exists (select 1 from contactos where id = c and funcion = 'contabilidad' and not recibe_avisos) then raise exception 'FALLO 274 · el cliente no puede cambiar un contacto de su empresa'; end if;
  delete from contactos where id = c;
  if exists (select 1 from contactos where id = c) then raise exception 'FALLO 274 · el cliente no puede borrar un contacto de su empresa'; end if;
  -- Los de OTRA empresa: ni crearlos.
  begin
    insert into contactos (cliente_id, nombre, funcion, email) values (current_setting('prueba.otro274')::uuid, 'Intruso 274', 'trafico', 'x274@contacto.prueba');
    raise exception 'FALLO 274 · un cliente crea contactos en otra empresa';
  exception when insufficient_privilege or check_violation then null; when others then if sqlerrm like 'FALLO 274%' then raise; end if; end;
  -- Y los datos fiscales de su empresa no los toca.
  begin
    update clientes set razon_social = 'Cambiada por el cliente 274' where id = current_setting('prueba.cli274')::uuid;
  exception when others then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  if exists (select 1 from clientes where razon_social = 'Cambiada por el cliente 274') then raise exception 'FALLO 274 · el cliente cambia la razón social de su empresa'; end if;
  if exists (select 1 from contactos where email = 'x274@contacto.prueba') then raise exception 'FALLO 274 · quedó un contacto creado en otra empresa'; end if;
  raise notice 'OK 274 · «Editar empresa» del cliente: lee su sector, cambia solo los contactos de su empresa y no toca los datos fiscales';
end $$;
set role anon;
do $$ begin
  begin perform mi_empresa_sector(); raise exception 'FALLO 274 · sin sesión se llama a mi_empresa_sector';
  exception when insufficient_privilege then null; end;
end $$;
reset role;


-- ---- 275. Consumo de crédito en la lista de clientes: el mismo número de CESCE - Riesgos ----
select set_config('prueba.dias275', parametro_num('riesgo_dias_asumido', 60)::int::text, false);
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r record; k record; n int; begin
  -- El cliente con más riesgo asumido (si lo hay) y otro cualquiera: los dos deben coincidir.
  for r in (select * from riesgos_clientes() order by asumido desc nulls last limit 1)
           union all (select * from riesgos_clientes() order by cliente_id limit 1) loop
    select * into k from consumo_clientes(array[r.cliente_id]);
    if k.cliente_id is null then raise exception 'FALLO 275 · consumo_clientes no devuelve al cliente pedido'; end if;
    if k.consumo is distinct from r.asumido or k.envios is distinct from r.envios
       or k.limite is distinct from r.riesgo_efectivo or k.disponible is distinct from r.disponible then
      raise exception 'FALLO 275 · el consumo de la lista no coincide con CESCE - Riesgos: % frente a %', row_to_json(k), row_to_json(r);
    end if;
    if k.dias is distinct from current_setting('prueba.dias275')::int then raise exception 'FALLO 275 · los días contados no son los del parámetro: %', k.dias; end if;
  end loop;
  -- Solo trae los clientes pedidos.
  select count(*) into n from consumo_clientes(array[]::uuid[]);
  if n <> 0 then raise exception 'FALLO 275 · sin clientes pedidos devuelve filas'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare n int; begin
  select count(*) into n from consumo_clientes(array(select id from clientes));
  if n <> 0 then raise exception 'FALLO 275 · un cliente lee el consumo de crédito (es solo del equipo)'; end if;
  raise notice 'OK 275 · consumo de crédito en la lista de clientes: coincide con CESCE - Riesgos y el cliente no lo ve';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
set role anon;
do $$ begin
  begin perform consumo_clientes(array[]::uuid[]); raise exception 'FALLO 275 · sin sesión se llama a consumo_clientes';
  exception when insufficient_privilege then null; end;
end $$;
reset role;


-- ---- 276. CMR en papel por el enlace: fotos subidas desde la hoja de firmas ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; tok uuid; begin
  -- Un envío vivo con su enlace de firmas (nace con el envío).
  select c.envio_id, c.token into e, tok from cmr_enlaces c join envios x on x.id = c.envio_id
   where not c.revocado and x.estado <> 'cancelado' and cmr_envio_de_token(c.token) is not null
     and not exists (select 1 from documentos d where d.envio_id = c.envio_id and d.tipo = 'cmr_firmado')
   order by x.creado_en desc limit 1;
  if tok is null then raise exception 'FALLO 276 · no hay ningún enlace de CMR vivo para la prueba'; end if;
  perform set_config('prueba.e276', e::text, false);
  perform set_config('prueba.tok276', tok::text, false);
  perform set_config('prueba.p276', 'cmr/' || tok::text || '/papel-' || gen_random_uuid()::text, false);
  delete from avisos where envio_id = e and tipo = 'cmr_papel_subido';
end $$;
set role anon;
do $$ declare tok text := current_setting('prueba.tok276'); begin
  -- La norma de rutas: la foto de una reserva y la página en papel se pueden subir…
  insert into storage.objects (bucket_id, name) values ('documentos', 'cmr/' || tok || '/foto-' || gen_random_uuid()::text || '.jpg');
  insert into storage.objects (bucket_id, name) values ('documentos', current_setting('prueba.p276') || '.jpg');
  -- …y cualquier otra cosa, no.
  begin
    insert into storage.objects (bucket_id, name) values ('documentos', 'cmr/' || tok || '/papel-' || gen_random_uuid()::text || '.exe');
    raise exception 'FALLO 276 · se sube un fichero que no es imagen ni PDF';
  exception when insufficient_privilege then null; end;
  begin
    insert into storage.objects (bucket_id, name) values ('documentos', 'cmr/' || tok || '/otra-cosa.jpg');
    raise exception 'FALLO 276 · se sube un fichero con un nombre libre';
  exception when insufficient_privilege then null; end;
  begin
    insert into storage.objects (bucket_id, name) values ('documentos', 'cmr/' || gen_random_uuid()::text || '/papel-' || gen_random_uuid()::text || '.jpg');
    raise exception 'FALLO 276 · se sube una página con un enlace inventado';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
do $$ declare tok text := current_setting('prueba.tok276'); begin
  -- Los datos del fichero los pone el almacén: aquí se simulan (una buena, una enorme, un PDF y un vídeo).
  update storage.objects set metadata = jsonb_build_object('mimetype', 'image/jpeg', 'size', 500000) where name = current_setting('prueba.p276') || '.jpg';
  insert into storage.objects (bucket_id, name, metadata) values
    ('documentos', current_setting('prueba.p276') || '.png',  jsonb_build_object('mimetype', 'image/png', 'size', 30000000)),
    ('documentos', current_setting('prueba.p276') || '.pdf',  jsonb_build_object('mimetype', 'application/pdf', 'size', 900000)),
    ('documentos', current_setting('prueba.p276') || '.webp', jsonb_build_object('mimetype', 'video/mp4', 'size', 1000));
end $$;
set role anon;
do $$ declare r jsonb; p text := current_setting('prueba.p276'); begin
  if (subir_cmr_papel_publico(gen_random_uuid(), array[p || '.jpg']))->>'resultado' <> 'enlace_no_valido' then
    raise exception 'FALLO 276 · un enlace inventado sube páginas del CMR'; end if;
  r := subir_cmr_papel_publico(current_setting('prueba.tok276')::uuid, array['cmr/' || gen_random_uuid()::text || '/papel-x.jpg', p || '-no-existe.jpg']);
  if r->>'resultado' <> 'sin_fotos' then raise exception 'FALLO 276 · cuelan rutas de otro enlace o inventadas: %', r; end if;
  r := subir_cmr_papel_publico(current_setting('prueba.tok276')::uuid, array[p || '.jpg', p || '.png', p || '.pdf', p || '.webp', p || '.jpg']);
  if r->>'resultado' <> 'ok' or (r->>'paginas')::int <> 2 then
    raise exception 'FALLO 276 · deben entrar solo la foto buena y el PDF (ni la de 30 MB, ni el vídeo, ni la repetida): %', r; end if;
  -- Repetir la misma subida no duplica nada.
  r := subir_cmr_papel_publico(current_setting('prueba.tok276')::uuid, array[p || '.jpg', p || '.pdf']);
  if r->>'resultado' <> 'sin_fotos' then raise exception 'FALLO 276 · la misma página se guarda dos veces: %', r; end if;
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e276')::uuid; n int; begin
  select count(*) into n from documentos d where d.envio_id = e and d.tipo = 'cmr_firmado' and d.storage_ruta like '%/papel-%' and not d.visible_cliente
     and d.nombre_archivo like 'CMR en papel · %';
  if n <> 2 then raise exception 'FALLO 276 · las páginas no cuelgan del envío como CMR firmado, sin enseñar al cliente: %', n; end if;
  if (select count(*) from avisos where envio_id = e and tipo = 'cmr_papel_subido' and para = 'dynamo') <> 1 then
    raise exception 'FALLO 276 · Dynamo no recibe (una vez) el aviso del CMR en papel'; end if;
  -- El tope: 10 páginas por enlace.
  insert into storage.objects (bucket_id, name, metadata)
  select 'documentos', 'cmr/' || current_setting('prueba.tok276') || '/papel-' || gen_random_uuid()::text || '.jpg', jsonb_build_object('mimetype', 'image/jpeg', 'size', 1000)
    from generate_series(1, 12);
end $$;
do $$ declare r jsonb; e uuid := current_setting('prueba.e276')::uuid; rutas text[]; begin
  select array_agg(o.name) into rutas from storage.objects o
   where o.name like 'cmr/' || current_setting('prueba.tok276') || '/papel-%'
     and not exists (select 1 from documentos d where d.storage_ruta = o.name);
  perform set_config('prueba.r276', array_to_string(rutas, ','), false);
end $$;
set role anon;
do $$ declare r jsonb; rutas text[] := string_to_array(current_setting('prueba.r276'), ','); begin
  r := subir_cmr_papel_publico(current_setting('prueba.tok276')::uuid, rutas[1:10]);
  if r->>'resultado' <> 'ok' or (r->>'total')::int <> 10 then raise exception 'FALLO 276 · el tope de 10 páginas no se respeta al llenar: %', r; end if;
  r := subir_cmr_papel_publico(current_setting('prueba.tok276')::uuid, rutas[11:14]);
  if r->>'resultado' <> 'demasiadas' then raise exception 'FALLO 276 · se pasa de 10 páginas: %', r; end if;
  raise notice 'OK 276 · CMR en papel por el enlace: solo imágenes o PDF de ese enlace, 20 MB y 10 páginas como mucho, sin duplicar, ocultas al cliente y con aviso a Dynamo';
end $$;
reset role;


-- ---- 277. Documentos adicionales por el enlace: fotos subidas desde la pantalla de firma ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  perform set_config('prueba.d277', 'cmr/' || current_setting('prueba.tok276') || '/doc-' || gen_random_uuid()::text, false);
  delete from avisos where envio_id = current_setting('prueba.e276')::uuid and tipo = 'documento_extra_subido';
end $$;
set role anon;
do $$ begin
  -- El almacén deja subir «doc-<uuid>.<ext>» en la carpeta del enlace.
  insert into storage.objects (bucket_id, name) values ('documentos', current_setting('prueba.d277') || '.jpg');
end $$;
reset role;
do $$ begin
  update storage.objects set metadata = jsonb_build_object('mimetype', 'image/jpeg', 'size', 400000) where name = current_setting('prueba.d277') || '.jpg';
end $$;
set role anon;
do $$ declare r jsonb; d text := current_setting('prueba.d277'); p text := current_setting('prueba.p276'); begin
  if (subir_documentos_extra_publico(gen_random_uuid(), array[d || '.jpg']))->>'resultado' <> 'enlace_no_valido' then
    raise exception 'FALLO 277 · un enlace inventado sube documentos'; end if;
  -- Una página del CMR en papel no cuela como documento adicional (cada cosa por su puerta).
  r := subir_documentos_extra_publico(current_setting('prueba.tok276')::uuid, array[p || '.jpg', d || '-no-existe.jpg']);
  if r->>'resultado' <> 'sin_fotos' then raise exception 'FALLO 277 · cuelan rutas que no son documentos adicionales: %', r; end if;
  r := subir_documentos_extra_publico(current_setting('prueba.tok276')::uuid, array[d || '.jpg', d || '.jpg']);
  if r->>'resultado' <> 'ok' or (r->>'paginas')::int <> 1 then raise exception 'FALLO 277 · el documento adicional no entra (una vez): %', r; end if;
  r := subir_documentos_extra_publico(current_setting('prueba.tok276')::uuid, array[d || '.jpg']);
  if r->>'resultado' <> 'sin_fotos' then raise exception 'FALLO 277 · el mismo documento se guarda dos veces: %', r; end if;
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e276')::uuid; begin
  if (select count(*) from documentos d where d.envio_id = e and d.tipo = 'otro' and d.storage_ruta like '%/doc-%'
        and not d.visible_cliente and d.nombre_archivo like 'Documento adicional · %') <> 1 then
    raise exception 'FALLO 277 · el documento no cuelga del envío como «otro», sin enseñar al cliente'; end if;
  if (select count(*) from avisos where envio_id = e and tipo = 'documento_extra_subido' and para = 'dynamo') <> 1 then
    raise exception 'FALLO 277 · Dynamo no recibe (una vez) el aviso de los documentos adicionales'; end if;
  -- No toca la cuenta de páginas del CMR en papel (siguen siendo 10).
  if (select count(*) from documentos d where d.envio_id = e and d.tipo = 'cmr_firmado' and d.storage_ruta like '%/papel-%') <> 10 then
    raise exception 'FALLO 277 · los documentos adicionales alteran las páginas del CMR en papel'; end if;
  raise notice 'OK 277 · documentos adicionales por el enlace: solo los «doc-» de ese enlace, sin duplicar, ocultos al cliente y con aviso a Dynamo';
end $$;


-- ---- 278. Marcar la transferencia con banco, concepto y fecha ----
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid; c record; begin
  -- Un envío pendiente de pago; si no queda ninguno, se le pide el pago a uno programado.
  select id into e from envios where estado = 'programado' and estado_pago_previo = 'pendiente' and not coalesce(es_manual, false)
   order by creado_en desc limit 1;
  if e is null then
    for c in select id from envios where estado = 'programado' and estado_pago_previo = 'no_requerido' and not coalesce(es_manual, false) and transportista_id is null loop
      if (marcar_pago_envio(c.id, 'requerir', 'Prueba 278')) ->> 'resultado' = 'ok' then e := c.id; exit; end if;
    end loop;
  end if;
  if e is null then raise exception 'FALLO 278 · no hay ningún envío pendiente de pago para la prueba'; end if;
  perform set_config('prueba.e278', e::text, false);
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  begin perform registrar_transferencia_envio(current_setting('prueba.e278')::uuid, 'BBVA', 'Pago', (now() at time zone 'Europe/Madrid')::date);
    raise exception 'FALLO 278 · un cliente marca una transferencia';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e278')::uuid; hoy date := (now() at time zone 'Europe/Madrid')::date; r jsonb; x record; begin
  if (registrar_transferencia_envio(e, ' ', 'Pago', hoy)) ->> 'resultado' <> 'falta_banco' then raise exception 'FALLO 278 · se marca sin banco'; end if;
  if (registrar_transferencia_envio(e, 'BBVA', 'Pago', hoy + 1)) ->> 'resultado' <> 'fecha_no_valida' then raise exception 'FALLO 278 · se marca con una fecha futura'; end if;
  if (registrar_transferencia_envio(e, 'BBVA', 'Pago', hoy - 200)) ->> 'resultado' <> 'fecha_no_valida' then raise exception 'FALLO 278 · se marca con una fecha de hace 200 días'; end if;
  if (registrar_transferencia_envio(e, 'BBVA', 'Pago', null)) ->> 'resultado' <> 'fecha_no_valida' then raise exception 'FALLO 278 · se marca sin fecha'; end if;
  if (registrar_transferencia_envio(e, 'BBVA', repeat('x', 201), hoy)) ->> 'resultado' <> 'concepto_largo' then raise exception 'FALLO 278 · se marca con un concepto de más de 200 caracteres'; end if;
  -- Nada de lo anterior ha marcado el pago.
  if (select estado_pago_previo from envios where id = e) <> 'pendiente' then raise exception 'FALLO 278 · un intento con datos malos marca el pago'; end if;
  r := registrar_transferencia_envio(e, ' CaixaBank ', ' Pago proforma GX - 17/11/26 ', hoy - 1);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 278 · no se marca la transferencia: %', r; end if;
  select estado_pago_previo, pago_metodo, pagado_en, pago_banco, pago_concepto, pago_fecha into x from envios where id = e;
  if x.estado_pago_previo <> 'pagado' or x.pago_metodo <> 'transferencia' or x.pagado_en is null
     or x.pago_banco <> 'CaixaBank' or x.pago_concepto <> 'Pago proforma GX - 17/11/26' or x.pago_fecha <> hoy - 1 then
    raise exception 'FALLO 278 · el envío no queda pagado con su banco, concepto y fecha: %', row_to_json(x); end if;
  if (registrar_transferencia_envio(e, 'BBVA', 'Otra vez', hoy)) ->> 'resultado' <> 'no_pendiente' then raise exception 'FALLO 278 · se marca dos veces'; end if;
  if (select pago_banco from envios where id = e) <> 'CaixaBank' then raise exception 'FALLO 278 · el segundo intento pisa el banco'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e278')::uuid; x record; begin
  -- Al deshacer el pago, los datos de la transferencia se vacían.
  update envios set estado_pago_previo = 'pendiente', pago_metodo = null, pagado_en = null where id = e;
  select pago_banco, pago_concepto, pago_fecha into x from envios where id = e;
  if x.pago_banco is not null or x.pago_concepto is not null or x.pago_fecha is not null then
    raise exception 'FALLO 278 · al deshacer el pago quedan los datos de la transferencia: %', row_to_json(x); end if;
  raise notice 'OK 278 · transferencia con banco, concepto y fecha: solo Dynamo, datos validados, una sola vez, y se vacían al deshacer el pago';
end $$;


-- ---- 279. El código de aceptación se apunta al repartirlo (sin choques entre altas simultáneas) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare v text; vistos text[] := '{}'; i int; begin
  v := generar_codigo_aceptacion();
  if v !~ '^[1-9][0-9]{5}$' then raise exception 'FALLO 279 · el código no tiene 6 cifras: %', v; end if;
  if not exists (select 1 from codigos_carga_retirados where codigo = v) then
    raise exception 'FALLO 279 · un código recién repartido no queda apuntado: otra alta simultánea podría sacarlo'; end if;
  -- Lo que hace que la segunda alta saque otro: el mismo número no entra dos veces.
  insert into codigos_carga_retirados (codigo) values (v) on conflict (codigo) do nothing;
  if found then raise exception 'FALLO 279 · el mismo código se apunta dos veces'; end if;
  -- Y seguidos, nunca repite ni reparte uno apuntado o en uso.
  for i in 1..60 loop
    v := generar_codigo_aceptacion();
    if v = any(vistos) then raise exception 'FALLO 279 · reparte dos veces el mismo código: %', v; end if;
    if exists (select 1 from envios where codigo_aceptacion = v) then raise exception 'FALLO 279 · reparte el código de un envío vivo: %', v; end if;
    vistos := vistos || v;
  end loop;
  -- Los envíos vivos siguen teniendo todos un código distinto.
  if exists (select 1 from envios where codigo_aceptacion is not null group by codigo_aceptacion having count(*) > 1) then
    raise exception 'FALLO 279 · hay dos envíos con el mismo código de aceptación'; end if;
  raise notice 'OK 279 · código de aceptación: se apunta al repartirlo, no entra dos veces y nunca repite';
end $$;


-- ---- 280. El plazo para cancelar gratis cuenta desde la fecha de carga ASIGNADA ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.envio')::uuid; n int; antes record; begin
  select estado, fecha_carga_desde, fecha_carga_hasta, fecha_carga_prevista, transportista_id into antes from envios where id = e;
  if antes.transportista_id is null then
    update envios set transportista_id = (select id from transportistas order by creado_en limit 1) where id = e;
  end if;
  update penalizaciones set estado = 'cancelada' where envio_id = e and estado <> 'cancelada';
  -- El caso del usuario: la ventana empezaba HOY (el corte de ese día ya pasó), pero la
  -- carga está ASIGNADA al último día de la ventana, dentro de 6 días: cancelar es gratis.
  -- (La fecha asignada se pone en un paso aparte: cambiar la ventana la vacía.)
  update envios set estado = 'programado', fecha_carga_desde = current_date, fecha_carga_hasta = current_date + 6 where id = e;
  update envios set fecha_carga_prevista = current_date + 6 where id = e;
  if (select fecha_carga_prevista from envios where id = e) is distinct from current_date + 6 then
    raise exception 'FALLO 280 · no se ha podido preparar el caso: la fecha asignada no queda puesta'; end if;
  update envios set estado = 'cancelado' where id = e;
  select count(*) into n from penalizaciones where envio_id = e and estado <> 'cancelada';
  if n <> 0 then raise exception 'FALLO 280 · con la carga asignada dentro de 6 días, cancelar penaliza (se sigue mirando el primer día de la ventana)'; end if;
  update envios set estado = 'programado' where id = e;
  -- Y al revés: la carga asignada es HOY → fuera de plazo, penaliza.
  update envios set fecha_carga_prevista = current_date where id = e;
  update envios set estado = 'cancelado' where id = e;
  select count(*) into n from penalizaciones where envio_id = e and generada_auto and estado <> 'cancelada';
  if n <> 1 then raise exception 'FALLO 280 · con la carga asignada hoy, cancelar no penaliza (%)', n; end if;
  update envios set estado = 'programado' where id = e;
  -- Sin fecha asignada sigue valiendo el primer día de la ventana: hoy → penaliza.
  update penalizaciones set estado = 'cancelada' where envio_id = e and estado <> 'cancelada';
  update envios set fecha_carga_prevista = null where id = e;
  update envios set estado = 'cancelado' where id = e;
  select count(*) into n from penalizaciones where envio_id = e and generada_auto and estado <> 'cancelada';
  if n <> 1 then raise exception 'FALLO 280 · sin fecha asignada y con la ventana empezando hoy, cancelar no penaliza (%)', n; end if;
  -- Se deja como estaba.
  update penalizaciones set estado = 'cancelada' where envio_id = e and estado <> 'cancelada';
  update envios set estado = antes.estado, fecha_carga_desde = antes.fecha_carga_desde, fecha_carga_hasta = antes.fecha_carga_hasta,
                    transportista_id = antes.transportista_id where id = e;
  update envios set fecha_carga_prevista = antes.fecha_carga_prevista where id = e;
  raise notice 'OK 280 · el plazo para cancelar gratis cuenta desde la fecha de carga asignada; sin asignar, desde el primer día de la ventana';
end $$;


-- ---- 281. Doble paso del equipo de Dynamo: sin el código, la base de datos no le reconoce ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
select set_config('request.jwt.claim.aal', '', false);
do $$ begin
  if (select valor #>> '{}' from parametros where clave = 'doble_paso_equipo') is distinct from 'false' then
    raise exception 'FALLO 281 · el doble paso no nace apagado'; end if;
end $$;
-- APAGADO (como nace): el Admin Master entra como siempre, sin segundo paso.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ begin
  if not (es_admin_master() and ve_todo() and es_equipo_dynamo()) then raise exception 'FALLO 281 · con el doble paso apagado, el Admin Master no es reconocido'; end if;
  if doble_paso_obligatorio() then raise exception 'FALLO 281 · dice que es obligatorio estando apagado'; end if;
end $$;
reset role;
update parametros set valor = 'true'::jsonb where clave = 'doble_paso_equipo';
-- ENCENDIDO y solo con la contraseña (aal1): no es nadie. Ni ayudantes, ni tablas, ni contadores.
set role authenticated;
do $$ declare n int; begin
  if sesion_nivel() <> 'aal1' then raise exception 'FALLO 281 · una sesión sin nivel no cuenta como aal1: %', sesion_nivel(); end if;
  if es_admin_master() or ve_todo() or es_equipo_dynamo() or es_solo_lectura() then
    raise exception 'FALLO 281 · FUGA: con el doble paso exigido y sin hacer, sigue siendo equipo de Dynamo'; end if;
  if not doble_paso_obligatorio() then raise exception 'FALLO 281 · a un usuario de Dynamo no le dice que es obligatorio'; end if;
  select count(*) into n from parametros;
  if n <> 0 then raise exception 'FALLO 281 · FUGA: sin el segundo paso lee % parámetros', n; end if;
  select count(*) into n from clientes;
  if n <> 0 then raise exception 'FALLO 281 · FUGA: sin el segundo paso lee % clientes', n; end if;
  select count(*) into n from envios;
  if n <> 0 then raise exception 'FALLO 281 · FUGA: sin el segundo paso lee % envíos', n; end if;
  if contadores_panel() <> '{}'::jsonb then raise exception 'FALLO 281 · FUGA: sin el segundo paso ve los contadores del menú: %', contadores_panel(); end if;
  begin
    perform registrar_doble_paso_quitado(current_setting('prueba.u_cli')::uuid);
    raise exception 'FALLO 281 · sin el segundo paso puede apuntar que quita un doble paso';
  exception when insufficient_privilege then null; end;
end $$;
-- Con el segundo paso hecho (aal2): vuelve a ser quien es.
select set_config('request.jwt.claim.aal', 'aal2', false);
do $$ declare n int; begin
  if not (es_admin_master() and ve_todo() and es_equipo_dynamo()) then raise exception 'FALLO 281 · con el segundo paso hecho, el Admin Master no es reconocido'; end if;
  select count(*) into n from parametros;
  if n = 0 then raise exception 'FALLO 281 · con el segundo paso hecho no lee los parámetros'; end if;
  if contadores_panel() = '{}'::jsonb then raise exception 'FALLO 281 · con el segundo paso hecho no ve los contadores'; end if;
  perform registrar_doble_paso_quitado(current_setting('prueba.u_cli')::uuid);
end $$;
-- El nivel también se lee del token entero (como lo manda Supabase).
select set_config('request.jwt.claim.aal', '', false);
select set_config('request.jwt.claims', '{"aal":"aal2"}', false);
do $$ begin
  if sesion_nivel() <> 'aal2' or not ve_todo() then raise exception 'FALLO 281 · no lee el nivel del token entero'; end if;
end $$;
select set_config('request.jwt.claims', '', false);
-- A un CLIENTE no le afecta: entra como siempre y no se le exige.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
do $$ begin
  if cliente_del_usuario() is null then raise exception 'FALLO 281 · el doble paso del equipo deja fuera a un cliente'; end if;
  if doble_paso_obligatorio() then raise exception 'FALLO 281 · a un cliente le dice que el doble paso es obligatorio'; end if;
  begin
    perform registrar_doble_paso_quitado(current_setting('prueba.u_admin')::uuid);
    raise exception 'FALLO 281 · un cliente puede apuntar que quita un doble paso';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false'::jsonb where clave = 'doble_paso_equipo';
do $$ begin
  if not exists (select 1 from auditoria where tabla = 'usuarios' and registro_id = current_setting('prueba.u_cli') and cambios ? 'doble_paso') then
    raise exception 'FALLO 281 · quitar un doble paso no queda en la auditoría'; end if;
  raise notice 'OK 281 · doble paso del equipo: nace apagado; encendido, sin el código la base de datos no reconoce a nadie de Dynamo (ni tablas ni contadores); con él, sí; a los clientes no les afecta; quitarlo queda en la auditoría';
end $$;


-- ---- 282. Al cliente se le avisa POR EMAIL cuando su albarán o su CMR firmado está disponible ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.envio')::uuid; d uuid; n int; antes int; begin
  select count(*) into antes from emails_enviados where tipo = 'documento_disponible';
  -- Un documento que el cliente todavía NO ve: ni aviso ni email.
  insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, visible_cliente)
    values (e, 'albaran', 'envios/prueba-282/albaran.pdf', 'albaran.pdf', false) returning id into d;
  select count(*) into n from emails_enviados where tipo = 'documento_disponible';
  if n <> antes then raise exception 'FALLO 282 · se manda el email de un documento que el cliente no ve'; end if;
  -- Al hacerlo visible: un email, una vez.
  update documentos set visible_cliente = true where id = d;
  select count(*) into n from emails_enviados where tipo = 'documento_disponible' and clave = 'documento_disponible:' || d and envio_id = e;
  if n <> 1 then raise exception 'FALLO 282 · al hacer visible el albarán no se encola el email al cliente (%)', n; end if;
  if not exists (select 1 from emails_enviados where clave = 'documento_disponible:' || d and asunto like 'Albarán disponible%' and cuerpo_html like '%Documentos%') then
    raise exception 'FALLO 282 · el email no dice qué documento es ni dónde está'; end if;
  update documentos set visible_cliente = false where id = d;
  update documentos set visible_cliente = true where id = d;
  select count(*) into n from emails_enviados where clave = 'documento_disponible:' || d;
  if n <> 1 then raise exception 'FALLO 282 · el email del mismo documento se repite (%)', n; end if;
  -- Un documento que no es albarán ni CMR firmado no avisa.
  insert into documentos (envio_id, tipo, storage_ruta, nombre_archivo, visible_cliente)
    values (e, 'otro', 'envios/prueba-282/otro.pdf', 'otro.pdf', true);
  select count(*) into n from emails_enviados where tipo = 'documento_disponible';
  if n <> antes + 1 then raise exception 'FALLO 282 · avisa por email de un documento que no es albarán ni CMR firmado'; end if;
  raise notice 'OK 282 · albarán o CMR firmado visible para el cliente: un email al cliente, una sola vez por documento';
end $$;

-- ---- 283. El email «Envío creado» de un envío pendiente de pago dice hasta cuándo se puede pagar ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; s uuid; r record; v record; cli uuid := current_setting('prueba.cliente')::uuid;
  adm uuid := current_setting('prueba.u_admin')::uuid;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date; esperado text;
begin
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  -- (a) Pendiente de pago: el email lleva la hora límite, la MISMA que enseña la ficha.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1, adm) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now() where id = e;
  update envios set estado = 'programado' where id = e;
  select estado_pago_previo, pago_pendiente_en, fecha_carga_desde, estado_revision_precio into v from envios where id = e;
  if v.estado_pago_previo <> 'pendiente' or v.pago_pendiente_en is null then raise exception 'FALLO 283 · la prueba no ha dejado el envío pendiente de pago (%)', v.estado_pago_previo; end if;
  select * into r from emails_enviados where clave = 'envio_creado:' || e;
  if r.id is null then raise exception 'FALLO 283 · no se encola el email «Envío creado»'; end if;
  if coalesce(precio_por_revisar(v.estado_revision_precio), false) then
    -- Precio provisional: el plazo aún no ha empezado y el email no puede prometer una hora.
    if position('Plazo para pagar' in r.cuerpo_html) > 0 then raise exception 'FALLO 283 · con precio provisional el email da un plazo que aún no corre'; end if;
  else
    esperado := 'Plazo para pagar: hasta el ' || fecha_hora_texto(pago_limite(v.pago_pendiente_en, v.fecha_carga_desde));
    if position(esperado in r.cuerpo_html) = 0 then raise exception 'FALLO 283 · el email no dice el plazo para pagar (%): %', esperado, r.cuerpo_html; end if;
    if position('se anulan solos' in r.cuerpo_html) = 0 or position('crear un envío nuevo' in r.cuerpo_html) = 0 then
      raise exception 'FALLO 283 · el email no dice qué pasa si no se paga a tiempo'; end if;
  end if;
  -- (b) Un envío que no espera ningún pago: ni «Pendiente de pago» ni plazo.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1, adm) returning id into s;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (s, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (s, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = s;
  if (select estado_pago_previo from envios where id = s) <> 'pendiente' then
    select * into r from emails_enviados where clave = 'envio_creado:' || s;
    if position('Plazo para pagar' in r.cuerpo_html) > 0 then raise exception 'FALLO 283 · un envío sin pago pendiente recibe un plazo para pagar'; end if;
  end if;
  raise notice 'OK 283 · el email «Envío creado» de un envío pendiente de pago dice la hora límite y que, pasada, se anula';
end $$;

-- ---- 284. El buscador de envíos encuentra por fecha, escrita como se lee en pantalla ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; cli uuid := current_setting('prueba.cliente')::uuid; adm uuid := current_setting('prueba.u_admin')::uuid;
begin
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por, descripcion_mercancia)
    values (cli, 5, 3, 500, 400, date '2031-01-23', date '2031-01-24', adm, 'zzfechas284') returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('prueba.e284', e::text, false);
  if position('23/01/31' in (select texto_busqueda from envios where id = e)) = 0 or position('24/01/2031' in (select texto_busqueda from envios where id = e)) = 0 then
    raise exception 'FALLO 284 · el texto de búsqueda no lleva las fechas: %', (select texto_busqueda from envios where id = e);
  end if;
end $$;
-- Dynamo: por día y mes, por la fecha corta, con el año entero y junto a otra palabra.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e284')::uuid; q text; begin
  foreach q in array array['zzfechas284 23/01', '23/01/31 zzfechas284', '24/01/2031 zzfechas284', 'zzfechas284 01/2031'] loop
    if not exists (select 1 from buscar_envios_pagina(q) b where b.id = e) then raise exception 'FALLO 284 · Dynamo no encuentra el envío buscando «%»', q; end if;
  end loop;
  if exists (select 1 from buscar_envios_pagina('zzfechas284 25/01') b where b.id = e) then raise exception 'FALLO 284 · sale con una fecha que no es suya'; end if;
end $$;
-- El cliente, en lo suyo: igual.
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e284')::uuid; begin
  if not exists (select 1 from buscar_envios_pagina('zzfechas284 23/01') b where b.id = e) then raise exception 'FALLO 284 · el cliente no encuentra su envío por fecha'; end if;
end $$;
-- Al cambiar la fecha, la búsqueda va con la nueva (y deja de salir con la vieja).
reset role;
select set_config('request.jwt.claim.sub', '', false);
update envios set fecha_carga_desde = date '2031-02-10', fecha_carga_hasta = date '2031-02-11' where id = current_setting('prueba.e284')::uuid;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e284')::uuid; begin
  if not exists (select 1 from buscar_envios_pagina('zzfechas284 10/02') b where b.id = e) then raise exception 'FALLO 284 · tras cambiar la fecha no se encuentra por la nueva'; end if;
  if exists (select 1 from buscar_envios_pagina('zzfechas284 23/01') b where b.id = e) then raise exception 'FALLO 284 · tras cambiar la fecha sigue saliendo por la vieja'; end if;
  raise notice 'OK 284 · el buscador de envíos encuentra por fecha (día/mes, corta y con año), Dynamo y cliente, y sigue los cambios de fecha';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 285. «Firmó en papel»: varias casillas de una vez (también el transportista) y sin teclear quién firmó ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; pc uuid; pd uuid; doc uuid; otro uuid; begin
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, matricula_camion, matricula_remolque)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 1, '2850ABC', 'R2850AB') returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, nombre_empresa, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', 'Cargas 285 SL', '19001', 'Guadalajara', 'ES') returning id into pc;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '16001', 'Cuenca', 'ES') returning id into pd;
  update envios set estado = 'programado' where id = e;
  insert into documentos (tipo, envio_id, storage_ruta, nombre_archivo) values ('cmr_firmado', e, 'envios/' || e || '/x/cmr-papel.jpg', 'cmr-papel.jpg') returning id into doc;
  insert into documentos (tipo, envio_id, storage_ruta, nombre_archivo) values ('adjunto', e, 'envios/' || e || '/y/otra.jpg', 'otra.jpg') returning id into otro;
  perform set_config('prueba.e285', e::text, false); perform set_config('prueba.pc285', pc::text, false); perform set_config('prueba.pd285', pd::text, false);
  perform set_config('prueba.doc285', doc::text, false); perform set_config('prueba.otro285', otro::text, false);
end $$;
-- Un cliente no registra firmas en papel.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform registrar_firmas_papel(current_setting('prueba.e285')::uuid, array[current_setting('prueba.pd285')::uuid], true, current_setting('prueba.doc285')::uuid);
  exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 285 · un cliente registra firmas en papel'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e285')::uuid; pc uuid := current_setting('prueba.pc285')::uuid; pd uuid := current_setting('prueba.pd285')::uuid;
        doc uuid := current_setting('prueba.doc285')::uuid; r jsonb; f record; n int; begin
  r := registrar_firmas_papel(e, '{}', false, doc);
  if r ->> 'resultado' <> 'nada_elegido' then raise exception 'FALLO 285 · se registra sin marcar ninguna casilla: %', r; end if;
  r := registrar_firmas_papel(e, array[gen_random_uuid()], false, doc);
  if r ->> 'resultado' <> 'parada_no_valida' then raise exception 'FALLO 285 · vale una parada que no es del envío: %', r; end if;
  r := registrar_firmas_papel(e, array[pc, pd], true, current_setting('prueba.otro285')::uuid);
  if r ->> 'resultado' <> 'falta_documento' then raise exception 'FALLO 285 · vale cualquier adjunto como CMR en papel: %', r; end if;
  if exists (select 1 from firmas_cmr where envio_id = e) then raise exception 'FALLO 285 · un intento rechazado deja firmas'; end if;
  -- Solo una casilla marcada: se apunta esa y nada más.
  r := registrar_firmas_papel(e, array[pc], false, doc);
  if r ->> 'resultado' <> 'ok' or (r ->> 'firmas')::int <> 1 then raise exception 'FALLO 285 · no se apunta la casilla marcada: %', r; end if;
  select * into f from firmas_cmr where envio_id = e;
  if f.rol <> 'remitente' or f.parada_id <> pc or f.nombre <> 'Cargas 285 SL' or f.documento <> 'EN PAPEL' or f.documento_pais <> 'XX'
     or not f.en_papel or f.documento_papel_id <> doc or f.documento_validado or f.extra then
    raise exception 'FALLO 285 · la firma en papel del remitente no queda como debe: %', row_to_json(f);
  end if;
  -- Después, todas marcadas: se apuntan las que faltan (transportista y destinatario); la ya firmada no se toca.
  r := registrar_firmas_papel(e, array[pc, pd], true, doc);
  if r ->> 'resultado' <> 'ok' or (r ->> 'firmas')::int <> 2 then raise exception 'FALLO 285 · con todas marcadas no se apuntan justo las que faltaban: %', r; end if;
  select count(*) into n from firmas_cmr where envio_id = e and en_papel and not extra;
  if n <> 3 then raise exception 'FALLO 285 · deberían quedar las tres casillas firmadas en papel (%)', n; end if;
  if not exists (select 1 from firmas_cmr where envio_id = e and rol = 'transportista' and parada_id is null and documento = 'EN PAPEL' and documento_papel_id = doc) then
    raise exception 'FALLO 285 · falta la firma en papel del transportista (casilla 23)'; end if;
  if not exists (select 1 from firmas_cmr where envio_id = e and rol = 'destinatario' and parada_id = pd and nombre = 'Cuenca') then
    raise exception 'FALLO 285 · el destinatario sin nombre de empresa no queda con su población'; end if;
  -- Todo firmado ya: no hay nada que apuntar.
  r := registrar_firmas_papel(e, array[pc, pd], true, doc);
  if r ->> 'resultado' <> 'ya_firmada' then raise exception 'FALLO 285 · se vuelven a apuntar casillas ya firmadas: %', r; end if;
  select count(*) into n from firmas_envio(e) x where x.en_papel;
  if n <> 3 then raise exception 'FALLO 285 · las firmas en papel no salen en la lista de firmas del envío (%)', n; end if;
  -- La hoja pública tapa los documentos de identidad, pero no la marca «EN PAPEL».
  if position($q$case when f.documento = 'EN PAPEL'$q$ in pg_get_functiondef('public.cmr_publico(uuid)'::regprocedure)) = 0 then
    raise exception 'FALLO 285 · la hoja pública de firma tapa la marca «EN PAPEL» como si fuera un documento'; end if;
  raise notice 'OK 285 · «Firmó en papel»: las casillas marcadas (transportista incluido) de una vez, con la misma foto y sin teclear quién firmó';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- ---- 286. «He hecho la transferencia»: el aviso del cliente para el plazo; Dynamo valida o rechaza ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; cli uuid := current_setting('prueba.cliente')::uuid; adm uuid := current_setting('prueba.u_admin')::uuid; lun date; begin
  lun := (now() at time zone 'Europe/Madrid')::date + (8 - extract(isodow from (now() at time zone 'Europe/Madrid')::date)::int) + 7;
  for i in 1..2 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por)
      values (cli, 13.30, 20, 900, 700, lun, lun + 1, adm) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
    update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now(), estado_revision_precio = 'no_requiere' where id = e;
    update envios set estado = 'programado' where id = e;
    if (select estado_pago_previo from envios where id = e) <> 'pendiente' then raise exception 'FALLO 286 · la prueba no deja el envío pendiente de pago'; end if;
    perform set_config('prueba.e286_' || i, e::text, false);
  end loop;
  perform set_config('prueba.h286', parametro_num('pago_previo_horas', 24)::text, false);   -- el cliente no lee parámetros
end $$;
-- Quien no es el dueño no avisa de nada.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform avisar_pago_transferencia(current_setting('prueba.e286_1')::uuid); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 286 · alguien que no es el dueño avisa de la transferencia de un envío ajeno'; end if;
end $$;
-- El cliente: ve su hora límite, avisa, y el plazo deja de correr.
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e286_1')::uuid; r jsonb; p record; ok boolean := false; begin
  select * into p from pagos_envio(e);
  if p.pago_limite is null or p.pago_avisado_en is not null then raise exception 'FALLO 286 · antes de avisar no se ve la hora límite: %', row_to_json(p); end if;
  if abs(extract(epoch from (p.pago_limite - now())) - current_setting('prueba.h286')::numeric * 3600) > 120 then
    raise exception 'FALLO 286 · el plazo no son las horas del parámetro: %', p.pago_limite - now(); end if;
  r := avisar_pago_transferencia(e);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 286 · el cliente no puede avisar de su transferencia: %', r; end if;
  if avisar_pago_transferencia(e) ->> 'resultado' <> 'ya_avisado' then raise exception 'FALLO 286 · el aviso se repite'; end if;
  select * into p from pagos_envio(e);
  if p.pago_limite is not null or p.pago_avisado_en is null or p.estado_pago_previo <> 'pendiente' then
    raise exception 'FALLO 286 · tras avisar, el plazo sigue corriendo o no consta el aviso: %', row_to_json(p); end if;
  -- El cliente no rechaza pagos (ni el suyo).
  begin perform rechazar_pago_transferencia(e); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 286 · un cliente rechaza un pago'; end if;
  perform avisar_pago_transferencia(current_setting('prueba.e286_2')::uuid);
end $$;
-- Aunque pasen días, el avisado NO se anula solo; y Dynamo recibe el aviso y el email sale.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e286_1')::uuid; begin
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'pago_avisado' and envio_id = e and nivel = 'urgente') then
    raise exception 'FALLO 286 · Dynamo no recibe el aviso de «transferencia avisada»'; end if;
  if not exists (select 1 from emails_enviados where envio_id = e and tipo = 'pago_avisado' and position('plazo para pagar queda parado' in cuerpo_html) > 0) then
    raise exception 'FALLO 286 · no sale el email de «transferencia avisada»'; end if;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  update envios set pago_pendiente_en = now() - interval '6 days' where id in (e, current_setting('prueba.e286_2')::uuid);
  perform caducar_pagos_pendientes();
  perform set_config('request.jwt.claim.role', '', true);
  if (select estado from envios where id = e) <> 'programado' then raise exception 'FALLO 286 · un envío con la transferencia avisada se anula solo'; end if;
end $$;
-- Dynamo: rechaza uno (no consta el cobro) y da por recibida la del otro.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e1 uuid := current_setting('prueba.e286_1')::uuid; e2 uuid := current_setting('prueba.e286_2')::uuid; r jsonb; begin
  r := rechazar_pago_transferencia(e1, 'no aparece en el banco');
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 286 · Dynamo no puede rechazar el pago: %', r; end if;
  if rechazar_pago_transferencia(e1) ->> 'resultado' <> 'no_pendiente' then raise exception 'FALLO 286 · se rechaza dos veces'; end if;
  r := registrar_transferencia_envio(e2, 'CaixaBank', 'PRO-286', (now() at time zone 'Europe/Madrid')::date);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 286 · Dynamo no puede dar por recibida una transferencia avisada: %', r; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e1 uuid := current_setting('prueba.e286_1')::uuid; e2 uuid := current_setting('prueba.e286_2')::uuid; begin
  if (select estado from envios where id = e1) <> 'cancelado' then raise exception 'FALLO 286 · el envío con el pago rechazado no queda anulado'; end if;
  if not exists (select 1 from avisos where para = 'cliente' and tipo = 'pago_caducado' and envio_id = e1 and texto like 'No nos consta tu transferencia%') then
    raise exception 'FALLO 286 · el cliente no recibe el aviso de pago rechazado'; end if;
  if not exists (select 1 from envio_hitos where envio_id = e1 and datos ->> 'motivo_cancelacion' like 'Anulado sin pago: no nos consta la transferencia (no aparece en el banco)') then
    raise exception 'FALLO 286 · el rechazo no queda en el historial con su motivo'; end if;
  if (select estado_pago_previo from envios where id = e2) <> 'pagado' then raise exception 'FALLO 286 · la transferencia validada no deja el envío pagado'; end if;
  -- Si vuelve a quedar pendiente de pago, el aviso viejo ya no vale: el plazo corre otra vez.
  update envios set estado_pago_previo = 'pendiente' where id = e2;
  if (select pago_avisado_en from envios where id = e2) is not null then raise exception 'FALLO 286 · al volver a pendiente de pago se conserva el aviso de transferencia anterior'; end if;
  raise notice 'OK 286 · transferencia avisada: para el plazo y la anulación automática, avisa a Dynamo, y Dynamo la valida (pagado) o la rechaza (anulado sin pago)';
end $$;

-- ---- 287. Las paradas traen el tipo de sitio (pastilla «1 · Recogida» con su icono) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; s uuid; cli uuid := current_setting('prueba.cliente')::uuid; adm uuid := current_setting('prueba.u_admin')::uuid; j jsonb; begin
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, pais_codigo_iso, tipo)
    values (cli, 'Obra 287', 'Calle Prueba 1', '28821', 'Coslada', 'ES', 'obra_zona_urbana') returning id into s;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta, creado_por)
    values (cli, 13.30, 20, 900, current_date + 10, current_date + 11, adm) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, sitio_id, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', s, '28821', 'Coslada', 'ES');
  j := paradas_json(e);
  if j -> 1 ->> 'tipo_sitio' is distinct from 'obra_zona_urbana' then raise exception 'FALLO 287 · paradas_json() no trae el tipo de sitio: %', j -> 1; end if;
  if (j -> 0) ? 'tipo_sitio' is not true or j -> 0 ->> 'tipo_sitio' is not null then raise exception 'FALLO 287 · una parada sin sitio debe traer tipo_sitio vacío: %', j -> 0; end if;
  j := paradas_viaje_json(e);
  if j -> 1 ->> 'tipo_sitio' is distinct from 'obra_zona_urbana' then raise exception 'FALLO 287 · paradas_viaje_json() no trae el tipo de sitio: %', j -> 1; end if;
  raise notice 'OK 287 · las paradas del cliente y del transportista traen el tipo de sitio';
end $$;

-- ---- 288. Tarifador de la web pública: límite de cálculos por IP (sin cuenta) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false' where clave = 'tarifador_web_con_precio';
set role anon;
do $$ declare h text := repeat('a', 64); r jsonb; begin
  -- Apagado: no se apunta nada y la web sigue sin precio.
  r := tarifa_web_apuntar(h);
  if r ->> 'resultado' <> 'apagado' then raise exception 'FALLO 288 · con el tarifador web apagado no responde «apagado»: %', r; end if;
  begin perform tarifa_web_apuntar('no-es-una-huella'); raise exception 'FALLO 288 · acepta una huella que no es SHA-256';
  exception when invalid_parameter_value then null; end;
  begin perform count(*) from consultas_precio_web; raise exception 'FALLO 288 · alguien sin sesión puede leer los cálculos de la web';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
update parametros set valor = 'true' where clave = 'tarifador_web_con_precio';
update parametros set valor = '3' where clave = 'tarifador_web_max_ip_dia';
set role anon;
do $$ declare h text := repeat('b', 64); otra text := repeat('c', 64); r jsonb; begin
  for i in 1..3 loop
    r := tarifa_web_apuntar(h);
    if r ->> 'resultado' <> 'ok' or (r ->> 'quedan')::int <> 3 - i then raise exception 'FALLO 288 · cálculo % de 3: %', i, r; end if;
  end loop;
  if jsonb_typeof(r -> 'festivos') <> 'array' then raise exception 'FALLO 288 · no devuelve los festivos'; end if;
  r := tarifa_web_apuntar(h);
  if r ->> 'resultado' <> 'limite' or (r ->> 'max')::int <> 3 then raise exception 'FALLO 288 · el cuarto cálculo del día no da «limite»: %', r; end if;
  -- Otra IP tiene sus propios 3.
  if tarifa_web_apuntar(otra) ->> 'resultado' <> 'ok' then raise exception 'FALLO 288 · el límite de una IP afecta a otra'; end if;
end $$;
reset role;
do $$ begin
  if (select count(*) from consultas_precio_web where ip_huella = repeat('b', 64)) <> 3 then raise exception 'FALLO 288 · el intento por encima del límite se ha apuntado'; end if;
  -- Al día siguiente vuelve a tener sus 3 (los de ayer no cuentan).
  update consultas_precio_web set cuando = cuando - interval '1 day' where ip_huella = repeat('b', 64);
  if tarifa_web_apuntar(repeat('b', 64)) ->> 'resultado' <> 'ok' then raise exception 'FALLO 288 · los cálculos de ayer siguen contando hoy'; end if;
  update parametros set valor = 'false' where clave = 'tarifador_web_con_precio';
  delete from consultas_precio_web;
  raise notice 'OK 288 · tarifador web: apagado por defecto, 3 cálculos al día por IP (huella), el 4.º da «limite», sin leer la tabla sin sesión';
end $$;

-- ---- 289. Sin matrículas, el transportista no ve las direcciones (ni el CMR) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e73')::uuid; begin
  perform set_config('prueba.m289', coalesce((select matricula_camion from envios where id = e), ''), false);
  perform set_config('prueba.r289', coalesce((select matricula_remolque from envios where id = e), ''), false);
  alter table envios disable trigger user;
  update envios set matricula_camion = null, matricula_remolque = null, estado = 'programado' where id = e;
  alter table envios enable trigger user;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e73')::uuid; j jsonb; p jsonb; begin
  j := datos_orden_transportista(e);
  -- Desde el 2026-11-20 las direcciones van SIEMPRE: sin matrículas solo se marca (aviso del DeCA).
  if not coalesce((j ->> 'faltan_matriculas')::boolean, false) then raise exception 'FALLO 289 · sin matrículas la orden no lo marca'; end if;
  p := j -> 'paradas' -> 0;
  if coalesce(p ->> 'direccion', '') = '********' or coalesce(p ->> 'nombre_empresa', '') = '********' or p ->> 'codigo_postal' is null then
    raise exception 'FALLO 289 · sin matrículas la orden sigue recortando la parada: %', p; end if;
  p := (select r.paradas -> 0 from mis_viajes_por_ids(array[e]) r);
  if coalesce(p ->> 'direccion', '') = '********' or not coalesce((p ->> 'sin_matriculas')::boolean, false) then
    raise exception 'FALLO 289 · el panel de viajes recorta la dirección o no marca que faltan las matrículas: %', p; end if;
  begin perform mi_enlace_cmr(e); raise exception 'FALLO 289 · da el enlace del CMR sin matrículas';
  exception when raise_exception then if sqlerrm not like 'Faltan las matrículas%' then raise; end if; end;
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e73')::uuid; begin
  alter table envios disable trigger user;
  update envios set matricula_camion = '1234BCD', matricula_remolque = 'R1234BCD' where id = e;
  alter table envios enable trigger user;
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
set role authenticated;
do $$ declare e uuid := current_setting('prueba.e73')::uuid; j jsonb; begin
  j := datos_orden_transportista(e);
  if j ? 'faltan_matriculas' or j -> 'paradas' -> 0 ->> 'direccion' = '********' then raise exception 'FALLO 289 · con matrículas la orden sigue marcada'; end if;
  if mi_enlace_cmr(e) is null then raise exception 'FALLO 289 · con matrículas no da el enlace del CMR'; end if;
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e73')::uuid; begin
  -- Dynamo y el cliente siempre lo ven todo: orden_carga_json no cambia.
  alter table envios disable trigger user;
  update envios set matricula_camion = nullif(current_setting('prueba.m289'), ''), matricula_remolque = nullif(current_setting('prueba.r289'), '') where id = e;
  alter table envios enable trigger user;
  if orden_carga_json(e) -> 'paradas' -> 0 ->> 'direccion' = '********' then raise exception 'FALLO 289 · Dynamo también ve la orden recortada'; end if;
  raise notice 'OK 289 · sin matrículas el transportista ve las direcciones con el aviso del DeCA y no tiene CMR; con ellas, el CMR; Dynamo siempre todo';
end $$;

-- ---- 290. Página «Proporcionar matrículas» (enlace del email) --------------------------
-- Un envío nuevo, asignado sin matrículas.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare e uuid; begin
  select (crear_envio(
    jsonb_build_object('cliente_id', current_setting('prueba.cliente'), 'metros_lineales', 13.3, 'fecha_carga_desde', (now() at time zone 'Europe/Madrid')::date + 3, 'importe_cliente', 900, 'importe_transportista', 750),
    jsonb_build_array(
      jsonb_build_object('tipo', 'carga',    'nombre_empresa', 'Muelle 290', 'direccion', 'Calle Secreta 1', 'codigo_postal', '41001', 'poblacion', 'Sevilla'),
      jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Destino 290', 'direccion', 'Calle Secreta 2', 'codigo_postal', '28001', 'poblacion', 'Madrid'))
  )).id into e;
  update envios set transportista_id = current_setting('prueba.transp')::uuid, estado_asignacion = 'confirmada' where id = e;
  perform set_config('prueba.e290', e::text, false);
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid := current_setting('prueba.e290')::uuid; t uuid; begin
  alter table envios disable trigger user;
  update envios set estado = 'programado' where id = e;
  alter table envios enable trigger user;
  select token into t from cmr_enlaces where envio_id = e and not revocado and caduca_en > now() limit 1;
  if t is null then insert into cmr_enlaces (envio_id) values (e) returning token into t; end if;
  perform set_config('prueba.tok290', t::text, false);
  perform set_config('prueba.f290', (select fecha_carga_desde from envios where id = e)::text, false);
end $$;
set role anon;
do $$ declare t uuid := current_setting('prueba.tok290')::uuid; tr uuid := current_setting('prueba.transp')::uuid;
  f date := current_setting('prueba.f290')::date; j jsonb; begin
  -- Sin la clave buena (o con un token inventado) no se ve nada ni se guarda nada.
  if matriculas_enlace_datos(t, gen_random_uuid()) ->> 'resultado' <> 'no_valido' then raise exception 'FALLO 290 · se ve el envío con una clave ajena'; end if;
  if matriculas_enlace_datos(gen_random_uuid(), tr) ->> 'resultado' <> 'no_valido' then raise exception 'FALLO 290 · se ve el envío con un token inventado'; end if;
  if guardar_matriculas_enlace(t, gen_random_uuid(), '1111BBB', 'R1111BBB', 'Pepe', '600111222', f) ->> 'resultado' <> 'no_valido' then
    raise exception 'FALLO 290 · se guardan matrículas con una clave ajena'; end if;
  j := matriculas_enlace_datos(t, tr);
  if j ->> 'resultado' <> 'ok' or (j ->> 'completas')::boolean or not (j ->> 'editable')::boolean then raise exception 'FALLO 290 · datos de la página: %', j; end if;
  if j::text like '%Secreta%' or j::text like '%Muelle 290%' or j -> 'paradas' -> 0 ->> 'codigo_postal' <> '41001' then
    raise exception 'FALLO 290 · la página enseña más que el código postal: %', j -> 'paradas'; end if;
  if guardar_matriculas_enlace(t, tr, '', '', '', '', f) ->> 'resultado' <> 'falta_camion' then raise exception 'FALLO 290 · deja guardar sin matrícula del camión'; end if;
  j := guardar_matriculas_enlace(t, tr, '2902 BCD', 'r-2902bcd', 'Conductor Prueba', '+34 600 290 290', f);
  if j ->> 'resultado' <> 'guardado' or not (j ->> 'completas')::boolean then raise exception 'FALLO 290 · no guarda las matrículas: %', j; end if;
  if not (matriculas_enlace_datos(t, tr) ->> 'completas')::boolean then raise exception 'FALLO 290 · tras guardar sigue sin matrículas'; end if;
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e290')::uuid; r record; begin
  select matricula_camion, matricula_remolque, conductor_nombre, conductor_telefono into r from envios where id = e;
  if r.matricula_camion is distinct from '2902BCD' or r.matricula_remolque is distinct from 'R2902BCD'
     or r.conductor_nombre is distinct from 'Conductor Prueba' or r.conductor_telefono is distinct from '+34600290290' then
    raise exception 'FALLO 290 · lo guardado no es lo escrito: %', r; end if;
  -- Al cliente le llega el email de matrículas, con el conductor pero SIN su teléfono (2026-11-20:
  -- el teléfono solo en la plataforma, desde la víspera de la carga).
  if not exists (select 1 from emails_enviados where clave like 'envio_matriculas:' || e || ':2902BCD:%'
                  and cuerpo_html like '%Conductor Prueba%' and cuerpo_html not like '%+34600290290%' and cuerpo_html like '%lo tienes en la ficha del envío%') then
    raise exception 'FALLO 290 · el email de matrículas al cliente no sale, o lleva el teléfono del conductor'; end if;
  raise notice 'OK 290 · página de matrículas: solo con token y clave buenos, solo CP, guarda limpio y el cliente recibe matrículas, conductor y teléfono';
end $$;

-- ---- 291. Primer envío sin pago previo con el crédito CESCE máximo (16.000 €) ----------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare c uuid; e uuid; i int; v_activo jsonb; v_cesce numeric; v_dyn numeric; v_esp text; begin
  select valor into v_activo from parametros where clave = 'pago_previo_activo';
  update parametros set valor = 'true' where clave = 'pago_previo_activo';
  if parametro_num('pago_previo_cesce_sin_primeros_euros', 0) <> 16000 then raise exception 'FALLO 291 · el parámetro no nace en 16.000 €'; end if;
  -- 1: CESCE 16.000 → primer envío a crédito · 2: CESCE 8.000 → pago previo ·
  -- 3: CESCE 20.000 → a crédito · 4: CESCE 16.000 pero Dynamo lo deja a 0 → pago previo.
  for i in 1..4 loop
    v_cesce := case i when 1 then 16000 when 2 then 8000 when 3 then 20000 else 16000 end;
    v_dyn := case when i = 4 then 0 end;
    v_esp := case when i in (1, 3) then 'no_requerido' else 'pendiente' end;
    insert into clientes (razon_social, cif, riesgo_cesce_euros, riesgo_manual_euros)
      values ('Cesce 291 ' || i, 'B2910000' || i, v_cesce, v_dyn) returning id into c;
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista)
      values (c, 13.30, 20, 500, 400) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28001', 'Madrid', 'ES');
    update envios set estado = 'programado' where id = e;
    if (select estado_pago_previo from envios where id = e)::text <> v_esp then
      raise exception 'FALLO 291 · CESCE % € (Dynamo %): el primer envío queda «%» y debía quedar «%»', v_cesce, coalesce(v_dyn::text, '—'),
        (select estado_pago_previo from envios where id = e), v_esp; end if;
  end loop;
  -- Con el parámetro a 0, la regla no se aplica: CESCE 16.000 → primer envío con pago previo.
  update parametros set valor = '0' where clave = 'pago_previo_cesce_sin_primeros_euros';
  insert into clientes (razon_social, cif, riesgo_cesce_euros) values ('Cesce 291 b', 'B29100009', 16000) returning id into c;
  if pago_previo_motivo(c, null) is distinct from 'Primer envío del cliente' then raise exception 'FALLO 291 · con el parámetro a 0 el CESCE máximo sigue librando del pago previo'; end if;
  update parametros set valor = '16000' where clave = 'pago_previo_cesce_sin_primeros_euros';
  update parametros set valor = v_activo where clave = 'pago_previo_activo';
  raise notice 'OK 291 · CESCE ≥ 16.000 € (parámetro): primer envío a crédito; con menos, o con el crédito de Dynamo a 0, pago previo; a 0 no se aplica';
end $$;

-- ---- 292. Si CESCE baja el crédito, se borra solo el crédito a mano de Dynamo ------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare c uuid; begin
  insert into clientes (razon_social, cif, riesgo_cesce_euros, riesgo_manual_euros) values ('Cesce baja 292', 'B29200001', 16000, 20000) returning id into c;
  -- CESCE sube o no cambia: el de Dynamo se queda.
  update clientes set riesgo_cesce_euros = 18000 where id = c;
  update clientes set riesgo_cesce_euros = 18000, razon_social = 'Cesce baja 292 SL' where id = c;
  if (select riesgo_manual_euros from clientes where id = c) is distinct from 20000 then raise exception 'FALLO 292 · se borra el crédito de Dynamo sin que baje CESCE'; end if;
  -- CESCE baja (18.000 → 8.000): el de Dynamo se borra y avisa a Dynamo.
  update clientes set riesgo_cesce_euros = 8000 where id = c;
  if (select riesgo_manual_euros from clientes where id = c) is not null then raise exception 'FALLO 292 · CESCE baja y el crédito de Dynamo sigue puesto'; end if;
  if (select riesgo_efectivo_euros from clientes where id = c) <> 8000 then raise exception 'FALLO 292 · tras bajar CESCE no manda CESCE'; end if;
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'credito_cesce_baja' and enlace = '/panel/clientes?ver=' || c
                  and texto like '%18.000,00 €%' and texto like '%8.000,00 €%' and texto like '%20.000,00 €%') then
    raise exception 'FALLO 292 · no avisa a Dynamo de que se ha quitado su crédito'; end if;
  -- Dynamo vuelve a darle 30.000 € a mano: se queda (CESCE no cambia).
  update clientes set riesgo_manual_euros = 30000 where id = c;
  if (select riesgo_efectivo_euros from clientes where id = c) <> 30000 then raise exception 'FALLO 292 · no se puede volver a poner el crédito a mano'; end if;
  -- CESCE baja y en el MISMO cambio Dynamo pone otro importe: se respeta lo de Dynamo.
  update clientes set riesgo_cesce_euros = 5000, riesgo_manual_euros = 25000 where id = c;
  if (select riesgo_manual_euros from clientes where id = c) is distinct from 25000 then raise exception 'FALLO 292 · se borra el crédito que Dynamo pone en el mismo cambio'; end if;
  -- CESCE deja de clasificar (vacío) o pasa a 0: también cuenta como bajar.
  update clientes set riesgo_cesce_euros = 0 where id = c;
  if (select riesgo_manual_euros from clientes where id = c) is not null then raise exception 'FALLO 292 · CESCE a 0 no borra el crédito de Dynamo'; end if;
  update clientes set riesgo_manual_euros = 10000 where id = c;
  update clientes set riesgo_cesce_euros = null where id = c;
  if (select riesgo_manual_euros from clientes where id = c) is not null then raise exception 'FALLO 292 · CESCE sin clasificar no borra el crédito de Dynamo'; end if;
  raise notice 'OK 292 · CESCE baja (a menos, a 0 o sin clasificar) → se borra el crédito a mano de Dynamo y avisa; sube o igual → se queda; puesto a la vez → se respeta';
end $$;

-- ---- 293. Cargas de vuelta para el email de la orden ------------------------------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare cli uuid := current_setting('prueba.cliente')::uuid; tr uuid := current_setting('prueba.transp')::uuid;
  dia date := (now() at time zone 'Europe/Madrid')::date + 10; a uuid; x uuid; j jsonb; refs text; i int;
  -- [CP origen, CP destino, tipo, días de margen, precio, reservada]
  defs text[][] := array[
    ['28005', '41003', 'grupaje',  '0', '300', 'no'],   -- 2: hacia donde venía (Sevilla), grupaje
    ['28010', '46010', 'grupaje',  '0', '900', 'no'],   -- 1: hacia su base (Valencia), grupaje
    ['28020', '46020', 'completa', '1', '500', 'no'],   -- 1: hacia su base, completo (va antes)
    ['28030', '16001', 'completa', '0', '400', 'no'],   -- 3: limítrofe de su base (Cuenca)
    ['28040', '08001', 'completa', '0', '800', 'no'],   -- fuera: ni a su base, ni a donde venía, ni a limítrofes («el resto» ya no sale)
    ['45001', '46001', 'completa', '0', '999', 'no'],   -- 4: sale de Toledo (limítrofe de Madrid) hacia su base
    ['28050', '46001', 'completa', '5', '999', 'no'],   -- fuera: otro día (la ventana no incluye la descarga)
    ['28060', '46001', 'completa', '0', '999', 'si'],   -- fuera: reservada ahora mismo
    ['45002', '28070', 'completa', '0', '999', 'no'],   -- fuera: vuelve a Madrid, de donde sale el bloque
    ['28080', '28090', 'completa', '0', '999', 'no']];  -- fuera: empieza y acaba en Madrid
begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  update transportistas set codigo_postal = '46001', pais_codigo_iso = 'ES' where id = tr;
  -- El envío de la orden: Sevilla → Madrid, descarga el día «dia».
  insert into envios (cliente_id, estado, transportista_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_entrega_estimada)
    values (cli, 'programado', tr, 13.3, 20, 900, 700, dia - 1, dia) returning id into a;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, pais_codigo_iso) values (a, 1, 'carga', '41001', 'ES'), (a, 2, 'descarga', '28001', 'ES');
  perform set_config('prueba.e293', a::text, false);
  for i in 1..array_length(defs, 1) loop
    insert into envios (cliente_id, estado, metros_lineales, toneladas, importe_cliente, importe_transportista,
                        fecha_carga_desde, fecha_carga_hasta, publicado_en_bolsa_en, referencia_cliente)
      values (cli, 'programado', case when defs[i][3] = 'completa' then 13.3 else 6 end, 10, 1200, defs[i][5]::numeric,
              dia + defs[i][4]::int, dia + defs[i][4]::int + 1, now(), 'V293-' || i) returning id into x;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, pais_codigo_iso) values (x, 1, 'carga', defs[i][1], 'ES'), (x, 2, 'descarga', defs[i][2], 'ES');
    if defs[i][6] = 'si' then
      insert into envio_reservas (envio_id, estado, hasta) values (x, 'viva', now() + interval '3 minutes');
    end if;
  end loop;
  -- El completo «hacia su base» con ventana que empieza el día anterior: también vale.
  update envios set fecha_carga_desde = dia - 1 where referencia_cliente = 'V293-3';
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
end $$;
-- Ni sin sesión ni un cliente la pueden llamar.
set role anon;
do $$ begin
  begin perform envios_de_vuelta(current_setting('prueba.e293')::uuid); raise exception 'FALLO 293 · sin sesión se ven las cargas de vuelta';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  begin perform envios_de_vuelta(current_setting('prueba.e293')::uuid); raise exception 'FALLO 293 · un cliente ve las cargas de vuelta';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare j jsonb; refs text; begin
  j := envios_de_vuelta(current_setting('prueba.e293')::uuid);
  select string_agg((select referencia_cliente from envios where referencia_gx = c ->> 'referencia') || ':' || (c ->> 'criterio'), ',' order by n)
    into refs from jsonb_array_elements(j -> 'cargas') with ordinality as t(c, n);
  -- El envío de la orden es un COMPLETO: primero los completos (grupos 1, 3, 4) y luego los grupajes (1, 2).
  if refs is distinct from 'V293-3:1,V293-4:3,V293-6:4,V293-2:1,V293-1:2' then raise exception 'FALLO 293 · orden o selección de las cargas de vuelta: %', refs; end if;
  if j ->> 'dia' <> ((now() at time zone 'Europe/Madrid')::date + 10)::text or j -> 'desde' ->> 'codigo_postal' <> '28001'
     or j -> 'base' ->> 'cp2' <> '46' or j -> 'previa' ->> 'cp2' <> '41' then raise exception 'FALLO 293 · día, lugar de la descarga, base o procedencia: %', j - 'cargas'; end if;
  if jsonb_array_length(envios_de_vuelta(current_setting('prueba.e293')::uuid, 2) -> 'cargas') <> 2 then raise exception 'FALLO 293 · no respeta el máximo'; end if;
  raise notice 'OK 293 · cargas de vuelta: desde la provincia de descarga el mismo día; mismo tipo primero (base, origen, limítrofes de la base, desde limítrofes); sin «el resto» ni reservadas; solo Dynamo';
end $$;
reset role;
-- Si el envío de la orden es un GRUPAJE, primero los grupajes.
do $$ declare refs text; begin
  alter table envios disable trigger user;
  update envios set metros_lineales = 6 where id = current_setting('prueba.e293')::uuid;
  alter table envios enable trigger user;
  select string_agg((select referencia_cliente from envios where referencia_gx = c ->> 'referencia') || ':' || (c ->> 'criterio'), ',' order by n)
    into refs from jsonb_array_elements(envios_de_vuelta(current_setting('prueba.e293')::uuid) -> 'cargas') with ordinality as t(c, n);
  if refs is distinct from 'V293-2:1,V293-1:2,V293-3:1,V293-4:3,V293-6:4' then raise exception 'FALLO 293 · con un grupaje no van primero los grupajes: %', refs; end if;
end $$;
-- Si viene de la provincia de su base, todo es «hacia tu base» (grupo 1) y no hay grupo 2.
do $$ declare refs text; begin
  update transportistas set codigo_postal = '41001' where id = current_setting('prueba.transp')::uuid;
  select string_agg((select referencia_cliente from envios where referencia_gx = c ->> 'referencia') || ':' || (c ->> 'criterio'), ',' order by n)
    into refs from jsonb_array_elements(envios_de_vuelta(current_setting('prueba.e293')::uuid) -> 'cargas') with ordinality as t(c, n);
  if refs is distinct from 'V293-1:1' then raise exception 'FALLO 293 · con la base en la provincia de donde viene: %', refs; end if;
  -- Con la base en Madrid (de donde sale el bloque): nada desde su base hacia sus limítrofes
  -- (Madrid → Cuenca fuera); solo queda Madrid → Sevilla (de donde viene).
  update transportistas set codigo_postal = '28001' where id = current_setting('prueba.transp')::uuid;
  select string_agg((select referencia_cliente from envios where referencia_gx = c ->> 'referencia') || ':' || (c ->> 'criterio'), ',' order by n)
    into refs from jsonb_array_elements(envios_de_vuelta(current_setting('prueba.e293')::uuid) -> 'cargas') with ordinality as t(c, n);
  if refs is distinct from 'V293-1:2' then raise exception 'FALLO 293 · se ofrece desde su base hacia una limítrofe de su base: %', refs; end if;
  update transportistas set codigo_postal = '46001' where id = current_setting('prueba.transp')::uuid;
end $$;
-- 295. «Ver todas»: la página pública entra con el token del CMR y la clave del transportista.
do $$ declare t uuid; begin
  insert into cmr_enlaces (envio_id) values (current_setting('prueba.e293')::uuid) returning token into t;
  perform set_config('prueba.tok295', t::text, false);
end $$;
