-- ---- 297. Emails con el diseño común: cabecera, botones, firma y pie --------------------
reset role;
do $$ declare h text; d text; begin
  h := email_con_diseno('<p>Hola,</p><p>Texto.</p><p><a href="https://x/y" style="display:inline-block;background:#3300cc">Ver el envío</a></p><p>— Dynamo · a@b · 1</p>');
  if h !~* '^<!doctype html>' or position('images/4.png' in h) = 0 then raise exception 'FALLO 297 · sin documento ni logo'; end if;
  if position('<p>— Dynamo' in h) > 0 then raise exception 'FALLO 297 · la firma antigua sigue en el cuerpo'; end if;
  if position('<a class="btn" href="https://x/y"' in h) = 0 then raise exception 'FALLO 297 · el botón no se marca para el móvil'; end if;
  if position('Equipo de operaciones' in h) = 0 or position('href="tel:' in h) = 0 or position('href="mailto:' in h) = 0 then
    raise exception 'FALLO 297 · falta la firma con botones'; end if;
  if position(coalesce(parametro('dynamo_razon_social') #>> '{}', 'Dynamo') in h) = 0 then raise exception 'FALLO 297 · el pie no lleva la empresa de Parámetros'; end if;
  if position('images/email/alvaro.png' in h) = 0 or position('Gestor de tráfico' in h) = 0 then raise exception 'FALLO 297 · la firma no lleva la foto ni el cargo de quien firma'; end if;
  if email_con_diseno(h) <> h then raise exception 'FALLO 297 · envuelve dos veces'; end if;
  h := email_con_diseno('<p>Orden</p>', 'Textil Prueba, SL');
  if position('Textil Prueba, SL' in h) = 0 or position('Equipo de operaciones' in h) > 0 then raise exception 'FALLO 297 · email de un cliente a su transportista con la firma de Dynamo'; end if;
  d := pg_get_functiondef('public.enviar_emails_pendientes()'::regprocedure);
  if position('email_con_diseno(r.cuerpo_html' in d) = 0 then raise exception 'FALLO 297 · la cola no envuelve los emails'; end if;
  d := pg_get_functiondef('public.fn_email_envio_cliente(uuid,text,text,text,text)'::regprocedure);
  if position('>Ver el envío</a>' in d) = 0 then raise exception 'FALLO 297 · el email al cliente sigue con el enlace de texto'; end if;
  d := pg_get_functiondef('public.fn_avisos_reservas()'::regprocedure);
  if position('<strong>Revisar y aceptar el alta</strong></a>' in d) > 0 then raise exception 'FALLO 297 · el aviso de alta pendiente sigue con el enlace de texto'; end if;
end $$;
set role authenticated;
do $$ begin
  begin perform email_con_diseno('<p>x</p>'); raise exception 'FALLO 297 · cualquiera con sesión puede usar el envoltorio';
  exception when insufficient_privilege then null; end;
  raise notice 'OK 297 · emails con diseño común: logo, botones a todo el ancho en el móvil, firma y pie de Parámetros; la cola los envuelve';
end $$;
reset role;

-- ---- 298. Los emails esperan 30 s y el cambio de un envío se puede anular -----------------
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid := current_setting('prueba.cliente')::uuid; x uuid; begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  insert into envios (cliente_id, estado, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, referencia_cliente)
    values (cli, 'programado', 6, 5, 600, 450, current_date + 20, current_date + 22, 'C298') returning id into x;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, pais_codigo_iso) values (x, 1, 'carga', '41001', 'ES'), (x, 2, 'descarga', '28001', 'ES');
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  perform set_config('prueba.e298', x::text, false);
  -- Sin persona (un proceso automático): el email espera, pero no se abre ningún cambio.
  insert into emails_enviados (clave, tipo, envio_id, destinatario, asunto, cuerpo_html) values ('p298a', 'envio_modificado', x, 'a@b.prueba', 'A', '<p>a</p>');
  if (select enviar_desde from emails_enviados where clave = 'p298a') < now() + interval '25 seconds' then raise exception 'FALLO 298 · el email no espera su plazo'; end if;
  update envios set referencia_cliente = 'C298b' where id = x;
  if exists (select 1 from envio_cambios where envio_id = x) then raise exception 'FALLO 298 · un proceso automático abre un cambio'; end if;
  if position('x.enviar_desde <= now()' in pg_get_functiondef('public.enviar_emails_pendientes()'::regprocedure)) = 0 then
    raise exception 'FALLO 298 · la cola no respeta el plazo de los emails'; end if;
end $$;
-- Dynamo cambia el envío y su ruta: se abre UN cambio con la foto de antes y el email se cuelga de él.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$ declare x uuid := current_setting('prueba.e298')::uuid; c record; begin
  update envios set metros_lineales = 8 where id = x;
  update envio_paradas set codigo_postal = '28002' where envio_id = x and orden = 2;
  insert into emails_enviados (clave, tipo, envio_id, destinatario, asunto, cuerpo_html) values ('p298b', 'envio_modificado', x, 'a@b.prueba', 'B', '<p>b</p>');
  select * into c from envio_cambios where envio_id = x and estado = 'abierto';
  if c.id is null or (select count(*) from envio_cambios where envio_id = x) <> 1 or c.tipo <> 'modificado'
     or (c.antes ->> 'metros_lineales')::numeric <> 6 or c.paradas_antes -> 1 ->> 'codigo_postal' <> '28001' then
    raise exception 'FALLO 298 · el cambio no guarda la foto de antes: %', c;
  end if;
  if (select cambio_id from emails_enviados where clave = 'p298b') is distinct from c.id
     or (select enviar_desde from emails_enviados where clave = 'p298b') < c.vence_en then
    raise exception 'FALLO 298 · el email no espera al final del cambio';
  end if;
  -- La lista lo deja en su pestaña de antes mientras corre (cambios_en_espera).
  if not exists (select 1 from cambios_en_espera() w where w.envio_id = x and w.estado_antes = 'programado' and w.tipo = 'modificado') then
    raise exception 'FALLO 298 · la lista no sabe cómo estaba el envío antes del cambio'; end if;
end $$;
-- Otro usuario (no es quien hizo el cambio ni Dynamo) no lo ve ni lo puede anular.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare x uuid := current_setting('prueba.e298')::uuid; begin
  if exists (select 1 from pendientes_envios(array[x])) then raise exception 'FALLO 298 · otro usuario ve el contador del cambio de Dynamo'; end if;
  if exists (select 1 from cambios_en_espera() w where w.envio_id = x) then raise exception 'FALLO 298 · otro usuario ve el cambio en espera de Dynamo'; end if;
  begin perform anular_cambio_envio(x); raise exception 'FALLO 298 · otro usuario anula el cambio de Dynamo';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare x uuid := current_setting('prueba.e298')::uuid; r record; j jsonb; begin
  select * into r from pendientes_envios(array[x]);
  if r.envio_id is null or r.tipo <> 'modificado' or not r.puede_anular or r.vence_en < now() + interval '20 seconds' then
    raise exception 'FALLO 298 · el contador de Dynamo no sale bien: %', r; end if;
  j := anular_cambio_envio(x);
  if j ->> 'resultado' <> 'anulado' then raise exception 'FALLO 298 · no se anula el cambio: %', j; end if;
end $$;
reset role;
do $$ declare x uuid := current_setting('prueba.e298')::uuid; begin
  if (select metros_lineales from envios where id = x) <> 6
     or (select codigo_postal from envio_paradas where envio_id = x and orden = 2) <> '28001' then
    raise exception 'FALLO 298 · al anular, el envío no vuelve a como estaba'; end if;
  if (select estado from emails_enviados where clave = 'p298b') <> 'omitido' then raise exception 'FALLO 298 · al anular, el email sale igual'; end if;
  if (select estado from envio_cambios where envio_id = x order by creado_en desc limit 1) <> 'anulado' then raise exception 'FALLO 298 · el cambio no queda anulado'; end if;
  -- Pasado el plazo ya no se puede anular.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  update envios set metros_lineales = 9 where id = x;
  update envio_cambios set vence_en = now() - interval '1 minute' where envio_id = x and estado = 'abierto';
  if anular_cambio_envio(x) ->> 'resultado' <> 'ya_salio' or (select metros_lineales from envios where id = x) <> 9 then
    raise exception 'FALLO 298 · se anula un cambio con el plazo vencido'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 298 · los emails esperan su plazo; el cambio guarda la foto de antes y solo lo anulan Dynamo o su autor: el envío vuelve atrás y el email no sale';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  delete from emails_enviados where clave in ('p298a', 'p298b') or envio_id = current_setting('prueba.e298')::uuid;
  delete from envio_ofertas where envio_id = current_setting('prueba.e298')::uuid;
  delete from avisos where envio_id = current_setting('prueba.e298')::uuid;
  delete from envio_paradas where envio_id = current_setting('prueba.e298')::uuid;
  delete from envios where id = current_setting('prueba.e298')::uuid;
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
end $$;

-- ---- 299. Direcciones de prueba: se quitan solo ellas y el resto del email sale -----------
reset role;
do $$ begin
  if emails_sin_prueba('a@prueba.invalid, real@gmail.com') <> 'real@gmail.com'
     or emails_sin_prueba('Ana <ana@x.invalid>;otro@empresa.es') <> 'otro@empresa.es'
     or emails_sin_prueba('a@prueba.invalid,b@prueba.invalid') is not null
     or emails_sin_prueba('invalido@empresa.es') <> 'invalido@empresa.es' then
    raise exception 'FALLO 299 · emails_sin_prueba no quita bien las direcciones de prueba'; end if;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html) values
    ('p299a', 'envio_creado', 'a@prueba.invalid, real299@gmail.com', 'A', '<p>a</p>'),
    ('p299b', 'envio_creado', 'a@prueba.invalid,b@prueba.invalid', 'B', '<p>b</p>');
  perform enviar_emails_pendientes();
  if (select destinatario from emails_enviados where clave = 'p299a') <> 'real299@gmail.com'
     or (select estado from emails_enviados where clave = 'p299a') = 'omitido' then
    raise exception 'FALLO 299 · un email con una dirección de prueba y otra real no sale a la real'; end if;
  if (select estado from emails_enviados where clave = 'p299b') <> 'omitido' then
    raise exception 'FALLO 299 · un email solo con direcciones de prueba se intenta mandar'; end if;
  delete from emails_enviados where clave in ('p299a', 'p299b');
  raise notice 'OK 299 · las direcciones de prueba (.invalid) se quitan y el email sale a las reales; sin ninguna real, no se manda';
end $$;

-- ---- 300. Envío con transportista propio del cliente: Dynamo no avisa a nadie ni lo oferta --
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare x uuid; j jsonb; begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  insert into envios (cliente_id, operador_id, precio_acordado_operador, estado, metros_lineales, toneladas, fecha_carga_desde, fecha_carga_hasta, referencia_cliente)
    values (current_setting('prueba.cliente')::uuid, current_setting('prueba.operador_a')::uuid, 300, 'programado', 6, 5, current_date + 20, current_date + 22, 'C300') returning id into x;
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  insert into emails_enviados (clave, tipo, envio_id, destinatario, asunto, cuerpo_html) values
    ('p300a', 'aviso_parada', x, 'sitio@empresa300.es', 'A', '<p>a</p>'),
    ('orden_manual:' || x || ':t:1', 'orden_carga', x, 'trafico@iberia300.es', 'B', '<p>b</p>');
  if (select estado from emails_enviados where clave = 'p300a') <> 'omitido' then
    raise exception 'FALLO 300 · sale un aviso de un envío con transportista propio del cliente'; end if;
  if (select estado from emails_enviados where clave like 'orden_manual:' || x || ':%') <> 'pendiente' then
    raise exception 'FALLO 300 · la orden que el cliente manda a su transportista no sale'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  j := iniciar_difusion(x, 500::numeric);
  if j ->> 'resultado' <> 'manual' then raise exception 'FALLO 300 · se puede ofertar un envío con transportista propio: %', j; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from emails_enviados where envio_id = x;
  alter table envios disable trigger user;
  delete from envios where id = x;
  alter table envios enable trigger user;
  raise notice 'OK 300 · envío con transportista propio: ningún aviso automático (solo la orden que manda el cliente) y no se oferta';
end $$;

-- ---- 301. Dos cambios seguidos: cada dato una vez (antes del primero → ahora del último) --
reset role;
do $$ declare r text; begin
  r := fundir_cambios_html(
    '<li><strong>Mercancía:</strong> antes 13,30 metros · 20,00 toneladas · ahora <strong>13,30 metros · 21,00 toneladas</strong></li><li><strong>Precio:</strong> antes 913,00 € · ahora <strong>930,00 € + IVA</strong></li>',
    '<li><strong>Mercancía:</strong> antes 13,30 metros · 21,00 toneladas · ahora <strong>13,30 metros · 23,00 toneladas</strong></li><li><strong>Precio:</strong> antes 930,00 € · ahora <strong>913,00 € + IVA</strong></li><li><strong>Fecha de carga:</strong> antes Lun · ahora <strong>Mar</strong></li>');
  if r <> '<li><strong>Mercancía:</strong> antes 13,30 metros · 20,00 toneladas · ahora <strong>13,30 metros · 23,00 toneladas</strong></li><li><strong>Fecha de carga:</strong> antes Lun · ahora <strong>Mar</strong></li>' then
    raise exception 'FALLO 301 · los cambios seguidos no se funden bien: %', r; end if;
  if position('fundir_cambios_html' in pg_get_functiondef('public.fn_encolar_email_envio_modificado(uuid, text)'::regprocedure)) = 0
     or position('fundir_cambios_html' in pg_get_functiondef('public.fn_encolar_email_transportista_modificado(uuid, uuid, text)'::regprocedure)) = 0 then
    raise exception 'FALLO 301 · los emails de envío modificado no funden los cambios'; end if;
  if position('width="96"' in firma_email_persona()) = 0 then raise exception 'FALLO 301 · la foto de la firma no es de 96 px'; end if;
  if position('>Entrar en dynamotrans.com</a>' in email_con_diseno('<p>x</p>', null)) = 0 then raise exception 'FALLO 301 · falta el botón «Entrar en dynamotrans.com» en la firma'; end if;
  if position('contactad con vuestro cliente' in pg_get_functiondef('public.encolar_anulacion_parada'::regproc)) = 0 then raise exception 'FALLO 301 · el aviso de anulación al sitio no dice que lo anula el cliente'; end if;
  if position('escapar_html(x.merc)' in pg_get_functiondef('public.encolar_resumen_sitios'::regproc)) = 0 then raise exception 'FALLO 301 · el resumen mensual no dice qué mercancía se movió'; end if;
  if position('>Abrir el envío</a>' in pg_get_functiondef('public.fn_difusion_paso'::regproc)) = 0 then raise exception 'FALLO 301 · el aviso de oferta sin aceptación no lleva «Abrir el envío»'; end if;
  if position('>Revisar la cuenta</a>' in pg_get_functiondef('public.fn_usuarios_aviso_suspension'::regproc)) = 0 then raise exception 'FALLO 301 · el aviso de cuenta suspendida no lleva «Revisar la cuenta»'; end if;
  if position('aviso_vispera_cliente_hora' in pg_get_functiondef('public.encolar_avisos_operativos'::regproc)) = 0 then raise exception 'FALLO 301 · la hora del aviso de víspera no sale de Parámetros'; end if;
  raise notice 'OK 301 · dos cambios seguidos salen en un email con cada dato una vez (y si vuelve a como estaba, no sale); foto de la firma a 96 px';
end $$;

-- ---- 302. Transportistas que nos dejan tirados: contador y suspensión automática ---------------
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$ declare t uuid; e uuid; i int; r jsonb; ids uuid[] := '{}'; cli uuid := current_setting('prueba.cliente')::uuid;
  dia date := (now() at time zone 'Europe/Madrid')::date + 30;
begin
  insert into transportistas (razon_social, cif) values ('Transportes 302 SL', 'B30200001') returning id into t;
  update transportistas set estado_operativo = 'activo' where id = t;
  for i in 1 .. 6 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
      values (cli, 6, 5, 600, 450, dia, dia + 1) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28821', 'Coslada', 'ES');
    update envios set estado = 'programado' where id = e;
    ids := ids || e;
  end loop;
  perform set_config('prueba.t302', t::text, false);
  perform set_config('prueba.e302', array_to_string(ids, ','), false);
  -- La primera vez que trabaja nos deja tirados (con margen): no es un «100 %», no se suspende.
  update envios set transportista_id = t, asignado_en = now() - interval '5 hours' where id = ids[1];
  r := quitar_transportista(ids[1], 'deja_tirado');
  if (r ->> 'suspendido')::boolean or (select estado_operativo from transportistas where id = t) <> 'activo' then
    raise exception 'FALLO 302 · una sola cancelación con margen suspende al transportista: %', r; end if;
  -- Tres cargas buenas y otra cancelación: 2 de sus últimas 5 → suspendido.
  update envios set transportista_id = t, asignado_en = now() - interval '4 hours' where id = ids[2];
  update envios set transportista_id = t, asignado_en = now() - interval '3 hours' where id = ids[3];
  update envios set transportista_id = t, asignado_en = now() - interval '2 hours' where id = ids[4];
  update envios set transportista_id = t, asignado_en = now() - interval '1 hours' where id = ids[5];
  r := quitar_transportista(ids[5], 'cambio_dynamo');   -- un cambio nuestro no cuenta
  if (select count(*) from transportista_cancelaciones where transportista_id = t) <> 1 then raise exception 'FALLO 302 · un cambio nuestro cuenta como cancelación suya'; end if;
  update envios set transportista_id = t, asignado_en = now() where id = ids[5];
  r := quitar_transportista(ids[5], 'deja_tirado');
  if not (r ->> 'suspendido')::boolean or (select estado_operativo from transportistas where id = t) <> 'suspendido'
     or (select suspension_motivo from transportistas where id = t) not like '%últimas 5%' then
    raise exception 'FALLO 302 · 2 cancelaciones en sus últimas 5 cargas no lo suspenden: % · %', r, (select suspension_motivo from transportistas where id = t); end if;
  if not exists (select 1 from emails_enviados where clave like 'transportista_suspendido:' || t || ':%' and cuerpo_html like '%>Revisar transportista</a>%') then
    raise exception 'FALLO 302 · no se avisa a Dynamo de la suspensión'; end if;
  if not exists (select 1 from pg_proc where proname = 'asignar_transportista' and pg_get_function_identity_arguments(oid) like '%p_forzar boolean%') then
    raise exception 'FALLO 302 · asignar_transportista no admite confirmar un suspendido'; end if;
end $$;
-- Suspendido: Dynamo no puede darle un envío… salvo que lo confirme.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e302'), ',')::uuid[]; t uuid := current_setting('prueba.t302')::uuid; begin
  begin update envios set transportista_id = t where id = ids[6]; raise exception 'FALLO 302 · se asigna un suspendido sin confirmarlo';
  exception when raise_exception then if sqlerrm like 'FALLO%' then raise; end if; end;
  perform set_config('dynamo.asignar_suspendido', 'on', true);
  update envios set transportista_id = t where id = ids[6];
  perform set_config('dynamo.asignar_suspendido', '', true);
  if (select transportista_id from envios where id = ids[6]) is distinct from t then raise exception 'FALLO 302 · confirmándolo, no se asigna el suspendido'; end if;
end $$;
reset role;
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e302'), ',')::uuid[]; t uuid := current_setting('prueba.t302')::uuid; r jsonb; begin
  -- Reactivado a mano: el contador vuelve a empezar.
  update transportistas set estado_operativo = 'activo' where id = t;
  if (select suspension_motivo from transportistas where id = t) is not null
     or (select cancelaciones from cancelaciones_transportistas(array[t])) <> 0 then
    raise exception 'FALLO 302 · al reactivarlo no vuelve a empezar el contador'; end if;
  -- Una sola cancelación a menos de 24 h de cargar: suspendido.
  insert into transportista_cancelaciones (transportista_id, envio_id, horas_antes) values (t, ids[6], 5);
  r := transportista_revisar_cancelaciones(t, 5);
  if not (r ->> 'suspendido')::boolean then raise exception 'FALLO 302 · cancelar a 5 h de la carga no lo suspende: %', r; end if;
  raise notice 'OK 302 · cancelaciones de transportistas: con margen y la primera vez no suspende; 2 de sus últimas 5 o a menos de 24 h, sí (con aviso a Dynamo); asignarlo a mano pide confirmarlo; al reactivarlo el contador vuelve a empezar';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e302'), ',')::uuid[]; t uuid := current_setting('prueba.t302')::uuid; begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  delete from emails_enviados where envio_id = any (ids) or clave like 'transportista_suspendido:' || t || ':%';
  delete from transportista_cancelaciones where transportista_id = t;
  delete from envio_ofertas where envio_id = any (ids);
  delete from avisos where envio_id = any (ids);
  delete from envio_cambios where envio_id = any (ids);
  alter table envio_hitos disable trigger user;
  delete from envio_hitos where envio_id = any (ids);
  alter table envio_hitos enable trigger user;
  delete from envio_reservas where envio_id = any (ids);
  delete from cmr_enlaces where envio_id = any (ids);
  delete from envio_paradas where envio_id = any (ids);
  delete from envios where id = any (ids);
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  delete from transportistas where id = t;
end $$;

-- ---- 303. Control de facturación: ningún envío entregado se queda sin cobrar --------------
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$ declare t uuid; o uuid; e uuid; i int; r jsonb; n int; ids uuid[] := '{}'; cli uuid := current_setting('prueba.cliente')::uuid;
  dia date := (now() at time zone 'Europe/Madrid')::date - 10;
begin
  -- Sin el «desde» de Parámetros (2026-11-23): aquí se prueba con envíos de hace 10 días.
  update parametros set valor = '""' where clave = 'control_facturacion_desde';
  insert into transportistas (razon_social, cif) values ('Transportes 303 SL', 'B30300001') returning id into t;
  insert into operadores (cliente_id, razon_social, cif) values (cli, 'Operador 303', 'B30300002') returning id into o;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  for i in 1 .. 6 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta,
                        transportista_id, estado, entregado_en, fecha_carga_real)
      values (cli, 6, 5, 600, 450, dia, dia, t, 'entregado', now() - interval '10 days', dia) returning id into e;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28821', 'Coslada', 'ES');
    ids := ids || e;
  end loop;
  update envios set importe_cliente = null where id = ids[1];                                  -- 1: sin precio de cliente
  update envios set holded_pedido_compra = referencia_gx, holded_compra_total = 450 where id = ids[2];   -- 2: compra sin venta
  update envios set holded_pedido_venta = referencia_gx, holded_venta_total = 600 where id = ids[4];   -- 4: venta pasada, compra no
  update envios set operador_id = o, importe_cliente = null, importe_transportista = null, transportista_id = null where id = ids[5];   -- 5: manual: no cuenta
  update envios set holded_pedido_venta = referencia_gx, holded_venta_total = 600, holded_pedido_compra = referencia_gx, holded_compra_total = 450,
                    facturado_venta = true, facturado_compra = true where id = ids[6];       -- 6: todo bien
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  perform set_config('prueba.e303', array_to_string(ids, ','), false);
  perform set_config('prueba.t303', t::text, false);
  perform set_config('prueba.o303', o::text, false);

  -- 3: se pasa a Holded (se guarda el total) y después cambia el precio.
  n := marcar_exportados('venta', array[(select referencia_gx from envios where id = ids[3])], true);
  if n <> 1 or (select holded_venta_total from envios where id = ids[3]) <> 600 then
    raise exception 'FALLO 303 · al pasar a Holded no se guarda el total de la venta'; end if;
  n := marcar_exportados('compra', array[(select referencia_gx from envios where id = ids[3])], true);
  alter table envios disable trigger user; update envios set importe_cliente = 650 where id = ids[3]; alter table envios enable trigger user;

  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[1] and c.tipo = 'venta_sin_precio' and c.gravedad = 'grave') then
    raise exception 'FALLO 303 · un entregado sin precio de cliente no sale en el control'; end if;
  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[2] and c.tipo = 'compra_sin_venta')
     or not exists (select 1 from control_facturacion() c where c.envio_id = ids[2] and c.tipo = 'venta_sin_holded') then
    raise exception 'FALLO 303 · una compra pasada a Holded sin su venta no sale en el control'; end if;
  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[3] and c.tipo = 'cambio_tras_holded' and c.detalle like '%600,00 €%650,00 €%') then
    raise exception 'FALLO 303 · un cambio de precio después de pasarlo a Holded no sale: %', (select array_agg(c.tipo || ': ' || c.detalle) from control_facturacion() c where c.envio_id = ids[3]); end if;
  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[4] and c.tipo = 'venta_sin_compra') then
    raise exception 'FALLO 303 · un pedido de venta pasado sin su compra no sale'; end if;
  if exists (select 1 from control_facturacion() c where c.envio_id in (ids[5], ids[6])) then
    raise exception 'FALLO 303 · sale un envío manual o uno que cuadra: %', (select array_agg(c.tipo) from control_facturacion() c where c.envio_id in (ids[5], ids[6])); end if;

  -- «Ya corregido en Holded»: se guarda lo que vale ahora y deja de salir.
  r := control_facturacion_resuelto(ids[3]);
  if not (r ->> 'ok')::boolean or exists (select 1 from control_facturacion() c where c.envio_id = ids[3] and c.tipo = 'cambio_tras_holded') then
    raise exception 'FALLO 303 · «ya corregido en Holded» no lo quita del control: %', r; end if;

  -- El cuadre del mes: los entregados de Dynamo (el manual no) frente a lo pasado y facturado.
  select q.envios - (select count(*) from envios x where x.operador_id is null and x.estado = 'entregado'
                          and date_trunc('month', coalesce(x.fecha_carga_real, x.fecha_carga_desde)) = date_trunc('month', dia) and not (x.id = any (ids)))
    into n from cuadre_facturacion(2) q where q.mes = date_trunc('month', dia)::date;
  if n is distinct from 5 then raise exception 'FALLO 303 · el cuadre no cuenta los 5 entregados de Dynamo (cuenta %)', n; end if;

  -- El email del lunes: uno por semana, con el botón al control.
  delete from emails_enviados where clave = 'control_facturacion:' || to_char((now() at time zone 'Europe/Madrid')::date, 'IYYY-IW');
  if avisar_control_facturacion(true) <> 1 or avisar_control_facturacion(true) <> 0 then
    raise exception 'FALLO 303 · el email del control no sale una sola vez por semana'; end if;
  if not exists (select 1 from emails_enviados where clave = 'control_facturacion:' || to_char((now() at time zone 'Europe/Madrid')::date, 'IYYY-IW')
                 and tipo = 'control_facturacion' and cuerpo_html like '%>Abrir el control de facturación</a>%' and cuerpo_html like '%Pedido de compra pasado y el de venta no%') then
    raise exception 'FALLO 303 · el email del control no lleva el resumen ni el botón'; end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if not exists (select 1 from cron.job where jobname = 'dynamo-control-facturacion') then raise exception 'FALLO 303 · falta la tarea del lunes'; end if;
  end if;
end $$;
-- El equipo de Dynamo lo lee con sus permisos de verdad (desde la plataforma).
set role authenticated;
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e303'), ',')::uuid[]; begin
  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[2] and c.tipo = 'compra_sin_venta') then
    raise exception 'FALLO 303 · desde la plataforma, Dynamo no ve el control'; end if;
  perform * from cuadre_facturacion(6);
end $$;
reset role;
-- Un cliente no ve el control.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ begin
  begin perform * from control_facturacion(); raise exception 'FALLO 303 · un cliente ve el control de facturación';
  exception when insufficient_privilege then null; end;
  begin perform * from cuadre_facturacion(); raise exception 'FALLO 303 · un cliente ve el cuadre de facturación';
  exception when insufficient_privilege then null; end;
  raise notice 'OK 303 · control de facturación: entregado sin precio, compra sin venta, venta sin compra y cambio después de Holded salen (los manuales y lo que cuadra, no); «ya corregido» lo quita; cuadre por meses; email del lunes una vez por semana; el cliente no lo ve';
end $$;
reset role;
-- «Revisar desde» de Parámetros (2026-11-23): con hoy, los entregados hace 10 días ya no salen
-- (datos viejos o de prueba); mal escrito, cuenta como vacío.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e303'), ',')::uuid[]; begin
  update parametros set valor = to_jsonb(((now() at time zone 'Europe/Madrid')::date)::text) where clave = 'control_facturacion_desde';
  if exists (select 1 from control_facturacion() c where c.envio_id = any(ids)) then
    raise exception 'FALLO 303 · con «desde» hoy siguen saliendo envíos entregados hace 10 días'; end if;
  update parametros set valor = '"mal-escrito"' where clave = 'control_facturacion_desde';
  if not exists (select 1 from control_facturacion() c where c.envio_id = ids[1]) then
    raise exception 'FALLO 303 · con el «desde» mal escrito el control no cuenta como vacío'; end if;
  -- El resto de las pruebas, sin «desde» (usan envíos de hace días).
  update parametros set valor = '""' where clave = 'control_facturacion_desde';
  raise notice 'OK 303b · control de facturación «desde»: con hoy no salen los envíos de hace 10 días; mal escrito, cuenta como vacío';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e303'), ',')::uuid[]; begin
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  delete from emails_enviados where envio_id = any (ids) or clave like 'control_facturacion:%';
  delete from envio_ofertas where envio_id = any (ids);
  delete from avisos where envio_id = any (ids);
  delete from envio_cambios where envio_id = any (ids);
  alter table envio_hitos disable trigger user;
  delete from envio_hitos where envio_id = any (ids);
  alter table envio_hitos enable trigger user;
  delete from envio_reservas where envio_id = any (ids);
  delete from cmr_enlaces where envio_id = any (ids);
  delete from envio_paradas where envio_id = any (ids);
  delete from envios where id = any (ids);
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  delete from operadores where id = current_setting('prueba.o303')::uuid;
  delete from transportistas where id = current_setting('prueba.t303')::uuid;
end $$;

-- ---- 304. Pedidos de venta y de compra a la par, también las líneas a 0 € ----------------
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$ declare t uuid; e uuid; s uuid; p uuid; n int; ref text; cli uuid := current_setting('prueba.cliente')::uuid;
  dia date := (now() at time zone 'Europe/Madrid')::date - 10;
begin
  insert into transportistas (razon_social, cif) values ('Transportes 304 SL', 'B30400001') returning id into t;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta,
                      transportista_id, estado, entregado_en, fecha_carga_real)
    values (cli, 6, 5, 600, 450, dia, dia, t, 'entregado', now() - interval '10 days', dia) returning id, referencia_gx into e, ref;
  -- Otro aún sin transportista: no saca ningún pedido (ni de venta ni de compra).
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta, estado)
    values (cli, 6, 5, 600, dia + 40, dia + 41, 'programado') returning id into s;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28821', 'Coslada', 'ES'),
                                                                                                       (s, 1, 'carga', '41001', 'Sevilla', 'ES'), (s, 2, 'descarga', '28821', 'Coslada', 'ES');
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  perform set_config('prueba.e304', e || ',' || s, false);
  perform set_config('prueba.t304', t::text, false);

  -- Paralización: 40 € al transportista, nada al cliente → la del cliente queda a 0 €.
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_transportista)
    values (e, (select id from tipos_penalizacion where clave = 'paralizacion'), 'Espera 3 h en carga', 40) returning id into p;
  update penalizaciones set estado = 'confirmada' where id = p;
  if (select importe_cliente from penalizaciones where id = p) is distinct from 0 then
    raise exception 'FALLO 304 · el importe vacío al cliente no se guarda como 0'; end if;
  if (select count(*) from v_holded_pedido_venta where "Num Pedido (referencia_gx_carga)" = ref) <> 2
     or (select count(*) from v_holded_pedido_compra where "Num Pedido (referencia_gx_carga)" = ref) <> 2
     or not exists (select 1 from v_holded_pedido_venta where "Num Pedido (referencia_gx_carga)" = ref and "Concepto" = 'paralizacion' and "Precio unidad" = 0)
     or not exists (select 1 from v_holded_pedido_compra where "Num Pedido (referencia_gx_carga)" = ref and "Concepto" = 'paralizacion' and "Precio unidad" = 40) then
    raise exception 'FALLO 304 · el porte y la paralización no salen en los dos pedidos (con su 0 €)'; end if;
  if exists (select 1 from v_lineas_pedido where envio_id = s) then
    raise exception 'FALLO 304 · un envío sin transportista saca un pedido sin el otro'; end if;

  -- Pasados los dos; luego otra penalización a 0 € en los dos lados: se nota.
  n := marcar_exportados('venta', array[ref], true) + marcar_exportados('compra', array[ref], true);
  if n <> 2 or (select holded_venta_lineas from envios where id = e) <> 2 or (select holded_compra_lineas from envios where id = e) <> 2 then
    raise exception 'FALLO 304 · al pasar a Holded no se guardan las líneas'; end if;
  if exists (select 1 from control_facturacion() c where c.envio_id = e) then
    raise exception 'FALLO 304 · con todo pasado sale en el control: %', (select array_agg(c.tipo) from control_facturacion() c where c.envio_id = e); end if;
  -- (Desde el 25-nov una penalización con los DOS importes a 0 no existe: aquí va con 0 € al cliente.)
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente, importe_transportista, estado)
    values (e, (select id from tipos_penalizacion where clave = 'otro'), 'Otra espera, sin repercutir', 0, 25, 'confirmada');
  if not exists (select 1 from control_facturacion() c where c.envio_id = e and c.tipo = 'cambio_tras_holded' and c.detalle like '%tenía 2 líneas y ahora 3%') then
    raise exception 'FALLO 304 · una penalización nueva después de pasarlo no sale en el control'; end if;
end $$;
-- El cliente NO ve la paralización que no se le cobra (usuario, 2026-11-25: a quien le toca 0 no se le genera).
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare e uuid := split_part(current_setting('prueba.e304'), ',', 1)::uuid; begin
  if exists (select 1 from mis_penalizaciones() m where m.envio_id = e) then
    raise exception 'FALLO 304 · el cliente ve una penalización que no se le cobra (0 €)'; end if;
  raise notice 'OK 304 · pedidos de venta y de compra a la par: el envío los saca a la vez al tener transportista; cada penalización sale en los dos aunque un lado sea a 0 € (vacío = 0), y el cliente no ve la que no se le cobra; una línea nueva después de pasarlo a Holded se nota';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare ids uuid[] := string_to_array(current_setting('prueba.e304'), ',')::uuid[]; begin
  alter table penalizaciones disable trigger user;
  delete from penalizaciones where envio_id = any (ids);
  alter table penalizaciones enable trigger user;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  delete from emails_enviados where envio_id = any (ids);
  delete from avisos where envio_id = any (ids);
  delete from envio_cambios where envio_id = any (ids);
  alter table envio_hitos disable trigger user;
  delete from envio_hitos where envio_id = any (ids);
  alter table envio_hitos enable trigger user;
  delete from envio_ofertas where envio_id = any (ids);
  delete from envio_reservas where envio_id = any (ids);
  delete from cmr_enlaces where envio_id = any (ids);
  delete from envio_paradas where envio_id = any (ids);
  delete from envios where id = any (ids);
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  delete from transportistas where id = current_setting('prueba.t304')::uuid;
end $$;

