-- ---- 312. Email de cuenta suspendida: qué envíos contaron, quién los canceló y cuándo --------
-- (usuario, 2026-11-21). La suspensión por la regla 4 de la prueba 217 encoló su email.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$
declare b uuid := current_setting('prueba.u_cli_b')::uuid; v_email text; n int; html text; r record;
begin
  select email into v_email from usuarios where id = b;
  select count(*) into n from autosuspension_cancelaciones(b, false) c where c.quien_email = v_email and not c.por_dynamo;
  if n < 2 then raise exception 'FALLO 312 · autosuspension_cancelaciones no lista las cancelaciones de la regla 4 (%)', n; end if;
  select cuerpo_html into html from emails_enviados where tipo = 'cuenta_suspendida' and clave like 'cuenta_suspendida:' || b || ':%'
   order by creado_en desc limit 1;
  if position('Envíos que han contado' in coalesce(html, '')) = 0 then
    raise exception 'FALLO 312 · el email de suspensión no lista los envíos que contaron'; end if;
  for r in select * from autosuspension_cancelaciones(b, false) loop
    if position('#' || r.referencia_gx in html) = 0 then raise exception 'FALLO 312 · falta el envío #% en el email', r.referencia_gx; end if;
  end loop;
  if position(v_email in html) = 0 or position(to_char(now() at time zone 'Europe/Madrid', 'DD/MM/YY') in html) = 0 then
    raise exception 'FALLO 312 · el email no dice quién canceló ni cuándo'; end if;
  raise notice 'OK 312 · email de cuenta suspendida por cancelaciones: lista cada envío que contó, quién lo canceló y cuándo';
end $$;

-- ---- 313. Límites de consultas de precio subidos (usuario, 2026-11-21) -------------------
-- «Crear varios envíos» enseña hasta 20 precios de golpe y cada uno cuenta: el límite del
-- día ya no puede ser 15.
do $$ begin
  if parametro_num('autosuspension_consultas_dia', 0) < 30 or parametro_num('autosuspension_consultas_semana', 0) < 100
     or parametro_num('autosuspension_consultas_mes', 0) < 300 then
    raise exception 'FALLO 313 · los límites de consultas de precio siguen bajos (% / % / %)', parametro_num('autosuspension_consultas_dia', 0),
      parametro_num('autosuspension_consultas_semana', 0), parametro_num('autosuspension_consultas_mes', 0);
  end if;
  raise notice 'OK 313 · límites de consultas de precio: 30 al día, 100 a la semana y 300 al mes';
end $$;

-- ---- 314. Transportista propio: provincia, país y tipos de camión (usuario, 2026-11-22) ----
-- Nace con el tráiler marcado y España; el país se guarda en ISO y la provincia no puede ir vacía.
do $$ declare c uuid; o uuid; r record; begin
  select id into c from clientes limit 1;
  insert into operadores (cliente_id, razon_social) values (c, 'Prueba 314 camiones') returning id into o;
  select * into r from operadores where id = o;
  if r.tipos_camion <> '{trailer_tauliner}'::tipo_camion[] or r.otros_camiones or r.pais_codigo_iso <> 'ES' then
    raise exception 'FALLO 314 · el transportista propio no nace con el tráiler y España (% / % / %)', r.tipos_camion, r.otros_camiones, r.pais_codigo_iso;
  end if;
  update operadores set tipos_camion = '{trailer_tauliner,rigido_plataforma}', otros_camiones = true, provincia = 'Sevilla', pais_codigo_iso = 'PT' where id = o;
  begin
    update operadores set pais_codigo_iso = 'España' where id = o;
    raise exception 'FALLO 314 · deja guardar un país que no es un código ISO';
  exception when check_violation or string_data_right_truncation then null; end;
  begin
    update operadores set provincia = '  ' where id = o;
    raise exception 'FALLO 314 · deja guardar una provincia en blanco';
  exception when check_violation then null; end;
  delete from operadores where id = o;
  raise notice 'OK 314 · transportista propio con provincia, país (ISO) y tipos de camión (tráiler por defecto)';
end $$;

-- ---- 315. Provincias: CP → provincia, limpieza de España y sugerencias por país (2026-11-22) ----
do $$ declare c uuid; s1 uuid; s2 uuid; n int; begin
  if provincia_de_codigo_postal('41016') <> 'Sevilla' or provincia_de_codigo_postal('11201') <> 'Cádiz'
     or provincia_de_codigo_postal('4101') is not null or provincia_de_codigo_postal('99000') is not null then
    raise exception 'FALLO 315 · provincia_de_codigo_postal no casa el CP con su provincia'; end if;
  if provincia_de_lista('SEVILLA') <> 'Sevilla' or provincia_de_lista('cadiz') <> 'Cádiz' or provincia_de_lista('Lisboa') is not null then
    raise exception 'FALLO 315 · provincia_de_lista no reconoce la provincia escrita de otra forma'; end if;
  select id into c from clientes limit 1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso)
    values (c, 'Prueba 315 ES', 'C/ Uno, 1', '41001', 'Sevilla', 'SEVILLA', 'ES') returning id into s1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso)
    values (c, 'Prueba 315 PT', 'Rua Um, 1', '1000-001', 'Lisboa', 'Prov315 Lisboa', 'PT') returning id into s2;
  perform normalizar_provincias_es();
  if (select provincia from sitios where id = s1) <> 'Sevilla' then raise exception 'FALLO 315 · la limpieza no deja «Sevilla»'; end if;
  if (select provincia from sitios where id = s2) <> 'Prov315 Lisboa' then raise exception 'FALLO 315 · la limpieza tocó una provincia de fuera de España'; end if;
  if not exists (select 1 from provincias_en_uso('PT') where provincia = 'Prov315 Lisboa') then
    raise exception 'FALLO 315 · la provincia que usa una ficha de Portugal no sale en las sugerencias'; end if;
  delete from sitios where id in (s1, s2);
  if exists (select 1 from provincias_en_uso('PT') where provincia = 'Prov315 Lisboa') then
    raise exception 'FALLO 315 · una provincia que ya no usa ninguna ficha sigue en las sugerencias'; end if;
  raise notice 'OK 315 · provincia sacada del CP, limpieza de España y sugerencias por país que salen de las fichas vivas';
end $$;

