-- ---- 318. Emails de incidencias y penalizaciones (usuario, 2026-11-22: «todo eso debería notificarse») ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t uuid; i uuid; i2 uuid; p uuid; p2 uuid; r record; n int; cli uuid := current_setting('prueba.cliente')::uuid;
  ti uuid := (select id from tipos_incidencia order by clave limit 1); tp uuid := (select id from tipos_penalizacion order by nombre limit 1);
  hoy date := (now() at time zone 'Europe/Madrid')::date;
begin
  insert into transportistas (razon_social, cif) values ('Transportes 318 SL', 'B31800001') returning id into t;
  insert into contactos (transportista_id, funcion, email) values (t, 'trafico', 'trafico318@t.prueba');
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 913, 707, hoy + 20, hoy + 21) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado', transportista_id = t where id = e;
  perform set_config('prueba.envio318', e::text, false);

  -- INCIDENCIA que abre Dynamo sobre el cliente: email al cliente y aviso en su campana.
  insert into incidencias (tipo_id, envio_id, titulo, detalle) values (ti, e, 'Retraso 318', 'Llega <tarde>') returning id into i;
  select * into r from emails_enviados where clave = 'incidencia_abierta:' || i;
  if r.id is null or r.envio_id <> e or r.asunto not like 'Incidencia abierta · envío #%' or position('Hemos abierto una incidencia' in r.cuerpo_html) = 0
     or position('Llega &lt;tarde&gt;' in r.cuerpo_html) = 0 or position('/panel/incidencias' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 318 · la incidencia que abre Dynamo no manda bien el email al cliente: %', r;
  end if;
  if not exists (select 1 from avisos where para = 'cliente' and cliente_id = cli and tipo = 'incidencia' and titulo like 'Incidencia abierta%') then
    raise exception 'FALLO 318 · la incidencia que abre Dynamo no sale en la campana del cliente'; end if;
  -- Resuelta: con la resolución. Retirada: su email.
  update incidencias set estado = 'resuelto', resolucion = 'Hablado con el almacén' where id = i;
  if not exists (select 1 from emails_enviados where tipo = 'incidencia_resuelta' and clave like 'incidencia_resuelta:' || i || ':%' and cuerpo_html like '%Hablado con el almacén%') then
    raise exception 'FALLO 318 · al resolver la incidencia no sale el email con la resolución'; end if;
  insert into incidencias (tipo_id, envio_id, titulo) values (ti, e, 'Otra 318') returning id into i2;
  update incidencias set estado = 'cancelado' where id = i2;
  if not exists (select 1 from emails_enviados where tipo = 'incidencia_retirada' and clave like 'incidencia_retirada:' || i2 || ':%') then
    raise exception 'FALLO 318 · al retirar la incidencia no sale su email'; end if;
  -- Incidencia sobre el transportista: el email va a su contacto, no al cliente.
  insert into incidencias (tipo_id, envio_id, transportista_id, titulo) values (ti, e, t, 'Conductor 318') returning id into i;
  select * into r from emails_enviados where clave = 'incidencia_abierta:' || i;
  if r.id is null or r.destinatario <> 'trafico318@t.prueba' then
    raise exception 'FALLO 318 · la incidencia del transportista no le llega a él: %', r.destinatario; end if;

  -- PENALIZACIÓN guardada (pendiente): no se avisa NUNCA, ni email ni campana.
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente, importe_transportista)
    values (e, tp, 'Espera 318', 120, 80) returning id into p;
  if exists (select 1 from emails_enviados where clave like 'penalizacion%:' || p || ':%')
     or exists (select 1 from avisos where envio_id = e and tipo = 'penalizacion') then
    raise exception 'FALLO 318 · al guardar una penalización pendiente se avisa'; end if;
  -- Confirmada: otro aviso a cada uno, una vez.
  update penalizaciones set estado = 'confirmada' where id = p;
  if not exists (select 1 from avisos where para = 'transportista' and transportista_id = t and titulo like 'Importe a tu favor confirmado%' and texto like '%80,00%' and texto not like '%120,00%') then
    raise exception 'FALLO 318 · la campana del transportista no dice su importe a favor'; end if;
  select * into r from emails_enviados where clave = 'penalizacion:' || p || ':cliente';
  if r.id is null or position('120,00' in r.cuerpo_html) = 0 or position('Espera 318' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 318 · el email de la penalización confirmada al cliente no lleva el importe o el motivo: %', r; end if;
  select * into r from emails_enviados where clave = 'penalizacion:' || p || ':transportista';
  if r.id is null or r.destinatario <> 'trafico318@t.prueba' or position('confirmado un importe a tu favor' in r.cuerpo_html) = 0
     or position('80,00' in r.cuerpo_html) = 0 or position('120,00' in r.cuerpo_html) > 0 or r.asunto ilike '%penalizaci%' then
    raise exception 'FALLO 318 · el email de confirmación al transportista no va bien: %', r; end if;
  update penalizaciones set estado = 'pendiente_confirmar' where id = p;
  update penalizaciones set estado = 'confirmada' where id = p;
  select count(*) into n from emails_enviados where clave like 'penalizacion:' || p || ':%';
  if n <> 2 then raise exception 'FALLO 318 · la penalización confirmada se comunica más de una vez (%)', n; end if;
  -- Anulada: a los dos.
  update penalizaciones set estado = 'cancelada' where id = p;
  select count(*) into n from emails_enviados where tipo = 'penalizacion_anulada' and clave like 'penalizacion_anulada:' || p || ':%';
  if n <> 2 then raise exception 'FALLO 318 · al anular la penalización no se avisa a los dos (%)', n; end if;
  -- Nace confirmada y se borra: aviso al crearla (sin «en revisión»), campana, y aviso al borrarla.
  insert into penalizaciones (envio_id, tipo_id, importe_cliente, estado) values (e, tp, 50, 'confirmada') returning id into p2;
  if not exists (select 1 from emails_enviados where clave = 'penalizacion:' || p2 || ':cliente')
     or exists (select 1 from emails_enviados where clave like 'penalizacion_revision:' || p2 || ':%') then
    raise exception 'FALLO 318 · la penalización que nace confirmada no se comunica bien'; end if;
  if not exists (select 1 from avisos where para = 'cliente' and cliente_id = cli and tipo = 'penalizacion' and texto like '%50,00%') then
    raise exception 'FALLO 318 · la penalización que nace confirmada no sale en la campana'; end if;
  delete from penalizaciones where id = p2;
  if not exists (select 1 from emails_enviados where tipo = 'penalizacion_anulada' and clave like 'penalizacion_anulada:' || p2 || ':cliente:%') then
    raise exception 'FALLO 318 · al borrar una penalización confirmada no se avisa'; end if;
end $$;
-- La abre el propio cliente: «la hemos recibido».
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare i uuid; begin
  insert into incidencias (tipo_id, envio_id, titulo) values ((select id from tipos_incidencia order by clave limit 1), current_setting('prueba.envio318')::uuid, 'Mía 318') returning id into i;
  perform set_config('prueba.inc318', i::text, false);
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare i uuid := current_setting('prueba.inc318')::uuid; e uuid := current_setting('prueba.envio318')::uuid; begin
  if not exists (select 1 from emails_enviados where clave = 'incidencia_abierta:' || i and position('Hemos recibido tu incidencia' in cuerpo_html) > 0) then
    raise exception 'FALLO 318 · al cliente que abre una incidencia no le llega «la hemos recibido»'; end if;
  -- Limpieza.
  delete from penalizaciones where envio_id = e;
  delete from emails_enviados where envio_id = e;
  raise notice 'OK 318 · incidencias (abierta, resuelta, retirada) y penalizaciones (al confirmarla, anularla o borrarla; guardarla no avisa) avisan a quien le afectan: el cliente con su importe + IVA; el transportista, importe a su favor con su cifra (nunca la del cliente)';
end $$;

-- ---- 319. Un CIF de transportista nunca puede darse de alta como cliente (usuario, 2026-11-22) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
insert into auth.users (email, raw_user_meta_data) values ('alta319@prueba.es', '{"nombre":"Alta Trescientos Diecinueve"}');
do $$ declare t uuid; c uuid; ok boolean; u uuid; r text; begin
  insert into transportistas (razon_social, cif) values ('Transportes 319 SL', 'B31900001') returning id into t;
  -- Ni Dynamo puede crear un cliente con ese CIF (escrito de otra forma, tampoco).
  ok := false;
  begin insert into clientes (razon_social, cif) values ('Cliente 319 SL', 'b-31900001');
  exception when others then ok := sqlerrm like '%dado de alta como transportista%'; end;
  if not ok then raise exception 'FALLO 319 · se crea un cliente con el CIF de un transportista'; end if;
  -- Ni cambiar el CIF de un cliente al de un transportista.
  insert into clientes (razon_social, cif) values ('Cliente 319 SL', 'B31900002') returning id into c;
  ok := false;
  begin update clientes set cif = 'B31900001' where id = c;
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 319 · se cambia el CIF de un cliente al de un transportista'; end if;
  -- Guardar otros datos de un cliente que ya existía (sin tocar el CIF) sigue funcionando.
  update clientes set razon_social = 'Cliente 319 Bis SL' where id = c;
  -- En el alta de la web: «no_admitido» (sin decir que es un transportista).
  select id into u from usuarios where email = 'alta319@prueba.es';
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  r := buscar_empresa_de_mi_alta('B31900001');
  if r <> 'no_admitido' then raise exception 'FALLO 319 · el alta de la web admite el CIF de un transportista: %', r; end if;
  reset role;
  delete from clientes where id = c;
  delete from transportistas where id = t;
  raise notice 'OK 319 · un CIF / NIF de transportista no se puede dar de alta como cliente (ni por la web ni por Dynamo)';
end $$;
reset role;

-- ---- 320. El email de un transportista tampoco puede darse de alta como cliente (usuario, 2026-11-22) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare t uuid; ok boolean; u uuid; cli uuid := current_setting('prueba.cliente')::uuid; begin
  insert into transportistas (razon_social, cif) values ('Transportes 320 SL', 'B32000001') returning id into t;
  insert into contactos (transportista_id, funcion, email) values (t, 'trafico', 'Trafico320@T.prueba');
  perform set_config('prueba.t320', t::text, false);
  if not email_es_de_transportista(' trafico320@t.prueba ') then raise exception 'FALLO 320 · no reconoce el email de un transportista'; end if;
  -- Darse de alta por su cuenta con ese email: no (aunque se salte la web).
  ok := false;
  begin insert into auth.users (email, raw_user_meta_data) values ('trafico320@t.prueba', '{"nombre":"Intruso"}');
  exception when others then ok := sqlerrm like '%alta_bloqueada%'; end;
  if not ok then raise exception 'FALLO 320 · se crea por su cuenta una cuenta con el email de un transportista'; end if;
  -- Dynamo sí crea la cuenta del transportista (desde «Usuarios»)…
  insert into auth.users (email, raw_user_meta_data) values ('trafico320@t.prueba', jsonb_build_object('nombre', 'Tráfico 320', 'anadido_por', current_setting('prueba.u_admin')))
    returning id into u;
  update usuarios set rol = 'transportista', transportista_id = t, estado = 'activa' where id = u;
  -- …pero nunca como usuario de un cliente.
  ok := false;
  begin update usuarios set rol = 'cliente', transportista_id = null, cliente_id = cli where id = u;
  exception when others then ok := sqlerrm like '%email es de un transportista%'; end;
  if not ok then raise exception 'FALLO 320 · el email de un transportista pasa a ser usuario de un cliente'; end if;
  -- Un usuario de cliente no puede cambiarse al email de un transportista.
  ok := false;
  begin update usuarios set email = 'trafico320@t.prueba ' where id = current_setting('prueba.u_cli')::uuid;
  exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 320 · un usuario de cliente se cambia al email de un transportista'; end if;
  perform set_config('prueba.u320', u::text, false);
end $$;
-- El registro de la web (sin sesión) lo pregunta antes de mandar el código.
set role anon;
do $$ begin
  if email_admitido_para_cliente('trafico320@t.prueba') then raise exception 'FALLO 320 · el registro de la web admite el email de un transportista'; end if;
  if not email_admitido_para_cliente('cualquiera320@cliente.prueba') then raise exception 'FALLO 320 · el registro rechaza un email normal'; end if;
end $$;
reset role;
do $$ begin
  if has_function_privilege('anon', 'public.email_es_de_transportista(text)', 'execute') then
    raise exception 'FALLO 320 · se puede preguntar sin sesión qué emails son de transportistas'; end if;
  delete from usuarios where id = current_setting('prueba.u320')::uuid;
  delete from auth.users where id = current_setting('prueba.u320')::uuid;
  delete from contactos where transportista_id = current_setting('prueba.t320')::uuid;
  delete from transportistas where id = current_setting('prueba.t320')::uuid;
  raise notice 'OK 320 · el email de un transportista no se puede dar de alta como cliente (web, cuenta por su cuenta, Dynamo ni cambio de email); las cuentas de transportista que crea Dynamo siguen funcionando';
end $$;

-- ---- 321. Autorrelleno de datos fiscales (APIEmpresas.es): apagado, tope, saldo y aviso (usuario, 2026-11-22) ----
reset role;
select set_config('request.jwt.claim.sub', '', false);
insert into auth.users (email, raw_user_meta_data) values ('alta321@prueba.es', '{"nombre":"Alta Trescientos Veintiuno"}');
do $$ declare u uuid; ok boolean; r jsonb; n int; begin
  select id into u from usuarios where email = 'alta321@prueba.es';
  perform set_config('prueba.u321', u::text, false);
  -- Nace APAGADO: ni Dynamo lo ve encendido ni se puede apuntar una consulta.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  if (autorrelleno_empresas_estado() ->> 'activo')::boolean then raise exception 'FALLO 321 · el autorrelleno nace encendido'; end if;
  ok := false;
  begin perform empresa_registro_apuntar_consulta('cif', 'B32100001'); exception when others then ok := sqlerrm like '%autorrelleno_apagado%'; end;
  if not ok then raise exception 'FALLO 321 · apagado, se apunta una consulta de pago'; end if;
  reset role;
  update parametros set valor = 'true'::jsonb where clave = 'autorrelleno_empresas_activo';
  update parametros set valor = '2'::jsonb where clave = 'autorrelleno_empresas_max_dia';
  update parametros set valor = '52'::jsonb where clave = 'autorrelleno_empresas_consultas_restantes';
  -- Quien tiene el alta pendiente: 2 al día y la tercera no.
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  r := autorrelleno_empresas_estado();
  if not (r ->> 'activo')::boolean or (r ->> 'quedan_hoy')::int <> 2 then raise exception 'FALLO 321 · el estado para el alta no es el esperado: %', r; end if;
  n := empresa_registro_apuntar_consulta('cif', 'B32100001');
  if n <> 51 then raise exception 'FALLO 321 · no descuenta del saldo (%)', n; end if;
  n := empresa_registro_apuntar_consulta('nombre', 'Marbex');
  ok := false;
  begin perform empresa_registro_apuntar_consulta('cif', 'B32100002'); exception when others then ok := sqlerrm like '%autorrelleno_tope%'; end;
  if not ok then raise exception 'FALLO 321 · deja pasar del tope diario'; end if;
  -- No puede guardar datos del Registro (solo el servidor).
  ok := false;
  begin perform empresa_registro_guardar('B32100001', 'FALSA SL', null, null, null, null, null); exception when others then ok := true; end;
  if not ok then raise exception 'FALLO 321 · un usuario guarda datos del Registro a mano'; end if;
  reset role;
  -- Al llegar al umbral (50): aviso a Dynamo en la campana y por email.
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'autorrelleno_saldo' and texto like '%Quedan 50 consultas%')
     or not exists (select 1 from emails_enviados where tipo = 'autorrelleno_saldo' and clave like 'autorrelleno_saldo:50:%') then
    raise exception 'FALLO 321 · al quedar 50 consultas no se avisa a Dynamo'; end if;
  -- El servidor guarda lo que devolvió la API y se lee sin coste; un cliente ya activo no lo ve.
  perform empresa_registro_guardar('b-321.00001', 'MARBEX INDUSTRIAL SL', 'CALLE EJEMPLO 1', '28001', 'MADRID', 'Madrid', 'activa');
  perform set_config('request.jwt.claim.sub', u::text, false);
  set local role authenticated;
  if (select razon_social from empresa_registro_guardada('B32100001')) is distinct from 'MARBEX INDUSTRIAL SL' then
    raise exception 'FALLO 321 · no se lee lo ya consultado de un CIF'; end if;
  reset role;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  if exists (select 1 from empresa_registro_guardada('B32100001')) or (autorrelleno_empresas_estado() ->> 'activo')::boolean then
    raise exception 'FALLO 321 · un cliente ya activo usa el autorrelleno'; end if;
  reset role;
  -- Sin saldo: Dynamo tampoco consulta.
  update parametros set valor = '0'::jsonb where clave = 'autorrelleno_empresas_consultas_restantes';
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  ok := false;
  begin perform empresa_registro_apuntar_consulta('cif', 'B32100003'); exception when others then ok := sqlerrm like '%autorrelleno_sin_saldo%'; end;
  if not ok then raise exception 'FALLO 321 · sin saldo se sigue consultando la API'; end if;
  reset role;
  if has_function_privilege('anon', 'public.autorrelleno_empresas_estado()', 'execute')
     or has_function_privilege('authenticated', 'public.empresa_registro_guardar(text, text, text, text, text, text, text)', 'execute') then
    raise exception 'FALLO 321 · permisos de las funciones del autorrelleno demasiado abiertos'; end if;
  -- Vuelta a como estaba.
  update parametros set valor = 'false'::jsonb where clave = 'autorrelleno_empresas_activo';
  update parametros set valor = '10'::jsonb where clave = 'autorrelleno_empresas_max_dia';
  update parametros set valor = '100'::jsonb where clave = 'autorrelleno_empresas_consultas_restantes';
  delete from empresas_registro where cif = 'B32100001';
  delete from empresas_registro_consultas where usuario_id = u;
  raise notice 'OK 321 · autorrelleno de datos fiscales: nace apagado; tope diario, saldo que se descuenta, aviso a Dynamo al umbral y sin saldo no consulta; solo el servidor guarda lo de la API';
end $$;
reset role;

-- ---- 322. e-CMR: la firma solo desde el servidor y código de 6 cifras al email ----------
-- Con la clave pública (rol anon o authenticated) no se registra ninguna firma ni reservas:
-- solo el servidor (clave de servicio). El código se apunta por su huella, con topes; si quien
-- firma lo escribe bien, la firma queda «email verificado» (lo decide la base de datos) y el
-- código se gasta; sin código, «sin verificar». Se ve en la hoja pública y en el PDF.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t uuid; tok uuid; begin
  insert into transportistas (razon_social, cif) values ('Transp 322 SL', 'B32200322') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado', transportista_id = t where id = e;
  select token into tok from cmr_enlaces where envio_id = e and not revocado;
  insert into storage.objects (bucket_id, name, metadata)
  values ('documentos', 'cmr/' || tok::text || '/t322-1.png', jsonb_build_object('mimetype', 'image/png', 'size', 2000)),
         ('documentos', 'cmr/' || tok::text || '/t322-2.png', jsonb_build_object('mimetype', 'image/png', 'size', 2000));
  perform set_config('prueba.tok322', tok::text, false);
end $$;
-- (a) Con la clave pública: rechazado, sin escribir nada.
set role anon;
do $$ declare tok uuid := current_setting('prueba.tok322')::uuid; r jsonb; begin
  perform set_config('request.jwt.claim.role', 'anon', true);
  r := firmar_cmr_publico(tok, null, 'transportista', 'Falso', '12345678Z', 'ES', true, 'falso@x.com', 'cmr/' || tok::text || '/t322-1.png',
                          '9.9.9.9', 'inventado', repeat('b', 64), p_matricula_camion => '3220AAA', p_matricula_remolque => 'R3220AAA');
  if r ->> 'resultado' <> 'solo_servidor' then raise exception 'FALLO 322 · con la clave pública se registra una firma: %', r; end if;
  r := anotar_reservas_cmr_publico(tok, null, 'transportista', 'Reservas inventadas');
  if r ->> 'resultado' <> 'solo_servidor' then raise exception 'FALLO 322 · con la clave pública se anotan reservas: %', r; end if;
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  r := firmar_cmr_publico(tok, null, 'transportista', 'Falso', '12345678Z', 'ES', true, null, 'cmr/' || tok::text || '/t322-1.png', null, null, null);
  if r ->> 'resultado' <> 'solo_servidor' then raise exception 'FALLO 322 · con sesión de usuario se registra una firma: %', r; end if;
  perform set_config('request.jwt.claim.role', '', true);
end $$;
reset role;
do $$ declare tok uuid := current_setting('prueba.tok322')::uuid; e uuid; r jsonb; i int;
  h text := encode(sha256(convert_to(current_setting('prueba.tok322') || ':322322', 'UTF8')), 'hex');
  mal text := encode(sha256(convert_to(current_setting('prueba.tok322') || ':000000', 'UTF8')), 'hex');
begin
  select envio_id into e from cmr_enlaces where token = tok;
  if exists (select 1 from firmas_cmr where envio_id = e) or exists (select 1 from incidencias where envio_id = e) then
    raise exception 'FALLO 322 · la llamada rechazada ha dejado algo escrito'; end if;
  if has_function_privilege('anon', 'public.cmr_codigo_firma_crear(uuid, uuid, text, text, text)', 'execute')
     or has_function_privilege('authenticated', 'public.cmr_codigo_firma_comprobar(uuid, uuid, text, text, text)', 'execute')
     or not has_function_privilege('service_role', 'public.cmr_codigo_firma_crear(uuid, uuid, text, text, text)', 'execute') then
    raise exception 'FALLO 322 · permisos de los códigos de firma mal puestos'; end if;
  -- (b) El servidor apunta el código (solo su huella) y lo comprueba.
  perform set_config('request.jwt.claim.role', 'service_role', true);
  r := cmr_codigo_firma_crear(tok, null, 'transportista', 'mal-email', h);
  if r ->> 'resultado' <> 'email_no_valido' then raise exception 'FALLO 322 · acepta un email no válido: %', r; end if;
  r := cmr_codigo_firma_crear(tok, null, 'transportista', ' Chofer@T322.com ', h);
  if r ->> 'resultado' <> 'ok' or r ->> 'email' <> 'chofer@t322.com' then raise exception 'FALLO 322 · no apunta el código: %', r; end if;
  if (select codigo_sha from cmr_codigos_firma where id = (r ->> 'id')::uuid) <> h then raise exception 'FALLO 322 · no guarda la huella'; end if;
  r := cmr_codigo_firma_crear(tok, null, 'transportista', 'chofer@t322.com', h);
  if r ->> 'resultado' <> 'espera' then raise exception 'FALLO 322 · deja pedir dos códigos seguidos: %', r; end if;
  r := cmr_codigo_firma_comprobar(tok, null, 'transportista', 'chofer@t322.com', mal);
  if r ->> 'resultado' <> 'no_coincide' or (r ->> 'quedan')::int <> 4 then raise exception 'FALLO 322 · un código mal no cuenta como fallo: %', r; end if;
  r := cmr_codigo_firma_comprobar(tok, gen_random_uuid(), 'remitente', 'chofer@t322.com', h);
  if r ->> 'resultado' <> 'caducado' then raise exception 'FALLO 322 · el código vale para otra casilla: %', r; end if;
  r := cmr_codigo_firma_comprobar(tok, null, 'transportista', 'CHOFER@t322.com', h);
  if r ->> 'resultado' <> 'ok' then raise exception 'FALLO 322 · el código bueno no verifica: %', r; end if;
  -- 5 fallos: el código ya no vale ni bien escrito.
  r := cmr_codigo_firma_crear(tok, null, 'transportista', 'otro@t322.com', h);
  for i in 1..5 loop r := cmr_codigo_firma_comprobar(tok, null, 'transportista', 'otro@t322.com', mal); end loop;
  if r ->> 'resultado' <> 'bloqueado' then raise exception 'FALLO 322 · el 5.º fallo no bloquea: %', r; end if;
  r := cmr_codigo_firma_comprobar(tok, null, 'transportista', 'otro@t322.com', h);
  if r ->> 'resultado' <> 'bloqueado' then raise exception 'FALLO 322 · tras 5 fallos vale el código: %', r; end if;
  -- (c) Firma con el email verificado (el código se gasta) y firma extra sin código.
  r := firmar_cmr_publico(tok, null, 'transportista', 'Chófer 322', '12345678Z', 'ES', true, 'chofer@t322.com', 'cmr/' || tok::text || '/t322-1.png',
                          '1.2.3.4', 'prueba', repeat('a', 64), p_matricula_camion => '3220AAA', p_matricula_remolque => 'R3220AAA');
  if r ->> 'resultado' <> 'firmada' then raise exception 'FALLO 322 · el servidor no puede firmar: %', r; end if;
  r := firmar_cmr_publico(tok, null, 'transportista', 'Ayudante 322', '12345678Z', 'ES', true, 'otro@t322.com', 'cmr/' || tok::text || '/t322-2.png',
                          null, 'prueba', null, true);
  if r ->> 'resultado' <> 'firmada' then raise exception 'FALLO 322 · no firma la extra: %', r; end if;
  if (select email_verificado from firmas_cmr where envio_id = e and not extra) is not true
     or (select email_verificado from firmas_cmr where envio_id = e and extra) is not false then
    raise exception 'FALLO 322 · la marca «email verificado» no es la esperada'; end if;
  if exists (select 1 from cmr_codigos_firma where envio_id = e and email = 'chofer@t322.com' and usado_en is null) then
    raise exception 'FALLO 322 · el código no se gasta al firmar'; end if;
  if not exists (select 1 from jsonb_array_elements(cmr_publico(tok) -> 'firmas') f where (f ->> 'email_verificado')::boolean)
     or not exists (select 1 from jsonb_array_elements(datos_cmr_por_token(tok) -> 'firmas') f where (f ->> 'email_verificado')::boolean)
     or pg_get_function_result('public.firmas_envio(uuid)'::regprocedure) not like '%email_verificado boolean%' then
    raise exception 'FALLO 322 · la hoja pública o el PDF no saben si el email se verificó'; end if;
  perform set_config('request.jwt.claim.role', '', true);
  raise notice 'OK 322 · e-CMR: con la clave pública no se firma ni se anotan reservas (solo el servidor); código de 6 cifras por su huella, con topes y 5 intentos; firma «email verificado» que decide la base de datos, y se ve en la hoja y el PDF';
end $$;

-- ---- 323. Mapa del envío con la posición estimada del camión --------------------------
-- Lo ven Dynamo, el cliente dueño y su transportista (otro cliente no; sin sesión, nada). Cada
-- parada con coordenadas (las suyas o el centro de su código postal); el camión según el
-- estado: sin salir, en una parada, en ruta entre dos (con la fracción del tramo) o entregado.
-- Las coordenadas de los códigos postales solo las guarda el servidor.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t uuid; begin
  insert into transportistas (razon_social, cif) values ('Transp 323 SL', 'B32300323') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, lat, lon)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES', 37.3891, -5.9845), (e, 2, 'descarga', '28323', 'Madrid', 'ES', null, null);
  update envios set estado = 'programado', transportista_id = t where id = e;
  perform set_config('prueba.e323', e::text, false);
end $$;
do $$ declare ok boolean := false; begin
  perform set_config('request.jwt.claim.role', 'service_role', true);
  perform guardar_geo_cp('es', '28 323', 40.4250, -3.6830);
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  begin perform guardar_geo_cp('ES', '28323', 1, 1); exception when others then ok := true; end;
  perform set_config('request.jwt.claim.role', '', true);
  if not ok or (select lat from geo_codigos_postales where pais_codigo_iso = 'ES' and codigo_postal = '28323') <> 40.425 then
    raise exception 'FALLO 323 · las coordenadas del código postal no las guarda solo el servidor'; end if;
  if has_function_privilege('anon', 'public.mapa_envio(uuid)', 'execute') then raise exception 'FALLO 323 · el mapa se abre sin sesión'; end if;
end $$;
do $$ declare e uuid := current_setting('prueba.e323')::uuid; r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  r := mapa_envio(e);
  if r ->> 'resultado' <> 'ok' or r -> 'camion' ->> 'modo' <> 'sin_salir' then raise exception 'FALLO 323 · el cliente no ve su mapa (sin salir): %', r; end if;
  if (r -> 'paradas' -> 1 ->> 'coord') <> 'codigo_postal' or (r -> 'paradas' -> 1 ->> 'lat')::numeric <> 40.425
     or (r -> 'paradas' -> 0 ->> 'coord') <> 'sitio' then
    raise exception 'FALLO 323 · coordenadas de las paradas mal resueltas: %', r -> 'paradas'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  if mapa_envio(e) ->> 'resultado' <> 'sin_permiso' then raise exception 'FALLO 323 · otro cliente ve el mapa de un envío ajeno'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
end $$;
update envios set estado = 'hacia_la_carga' where id = current_setting('prueba.e323')::uuid;
update envios set estado = 'cargando', parada_actual = 1 where id = current_setting('prueba.e323')::uuid;
do $$ declare r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := mapa_envio(current_setting('prueba.e323')::uuid) -> 'camion';
  if r ->> 'modo' <> 'en_parada' or (r ->> 'hasta')::int <> 1 then raise exception 'FALLO 323 · cargando, el camión no está en la 1.ª parada: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
end $$;
update envios set estado = 'en_ruta', parada_actual = 2 where id = current_setting('prueba.e323')::uuid;
do $$ declare r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := mapa_envio(current_setting('prueba.e323')::uuid) -> 'camion';
  if r ->> 'modo' <> 'en_ruta' or (r ->> 'desde')::int <> 1 or (r ->> 'hasta')::int <> 2
     or (r ->> 'fraccion')::numeric not between 0 and 1 or r ->> 'llegada_prevista' is null then
    raise exception 'FALLO 323 · en ruta, el camión no va entre la 1.ª y la 2.ª parada: %', r; end if;
  -- Parado dice por qué (pausa, descanso, espera) y cuándo sigue; sin parar, sin motivo (2026-11-22).
  if not (r ? 'motivo_parada' and r ? 'sigue_en')
     or ((r ->> 'parado')::boolean and coalesce(r ->> 'motivo_parada', '') not in ('pausa', 'descanso', 'espera'))
     or (not (r ->> 'parado')::boolean and r ->> 'motivo_parada' is not null) then
    raise exception 'FALLO 323 · el motivo de la parada no cuadra: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
end $$;
update envios set estado = 'entregado' where id = current_setting('prueba.e323')::uuid;
do $$ declare r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := mapa_envio(current_setting('prueba.e323')::uuid) -> 'camion';
  if r ->> 'modo' <> 'entregado' or (r ->> 'hasta')::int <> 2 then raise exception 'FALLO 323 · entregado, el camión no está en la última parada: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from geo_codigos_postales where codigo_postal = '28323';
  raise notice 'OK 323 · mapa del envío: lo ven Dynamo, el cliente y su transportista (otro cliente no); coordenadas de la parada o de su código postal (que solo guarda el servidor); camión sin salir, en parada, en ruta con su fracción y entregado';
end $$;

-- ---- 324. Verificación de albaranes ------------------------------------------------------
-- La entrada (solo el servidor) apunta el archivo, no repite el mismo archivo de Drive ni el
-- mismo contenido y lo asigna al envío de la GX del nombre. Solo Dynamo lo ve en la bandeja; el
-- cliente no hasta que se acepta (entonces pasa a sus documentos, visible, con aviso). Rechazar
-- devuelve la ruta para borrar el archivo. Se puede cambiar de envío (y cambia la GX del nombre).
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; e2 uuid; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e2;
  perform set_config('request.jwt.claim.sub', '', false);
  perform set_config('prueba.e324', e::text, false);
  perform set_config('prueba.e324b', e2::text, false);
end $$;
set role anon;
do $$ begin
  perform set_config('request.jwt.claim.role', 'anon', true);
  if entrada_documento_iniciar('x.pdf', 'drive', 'anon-324') ->> 'resultado' <> 'solo_servidor' then
    raise exception 'FALLO 324 · con la clave pública se mete un albarán'; end if;
  perform set_config('request.jwt.claim.role', '', true);
exception when insufficient_privilege then perform set_config('request.jwt.claim.role', '', true);
end $$;
reset role;
do $$ declare e uuid := current_setting('prueba.e324')::uuid; ref text; ref2 text; r jsonb; id1 uuid; id2 uuid; id3 uuid; v_doc uuid; ok boolean := false;
  sha1 text := repeat('a', 64); sha2 text := repeat('b', 64);
begin
  select referencia_gx into ref from envios where id = e;
  select referencia_gx into ref2 from envios where id = current_setting('prueba.e324b')::uuid;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  -- (a) Entrada: dos pasos; el mismo archivo de Drive no entra dos veces; el mismo contenido tampoco.
  r := entrada_documento_iniciar(ref || '_ALB_20261030_41001-SEVILLA_28001-MADRID_1234ABC.pdf', 'drive', 'drive-324-1', '{"origen":"41001 SEVILLA"}');
  if r ->> 'resultado' <> 'ok' or r ->> 'ruta' !~ '^entrada/[0-9a-f-]{36}\.pdf$' then raise exception 'FALLO 324 · no apunta la entrada: %', r; end if;
  id1 := (r ->> 'id')::uuid;
  if (entrada_documento_iniciar('otro.pdf', 'drive', 'drive-324-1') ->> 'id')::uuid <> id1 then raise exception 'FALLO 324 · una subida a medias no se reintenta en su sitio'; end if;
  if entrada_documento_iniciar('virus.exe', 'drive', 'drive-324-x') ->> 'resultado' <> 'tipo_no_valido' then raise exception 'FALLO 324 · deja entrar un .exe'; end if;
  r := entrada_documento_confirmar(id1, sha1, 1234, 'application/pdf');
  if r ->> 'resultado' <> 'ok' or (r ->> 'envio_id')::uuid <> e then raise exception 'FALLO 324 · no lo asigna al envío de su GX: %', r; end if;
  if entrada_documento_iniciar('otro.pdf', 'drive', 'drive-324-1') ->> 'resultado' <> 'ya_existe' then raise exception 'FALLO 324 · el mismo archivo de Drive entra dos veces'; end if;
  id2 := (entrada_documento_iniciar('copia.pdf', 'drive', 'drive-324-2') ->> 'id')::uuid;
  r := entrada_documento_confirmar(id2, sha1, 1234, 'application/pdf');
  if r ->> 'resultado' <> 'duplicado' or exists (select 1 from documentos_entrada where id = id2) then raise exception 'FALLO 324 · el mismo contenido entra dos veces: %', r; end if;
  -- Uno sin GX (para reasignar) y otro para rechazar.
  id2 := (entrada_documento_iniciar('escaneo sin nombre.pdf', 'drive', 'drive-324-3') ->> 'id')::uuid;
  perform entrada_documento_confirmar(id2, sha2, 99, 'application/pdf');
  id3 := (entrada_documento_iniciar(ref || '_ALB_factura.pdf', 'drive', 'drive-324-4') ->> 'id')::uuid;
  perform entrada_documento_confirmar(id3, repeat('c', 64), 99, 'application/pdf');
  perform set_config('request.jwt.claim.role', '', true);
  if has_function_privilege('authenticated', 'public.entrada_documento_iniciar(text, text, text, jsonb)', 'execute') then raise exception 'FALLO 324 · un usuario puede meter albaranes'; end if;
  perform set_config('prueba.d324', id1::text, false);
  perform set_config('prueba.d324b', id2::text, false);
  perform set_config('prueba.d324c', id3::text, false);
  perform set_config('prueba.ref324b', ref2, false);
end $$;
-- (b) El cliente no ve la bandeja; Dynamo sí, con el envío y el contador del menú.
do $$ declare r jsonb; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  if jsonb_array_length(verificacion_albaranes_lista()) <> 0 or exists (select 1 from documentos_entrada) then
    raise exception 'FALLO 324 · el cliente ve albaranes sin verificar'; end if;
  if exists (select 1 from documentos where envio_id = current_setting('prueba.e324')::uuid) then raise exception 'FALLO 324 · el albarán sin verificar ya está en el envío'; end if;
  reset role;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  select x into r from jsonb_array_elements(verificacion_albaranes_lista()) x where x ->> 'id' = current_setting('prueba.d324');
  if r is null or r -> 'envio' ->> 'id' <> current_setting('prueba.e324') then raise exception 'FALLO 324 · Dynamo no ve el albarán con su envío: %', r; end if;
  if (contadores_panel() ->> 'albaranes')::int < 3 then raise exception 'FALLO 324 · el menú no cuenta los albaranes por verificar: %', contadores_panel(); end if;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);
end $$;
-- (c) Revisar: sin envío no se acepta; se reasigna (cambia la GX del nombre); aceptar lo hace
-- visible para el cliente (con aviso); rechazar devuelve la ruta para borrar el archivo.
do $$ declare r jsonb; v_doc uuid; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if verificacion_albaran_aceptar(current_setting('prueba.d324b')::uuid) ->> 'resultado' <> 'sin_envio' then raise exception 'FALLO 324 · se acepta un albarán sin envío'; end if;
  if verificacion_albaran_reasignar(current_setting('prueba.d324b')::uuid, 'hola') ->> 'resultado' <> 'referencia_no_valida' then raise exception 'FALLO 324 · acepta una referencia sin forma de GX'; end if;
  if verificacion_albaran_reasignar(current_setting('prueba.d324b')::uuid, 'GX999999999') ->> 'resultado' <> 'sin_envio' then raise exception 'FALLO 324 · reasigna a un envío que no existe'; end if;
  r := verificacion_albaran_reasignar(current_setting('prueba.d324b')::uuid, substr(current_setting('prueba.ref324b'), 3));
  if r ->> 'resultado' <> 'ok' or r ->> 'nombre_archivo' <> current_setting('prueba.ref324b') || '_escaneo sin nombre.pdf'
     or (select envio_id from documentos_entrada where id = current_setting('prueba.d324b')::uuid) <> current_setting('prueba.e324b')::uuid then
    raise exception 'FALLO 324 · no reasigna bien (envío y nombre): %', r; end if;
  r := verificacion_albaran_aceptar(current_setting('prueba.d324')::uuid, 'cmr_firmado');
  v_doc := (r ->> 'documento_id')::uuid;
  if r ->> 'resultado' <> 'ok' or not exists (select 1 from documentos where id = v_doc and visible_cliente and tipo = 'cmr_firmado' and envio_id = current_setting('prueba.e324')::uuid)
     or (select estado from documentos_entrada where id = current_setting('prueba.d324')::uuid) <> 'aceptado' then
    raise exception 'FALLO 324 · aceptar no lo pasa visible al envío: %', r; end if;
  if not exists (select 1 from avisos where para = 'cliente' and envio_id = current_setting('prueba.e324')::uuid and titulo like 'CMR firmado disponible%') then
    raise exception 'FALLO 324 · al aceptarlo no se avisa al cliente'; end if;
  if verificacion_albaran_aceptar(current_setting('prueba.d324')::uuid) ->> 'resultado' <> 'no_pendiente' then raise exception 'FALLO 324 · se acepta dos veces'; end if;
  r := verificacion_albaran_rechazar(current_setting('prueba.d324c')::uuid, 'Es una factura del transportista');
  if r ->> 'resultado' <> 'ok' or r ->> 'ruta' !~ '^entrada/' or (select estado from documentos_entrada where id = current_setting('prueba.d324c')::uuid) <> 'rechazado' then
    raise exception 'FALLO 324 · no rechaza bien: %', r; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  if not exists (select 1 from documentos where envio_id = current_setting('prueba.e324')::uuid and visible_cliente) then raise exception 'FALLO 324 · el cliente no ve el albarán aceptado'; end if;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 324 · verificación de albaranes: entrada solo del servidor, sin repetir archivo ni contenido, asignada por la GX del nombre; el cliente no los ve hasta aceptarlos (con aviso); rechazar borra; reasignar cambia envío y nombre';
end $$;

-- ---- 325. Mapa general de envíos en curso -----------------------------------------------
-- Dynamo ve todos los que están en programación o en marcha; el cliente, solo los suyos; el
-- transportista, nada. Nunca entregados ni cancelados.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('prueba.e325', e::text, false);
end $$;
do $$ declare r jsonb; ids text[]; e323 text := current_setting('prueba.e323'); e324 text := current_setting('prueba.e325'); begin
  -- 323 está entregado; 325 está programado (del cliente de pruebas).
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  r := mapa_envios_en_curso();
  select array_agg(x ->> 'id') into ids from jsonb_array_elements(r) x;
  if not (e324 = any(ids)) or e323 = any(ids) then raise exception 'FALLO 325 · Dynamo no ve lo programado o ve lo entregado'; end if;
  if exists (select 1 from jsonb_array_elements(r) x where x ->> 'estado' not in ('programado', 'hacia_la_carga', 'cargando', 'en_ruta')) then
    raise exception 'FALLO 325 · salen entregados o cancelados'; end if;
  if (select x ->> 'cliente' from jsonb_array_elements(r) x where x ->> 'id' = e324) is null then raise exception 'FALLO 325 · Dynamo no ve el cliente'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  r := mapa_envios_en_curso();
  if not exists (select 1 from jsonb_array_elements(r) x where x ->> 'id' = e324)
     or exists (select 1 from jsonb_array_elements(r) x join envios v on v.id = (x ->> 'id')::uuid where v.cliente_id <> current_setting('prueba.cliente')::uuid)
     or exists (select 1 from jsonb_array_elements(r) x where x ->> 'cliente' is not null) then
    raise exception 'FALLO 325 · el cliente no ve solo lo suyo (o ve el nombre del cliente)'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  if exists (select 1 from jsonb_array_elements(mapa_envios_en_curso()) x where x ->> 'id' = e324) then raise exception 'FALLO 325 · otro cliente ve envíos ajenos en el mapa'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
  if jsonb_array_length(mapa_envios_en_curso()) <> 0 then raise exception 'FALLO 325 · el transportista ve el mapa general'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 325 · mapa general: Dynamo ve todos los envíos en programación o en marcha (con cliente), el cliente solo los suyos, el transportista nada; nunca entregados ni cancelados';
end $$;

-- ---- 326. La firma del CMR se cierra 3 días después de la entrega ---------------------
-- Mientras el envío está vivo se firma; entregado, hasta el final del 3.er día (hora de
-- Madrid) después de la entrega en la última parada; pasado eso, ni firmas, ni reservas, ni
-- código: la hoja sigue abriendo (para ver y descargar) y dice que está cerrada.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; t uuid; tok uuid; r jsonb; begin
  insert into transportistas (razon_social, cif) values ('Transp 326 SL', 'B32600326') returning id into t;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado', transportista_id = t where id = e;
  select token into tok from cmr_enlaces where envio_id = e and not revocado;
  if not cmr_firma_abierta(e) or cmr_firma_hasta(e) is not null or (cmr_publico(tok) ->> 'firma_abierta')::boolean is not true then
    raise exception 'FALLO 326 · un envío programado no se puede firmar'; end if;
  -- Entregado hace un rato: abierta, con plazo hasta el final del 3.er día.
  update envios set estado = 'entregado' where id = e;
  if not cmr_firma_abierta(e)
     or cmr_firma_hasta(e) <> ((((now() at time zone 'Europe/Madrid')::date + 4)::timestamp) at time zone 'Europe/Madrid') then
    raise exception 'FALLO 326 · recién entregado, el plazo no es el final del 3.er día: %', cmr_firma_hasta(e); end if;
  -- Entregado hace 5 días: cerrada.
  alter table envios disable trigger user;
  update envios set entregado_en = now() - interval '5 days' where id = e;
  alter table envios enable trigger user;
  if (select entregado_en from envios where id = e) > now() - interval '4 days' then raise exception 'FALLO 326 · no se pudo fechar la entrega'; end if;
  if cmr_firma_abierta(e) then raise exception 'FALLO 326 · 5 días después de la entrega aún se puede firmar'; end if;
  r := cmr_publico(tok);
  if r ->> 'resultado' <> 'ok' or (r ->> 'firma_abierta')::boolean is not false or r ->> 'firma_hasta' is null then
    raise exception 'FALLO 326 · la hoja no abre para ver o no dice que está cerrada: %', r - 'paradas' - 'firmas'; end if;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  r := firmar_cmr_publico(tok, null, 'transportista', 'Tarde 326', '12345678Z', 'ES', true, null, 'cmr/' || tok::text || '/t326.png',
                          null, 'prueba', null, p_matricula_camion => '3260AAA', p_matricula_remolque => 'R3260AAA');
  if r ->> 'resultado' <> 'firma_cerrada' then raise exception 'FALLO 326 · se firma un CMR cerrado: %', r; end if;
  r := anotar_reservas_cmr_publico(tok, null, 'transportista', 'Reservas tardías');
  if r ->> 'resultado' <> 'firma_cerrada' then raise exception 'FALLO 326 · se anotan reservas en un CMR cerrado: %', r; end if;
  r := cmr_codigo_firma_crear(tok, null, 'transportista', 'tarde@t326.com', repeat('c', 64));
  if r ->> 'resultado' <> 'firma_cerrada' then raise exception 'FALLO 326 · se pide código en un CMR cerrado: %', r; end if;
  perform set_config('request.jwt.claim.role', '', true);
  if exists (select 1 from firmas_cmr where envio_id = e) or exists (select 1 from cmr_codigos_firma where envio_id = e) then
    raise exception 'FALLO 326 · el CMR cerrado ha dejado algo escrito'; end if;
  if has_function_privilege('anon', 'public.cmr_firma_abierta(uuid)', 'execute') or has_function_privilege('authenticated', 'public.cmr_firma_hasta(uuid)', 'execute') then
    raise exception 'FALLO 326 · las funciones del plazo están abiertas'; end if;
  raise notice 'OK 326 · la firma del CMR se cierra al final del 3.er día tras la entrega: después no se firma, ni se anotan reservas, ni se pide código; la hoja sigue abriendo para ver y descargar';
end $$;

-- ---- 327. Mapa general: coordenadas que faltan, aparte ----------------------------------
-- Las paradas sin coordenadas de los envíos del mapa las dice la base de datos (Dynamo,
-- todas; el cliente, las suyas; el transportista y otro cliente, nada); en cuanto su código
-- postal tiene coordenadas, deja de salir. Los «no encontrados» solo los toca el servidor.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; r jsonb; ok boolean := false; begin
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde)
    values (current_setting('prueba.cliente')::uuid, 13.30, 20, 1000, 800, (now() at time zone 'Europe/Madrid')::date + 3) returning id into e;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso)
    values (e, 1, 'carga', '99 327', 'Villa327', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if not exists (select 1 from jsonb_array_elements(mapa_paradas_sin_coordenadas()) x where x ->> 'codigo_postal' = '99 327' and x ->> 'pais' = 'ES') then
    raise exception 'FALLO 327 · Dynamo no ve la parada sin coordenadas'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  if not exists (select 1 from jsonb_array_elements(mapa_paradas_sin_coordenadas()) x where x ->> 'codigo_postal' = '99 327') then
    raise exception 'FALLO 327 · el cliente no ve su parada sin coordenadas'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  if exists (select 1 from jsonb_array_elements(mapa_paradas_sin_coordenadas()) x where x ->> 'codigo_postal' = '99 327') then
    raise exception 'FALLO 327 · otro cliente ve paradas ajenas'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
  if jsonb_array_length(mapa_paradas_sin_coordenadas()) <> 0 then raise exception 'FALLO 327 · el transportista ve paradas del mapa general'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into geo_codigos_postales (pais_codigo_iso, codigo_postal, lat, lon) values ('ES', '99327', 40, -3);
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if exists (select 1 from jsonb_array_elements(mapa_paradas_sin_coordenadas()) x where x ->> 'codigo_postal' = '99 327') then
    raise exception 'FALLO 327 · con su código postal situado sigue saliendo'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from geo_codigos_postales where codigo_postal = '99327';
  update envios set estado = 'cancelado' where id = e;
  if has_function_privilege('anon', 'public.mapa_paradas_sin_coordenadas()', 'execute')
     or has_table_privilege('authenticated', 'public.geo_no_encontrados', 'select')
     or has_table_privilege('anon', 'public.geo_no_encontrados', 'insert') then
    raise exception 'FALLO 327 · permisos de las coordenadas aparte mal puestos'; end if;
  raise notice 'OK 327 · mapa general: las paradas sin coordenadas se piden aparte (Dynamo todas, el cliente las suyas, nadie más); en cuanto se sitúan dejan de salir; los «no encontrados» solo el servidor';
end $$;

-- 328 · EL PRECIO DEL CLIENTE LO COMPRUEBA LA BASE DE DATOS (repaso de seguridad, 2026-11-23):
-- crear_envio_cliente rechaza un precio que no es el del tarifador y, con el bueno, guarda
-- también el de tarifa que calcula ella; las funciones del cálculo no se llaman desde fuera.
do $$
declare v_desde date := primera_fecha_carga(false, now(), 3); v_datos jsonb; v_p jsonb; v_precio jsonb;
  v_id uuid; ok boolean := false; e envios%rowtype;
begin
  v_datos := jsonb_build_object('fecha_carga_desde', v_desde, 'fecha_carga_hasta', sumar_dias_habiles(v_desde, 2),
    'metros_lineales', 13.3, 'toneladas', 24, 'paletizado', true, 'requiere_plataforma_elevadora', false);
  v_p := jsonb_build_array(
    jsonb_build_object('tipo', 'carga', 'nombre_empresa', 'Origen 328', 'poblacion', 'Sevilla', 'codigo_postal', '41001', 'pais_codigo_iso', 'ES', 'tipo_sitio', 'finca'),
    jsonb_build_object('tipo', 'descarga', 'nombre_empresa', 'Destino 328', 'poblacion', 'Madrid', 'codigo_postal', '28001', 'pais_codigo_iso', 'ES'));
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  begin
    perform crear_envio_cliente(v_datos || '{"importe_cliente": 1, "importe_tarifa": 1}', v_p);
  exception when others then ok := sqlerrm like 'El precio de este envío ha cambiado%';
  end;
  if not ok then raise exception 'FALLO 328 · un envío del cliente a 1 € se ha creado'; end if;
  -- Con el del tarifador (finca: +180 € sobre los 700, con el factor del cliente) sí entra.
  v_precio := precio_tarifa_cliente(v_datos, array['finca', 'almacen_nave'], factor_tarifa_envio(cliente_del_usuario()));
  if (v_precio ->> 'base')::numeric <> 880 then raise exception 'FALLO 328 · el precio de tarifa no es 880 (%)', v_precio; end if;
  select x.id into v_id from crear_envio_cliente(v_datos || jsonb_build_object('importe_cliente', v_precio -> 'neto', 'importe_tarifa', 1), v_p) x;
  perform set_config('request.jwt.claim.sub', '', false);
  select * into e from envios where id = v_id;
  if e.importe_cliente <> (v_precio ->> 'neto')::numeric or e.importe_tarifa <> 880 then
    raise exception 'FALLO 328 · guardado % / tarifa % (esperado % / 880)', e.importe_cliente, e.importe_tarifa, v_precio ->> 'neto'; end if;
  update envios set estado = 'cancelado' where id = v_id;
  if has_function_privilege('authenticated', 'public.precio_tarifa_cliente(jsonb, text[], numeric, timestamptz)', 'execute')
     or has_function_privilege('anon', 'public.precio_tarifa_cliente(jsonb, text[], numeric, timestamptz)', 'execute')
     or has_function_privilege('authenticated', 'public.precio_cliente_comprobado(jsonb, text[], numeric)', 'execute')
     or has_function_privilege('authenticated', 'public.tarifa_tipos_ruta(uuid, jsonb)', 'execute') then
    raise exception 'FALLO 328 · las funciones del precio se pueden llamar desde fuera'; end if;
  raise notice 'OK 328 · el precio del cliente lo comprueba la base de datos: a 1 € no entra, con el del tarifador sí (y guarda su precio de tarifa); el cálculo no se llama desde fuera';
end $$;

-- 329 · PACKS DE GRUPAJE (usuario, 2026-11-23): se juntan partidas programadas, sin
-- transportista y de grupaje que van por la misma ruta de provincias (o le pillan al paso),
-- con un día de carga en común y sin pasar del tráiler (13,30 m y 24 t). Solo Dynamo.
reset role;
select set_config('request.jwt.claim.sub', '', false);
update parametros set valor = 'false' where clave = 'pago_previo_activo';
do $$
declare d date := sumar_dias_habiles(current_date, 5); cli uuid := current_setting('prueba.cliente')::uuid;
  v text; n uuid;
begin
  -- a, b, c, x: Sevilla → Madrid · e: Córdoba → Toledo (al paso) · f: con plataforma elevadora.
  -- g/h e i/j, otras dos parejas para probar lo que saca a una partida de su pack.
  foreach v in array array['a','b','c','x','e','f','g','h','i','j'] loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta, requiere_plataforma_elevadora)
      values (cli, case v when 'a' then 4 when 'b' then 5 when 'c' then 6 when 'e' then 3 when 'j' then 6 else 4 end, 5, 700,
              case v when 'x' then d + 20 else d end, case v when 'x' then d + 22 when 'b' then d + 2 else d + 3 end, v = 'f')
      returning id into n;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, lat, lon) values
      (n, 1, 'carga',    case v when 'e' then '14001' else '41001' end, case v when 'e' then 'Córdoba' else 'Sevilla' end, 'ES',
                         case v when 'e' then 37.996 else 37.39 end, case v when 'e' then -5.524 else -5.98 end),
      (n, 2, 'descarga', case v when 'e' then '45001' else '28001' end, case v when 'e' then 'Toledo' else 'Madrid' end, 'ES',
                         case v when 'e' then 40.117 else 40.42 end, case v when 'e' then -3.928 else -3.70 end);
    perform set_config('prueba.p329' || v, n::text, false);
  end loop;
  update envios set estado = 'programado' where id in (select current_setting('prueba.p329' || z)::uuid from unnest(array['a','b','c','x','e','f','g','h','i','j']) z);
end $$;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform envio_pack_info(current_setting('prueba.p329a')::uuid); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 329 · un cliente ve los packs'; end if;
  ok := false;
  begin perform crear_pack(array[current_setting('prueba.p329a')::uuid, current_setting('prueba.p329b')::uuid]); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 329 · un cliente agrupa envíos'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
do $$
declare a uuid := current_setting('prueba.p329a')::uuid; b uuid := current_setting('prueba.p329b')::uuid;
  c uuid := current_setting('prueba.p329c')::uuid; x uuid := current_setting('prueba.p329x')::uuid;
  e uuid := current_setting('prueba.p329e')::uuid; f uuid := current_setting('prueba.p329f')::uuid;
  info jsonb; ids text[]; r jsonb; ok boolean; k uuid;
begin
  info := envio_pack_info(a);
  select array_agg(z ->> 'id') into ids from jsonb_array_elements(info -> 'compatibles') z;
  if not (b::text = any(ids)) or not (c::text = any(ids)) or not (e::text = any(ids)) then
    raise exception 'FALLO 329 · faltan partidas compatibles (misma ruta o al paso): %', info -> 'compatibles'; end if;
  if x::text = any(ids) or f::text = any(ids) then raise exception 'FALLO 329 · salen partidas sin día común o con plataforma'; end if;
  if (select z ->> 'tipo' from jsonb_array_elements(info -> 'compatibles') z where z ->> 'id' = e::text) <> 'al_paso'
     or (select z ->> 'tipo' from jsonb_array_elements(info -> 'compatibles') z where z ->> 'id' = b::text) <> 'misma_ruta' then
    raise exception 'FALLO 329 · no distingue misma ruta de al paso'; end if;
  if envio_pack_info(f) ->> 'motivo' not like '%plataforma%' then raise exception 'FALLO 329 · no dice por qué no se agrupa el de plataforma'; end if;
  -- a + b (9 m) entra; c (6 m más) ya no cabe; e (al paso, 3 m) sí.
  r := crear_pack(array[a, b]); k := (r ->> 'pack_id')::uuid;
  if (select count(*) from envios where pack_id = k) <> 2 then raise exception 'FALLO 329 · el pack no se crea'; end if;
  if (select z ->> 'cabe' from jsonb_array_elements(envio_pack_info(a) -> 'compatibles') z where z ->> 'id' = c::text)::boolean then
    raise exception 'FALLO 329 · dice que cabe una partida que pasa del tráiler'; end if;
  ok := false;
  begin perform crear_pack(array[c], k); exception when others then ok := sqlerrm like '%se pasan del tráiler%'; end;
  if not ok then raise exception 'FALLO 329 · un pack pasa de 13,30 m'; end if;
  ok := false;
  begin perform crear_pack(array[c, x]); exception when others then ok := sqlerrm like '%ningún día en común%'; end;
  if not ok then raise exception 'FALLO 329 · agrupa partidas sin un día de carga en común'; end if;
  ok := false;
  begin perform crear_pack(array[f, c]); exception when others then ok := sqlerrm like '%plataforma%'; end;
  if not ok then raise exception 'FALLO 329 · agrupa una partida con plataforma elevadora'; end if;
  perform crear_pack(array[e], k);
  if (select count(*) from envios where pack_id = k) <> 3 then raise exception 'FALLO 329 · no añade la partida al paso'; end if;
  if not exists (select 1 from jsonb_array_elements(packs_de_grupaje() -> 'creados') z where z -> 'pack' ->> 'id' = k::text) then
    raise exception 'FALLO 329 · la lista no enseña el pack creado'; end if;
  perform set_config('prueba.k329', k::text, false);
end $$;
-- Asignar el pack: Dynamo asigna una partida y se le asignan todas (mismo camión y día).
do $$
declare a uuid := current_setting('prueba.p329a')::uuid; k uuid := current_setting('prueba.k329')::uuid;
  t uuid := current_setting('prueba.transp')::uuid; r jsonb; ok boolean := false; dd date;
begin
  select max(fecha_carga_desde) into dd from envios where pack_id = k;
  -- Sin precio en las demás partidas, no se asigna.
  begin perform asignar_transportista(a, t, 900, '1234ABC', null, 'Pepe', '600111222', dd);
  exception when others then ok := sqlerrm like '%no tiene precio del transportista%'; end;
  if not ok then raise exception 'FALLO 329 · asigna el pack con partidas sin precio del transportista'; end if;
  update envios set importe_transportista = 300 where pack_id = k and id <> a;
  ok := false;
  begin perform asignar_transportista(a, t, 900, '1234ABC', null, 'Pepe', '600111222', dd + 3);
  exception when others then ok := sqlerrm like '%día común%'; end;
  if not ok then raise exception 'FALLO 329 · asigna el pack un día que no es común a todas sus partidas'; end if;
  r := asignar_transportista(a, t, 900, '1234ABC', null, 'Pepe', '600111222', dd);
  if r ->> 'resultado' <> 'asignado' then raise exception 'FALLO 329 · no asigna: %', r; end if;
  if (select count(*) from envios where pack_id = k and transportista_id = t and matricula_camion = '1234ABC' and fecha_carga_prevista = dd) <> 3
     or (select estado from packs where id = k) <> 'asignado' then
    raise exception 'FALLO 329 · asignar una partida no asigna todo el pack con el mismo camión y día'; end if;
end $$;
-- Un transportista acepta una partida por su cuenta: sale del pack (y el pack de 2 se deshace).
do $$
declare g uuid := current_setting('prueba.p329g')::uuid; h uuid := current_setting('prueba.p329h')::uuid;
  i uuid := current_setting('prueba.p329i')::uuid; j uuid := current_setting('prueba.p329j')::uuid; k uuid; k2 uuid;
begin
  k := (crear_pack(array[g, h]) ->> 'pack_id')::uuid;
  k2 := (crear_pack(array[i, j]) ->> 'pack_id')::uuid;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_transp'), false);
  update envios set transportista_id = current_setting('prueba.transp')::uuid, fecha_carga_prevista = fecha_carga_desde where id = g;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  if (select pack_id from envios where id = g) is not null or (select pack_id from envios where id = h) is not null
     or (select estado from packs where id = k) <> 'deshecho' then
    raise exception 'FALLO 329 · la partida aceptada por un transportista sigue en el pack'; end if;
  if (select transportista_id from envios where id = h) is not null then raise exception 'FALLO 329 · el transportista se lleva el pack entero sin saberlo'; end if;
  if not exists (select 1 from avisos where para = 'dynamo' and tipo = 'pack_partida_fuera' and envio_id = g) then
    raise exception 'FALLO 329 · Dynamo no se entera de que una partida sale del pack'; end if;
  -- Cambia de medidas y el pack se pasaría del tráiler: sale del pack.
  update envios set metros_lineales = 10 where id = j;
  if (select pack_id from envios where id = j) is not null then raise exception 'FALLO 329 · una partida que ya no cabe sigue en el pack'; end if;
  update envios set estado = 'cancelado' where id in (g, h, i, j);
  update envios set estado = 'cancelado' where id in (select current_setting('prueba.p329' || z)::uuid from unnest(array['c','x','f']) z) and transportista_id is null;
  if has_function_privilege('anon', 'public.crear_pack(uuid[], uuid)', 'execute')
     or has_table_privilege('authenticated', 'public.packs', 'insert')
     or has_function_privilege('authenticated', 'public.pack_ruta(uuid)', 'execute') then
    raise exception 'FALLO 329 · permisos de los packs mal puestos'; end if;
  raise notice 'OK 329 · packs de grupaje: misma ruta o al paso, un día en común y sin pasar del tráiler; asignar una partida asigna el pack; aceptada por separado, cambiada o cancelada sale del pack con aviso; solo Dynamo';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 330 · COBERTURA DE CRÉDITO «SUPERADO» (usuario, 2026-11-23): con crédito pero consumido, o con
--       un envío esperando el pago porque no le cabía, el indicador ya no dice «disponible».
do $$
declare v_cli uuid; v_man numeric; v_ces numeric; e uuid; r text;
begin
  select cliente_id into v_cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  select riesgo_manual_euros, riesgo_cesce_euros into v_man, v_ces from clientes where id = v_cli;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  -- Sin clasificar y sin crédito, como antes.
  update clientes set riesgo_cesce_euros = null, riesgo_manual_euros = null where id = v_cli;
  if mi_cobertura_credito() <> 'sinclasif' then raise exception 'FALLO 330 · sin riesgo informado no sale «sinclasif»: %', mi_cobertura_credito(); end if;
  update clientes set riesgo_manual_euros = 0 where id = v_cli;
  if mi_cobertura_credito() <> 'nulo' then raise exception 'FALLO 330 · con crédito 0 no sale «nulo»: %', mi_cobertura_credito(); end if;
  -- Con crédito de sobra y sin envíos esperando pago: disponible.
  update clientes set riesgo_manual_euros = 1000000 where id = v_cli;
  update envios set estado = 'cancelado' where cliente_id = v_cli and estado_pago_previo = 'pendiente' and estado not in ('borrador', 'cancelado');
  r := mi_cobertura_credito();
  if r <> 'disponible' then raise exception 'FALLO 330 · con crédito de sobra no sale «disponible»: %', r; end if;
  -- Un envío esperando el pago porque no le cabía en el crédito: superado.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde, fecha_carga_hasta)
    values (v_cli, 3, 2, 500, current_date + 20, current_date + 22) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso, nombre_empresa) values
    (e, 1, 'carga', '41001', 'Sevilla', 'ES', 'Nave 330'), (e, 2, 'descarga', '28001', 'Madrid', 'ES', 'Destino 330');
  update envios set estado = 'programado' where id = e;
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Crédito insuficiente (prueba 330)', pago_pendiente_en = now() where id = e;
  r := mi_cobertura_credito();
  if r <> 'superado' then raise exception 'FALLO 330 · con un envío pendiente de pago por crédito no sale «superado»: %', r; end if;
  -- Cancelado ese envío vuelve a disponible; con el crédito consumido, superado otra vez.
  update envios set estado = 'cancelado' where id = e;
  if mi_cobertura_credito() <> 'disponible' then raise exception 'FALLO 330 · cancelado el envío pendiente no vuelve a «disponible»: %', mi_cobertura_credito(); end if;
  update clientes set riesgo_manual_euros = 0.01 where id = v_cli;
  if (select usado from credito_uso_cliente(v_cli)) >= 0.01 and mi_cobertura_credito() <> 'superado' then
    raise exception 'FALLO 330 · con el crédito consumido no sale «superado»: %', mi_cobertura_credito(); end if;
  update clientes set riesgo_manual_euros = v_man, riesgo_cesce_euros = v_ces where id = v_cli;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 330 · cobertura de crédito: sin clasificar, sin crédito (0), superado (consumido o con un envío esperando el pago por crédito) y disponible';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 331 · EMAIL «ENVÍO CREADO» PENDIENTE DE PAGO (usuario, 2026-11-23): dice cómo pagar, lleva el
--       botón «Pagar el envío» y deja los dos huecos que completa el servidor web (tarjeta y
--       proforma adjunta). Sin pago pendiente no dice nada de pagar.
do $$
declare cli uuid; adm uuid; e uuid; s uuid; r record; lun date;
begin
  select cliente_id into cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  adm := current_setting('prueba.u_al85', true)::uuid;
  lun := current_date + ((8 - extract(isodow from current_date)::int) % 7) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now() where id = e;
  update envios set estado = 'programado' where id = e;
  select * into r from emails_enviados where clave = 'envio_creado:' || e;
  if r.id is null then raise exception 'FALLO 331 · no se encola el email «Envío creado»'; end if;
  if coalesce(precio_por_revisar((select estado_revision_precio from envios where id = e)), false) then
    if position('Cómo pagar' in r.cuerpo_html) > 0 or position('Pagar el envío' in r.cuerpo_html) > 0 then
      raise exception 'FALLO 331 · con el precio provisional el email invita a pagar'; end if;
    if position('provisional' in r.cuerpo_html) = 0 then raise exception 'FALLO 331 · con el precio provisional el email no lo dice'; end if;
  else
    if position('Cómo pagar' in r.cuerpo_html) = 0 or position('Ya he hecho la transferencia' in r.cuerpo_html) = 0
       or position('ha llegado a nuestra cuenta' in r.cuerpo_html) = 0 then
      raise exception 'FALLO 331 · el email de un envío pendiente de pago no dice cómo pagar: %', r.cuerpo_html; end if;
    if position('<!--pago-tarjeta-->' in r.cuerpo_html) = 0 or position('<!--pago-proforma-->' in r.cuerpo_html) = 0 then
      raise exception 'FALLO 331 · faltan los huecos que completa el servidor web (tarjeta y proforma adjunta)'; end if;
    if position('/panel/envios?ver=' || e in r.cuerpo_html) = 0 or position('>Pagar el envío</a>' in r.cuerpo_html) = 0 then
      raise exception 'FALLO 331 · falta el botón «Pagar el envío» a la ficha'; end if;
  end if;
  update envios set estado = 'cancelado' where id = e;
  -- Un envío que no espera pago: ni cómo pagar, ni botón de pagar, ni huecos.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1) returning id into s;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (s, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (s, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'exento', pago_exento_motivo = 'Prueba 331' where id = s;
  update envios set estado = 'programado' where id = s;
  select * into r from emails_enviados where clave = 'envio_creado:' || s;
  if r.id is not null and (position('Cómo pagar' in r.cuerpo_html) > 0 or position('Pagar el envío' in r.cuerpo_html) > 0 or position('<!--pago-' in r.cuerpo_html) > 0) then
    raise exception 'FALLO 331 · un envío sin pago pendiente recibe instrucciones de pago'; end if;
  update envios set estado = 'cancelado' where id = s;
  raise notice 'OK 331 · email «Envío creado» pendiente de pago: cómo pagar, botón «Pagar el envío» y huecos para la tarjeta y la proforma adjunta; sin pago pendiente, nada de eso';
end $$;
select set_config('request.jwt.claim.sub', '', false);


-- 332 · DEVOLUCIÓN DE UN PAGO CON TARJETA (usuario, 2026-11-23): solo el Admin Master; el importe
--       no pasa de lo cobrado; total → el envío deja de estar pagado, con hito y email al cliente;
--       parcial → además una penalización sin confirmar por lo retenido, ya cobrada con ese pago;
--       si Stripe falla no cambia nada; cerrada una vez, no se cierra dos.
do $$
declare cli uuid; adm uuid := current_setting('prueba.u_admin')::uuid; e uuid; e2 uuid; r jsonb; d uuid; lun date; v_man numeric; v_ces numeric;
        p record; n int; ok boolean;
begin
  select cliente_id into cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  select riesgo_manual_euros, riesgo_cesce_euros into v_man, v_ces from clientes where id = cli;
  update clientes set riesgo_manual_euros = 0, riesgo_cesce_euros = 0 where id = cli;   -- sin crédito: al devolver vuelve a pendiente
  lun := current_date + ((8 - extract(isodow from current_date)::int) % 7) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 1000, 700, lun, lun + 1) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now() where id = e;
  update envios set estado = 'programado' where id = e;
  update envios set estado_pago_previo = 'pagado', pago_metodo = 'stripe', pagado_en = now(), stripe_pago_ref = 'pi_332a' where id = e;

  -- Nadie más que el Admin Master: ni el cliente, ni un usuario de Dynamo de solo lectura.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  ok := false;
  begin perform devolucion_pago_abrir(e, 1210, 1210, null); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 332 · un cliente puede abrir una devolución'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_al85'), false);
  ok := false;
  begin perform devolucion_pago_abrir(e, 1210, 1210, null); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 332 · un usuario de solo lectura puede abrir una devolución'; end if;
  ok := false;
  begin perform devolucion_pago_cerrar(gen_random_uuid(), true, 're_x', null); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 332 · un usuario de solo lectura puede cerrar una devolución'; end if;

  perform set_config('request.jwt.claim.sub', adm::text, false);
  -- Importes que no valen.
  r := devolucion_pago_abrir(e, 1300, 1210, null);
  if r->>'resultado' <> 'importe_excesivo' then raise exception 'FALLO 332 · deja devolver más de lo cobrado: %', r; end if;
  r := devolucion_pago_abrir(e, 0, 1210, null);
  if r->>'resultado' <> 'importe_no_valido' then raise exception 'FALLO 332 · deja devolver 0: %', r; end if;

  -- Si Stripe la rechaza: fallida y el envío sigue pagado.
  r := devolucion_pago_abrir(e, 1210, 1210, 'Prueba 332');
  if r->>'resultado' <> 'ok' or r->>'pago_ref' <> 'pi_332a' then raise exception 'FALLO 332 · no abre la devolución: %', r; end if;
  d := (r->>'id')::uuid;
  -- Abrirla otra vez con el mismo importe la retoma (misma fila); con otro importe, espera.
  r := devolucion_pago_abrir(e, 1210, 1210, null);
  if (r->>'id')::uuid is distinct from d then raise exception 'FALLO 332 · repetir la misma devolución abre otra: %', r; end if;
  r := devolucion_pago_abrir(e, 500, 1210, null);
  if r->>'resultado' <> 'en_curso' then raise exception 'FALLO 332 · con una en curso deja abrir otra distinta: %', r; end if;
  r := devolucion_pago_cerrar(d, false, null, 'tarjeta caducada');
  if r->>'resultado' <> 'fallida' or (select estado_pago_previo from envios where id = e) <> 'pagado' then
    raise exception 'FALLO 332 · una devolución fallida cambia el envío: %', r; end if;
  if exists (select 1 from envio_hitos where envio_id = e and hito = 'pago_devuelto') then raise exception 'FALLO 332 · una devolución fallida deja hito'; end if;

  -- TOTAL: el envío vuelve a pendiente de pago (sin crédito), con plazo nuevo, hito y email; sin penalización.
  d := (devolucion_pago_abrir(e, 1210, 1210, 'Lo pide el cliente')->>'id')::uuid;
  r := devolucion_pago_cerrar(d, true, 're_332a', null);
  if r->>'resultado' <> 'ok' or (r->>'retenido')::numeric <> 0 or r->>'estado_pago' <> 'pendiente' or r->>'penalizacion' is not null then
    raise exception 'FALLO 332 · devolución total: %', r; end if;
  if (r->>'base_devuelta')::numeric <> 1000 then raise exception 'FALLO 332 · base devuelta mal: %', r; end if;
  select estado_pago_previo, pago_metodo, pagado_en, stripe_pago_ref, pago_pendiente_en into p from envios where id = e;
  if p.estado_pago_previo <> 'pendiente' or p.pago_metodo is not null or p.pagado_en is not null or p.stripe_pago_ref is not null then
    raise exception 'FALLO 332 · tras devolver, el envío sigue con datos del pago: %', p; end if;
  if p.pago_pendiente_en is null or p.pago_pendiente_en < now() - interval '1 minute' then
    raise exception 'FALLO 332 · al volver a pendiente no empieza un plazo nuevo: %', p.pago_pendiente_en; end if;
  if not exists (select 1 from envio_hitos where envio_id = e and hito = 'pago_devuelto' and (datos->>'devuelto')::numeric = 1210) then
    raise exception 'FALLO 332 · no queda el hito de la devolución'; end if;
  if not hito_visible_fuera('pago_devuelto') then raise exception 'FALLO 332 · el cliente no ve el hito «pago devuelto»'; end if;
  if not exists (select 1 from emails_enviados where clave = 'pago_devuelto:' || d and tipo = 'pago_devuelto' and position('1.210,00' in cuerpo_html) > 0) then
    raise exception 'FALLO 332 · no se encola el email «Pago devuelto» con el importe'; end if;
  if (select estado from devoluciones_pago where id = d) <> 'hecha' or (select stripe_devolucion_ref from devoluciones_pago where id = d) <> 're_332a' then
    raise exception 'FALLO 332 · la devolución no queda hecha con su referencia'; end if;
  r := devolucion_pago_cerrar(d, true, 're_otra', null);
  if r->>'resultado' <> 'ya_cerrada' then raise exception 'FALLO 332 · una devolución se cierra dos veces: %', r; end if;
  r := devolucion_pago_abrir(e, 100, 1210, null);
  if r->>'resultado' <> 'no_pagado_con_tarjeta' then raise exception 'FALLO 332 · deja devolver un envío que ya no está pagado: %', r; end if;
  update envios set estado = 'cancelado' where id = e;

  -- PARCIAL sobre un envío ya cancelado: se devuelven 847 de 1.210; los 363 (300 + IVA) quedan
  -- en una penalización sin confirmar, ya cobrada con ese pago; el envío no pide pago.
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (cli, 13.30, 20, 1000, 700, lun, lun + 1) returning id into e2;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e2, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e2, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now() where id = e2;
  update envios set estado = 'programado' where id = e2;
  update envios set estado_pago_previo = 'pagado', pago_metodo = 'stripe', pagado_en = now(), stripe_pago_ref = 'pi_332b' where id = e2;
  update envios set estado = 'cancelado' where id = e2;
  select count(*) into n from penalizaciones where envio_id = e2;
  d := (devolucion_pago_abrir(e2, 847, 1210, null)->>'id')::uuid;
  r := devolucion_pago_cerrar(d, true, 're_332b', null);
  if r->>'resultado' <> 'ok' or (r->>'retenido')::numeric <> 363 or (r->>'base_retenida')::numeric <> 300 or (r->>'base_devuelta')::numeric <> 700
     or r->>'estado_pago' <> 'no_requerido' or r->>'penalizacion' is null then
    raise exception 'FALLO 332 · devolución parcial: %', r; end if;
  select * into p from penalizaciones where id = (select penalizacion_id from devoluciones_pago where id = d);
  if p.id is null or p.envio_id <> e2 or p.estado <> 'pendiente_confirmar' or p.importe_cliente <> 300 or p.descripcion <> 'Cancelación transporte fuera de plazo'
     or p.cobrada_importe <> 363 or p.cobrada_pago_ref <> 'pi_332b' or p.cobrada_en is null then
    raise exception 'FALLO 332 · la penalización por lo retenido no queda bien: %', p; end if;
  if (select count(*) from penalizaciones where envio_id = e2) <> n + 1 then raise exception 'FALLO 332 · la devolución parcial no crea exactamente una penalización'; end if;
  if (select estado from envios where id = e2) <> 'cancelado' then raise exception 'FALLO 332 · devolver cambia el estado del envío'; end if;
  -- Lo cobrado no se toca a mano desde el panel (aunque el equipo pueda editar la penalización).
  set local role authenticated;
  update penalizaciones set cobrada_importe = 1, cobrada_pago_ref = 'pi_falso', descripcion = 'Cancelación fuera de plazo (editada)' where id = p.id;
  reset role;
  select * into p from penalizaciones where id = p.id;
  if p.cobrada_importe <> 363 or p.cobrada_pago_ref <> 'pi_332b' or p.descripcion <> 'Cancelación fuera de plazo (editada)' then
    raise exception 'FALLO 332 · lo cobrado de una penalización se puede cambiar a mano: %', p; end if;
  if not exists (select 1 from emails_enviados where clave = 'pago_devuelto:' || d and position('847,00' in cuerpo_html) > 0 and position('1.210,00' in cuerpo_html) > 0) then
    raise exception 'FALLO 332 · el email de la devolución parcial no dice lo devuelto y lo pagado'; end if;

  update clientes set riesgo_manual_euros = v_man, riesgo_cesce_euros = v_ces where id = cli;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 332 · devolución de un pago con tarjeta: solo el Admin Master, importe acotado, total y parcial (con su penalización ya cobrada), fallo de Stripe sin cambios, hito y email';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 333 · TRANSFERENCIAS AVISADAS, ARRIBA (usuario, 2026-11-23): en «Pendientes de pago» y en
--       «Todas» salen primero los envíos con la transferencia avisada (el que más espera, antes);
--       el resto, como siempre, lo más nuevo arriba. Pagado o cancelado, deja de ir arriba.
do $$
declare cli uuid; a uuid; b uuid; c uuid; lun date; ids uuid[]; base uuid[];
begin
  select cliente_id into cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  lun := current_date + ((8 - extract(isodow from current_date)::int) % 7) + 7;
  for i in 1..3 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
      values (cli, 13.30, 20, 900, 700, lun, lun + 1) returning id into c;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (c, 1, 'carga', '41001', 'Sevilla', 'ES');
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (c, 2, 'descarga', '28821', 'Coslada', 'ES');
    update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now() where id = c;
    update envios set estado = 'programado' where id = c;
    base := array_append(base, c);
  end loop;
  -- Sin avisos: el orden de siempre (lo más nuevo arriba; nacidos a la vez, por su id).
  select array_agg(id) into ids from (select id from envios_pagina('sin-pagar', 1, 200, cli) where id = any(base)) x;
  if ids is distinct from (select array_agg(id order by creado_en desc, id) from envios where id = any(base)) then
    raise exception 'FALLO 333 · sin avisos el orden no es por creación: %', ids; end if;
  -- Para que el aviso cambie el orden de verdad: «a» es el ÚLTIMO de la lista, «b» el del medio.
  a := ids[3]; b := ids[2]; c := ids[1];
  -- Avisan a (el más antiguo) y luego b: a va primero (lleva más esperando), después b, después c.
  update envios set pago_avisado_en = now() - interval '2 hours' where id = a;
  update envios set pago_avisado_en = now() - interval '1 hour' where id = b;
  select array_agg(id) into ids from (select id from envios_pagina('sin-pagar', 1, 200, cli) where id in (a, b, c)) x;
  if ids is distinct from array[a, b, c] then raise exception 'FALLO 333 · las transferencias avisadas no van arriba en «Pendientes de pago»: %', ids; end if;
  select array_agg(id) into ids from (select id from envios_pagina('todas', 1, 200, cli) where id in (a, b, c)) x;
  if ids is distinct from array[a, b, c] then raise exception 'FALLO 333 · las transferencias avisadas no van arriba en «Todas»: %', ids; end if;
  if (select id from envios_pagina('sin-pagar', 1, 1, cli)) is distinct from a then raise exception 'FALLO 333 · la avisada que más espera no es la primera de la página'; end if;
  -- Cancelado a, deja de ir arriba en «Todas» (ya no espera nada de Dynamo).
  update envios set estado = 'cancelado' where id = a;
  select array_agg(id) into ids from (select id from envios_pagina('todas', 1, 200, cli) where id in (a, b, c)) x;
  if ids is distinct from array[b, c, a] then raise exception 'FALLO 333 · un envío cancelado sigue arriba por su aviso: %', ids; end if;
  update envios set estado = 'cancelado' where id in (b, c);
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 333 · lista de envíos: las transferencias avisadas van arriba (la que más espera, primero) en «Pendientes de pago» y «Todas»';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 334 · GOOGLE MAPS (usuario, 2026-11-24): el sitio guarda si su horario está sin verificar (por
--       defecto no), y el aviso de «límite diario alcanzado» llega a Dynamo una sola vez por día
--       y por API, con el texto que pone la base de datos; sin sesión no se puede lanzar.
do $$
declare v_s uuid; v_u uuid; ok boolean; n int; m int; r record;
begin
  if (select column_default from information_schema.columns where table_schema = 'public' and table_name = 'sitios' and column_name = 'horario_sin_verificar') <> 'false' then
    raise exception 'FALLO 334 · un sitio nace con el horario sin verificar'; end if;
  -- Sin sesión (anónimo): no se puede.
  perform set_config('request.jwt.claim.sub', '', false);
  set local role anon;
  ok := false;
  begin perform aviso_limite_api('sitios'); exception when insufficient_privilege then ok := true; end;
  reset role;
  if not ok then raise exception 'FALLO 334 · un anónimo puede lanzar el aviso de límite'; end if;
  -- Un cliente (es quien está buscando cuando Google se queda sin consultas).
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  select count(*) into n from avisos where tipo = 'api_limite';
  if aviso_limite_api('cualquier cosa') then raise exception 'FALLO 334 · avisa de una API que no existe'; end if;
  if not aviso_limite_api('sitios') then raise exception 'FALLO 334 · no avisa la primera vez'; end if;
  if aviso_limite_api('sitios') then raise exception 'FALLO 334 · avisa dos veces el mismo día por la misma API'; end if;
  if not aviso_limite_api('kilometros') then raise exception 'FALLO 334 · no avisa de otra API el mismo día'; end if;
  select count(*) into m from avisos where tipo = 'api_limite';
  if m <> n + 2 then raise exception 'FALLO 334 · avisos en la campana: % (esperados %)', m, n + 2; end if;
  select * into r from avisos where tipo = 'api_limite' and titulo like '%buscador de sitios%' order by creado_en desc limit 1;
  if r.para <> 'dynamo' or r.cliente_id is not null then raise exception 'FALLO 334 · el aviso no es solo para Dynamo: %', r; end if;
  select * into r from emails_enviados where tipo = 'api_limite' and clave like 'api_limite:google:sitios:%';
  if r.id is null or r.destinatario <> email_dynamo() or position('límite diario' in r.asunto) = 0 then
    raise exception 'FALLO 334 · no se encola el email a Dynamo: %', r; end if;
  -- El enlace de Maps: un cliente lo guarda al CREAR (si es de Google Maps) y no lo cambia después.
  -- (Con un usuario de cliente recién creado: los de otras pruebas pueden haber quedado suspendidos.)
  perform set_config('request.jwt.claim.sub', '', false);
  insert into auth.users (email) values ('sitios334@cliente.prueba') returning id into v_u;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = current_setting('prueba.cliente')::uuid where id = v_u;
  perform set_config('request.jwt.claim.sub', v_u::text, false);
  set local role authenticated;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, url_google_maps)
    values ((select cliente_id from usuarios where id = auth.uid()), 'Sitio Google 334', 'C/ Uno, 1', '41001', 'Sevilla', 'Sevilla', 'https://maps.google.com/?cid=334')
    returning id into v_s;
  if (select url_google_maps from sitios where id = v_s) is distinct from 'https://maps.google.com/?cid=334' then
    raise exception 'FALLO 334 · al crear un sitio no se guarda el enlace de Google Maps'; end if;
  update sitios set url_google_maps = 'https://maps.google.com/?cid=otro' where id = v_s;
  if (select url_google_maps from sitios where id = v_s) <> 'https://maps.google.com/?cid=334' then
    raise exception 'FALLO 334 · un cliente cambia el enlace del mapa de un sitio ya creado'; end if;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, url_google_maps)
    values ((select cliente_id from usuarios where id = auth.uid()), 'Sitio no Google 334', 'C/ Dos, 2', '41001', 'Sevilla', 'Sevilla', 'https://ejemplo.malo/mapa')
    returning id into v_s;
  if (select url_google_maps from sitios where id = v_s) is not null then
    raise exception 'FALLO 334 · un cliente guarda un enlace que no es de Google Maps'; end if;
  reset role;
  update sitios set borrado = true where nombre_empresa in ('Sitio Google 334', 'Sitio no Google 334');
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 334 · Google Maps: horario sin verificar (por defecto no), aviso de límite diario a Dynamo una vez por día y API, y enlace de Maps al crear el sitio';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 335 · RUTAS DE GOOGLE (usuario, 2026-11-24): la distancia guardada entre dos sitios o dos códigos
--       postales admite la línea de la ruta, y los clientes siguen sin leer esas tablas (las lee
--       y las escribe el servidor).
do $$
declare n int; ok boolean;
begin
  select count(*) into n from information_schema.columns
   where table_schema = 'public' and table_name in ('distancias_sitios', 'distancias_cp') and column_name = 'linea';
  if n <> 2 then raise exception 'FALLO 335 · falta la columna de la línea de la ruta'; end if;
  perform guardar_km_cp('ES', '41001', 'ES', '28821', 531.23, 316, 'google_routes');
  update distancias_cp set linea = 'abc' where codigo_postal_origen = '41001' and codigo_postal_destino = '28821' and pais_codigo_iso_origen = 'ES';
  if km_cp('ES', '41001', 'ES', '28821') <> 531.23 then raise exception 'FALLO 335 · no se lee la distancia guardada'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  set local role authenticated;
  select count(*) into n from distancias_cp;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);
  if n <> 0 then raise exception 'FALLO 335 · un cliente lee las distancias guardadas (%)', n; end if;
  raise notice 'OK 335 · rutas de Google: la distancia guardada admite su línea y los clientes no leen esas tablas';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 336 · RUTAS PINTADAS POR CARRETERA (usuario, 2026-11-24): mapa_trazados da, de los envíos que
--       ve quien pregunta, el trazado guardado de cada tramo: el de sus dos sitios (con las
--       coordenadas de ahora: si un sitio se muda, deja de valer) y, si no, el de sus códigos
--       postales. De un envío ajeno no da nada; sin sesión no se puede llamar.
do $$
declare e uuid := current_setting('prueba.e323')::uuid; r jsonb; t jsonb; s1 uuid; s2 uuid; f uuid;
begin
  if has_function_privilege('anon', 'public.mapa_trazados(uuid[])', 'execute') then raise exception 'FALLO 336 · los trazados se piden sin sesión'; end if;
  perform guardar_km_cp('ES', '41001', 'ES', '28323', 530, 320, 'google_routes');
  -- La 2.ª parada no tiene coordenadas propias: se sitúa por el centro de su código postal.
  perform set_config('request.jwt.claim.role', 'service_role', true);
  perform guardar_geo_cp('ES', '28323', 40.4250, -3.6830);
  perform set_config('request.jwt.claim.role', '', true);
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  r := mapa_trazados(array[e]);
  t := r -> 0;
  if jsonb_array_length(r) <> 1 or (t ->> 'desde')::int <> 1 or (t ->> 'hasta')::int <> 2 or t ->> 'linea' is not null
     or t ->> 'fila_cp' is null or t ->> 'cp_a' <> '41001' or t ->> 'cp_b' <> '28323' or (t -> 'b' ->> 0)::numeric <> 40.425 then
    raise exception 'FALLO 336 · tramo sin trazado mal descrito: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update distancias_cp set linea = 'trazado336' where pais_codigo_iso_origen = 'ES' and codigo_postal_origen = '41001' and codigo_postal_destino = '28323';
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  if mapa_trazados(array[e]) -> 0 ->> 'linea' is distinct from 'trazado336' then raise exception 'FALLO 336 · no sale el trazado guardado por código postal'; end if;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  if jsonb_array_length(mapa_trazados(array[e])) <> 0 then raise exception 'FALLO 336 · otro cliente ve los trazados de un envío ajeno'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  -- Entre dos sitios: manda su trazado; si uno se muda (cambian sus coordenadas), deja de valer.
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values (current_setting('prueba.cliente')::uuid, 'Sitio A 336', 'C/ Uno, 1', '41001', 'Sevilla', 'Sevilla', 37.39, -5.98) returning id into s1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values (current_setting('prueba.cliente')::uuid, 'Sitio B 336', 'C/ Dos, 2', '28323', 'Madrid', 'Madrid', 40.42, -3.68) returning id into s2;
  update envio_paradas set sitio_id = s1 where envio_id = e and orden = 1;
  update envio_paradas set sitio_id = s2 where envio_id = e and orden = 2;
  f := guardar_km_sitios(s1, s2, 531, 321, 'google_routes');
  update distancias_sitios set linea = 'sitios336' where id = f;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  t := mapa_trazados(array[e]) -> 0;
  if t ->> 'linea' is distinct from 'sitios336' or t ->> 'fila_sitios' is distinct from f::text then raise exception 'FALLO 336 · no sale el trazado entre los dos sitios: %', t; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update sitios set lat = 37.40 where id = s1;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  t := mapa_trazados(array[e]) -> 0;
  if t ->> 'linea' is distinct from 'trazado336' or t ->> 'fila_sitios' is not null then raise exception 'FALLO 336 · un sitio que se muda conserva el trazado viejo: %', t; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update envio_paradas set sitio_id = null where envio_id = e;
  update sitios set borrado = true where id in (s1, s2);
  raise notice 'OK 336 · rutas pintadas: trazado guardado de cada tramo (sitios o códigos postales) solo para quien ve el envío';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 337 · UBICACIÓN DE CADA SITIO (usuario, 2026-11-24): con coordenadas y sin enlace propio, el
--       sitio lleva un enlace de Google Maps a sus coordenadas; el de Google (ficha del negocio)
--       se respeta; si cambia la dirección sin coordenadas nuevas, se vacían (y el enlace
--       automático con ellas); y un cliente no cambia las coordenadas de sus sitios.
do $$
declare s1 uuid; s2 uuid; s3 uuid; v_u uuid; r record;
begin
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values (current_setting('prueba.cliente')::uuid, 'Sitio 337 A', 'C/ Uno, 1', '41001', 'Sevilla', 'Sevilla', 37.3891, -5.9845) returning id into s1;
  if (select url_google_maps from sitios where id = s1) is distinct from 'https://www.google.com/maps/search/?api=1&query=37.3891,-5.9845' then
    raise exception 'FALLO 337 · un sitio con coordenadas no lleva su enlace de ubicación: %', (select url_google_maps from sitios where id = s1); end if;
  update sitios set lat = 37.4, lon = -5.99 where id = s1;
  if (select url_google_maps from sitios where id = s1) is distinct from 'https://www.google.com/maps/search/?api=1&query=37.4,-5.99' then
    raise exception 'FALLO 337 · el enlace no sigue a las coordenadas nuevas'; end if;
  update sitios set direccion = 'C/ Otra, 9' where id = s1;
  select lat, lon, url_google_maps into r from sitios where id = s1;
  if r.lat is not null or r.lon is not null or r.url_google_maps is not null then
    raise exception 'FALLO 337 · al cambiar la dirección siguen las coordenadas viejas: %', r; end if;
  update sitios set direccion = 'C/ Tres, 3', lat = 37.41, lon = -5.98 where id = s1;
  if (select url_google_maps from sitios where id = s1) is distinct from 'https://www.google.com/maps/search/?api=1&query=37.41,-5.98' then
    raise exception 'FALLO 337 · dirección y coordenadas nuevas a la vez no dejan su enlace'; end if;
  -- El enlace que trae Google (la ficha del negocio) se respeta.
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon, url_google_maps)
    values (current_setting('prueba.cliente')::uuid, 'Sitio 337 B', 'C/ Dos, 2', '41001', 'Sevilla', 'Sevilla', 37.39, -5.98, 'https://maps.google.com/?cid=337') returning id into s2;
  update sitios set lat = 37.5 where id = s2;
  if (select url_google_maps from sitios where id = s2) <> 'https://maps.google.com/?cid=337' then
    raise exception 'FALLO 337 · se pisa el enlace de Google del sitio'; end if;
  -- Un cliente no pone ni cambia coordenadas.
  insert into auth.users (email) values ('sitios337@cliente.prueba') returning id into v_u;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = current_setting('prueba.cliente')::uuid where id = v_u;
  perform set_config('request.jwt.claim.sub', v_u::text, false);
  set local role authenticated;
  update sitios set lat = 1, lon = 1 where id = s1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values ((select cliente_id from usuarios where id = auth.uid()), 'Sitio 337 C', 'C/ Cuatro, 4', '41001', 'Sevilla', 'Sevilla', 1, 1) returning id into s3;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);
  if (select lat from sitios where id = s1) <> 37.41 then raise exception 'FALLO 337 · un cliente cambia las coordenadas de un sitio'; end if;
  select lat, lon, url_google_maps into r from sitios where id = s3;
  if r.lat is not null or r.url_google_maps is not null then raise exception 'FALLO 337 · un cliente crea un sitio con coordenadas puestas por él: %', r; end if;
  update sitios set borrado = true where id in (s1, s2, s3);
  raise notice 'OK 337 · ubicación del sitio: enlace de Google Maps a sus coordenadas, que solo ponen el servidor o Dynamo';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 338 · LA IDA VALE PARA LA VUELTA (usuario, 2026-11-24): los km guardados entre dos códigos
--       postales o dos sitios sirven en los dos sentidos (manda el sentido exacto si está), y
--       el trazado del sentido contrario sale marcado como invertido.
do $$
declare e uuid := current_setting('prueba.e323')::uuid; t jsonb; s1 uuid; s2 uuid;
begin
  perform guardar_km_cp('ES', '41011', 'ES', '28340', 512.40, 300, 'google_routes');
  if km_cp('ES', '28340', 'ES', '41011', interval '100 years') is distinct from 512.40 then raise exception 'FALLO 338 · la ida entre códigos postales no vale para la vuelta'; end if;
  perform guardar_km_cp('ES', '28340', 'ES', '41011', 514.10, 301, 'google_routes');
  if km_cp('ES', '28340', 'ES', '41011', interval '100 years') <> 514.10 or km_cp('ES', '41011', 'ES', '28340', interval '100 years') <> 512.40 then
    raise exception 'FALLO 338 · con los dos sentidos guardados no manda el pedido'; end if;
  if km_cp('ES', '41011', 'ES', '08200', interval '100 years') is not null then raise exception 'FALLO 338 · salen km de una pareja que no está guardada'; end if;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values (current_setting('prueba.cliente')::uuid, 'Sitio A 338', 'C/ Uno, 1', '41011', 'Sevilla', 'Sevilla', 37.37, -6.0) returning id into s1;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, lat, lon)
    values (current_setting('prueba.cliente')::uuid, 'Sitio B 338', 'C/ Dos, 2', '28340', 'Valdemoro', 'Madrid', 40.19, -3.67) returning id into s2;
  perform guardar_km_sitios(s1, s2, 520, 305, 'google_routes');
  if km_sitios(s2, s1, interval '100 years') is distinct from 520 then raise exception 'FALLO 338 · la ida entre sitios no vale para la vuelta'; end if;
  update sitios set lat = 37.38 where id = s1;
  if km_sitios(s2, s1, interval '100 years') is not null then raise exception 'FALLO 338 · la vuelta vale aunque el sitio se haya movido'; end if;
  -- El trazado del sentido contrario: sale, marcado para pintarlo al revés.
  delete from distancias_cp where codigo_postal_origen in ('41001', '28323') and codigo_postal_destino in ('41001', '28323');
  perform guardar_km_cp('ES', '28323', 'ES', '41001', 530, 320, 'google_routes');
  update distancias_cp set linea = 'vuelta338' where codigo_postal_origen = '28323' and codigo_postal_destino = '41001';
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  t := mapa_trazados(array[e]) -> 0;
  perform set_config('request.jwt.claim.sub', '', false);
  if t ->> 'linea' is distinct from 'vuelta338' or (t ->> 'invertida')::boolean is not true then raise exception 'FALLO 338 · el trazado de la vuelta no sale invertido: %', t; end if;
  perform guardar_km_cp('ES', '41001', 'ES', '28323', 530, 320, 'google_routes');
  update distancias_cp set linea = 'ida338' where codigo_postal_origen = '41001' and codigo_postal_destino = '28323';
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  t := mapa_trazados(array[e]) -> 0;
  perform set_config('request.jwt.claim.sub', '', false);
  if t ->> 'linea' is distinct from 'ida338' or (t ->> 'invertida')::boolean then raise exception 'FALLO 338 · con el trazado de ida guardado no manda la ida: %', t; end if;
  update sitios set borrado = true where id in (s1, s2);
  raise notice 'OK 338 · rutas guardadas: la ida vale para la vuelta (km y trazado), y manda el sentido exacto si está';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 339 · «Asignando transportista» se ve a 12 h de poder cargar (usuario, 2026-11-24; antes 36).
do $$
begin
  if (parametro('seguimiento_horas_asignando') #>> '{}')::numeric <> 12 then
    raise exception 'FALLO 339 · «Asignando transportista» debe salir a 12 h y está a % h', parametro('seguimiento_horas_asignando') #>> '{}';
  end if;
  raise notice 'OK 339 · «Asignando transportista» se ve a 12 h de la primera posibilidad de cargar';
end $$;

-- 340 · Cuadro de mando: la evolución lleva los clientes distintos con envío REALIZADO de cada mes.
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r jsonb; hoy date := (now() at time zone 'Europe/Madrid')::date; mal int; total int; begin
  r := cuadro_mando(hoy - 400, hoy + 60);
  if exists (select 1 from jsonb_array_elements(r -> 'serie') x where x -> 'clientes' is null) then raise exception 'FALLO 340 · la serie no trae «clientes»'; end if;
  select count(*) filter (where (x ->> 'clientes')::int is distinct from
           (select count(distinct e.cliente_id) from envios e
             where not coalesce(e.es_manual, false) and e.estado in ('hacia_la_carga', 'cargando', 'en_ruta', 'entregado')
               and e.fecha_efectiva between hoy - 400 and hoy + 60
               and date_trunc('month', e.fecha_efectiva)::date = (x ->> 'k')::date)),
         coalesce(sum((x ->> 'clientes')::int), 0)
    into mal, total from jsonb_array_elements(r -> 'serie') x;
  if mal > 0 then raise exception 'FALLO 340 · % meses con un número de clientes que no cuadra con los envíos realizados', mal; end if;
  if exists (select 1 from jsonb_array_elements(r -> 'serie') x where (x ->> 'clientes')::int > (x ->> 'realizados')::int) then raise exception 'FALLO 340 · más clientes que envíos realizados en un mes'; end if;
  raise notice 'OK 340 · cuadro de mando: clientes distintos con envío realizado por mes (% en el periodo)', total;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- 341 · Previsión de pago por adelantado ANTES de crear (usuario, 2026-11-24): sí/no por envío,
-- con la misma cuenta que al crearlo, sin cifras; cada cliente solo pregunta por sí mismo.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare cli uuid; uc uuid; a uuid; r boolean[]; antes jsonb; n numeric;
  hoy date := (now() at time zone 'Europe/Madrid')::date; lun date;
begin
  select valor into antes from parametros where clave = 'pago_previo_activo';
  update parametros set valor = 'true'::jsonb where clave = 'pago_previo_activo';
  n := parametro_num('pago_previo_primeros_envios', 1);
  insert into clientes (razon_social, cif) values ('Cliente Previsión 341 SL', 'B34100341') returning id into cli;
  insert into auth.users (email) values ('prevision341@cliente.prueba') returning id into uc;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = cli where id = uc;
  update clientes set riesgo_cesce_euros = 5000, riesgo_manual_euros = 1000, exento_pago_previo_primer_envio = true where id = cli;
  if has_function_privilege('anon', 'pago_previo_previsto(numeric[], uuid)', 'execute') then raise exception 'FALLO 341 · un visitante sin sesión puede preguntar la previsión de pago'; end if;

  perform set_config('request.jwt.claim.sub', uc::text, false);
  -- 1.000 € de crédito: 600 (726 con IVA) cabe; 400 (484) ya no; 200 (242) sí, porque el pendiente no gasta.
  r := pago_previo_previsto(array[600, 400, 200]::numeric[]);
  if r is distinct from array[false, true, false] then raise exception 'FALLO 341 · con crédito, la previsión de 600/400/200 sale %', r; end if;
  if pago_previo_previsto('{}'::numeric[]) is distinct from '{}'::boolean[] then raise exception 'FALLO 341 · sin envíos no devuelve una lista vacía'; end if;
  -- Pedir por OTRO cliente no sirve: el cliente siempre pregunta por sí mismo.
  if pago_previo_previsto(array[600, 400]::numeric[], current_setting('prueba.cliente')::uuid) is distinct from array[false, true] then
    raise exception 'FALLO 341 · un cliente puede preguntar la previsión de pago de otro cliente'; end if;
  perform set_config('request.jwt.claim.sub', '', false);

  -- Cuadra con lo que pasa de verdad al crear: con 600 € ya a crédito, 400 no cabe y 200 sí.
  lun := hoy + (8 - extract(isodow from hoy)::int) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, fecha_carga_desde) values (cli, 6, 5, 600, lun) returning id into a;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (a, 1, 'carga', '41001', 'Sevilla', 'ES'), (a, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado = 'programado' where id = a;
  if (select estado_pago_previo from envios where id = a) <> 'no_requerido' then raise exception 'FALLO 341 · el envío de 600 € no ha ido a crédito'; end if;
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if pago_previo_previsto(array[400]::numeric[]) is distinct from array[true] or pago_previo_previsto(array[200]::numeric[]) is distinct from array[false] then
    raise exception 'FALLO 341 · con 600 € ya usados, la previsión de 400 y de 200 no cuadra con el crédito que queda'; end if;
  perform set_config('request.jwt.claim.sub', '', false);

  -- Regla del crédito apagada: con crédito concedido nunca se prevé pago por pasarse.
  update parametros set valor = 'false'::jsonb where clave = 'credito_limite_exige_pago';
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if pago_previo_previsto(array[5000]::numeric[]) is distinct from array[false] then raise exception 'FALLO 341 · con la regla del crédito apagada sigue previendo pago'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update parametros set valor = 'true'::jsonb where clave = 'credito_limite_exige_pago';

  -- Primeros envíos (sin exención): mientras no haya envíos hechos, todos se pagan antes.
  update envios set estado = 'cancelado' where id = a;
  update clientes set exento_pago_previo_primer_envio = false where id = cli;
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if n >= 1 and pago_previo_previsto(array[100, 100]::numeric[]) is distinct from array[true, true] then
    raise exception 'FALLO 341 · en los primeros envíos del cliente no se prevé pago por adelantado'; end if;
  perform set_config('request.jwt.claim.sub', '', false);

  -- Sin crédito: todos.
  update clientes set riesgo_manual_euros = 0, exento_pago_previo_primer_envio = true where id = cli;
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if pago_previo_previsto(array[100, 50]::numeric[]) is distinct from array[true, true] then raise exception 'FALLO 341 · sin crédito no se prevé pago por adelantado'; end if;
  -- Pago por adelantado apagado: ninguno.
  perform set_config('request.jwt.claim.sub', '', false);
  update parametros set valor = 'false'::jsonb where clave = 'pago_previo_activo';
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if pago_previo_previsto(array[100]::numeric[]) is distinct from array[false] then raise exception 'FALLO 341 · con el pago por adelantado apagado se prevé pago'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update parametros set valor = antes where clave = 'pago_previo_activo';
  raise notice 'OK 341 · previsión de pago por adelantado antes de crear: crédito que no alcanza, primeros envíos, sin crédito y apagado';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 342 · El plazo para pagar un envío pendiente de pago es de 60 minutos (usuario, 2026-11-24; antes 24 h).
do $$ declare t timestamptz := '2026-11-24 10:00:00+01'; begin
  if (parametro('pago_previo_horas') #>> '{}')::numeric <> 1 then
    raise exception 'FALLO 342 · el plazo para pagar debe ser de 1 hora y está en % h', parametro('pago_previo_horas') #>> '{}';
  end if;
  if pago_limite(t) <> t + interval '60 minutes' then raise exception 'FALLO 342 · el límite de pago no cae 60 minutos después: %', pago_limite(t); end if;
  raise notice 'OK 342 · plazo para pagar: 60 minutos desde que el envío queda pendiente de pago';
end $$;

-- 343 · Anulación por falta de pago: margen de 5 minutos y espera al enlace de pago abierto
-- (usuario, 2026-11-24): nadie paga un envío ya anulado.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare c uuid; e uuid; antes jsonb; mal boolean := false; h numeric := parametro_num('pago_previo_horas', 24); begin
  select valor into antes from parametros where clave = 'pago_previo_activo';
  update parametros set valor = 'true'::jsonb where clave = 'pago_previo_activo';
  if parametro_num('pago_previo_gracia_minutos', -1) <> 5 then raise exception 'FALLO 343 · el margen tras el plazo para pagar no es de 5 minutos'; end if;
  if has_function_privilege('authenticated', 'pago_enlace_stripe(uuid, timestamptz)', 'execute')
     or has_function_privilege('anon', 'pago_enlace_stripe(uuid, timestamptz)', 'execute') then
    raise exception 'FALLO 343 · un usuario puede apuntar la caducidad de un enlace de pago (solo el servidor)'; end if;
  insert into clientes (razon_social, cif) values ('Paga Justo SL', 'B34300343') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (c, 13.30, 20, 1000, 800) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  if (select estado_pago_previo from envios where id = e) <> 'pendiente' then raise exception 'FALLO 343 · el envío de prueba no nace pendiente de pago'; end if;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  -- Plazo vencido hace 3 minutos: dentro del margen, no se anula.
  update envios set pago_pendiente_en = now() - make_interval(mins => round(h * 60)::int + 3) where id = e;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = e) <> 'programado' then raise exception 'FALLO 343 · se anula dentro del margen de 5 minutos'; end if;
  -- Vencido hace 7 minutos, pero con un enlace de pago abierto 20 minutos más: espera.
  update envios set pago_pendiente_en = now() - make_interval(mins => round(h * 60)::int + 7) where id = e;
  perform pago_enlace_stripe(e, now() + interval '20 minutes');
  perform pago_enlace_stripe(e, now() + interval '5 minutes');   -- un enlace más corto no acorta lo apuntado
  if (select stripe_enlace_caduca_en from envios where id = e) < now() + interval '19 minutes' then raise exception 'FALLO 343 · un enlace más corto acorta la espera del envío'; end if;
  begin perform pago_enlace_stripe(e, now() + interval '3 days'); mal := true; exception when others then null; end;
  if mal then raise exception 'FALLO 343 · se admite una caducidad de enlace de varios días'; end if;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = e) <> 'programado' then raise exception 'FALLO 343 · se anula un envío con un enlace de pago todavía abierto'; end if;
  -- El enlace caducó hace 2 minutos: ahora sí se anula.
  update envios set stripe_enlace_caduca_en = now() - interval '2 minutes' where id = e;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = e) <> 'cancelado' then raise exception 'FALLO 343 · con el enlace de pago ya caducado el envío no se anula'; end if;
  perform set_config('request.jwt.claim.role', '', true);
  update parametros set valor = antes where clave = 'pago_previo_activo';
  raise notice 'OK 343 · anulación por falta de pago: margen de 5 minutos y espera al enlace de pago abierto';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 344 · El cliente sabe si su envío se anuló por no pagar dentro del plazo (usuario, 2026-11-24):
-- sí/no solo para SU envío; un envío cancelado por otra causa, o de otro cliente, dice que no.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare c uuid; uc uuid; e uuid; e2 uuid; antes jsonb; h numeric := parametro_num('pago_previo_horas', 24); begin
  select valor into antes from parametros where clave = 'pago_previo_activo';
  update parametros set valor = 'true'::jsonb where clave = 'pago_previo_activo';
  if has_function_privilege('anon', 'envio_anulado_sin_pago(uuid)', 'execute') then raise exception 'FALLO 344 · un visitante sin sesión puede preguntar por qué se canceló un envío'; end if;
  insert into clientes (razon_social, cif) values ('No Paga 344 SL', 'B34400344') returning id into c;
  insert into auth.users (email) values ('nopaga344@cliente.prueba') returning id into uc;
  update usuarios set rol = 'cliente', estado = 'activa', cliente_id = c where id = uc;
  for i in 1..2 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (c, 13.30, 20, 1000, 800) returning id into e2;
    insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e2, 1, 'carga', '41001', 'Sevilla', 'ES'), (e2, 2, 'descarga', '28001', 'Madrid', 'ES');
    update envios set estado = 'programado' where id = e2;
    if i = 1 then e := e2; end if;
  end loop;
  -- e: lo anula el sistema por falta de pago. e2: se cancela por otra causa.
  perform set_config('request.jwt.claim.role', 'service_role', true);
  update envios set pago_pendiente_en = now() - make_interval(mins => round(h * 60)::int + 120) where id = e;
  perform caducar_pagos_pendientes();
  update envios set estado = 'cancelado' where id = e2;
  perform set_config('request.jwt.claim.role', '', true);
  if (select estado from envios where id = e) <> 'cancelado' then raise exception 'FALLO 344 · el envío de prueba no se ha anulado por falta de pago'; end if;
  -- Su dueño: sí en el anulado sin pago, no en el otro.
  perform set_config('request.jwt.claim.sub', uc::text, false);
  if envio_anulado_sin_pago(e) is not true then raise exception 'FALLO 344 · el cliente no ve que su envío se anuló por falta de pago'; end if;
  if envio_anulado_sin_pago(e2) is not false then raise exception 'FALLO 344 · un envío cancelado por otra causa sale como anulado por falta de pago'; end if;
  -- Otro cliente: no.
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
  if envio_anulado_sin_pago(e) is not false then raise exception 'FALLO 344 · un cliente ve por qué se canceló el envío de otro'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  update parametros set valor = antes where clave = 'pago_previo_activo';
  raise notice 'OK 344 · el cliente ve si su envío se anuló por no pagar dentro del plazo, y solo el suyo';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 345 · CORTE DEL ENLACE DE PAGO AL ACABAR EL PLAZO (usuario, 2026-11-24): el servidor apunta
-- los enlaces de Stripe que abre; pasado el plazo y su margen se sabe cuáles hay que cerrar
-- y, una vez cerrados, el envío se anula sin esperar a que el enlace caduque solo.
do $$ declare c uuid; e uuid; antes jsonb; mal boolean := false; f text; h numeric := parametro_num('pago_previo_horas', 24); begin
  select valor into antes from parametros where clave = 'pago_previo_activo';
  update parametros set valor = 'true'::jsonb where clave = 'pago_previo_activo';
  foreach f in array array['pago_sesion_stripe(uuid, text)', 'pago_sesiones_por_cerrar(uuid)', 'pago_enlace_cerrado(uuid)'] loop
    if has_function_privilege('authenticated', f, 'execute') or has_function_privilege('anon', f, 'execute') then
      raise exception 'FALLO 345 · un usuario puede llamar a % (solo el servidor)', f; end if;
  end loop;
  insert into clientes (razon_social, cif) values ('Corta Enlace SL', 'B34500345') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (c, 13.30, 20, 1000, 800) returning id into e;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES'), (e, 2, 'descarga', '28001', 'Madrid', 'ES');
  update envios set estado = 'programado' where id = e;
  if (select estado_pago_previo from envios where id = e) <> 'pendiente' then raise exception 'FALLO 345 · el envío de prueba no nace pendiente de pago'; end if;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  begin perform pago_sesion_stripe(e, 'cualquier cosa; drop'); mal := true; exception when others then null; end;
  if mal then raise exception 'FALLO 345 · se apunta un identificador de enlace que no es de Stripe'; end if;
  perform pago_sesion_stripe(e, 'cs_test_aaaaa1');
  perform pago_sesion_stripe(e, 'cs_test_bbbbb2');
  perform pago_sesion_stripe(e, 'cs_test_aaaaa1');   -- repetido: no se duplica, pasa a ser el último
  if (select stripe_sesiones from envios where id = e) <> array['cs_test_bbbbb2', 'cs_test_aaaaa1'] then
    raise exception 'FALLO 345 · los enlaces de pago abiertos no se apuntan bien: %', (select stripe_sesiones from envios where id = e); end if;
  -- Dentro del plazo, con el enlace abierto: no toca cortar nada.
  perform pago_enlace_stripe(e, now() + interval '30 minutes');
  if pago_sesiones_por_cerrar(e) is not null then raise exception 'FALLO 345 · se manda cortar el enlace de un envío que aún está en plazo'; end if;
  -- Dentro del margen (plazo vencido hace 3 minutos): tampoco.
  update envios set pago_pendiente_en = now() - make_interval(mins => round(h * 60)::int + 3) where id = e;
  if pago_sesiones_por_cerrar(e) is not null then raise exception 'FALLO 345 · se manda cortar el enlace dentro del margen de 5 minutos'; end if;
  -- Plazo y margen vencidos, enlace todavía abierto: toca cortarlo; mientras, el envío espera.
  update envios set pago_pendiente_en = now() - make_interval(mins => round(h * 60)::int + 7) where id = e;
  if pago_sesiones_por_cerrar(e) is distinct from array['cs_test_bbbbb2', 'cs_test_aaaaa1'] then
    raise exception 'FALLO 345 · pasado el plazo y su margen no se sabe qué enlaces hay que cerrar'; end if;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = e) <> 'programado' then raise exception 'FALLO 345 · se anula un envío con el enlace de pago aún sin cerrar'; end if;
  -- Stripe confirma el cierre: se vacía lo apuntado y el envío se anula en la misma pasada.
  perform pago_enlace_cerrado(e);
  if cardinality((select stripe_sesiones from envios where id = e)) <> 0 or pago_sesiones_por_cerrar(e) is not null then
    raise exception 'FALLO 345 · cerrado el enlace, siguen apuntados enlaces por cerrar'; end if;
  perform caducar_pagos_pendientes();
  if (select estado from envios where id = e) <> 'cancelado' then raise exception 'FALLO 345 · con el enlace ya cerrado en Stripe el envío no se anula al momento'; end if;
  -- En un envío ya anulado no se apunta nada más.
  perform pago_sesion_stripe(e, 'cs_test_ccccc3');
  if cardinality((select stripe_sesiones from envios where id = e)) <> 0 then raise exception 'FALLO 345 · se apuntan enlaces de pago en un envío anulado'; end if;
  perform set_config('request.jwt.claim.role', '', true);
  update parametros set valor = antes where clave = 'pago_previo_activo';
  raise notice 'OK 345 · corte del enlace de pago: se apuntan los enlaces, se cierran pasado el plazo y el envío se anula al momento';
end $$;

-- 346 · LO QUE DEBE CADA CLIENTE, LEÍDO DE LA FACTURACIÓN (usuario, 2026-11-25): la foto de
-- facturas pendientes de cobro la guarda solo el servidor, se casa por CIF (con o sin «ES»),
-- se sustituye ENTERA en cada lectura y una lectura fallida no la toca.
do $$ declare c1 uuid; c2 uuid; r jsonb; mal boolean := false; f text; d record; hoy date := (now() at time zone 'Europe/Madrid')::date; begin
  foreach f in array array['deuda_guardar_foto(jsonb, uuid, text[])', 'deuda_lectura_fallida(text)'] loop
    if has_function_privilege('authenticated', f, 'execute') or has_function_privilege('anon', f, 'execute') then
      raise exception 'FALLO 346 · un usuario puede llamar a % (solo el servidor)', f; end if;
  end loop;
  if has_function_privilege('anon', 'deuda_clientes(uuid[])', 'execute') or has_function_privilege('anon', 'deuda_estado()', 'execute') then
    raise exception 'FALLO 346 · alguien sin entrar puede ver lo que deben los clientes'; end if;
  foreach f in array array['facturas_pendientes', 'holded_contactos', 'facturas_pendientes_estado'] loop
    if has_table_privilege('authenticated', f, 'insert') or has_table_privilege('authenticated', f, 'delete') or has_table_privilege('anon', f, 'select') then
      raise exception 'FALLO 346 · permisos de más en la tabla %', f; end if;
  end loop;
  if cif_base('es-b.12345678') <> 'B12345678' or cif_base('B12345678') <> 'B12345678' or cif_base('PT123456789') <> 'PT123456789' then
    raise exception 'FALLO 346 · cif_base no deja el CIF listo para comparar'; end if;
  insert into clientes (razon_social, cif) values ('Debe Mucho SL', 'B34600346') returning id into c1;
  insert into clientes (razon_social, cif) values ('Debe Poco SL', 'ESB34600347') returning id into c2;
  perform set_config('request.jwt.claim.role', 'service_role', true);
  -- Foto completa: dos de c1 (una vencida), una de c2 (CIF sin «ES» en la facturación), una de
  -- un contacto que no es cliente, una sin CIF y una que ya no debe nada (no se guarda).
  r := deuda_guardar_foto(jsonb_build_array(
    jsonb_build_object('id', 'h346a', 'numero', 'F1', 'contacto_id', 'k1', 'contacto_nombre', 'Debe Mucho', 'cif', 'ES-B34600346', 'emision', hoy - 40, 'vence', hoy - 10, 'total', 1210, 'pendiente', 1210),
    jsonb_build_object('id', 'h346b', 'numero', 'F2', 'contacto_id', 'k1', 'contacto_nombre', 'Debe Mucho', 'cif', 'ES-B34600346', 'emision', hoy - 5, 'vence', hoy + 25, 'total', 605, 'pendiente', 300.5),
    jsonb_build_object('id', 'h346c', 'numero', 'F3', 'contacto_id', 'k2', 'contacto_nombre', 'Debe Poco', 'cif', 'b34600347', 'emision', hoy - 5, 'vence', hoy, 'total', 121, 'pendiente', 121),
    jsonb_build_object('id', 'h346d', 'numero', 'F4', 'contacto_id', 'k3', 'contacto_nombre', 'No es cliente', 'cif', 'B99999346', 'emision', hoy - 5, 'vence', hoy - 1, 'total', 50, 'pendiente', 50),
    jsonb_build_object('id', 'h346e', 'numero', 'F5', 'contacto_id', 'k4', 'contacto_nombre', 'Sin CIF', 'cif', null, 'emision', hoy - 5, 'vence', null, 'total', 10, 'pendiente', 10),
    jsonb_build_object('id', 'h346f', 'numero', 'F6', 'contacto_id', 'k1', 'contacto_nombre', 'Debe Mucho', 'cif', 'B34600346', 'emision', hoy - 5, 'vence', hoy, 'total', 99, 'pendiente', 0)));
  if (r ->> 'facturas')::int <> 5 or (r ->> 'sin_cliente')::int <> 1 or (r ->> 'sin_cif')::int <> 1 or (r ->> 'pendiente')::numeric <> 1691.50 then
    raise exception 'FALLO 346 · la foto no cuenta bien: %', r; end if;
  select * into d from deuda_clientes(array[c1, c2]) where cliente_id = c1;
  if d.pendiente <> 1510.50 or d.vencido <> 1210 or d.facturas <> 2 or d.vence_primera <> hoy - 10 then raise exception 'FALLO 346 · la deuda del primer cliente no cuadra: %', d; end if;
  select * into d from deuda_clientes(array[c1, c2]) where cliente_id = c2;
  if d.pendiente <> 121 or d.vencido <> 0 then raise exception 'FALLO 346 · no casa un CIF con «ES» con el mismo sin «ES», o da por vencido lo que vence hoy: %', d; end if;
  -- Una lectura fallida no toca la foto.
  perform deuda_lectura_fallida('La facturación no contesta');
  r := deuda_estado();
  if (r ->> 'pendiente')::numeric <> 1691.50 or r ->> 'error' is null or r ->> 'ultima_ok_en' is null then raise exception 'FALLO 346 · una lectura fallida cambia la foto o no queda apuntada: %', r; end if;
  -- Refrescar SOLO un cliente: c1 ya solo debe una; lo de los demás sigue igual.
  r := deuda_guardar_foto(jsonb_build_array(
    jsonb_build_object('id', 'h346b', 'numero', 'F2', 'contacto_id', 'k1', 'cif', 'B34600346', 'emision', hoy - 5, 'vence', hoy + 25, 'total', 605, 'pendiente', 100)), c1, array['k1']);
  if (select count(*) from facturas_pendientes where cliente_id = c1) <> 1 or (select pendiente from facturas_pendientes where ref_externa = 'h346b') <> 100
     or not exists (select 1 from facturas_pendientes where ref_externa = 'h346c') then raise exception 'FALLO 346 · refrescar un cliente toca la deuda de los demás o no sustituye la suya'; end if;
  -- Foto completa nueva: lo que ya no viene (cobrado o anulado) desaparece; el error se limpia.
  r := deuda_guardar_foto(jsonb_build_array(
    jsonb_build_object('id', 'h346c', 'numero', 'F3', 'contacto_id', 'k2', 'cif', 'b34600347', 'emision', hoy - 5, 'vence', hoy, 'total', 121, 'pendiente', 121)));
  if (select count(*) from facturas_pendientes) <> 1 or (deuda_estado() ->> 'error') is not null then raise exception 'FALLO 346 · la foto nueva no sustituye entera a la anterior'; end if;
  if exists (select 1 from deuda_clientes(array[c1])) then raise exception 'FALLO 346 · sigue debiendo un cliente que ya no tiene nada pendiente'; end if;
  begin perform deuda_guardar_foto('{"no": "lista"}'::jsonb); mal := true; exception when others then null; end;
  if mal then raise exception 'FALLO 346 · se acepta una foto que no es una lista'; end if;
  perform deuda_guardar_foto('[]'::jsonb);
  perform set_config('request.jwt.claim.role', '', true);
  raise notice 'OK 346 · deuda real de clientes: la foto se casa por CIF, se sustituye entera y una lectura fallida no la toca';
end $$;

-- 347 · CRÉDITO: CUANDO EL «SIN CRÉDITO» ES DE CESCE SE DICE Y SE DA SU TELÉFONO (usuario,
-- 2026-11-25); cuando el 0 lo pone Dynamo a mano, NO se manda al cliente a CESCE.
do $$ declare v_cli uuid; v_man numeric; v_ces numeric; r record; begin
  select cliente_id into v_cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  select riesgo_manual_euros, riesgo_cesce_euros into v_man, v_ces from clientes where id = v_cli;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_cli_b'), false);
  -- El 0 es de CESCE (sin crédito manual): estado propio.
  update clientes set riesgo_manual_euros = null, riesgo_cesce_euros = 5000 where id = v_cli;
  update clientes set riesgo_cesce_euros = 0 where id = v_cli;
  if mi_cobertura_credito() <> 'nulo_cesce' then raise exception 'FALLO 347 · con el crédito de CESCE a 0 y sin manual no sale «nulo_cesce»: %', mi_cobertura_credito(); end if;
  select * into r from emails_enviados where clave like 'credito_cambio:' || v_cli || ':%' order by clave desc limit 1;
  if r.id is null or r.asunto <> 'Línea de crédito retirada · Dynamo' or position('por cambios en su clasificación' in r.cuerpo_html) = 0
     or position('+34 900 115 000' in r.cuerpo_html) = 0 or position('escríbenos' in r.cuerpo_html) > 0 then
    raise exception 'FALLO 347 · el email de línea retirada por CESCE no lo dice o no da el teléfono de CESCE: %', r.cuerpo_html; end if;
  -- El 0 lo pone Dynamo a mano (CESCE sí le da): ni estado de CESCE ni teléfono de CESCE.
  update clientes set riesgo_cesce_euros = 5000 where id = v_cli;
  update clientes set riesgo_manual_euros = 0 where id = v_cli;
  if mi_cobertura_credito() <> 'nulo' then raise exception 'FALLO 347 · con el crédito manual a 0 no sale «nulo»: %', mi_cobertura_credito(); end if;
  select * into r from emails_enviados where clave like 'credito_cambio:' || v_cli || ':%' order by clave desc limit 1;
  if r.id is null or r.asunto <> 'Línea de crédito retirada · Dynamo' or position('900 115 000' in r.cuerpo_html) > 0 or position('clasificación' in r.cuerpo_html) > 0
     or position('escríbenos' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 347 · al quitar Dynamo el crédito a mano, el email manda al cliente a CESCE: %', r.cuerpo_html; end if;
  -- Sin nada informado: sin clasificar, como siempre.
  update clientes set riesgo_manual_euros = null, riesgo_cesce_euros = null where id = v_cli;
  if mi_cobertura_credito() <> 'sinclasif' then raise exception 'FALLO 347 · sin riesgo informado no sale «sinclasif»'; end if;
  update clientes set riesgo_manual_euros = v_man, riesgo_cesce_euros = v_ces where id = v_cli;
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 347 · crédito: el «sin crédito» de CESCE se distingue del de Dynamo, en el estado y en el email';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 348 · CUADRO DE MANDO: ENVÍOS DIGITALES (usuario, 2026-11-25). Cada envío realizado cae en
-- una de cuatro casillas según quién lo creó (cliente o Dynamo) y cómo llegó el transportista
-- (lo aceptó por su enlace o lo asignó Dynamo); las cuatro suman los realizados.
do $$ declare c uuid; ids uuid[] := '{}'; e uuid; i int; r jsonb; d date := date '2035-03-10';
  u_cli uuid := current_setting('prueba.u_cli_b')::uuid; u_adm uuid := current_setting('prueba.u_admin')::uuid; t uuid := current_setting('prueba.transp')::uuid; begin
  if has_function_privilege('anon', 'cuadro_mando_digital(date, date)', 'execute') then raise exception 'FALLO 348 · alguien sin entrar ve el cuadro de mando'; end if;
  insert into clientes (razon_social, cif) values ('Digital SL', 'B34800348') returning id into c;
  for i in 1..6 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (c, 13.30, 20, 1000, 800) returning id into e;
    ids := ids || e;
  end loop;
  alter table envios disable trigger user; alter table envio_ofertas disable trigger user;
  update envios set estado = 'entregado', fecha_efectiva = d, transportista_id = t where id = any(ids);
  update envios set creado_por = u_cli where id in (ids[1], ids[2]);     -- los crea el cliente
  update envios set creado_por = u_adm where id in (ids[3], ids[4]);     -- los crea Dynamo
  update envios set creado_por = null where id = ids[5];                 -- carga antigua: cuenta como Dynamo
  update envios set creado_por = u_cli, estado = 'cancelado' where id = ids[6];   -- no realizado: no cuenta
  -- El transportista aceptó por su enlace en el 1 y en el 3; en el 4 la oferta aceptada es de un
  -- transportista que ya no lo lleva (después lo cambió Dynamo a mano): no cuenta como aceptado por enlace.
  insert into envio_ofertas (envio_id, transportista_id, canal, precio_ofertado, estado, caduca_en) values
    (ids[1], t, 'enlace', 800, 'aceptada', now() + interval '1 day'),
    (ids[3], null, 'enlace', 800, 'aceptada', now() + interval '1 day'),
    (ids[2], t, 'enlace', 800, 'cerrada', now() + interval '1 day'),
    (ids[4], t, 'enlace', 800, 'aceptada', now() + interval '1 day');
  update envios set transportista_id = null where id = ids[4];   -- ya no lo lleva quien aceptó aquella oferta
  alter table envios enable trigger user; alter table envio_ofertas enable trigger user;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  r := cuadro_mando_digital(d - 1, d + 1);
  if (r ->> 'realizados')::int <> 5 or (r ->> 'digital_total')::int <> 1 or (r ->> 'digital_cliente')::int <> 1
     or (r ->> 'digital_transportista')::int <> 1 or (r ->> 'dynamo')::int <> 2 then
    raise exception 'FALLO 348 · el reparto de envíos digitales no cuadra: %', r; end if;
  -- Un cliente no ve nada del cuadro.
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  if (cuadro_mando_digital(d - 1, d + 1) ->> 'realizados')::int <> 0 then raise exception 'FALLO 348 · un cliente ve el reparto del cuadro de mando'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  alter table envios disable trigger user; alter table envio_ofertas disable trigger user;
  delete from envio_ofertas where envio_id = any(ids);
  update envios set estado = 'cancelado', transportista_id = null, fecha_efectiva = null where id = any(ids);
  alter table envios enable trigger user; alter table envio_ofertas enable trigger user;
  raise notice 'OK 348 · cuadro de mando: envíos 100 %% digital, digital cliente, digital transportista y 100 %% Dynamo';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 349 · DESCUADRES DE PANTALLA EN EL MÓVIL (usuario, 2026-11-25). El navegador apunta cada vez
-- que recoloca la pantalla; lo ve solo Dynamo; nadie escribe a mano; tope de 20 al día.
do $$ declare n int; i int;
  u_cli uuid := current_setting('prueba.u_cli_b')::uuid; u_adm uuid := current_setting('prueba.u_admin')::uuid; begin
  if has_function_privilege('anon', 'pantalla_descuadre_anotar(text, text, text, boolean, jsonb)', 'execute') then
    raise exception 'FALLO 349 · alguien sin entrar puede apuntar descuadres'; end if;
  if has_table_privilege('authenticated', 'pantalla_descuadres', 'insert') or has_table_privilege('authenticated', 'pantalla_descuadres', 'delete')
     or has_table_privilege('anon', 'pantalla_descuadres', 'select') then
    raise exception 'FALLO 349 · permisos de más en pantalla_descuadres'; end if;
  -- Sin sesión no apunta nada.
  perform set_config('request.jwt.claim.sub', '', false);
  perform pantalla_descuadre_anotar('pasado_del_final', '/panel/dashboard', 'iPhone/iPad (iOS 26.1) · Chrome', true, '{}'::jsonb);
  select count(*) into n from pantalla_descuadres; if n <> 0 then raise exception 'FALLO 349 · se apuntó un descuadre sin sesión'; end if;
  -- Un cliente apunta el suyo; una causa inventada no entra; unos datos enormes se guardan vacíos.
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  perform pantalla_descuadre_anotar('pasado_del_final', '/panel/dashboard', 'iPhone/iPad (iOS 26.1) · Chrome', true, '{"motivo":"scroll","antes":{"y":900,"doc":1200}}'::jsonb);
  perform pantalla_descuadre_anotar('lo_que_sea', '/panel/dashboard', 'x', true, '{}'::jsonb);
  perform pantalla_descuadre_anotar('zona_desplazada', repeat('r', 500), repeat('n', 500), null, jsonb_build_object('x', repeat('a', 3000)));
  select count(*) into n from pantalla_descuadres where usuario_id = u_cli;
  if n <> 2 then raise exception 'FALLO 349 · se esperaban 2 apuntes del cliente y hay %', n; end if;
  if not exists (select 1 from pantalla_descuadres where causa = 'zona_desplazada' and length(ruta) = 120 and length(navegador) = 80 and datos = '{}'::jsonb and not corregido) then
    raise exception 'FALLO 349 · no se recortan la ruta, el navegador o los datos'; end if;
  -- Tope de 20 al día por usuario.
  for i in 1..30 loop perform pantalla_descuadre_anotar('scroll_de_mas', '/panel/envios', 'Android 15 · Chrome', false, '{}'::jsonb); end loop;
  select count(*) into n from pantalla_descuadres where usuario_id = u_cli;
  if n <> 20 then raise exception 'FALLO 349 · el tope diario no es 20 (hay %)', n; end if;
  -- El cliente no ve la lista (ni la suya); Dynamo sí.
  set local role authenticated;
  select count(*) into n from pantalla_descuadres;
  reset role;
  if n <> 0 then raise exception 'FALLO 349 · un cliente ve los descuadres de pantalla'; end if;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  set local role authenticated;
  select count(*) into n from pantalla_descuadres;
  reset role;
  if n <> 20 then raise exception 'FALLO 349 · Dynamo no ve los descuadres de pantalla (%)', n; end if;
  -- Los de más de 90 días se borran al apuntar el siguiente.
  alter table pantalla_descuadres disable trigger user;
  update pantalla_descuadres set creado_en = now() - interval '100 days';
  alter table pantalla_descuadres enable trigger user;
  perform pantalla_descuadre_anotar('pagina_larga', '/panel/riesgos', 'Ordenador · Chrome', false, '{}'::jsonb);
  select count(*) into n from pantalla_descuadres;
  if n <> 1 then raise exception 'FALLO 349 · no se borran los apuntes antiguos (quedan %)', n; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  alter table pantalla_descuadres disable trigger user; delete from pantalla_descuadres; alter table pantalla_descuadres enable trigger user;
  raise notice 'OK 349 · descuadres de pantalla: los apunta el navegador, tope diario, solo los ve Dynamo y se borran a los 90 días';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 350 · UNA PENALIZACIÓN A 0 € NO EXISTE (usuario, 2026-11-25). Con los dos importes a 0 no se
-- crea; a quien le toca 0 no le aparece (ni en su lista ni en su contador).
do $$ declare c uuid; e uuid; p uuid; n int; tp uuid := (select id from tipos_penalizacion where clave = 'paralizacion');
  u_cli uuid := current_setting('prueba.u_cli_b')::uuid; u_adm uuid := current_setting('prueba.u_admin')::uuid; t uuid := current_setting('prueba.transp')::uuid;
  u_tra uuid; cli_b uuid; begin
  select cliente_id into cli_b from usuarios where id = u_cli;
  select id into u_tra from usuarios where transportista_id = t and estado = 'activa' limit 1;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (cli_b, 13.30, 20, 1000, 800) returning id into e;
  alter table envios disable trigger user;
  update envios set estado = 'entregado', transportista_id = t where id = e;
  alter table envios enable trigger user;
  -- Los dos a 0, o vacíos: no se crea.
  begin
    insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente, importe_transportista) values (e, tp, 'A cero', 0, 0);
    raise exception 'FALLO 350 · se crea una penalización con los dos importes a 0';
  exception when check_violation then null; end;
  begin
    insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente) values (e, tp, 'A cero', 0);
    raise exception 'FALLO 350 · se crea una penalización a 0 € con el otro importe vacío';
  exception when check_violation then null; end;
  -- La automática sin importes no se genera (y no da error).
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente, importe_transportista, generada_auto) values (e, tp, 'Automática a cero', 0, null, true);
  select count(*) into n from penalizaciones where envio_id = e;
  if n <> 0 then raise exception 'FALLO 350 · se genera una penalización automática a 0 €'; end if;
  -- Solo al transportista: el cliente no la ve ni la cuenta; el transportista sí.
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_transportista) values (e, tp, 'Espera en carga', 40) returning id into p;
  -- Solo al cliente: al revés.
  insert into penalizaciones (envio_id, tipo_id, descripcion, importe_cliente, importe_transportista) values (e, tp, 'Espera en descarga', 60, 0);
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  if (contadores_panel(cli_b, null) ->> 'penalizaciones')::int <> (select count(*) from penalizaciones x join envios y on y.id = x.envio_id where y.cliente_id = cli_b and x.importe_cliente > 0 and x.estado = 'pendiente_confirmar') then
    raise exception 'FALLO 350 · el contador del cliente cuenta penalizaciones que no se le cobran'; end if;
  if (contadores_panel(null, t) ->> 'penalizaciones')::int <> (select count(*) from penalizaciones x join envios y on y.id = x.envio_id where y.transportista_id = t and x.importe_transportista > 0 and x.estado = 'pendiente_confirmar') then
    raise exception 'FALLO 350 · el contador del transportista cuenta penalizaciones que no se le pagan'; end if;
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  select count(*) into n from mis_penalizaciones() m where m.envio_id = e;
  if n <> 1 or exists (select 1 from mis_penalizaciones() m where m.envio_id = e and m.importe_cliente <> 60) then
    raise exception 'FALLO 350 · el cliente no ve solo la penalización que se le cobra (ve %)', n; end if;
  if u_tra is not null then
    perform set_config('request.jwt.claim.sub', u_tra::text, false);
    select count(*) into n from mis_penalizaciones_transportista() m where m.envio_id = e;
    if n <> 1 or exists (select 1 from mis_penalizaciones_transportista() m where m.envio_id = e and m.importe_transportista <> 40) then
      raise exception 'FALLO 350 · el transportista no ve solo la penalización que se le paga (ve %)', n; end if;
  end if;
  perform set_config('request.jwt.claim.sub', '', false);
  alter table penalizaciones disable trigger user; delete from penalizaciones where envio_id = e; alter table penalizaciones enable trigger user;
  alter table envios disable trigger user; update envios set estado = 'cancelado', transportista_id = null where id = e; alter table envios enable trigger user;
  raise notice 'OK 350 · una penalización a 0 € no existe: no se crea con los dos importes a 0 y a quien le toca 0 no le aparece';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 351 · CUADRO DE MANDO: ENVÍOS DIGITALES MES A MES (usuario, 2026-11-25). La serie suma lo
-- mismo que las cuatro casillas, va por día hasta 62 días y por mes si es más, y sin huecos.
do $$ declare c uuid; ids uuid[] := '{}'; e uuid; i int; r jsonb; t jsonb; d date := date '2036-05-10';
  u_cli uuid := current_setting('prueba.u_cli_b')::uuid; u_adm uuid := current_setting('prueba.u_admin')::uuid; tr uuid := current_setting('prueba.transp')::uuid; begin
  if has_function_privilege('anon', 'cuadro_mando_digital_serie(date, date)', 'execute') then raise exception 'FALLO 351 · alguien sin entrar ve la serie del cuadro de mando'; end if;
  insert into clientes (razon_social, cif) values ('Serie Digital SL', 'B35100351') returning id into c;
  for i in 1..4 loop
    insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista) values (c, 13.30, 20, 1000, 800) returning id into e;
    ids := ids || e;
  end loop;
  alter table envios disable trigger user; alter table envio_ofertas disable trigger user;
  update envios set estado = 'entregado', transportista_id = tr, creado_por = null where id = any(ids);
  update envios set fecha_efectiva = d where id in (ids[1], ids[2]);              -- mayo
  update envios set fecha_efectiva = d + 40 where id in (ids[3], ids[4]);         -- junio
  update envios set creado_por = u_cli where id in (ids[1], ids[3]);              -- los crea el cliente
  insert into envio_ofertas (envio_id, transportista_id, canal, precio_ofertado, estado, caduca_en) values
    (ids[1], tr, 'enlace', 800, 'aceptada', now() + interval '1 day'),            -- mayo: full digital
    (ids[4], tr, 'enlace', 800, 'aceptada', now() + interval '1 day');            -- junio: digital transportista
  alter table envios enable trigger user; alter table envio_ofertas enable trigger user;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  -- Periodo largo: por mes, tres meses seguidos (mayo, junio y julio, este a cero).
  r := cuadro_mando_digital_serie(date '2036-05-01', date '2036-07-31');
  t := cuadro_mando_digital(date '2036-05-01', date '2036-07-31');
  if r ->> 'granularidad' <> 'mes' or jsonb_array_length(r -> 'serie') <> 3 then raise exception 'FALLO 351 · la serie larga no va por mes o tiene huecos: %', r; end if;
  if (r -> 'serie' -> 0 ->> 'digital_total')::int <> 1 or (r -> 'serie' -> 0 ->> 'dynamo')::int <> 1
     or (r -> 'serie' -> 1 ->> 'digital_cliente')::int <> 1 or (r -> 'serie' -> 1 ->> 'digital_transportista')::int <> 1
     or (select sum((x ->> 'digital_total')::int + (x ->> 'digital_cliente')::int + (x ->> 'digital_transportista')::int + (x ->> 'dynamo')::int) from jsonb_array_elements(r -> 'serie') x) <> (t ->> 'realizados')::int
     or (r -> 'serie' -> 2 ->> 'dynamo')::int <> 0 then
    raise exception 'FALLO 351 · la serie por mes no cuadra con las cuatro casillas: % / %', r, t; end if;
  -- Periodo corto: por día, uno por cada día.
  r := cuadro_mando_digital_serie(d - 2, d + 2);
  if r ->> 'granularidad' <> 'dia' or jsonb_array_length(r -> 'serie') <> 5 or (r -> 'serie' -> 2 ->> 'digital_total')::int <> 1 then
    raise exception 'FALLO 351 · la serie corta no va por día: %', r; end if;
  -- Un cliente no ve nada.
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  r := cuadro_mando_digital_serie(date '2036-05-01', date '2036-07-31');
  if exists (select 1 from jsonb_array_elements(r -> 'serie') x where (x ->> 'digital_total')::int + (x ->> 'digital_cliente')::int + (x ->> 'digital_transportista')::int + (x ->> 'dynamo')::int <> 0) then
    raise exception 'FALLO 351 · un cliente ve la serie del cuadro de mando'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  alter table envios disable trigger user; alter table envio_ofertas disable trigger user;
  delete from envio_ofertas where envio_id = any(ids);
  update envios set estado = 'cancelado', transportista_id = null, fecha_efectiva = null where id = any(ids);
  alter table envios enable trigger user; alter table envio_ofertas enable trigger user;
  raise notice 'OK 351 · cuadro de mando: envíos digitales por día o por mes, sin huecos, y cuadra con las cuatro casillas';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 352 · ENLACE DE PAGO PÚBLICO (usuario, 2026-11-25). Con la llave del envío, sin sesión, se ve
-- lo mínimo de un envío pendiente de pago (sin calles, empresas ni contactos) y se puede avisar
-- de la transferencia; sin la llave buena, nada. Las etapas siguen pidiendo permiso.
do $$ declare c uuid; e uuid; tok uuid; r jsonb; n int;
  u_adm uuid := current_setting('prueba.u_admin')::uuid; u_cli uuid := current_setting('prueba.u_cli_b')::uuid; begin
  if not has_function_privilege('anon', 'pago_publico(uuid)', 'execute') or not has_function_privilege('anon', 'pago_publico_avisar(uuid)', 'execute') then
    raise exception 'FALLO 352 · la página pública de pago no puede leer o avisar'; end if;
  if has_function_privilege('anon', 'etapas_envio_interno(uuid)', 'execute') or has_function_privilege('authenticated', 'etapas_envio_interno(uuid)', 'execute')
     or has_function_privilege('anon', 'fn_pago_avisar(uuid, boolean)', 'execute') or has_function_privilege('authenticated', 'fn_pago_avisar(uuid, boolean)', 'execute') then
    raise exception 'FALLO 352 · las funciones internas del pago se pueden llamar por la API'; end if;
  insert into clientes (razon_social, cif) values ('Paga Enlace SL', 'B35200352') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id, pago_token into e, tok;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  update envios set estado = 'programado', estado_pago_previo = 'pendiente', pago_pendiente_en = now(), pago_a_cuenta = 0, pago_avisado_en = null where id = e;
  delete from envio_paradas where envio_id = e;
  insert into envio_paradas (envio_id, orden, tipo, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso) values
    (e, 1, 'carga', 'Empresa Oculta SL', 'Calle Secreta 7', '41001', 'Sevilla', 'Sevilla', 'ES'),
    (e, 2, 'descarga', 'Destino Oculto SA', 'Avenida Reservada 9', '12550', 'Almassora', 'Castellón', 'ES');
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  if tok is null or (select count(*) from envios where pago_token = tok) <> 1 then raise exception 'FALLO 352 · el envío no tiene su llave de pago'; end if;
  -- Sin sesión, con la llave: lo mínimo.
  perform set_config('request.jwt.claim.sub', '', false);
  set local role anon;
  r := pago_publico(tok);
  reset role;
  if r ->> 'resultado' <> 'pendiente' or (r ->> 'total')::numeric <> 1210 or (r ->> 'pendiente')::numeric <> 1210 or r ->> 'pago_limite' is null
     or jsonb_array_length(r -> 'paradas') <> 2 or r -> 'paradas' -> 0 ->> 'tipo' <> 'carga' or r -> 'paradas' -> 1 ->> 'poblacion' <> 'Almassora' then
    raise exception 'FALLO 352 · la página de pago no trae lo que debe: %', r; end if;
  if r::text ~* 'oculta|oculto|secreta|reservada|importe_transportista|800' then raise exception 'FALLO 352 · la página de pago enseña calles, empresas o el coste: %', r; end if;
  -- Una llave inventada no enseña nada.
  set local role anon;
  r := pago_publico(gen_random_uuid());
  reset role;
  if r <> '{"resultado": "enlace_no_valido"}'::jsonb then raise exception 'FALLO 352 · una llave inventada enseña algo: %', r; end if;
  -- «Ya he hecho la transferencia» desde el enlace: para el plazo y avisa a Dynamo; dos veces no repite.
  set local role anon;
  r := pago_publico_avisar(tok);
  reset role;
  if r ->> 'resultado' <> 'ok' or (select pago_avisado_en from envios where id = e) is null then raise exception 'FALLO 352 · el aviso de transferencia desde el enlace no queda apuntado: %', r; end if;
  if not exists (select 1 from avisos where envio_id = e and para = 'dynamo' and tipo = 'pago_avisado' and texto like '%desde el enlace de pago%') then
    raise exception 'FALLO 352 · Dynamo no recibe el aviso de la transferencia hecha desde el enlace'; end if;
  set local role anon;
  r := pago_publico_avisar(tok);
  reset role;
  if r ->> 'resultado' <> 'ya_avisado' then raise exception 'FALLO 352 · avisar dos veces no dice que ya estaba: %', r; end if;
  r := pago_publico(tok);
  if r ->> 'avisado_en' is null or r ->> 'pago_limite' is not null then raise exception 'FALLO 352 · con la transferencia avisada el plazo no sale parado: %', r; end if;
  if (pago_publico_avisar(gen_random_uuid()) ->> 'resultado') <> 'enlace_no_valido' then raise exception 'FALLO 352 · se puede avisar con una llave inventada'; end if;
  -- El cliente sigue avisando por su botón (con permiso) y un desconocido no.
  alter table envios disable trigger user; update envios set pago_avisado_en = null where id = e; alter table envios enable trigger user;
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  begin perform avisar_pago_transferencia(e); raise exception 'FALLO 352 · otro cliente avisa de la transferencia de un envío ajeno';
  exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  if (avisar_pago_transferencia(e) ->> 'resultado') <> 'ok' then raise exception 'FALLO 352 · Dynamo ya no puede avisar de la transferencia en nombre del cliente'; end if;
  -- Las etapas: Dynamo las ve (por la de siempre); sin sesión, no.
  select count(*) into n from etapas_envio(e);
  if n = 0 then raise exception 'FALLO 352 · etapas_envio ya no devuelve las etapas a Dynamo'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  select count(*) into n from etapas_envio(e);
  if n <> 0 then raise exception 'FALLO 352 · etapas_envio devuelve etapas sin permiso'; end if;
  -- Pagado o anulado: la página solo lo dice.
  alter table envios disable trigger user;
  update envios set estado_pago_previo = 'pagado' where id = e;
  if pago_publico(tok) - 'referencia' <> '{"resultado": "pagado"}'::jsonb then raise exception 'FALLO 352 · un envío pagado enseña más que «pagado»'; end if;
  update envios set estado = 'cancelado' where id = e;
  if pago_publico(tok) - 'referencia' <> '{"resultado": "anulado"}'::jsonb then raise exception 'FALLO 352 · un envío anulado enseña más que «anulado»'; end if;
  alter table envios enable trigger user;
  -- El botón del email de «Envío creado» lleva a la página de pago.
  if position('''/pago/'' || e.pago_token' in pg_get_functiondef('public.fn_email_envio_creado()'::regprocedure)) = 0 then
    raise exception 'FALLO 352 · el botón «Pagar el envío» del email no lleva a la página de pago'; end if;
  alter table avisos disable trigger user; delete from avisos where envio_id = e; alter table avisos enable trigger user;
  raise notice 'OK 352 · enlace de pago público: lo mínimo con la llave, aviso de transferencia sin sesión, nada con una llave inventada y las etapas siguen pidiendo permiso';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 353 · PREVISIÓN DE ENTREGA DE UN GRUPAJE (usuario, 2026-11-25): «siempre más 3 horas en
-- grupajes». El mismo envío, con la misma ruta, llega a su primera entrega 3 horas más tarde si
-- es grupaje que si es camión completo; se suma UNA vez (la segunda entrega solo lo arrastra), la
-- carga no se mueve, y con el parámetro a 0 queda como un completo.
do $$ declare c uuid; e uuid; n int; d interval;
  a timestamptz[]; g timestamptz[]; z timestamptz[]; begin
  if (select valor from parametros where clave = 'seguimiento_horas_extra_grupaje') <> '3' then
    raise exception 'FALLO 353 · falta el parámetro de las horas de más del grupaje, o no vale 3'; end if;
  insert into clientes (razon_social, cif) values ('Grupaje Tarde SL', 'B35300353') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id into e;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  update envios set estado = 'programado' where id = e;
  delete from envio_paradas where envio_id = e;
  insert into envio_paradas (envio_id, orden, tipo, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso) values
    (e, 1, 'carga', 'Sale SL', 'Calle Uno 1', '41001', 'Sevilla', 'Sevilla', 'ES'),
    (e, 2, 'descarga', 'Llega SA', 'Calle Dos 2', '12550', 'Almassora', 'Castellón', 'ES'),
    (e, 3, 'descarga', 'Llega Dos SA', 'Calle Tres 3', '46001', 'Valencia', 'Valencia', 'ES');
  if (select tipo_carga from envios where id = e) <> 'completa' then raise exception 'FALLO 353 · 13,30 m no sale como carga completa'; end if;
  select array_agg(x.hora order by x.paso) into a from seguimiento_calcular(e) x where x.paso >= 1;
  update envios set metros_lineales = 3 where id = e;
  if (select tipo_carga from envios where id = e) <> 'grupaje' then raise exception 'FALLO 353 · 3 m no sale como grupaje'; end if;
  select array_agg(x.hora order by x.paso) into g from seguimiento_calcular(e) x where x.paso >= 1;
  n := array_length(a, 1);
  if n <> 7 or array_length(g, 1) <> 7 then raise exception 'FALLO 353 · el envío de prueba no tiene sus 7 etapas: % / %', a, g; end if;
  -- La recogida no cambia (pasos 1 a 3: hacia la carga, cargando, en ruta).
  if a[1] <> g[1] or a[2] <> g[2] or a[3] <> g[3] then raise exception 'FALLO 353 · el grupaje mueve la hora de la recogida: % / %', a, g; end if;
  -- Llegada a la primera entrega (paso 4): 3 horas más. Sin horario de sitio no hay espera que lo tape.
  d := g[4] - a[4];
  if d <> interval '3 hours' then raise exception 'FALLO 353 · el grupaje no llega 3 h más tarde a su primera entrega: % (completo %, grupaje %)', d, a[4], g[4]; end if;
  -- Una sola vez: lo que tarda en descargar es lo mismo y la segunda entrega no vuelve a sumar.
  if g[5] - g[4] <> a[5] - a[4] then raise exception 'FALLO 353 · el grupaje cambia el tiempo de descarga'; end if;
  if g[7] <= a[7] or g[7] - a[7] >= interval '6 hours' then
    raise exception 'FALLO 353 · la segunda entrega del grupaje no arrastra la demora una sola vez: completo %, grupaje %', a[7], g[7]; end if;
  -- Con el parámetro a 0, el grupaje se calcula como un completo.
  update parametros set valor = '0' where clave = 'seguimiento_horas_extra_grupaje';
  select array_agg(x.hora order by x.paso) into z from seguimiento_calcular(e) x where x.paso >= 1;
  update parametros set valor = '3' where clave = 'seguimiento_horas_extra_grupaje';
  if z <> a then raise exception 'FALLO 353 · con 0 horas el grupaje no queda como un completo: % / %', a, z; end if;
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  raise notice 'OK 353 · previsión del grupaje: 3 h más en su primera entrega, una sola vez, la recogida igual y editable en Parámetros';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 354 · PÁGINA DE PAGO CON EL PLAZO PASADO (usuario, 2026-11-25): «debe salir eso de que pasó el
-- plazo… y algo de más info mínima para darle contexto». Un envío anulado por no pagar a tiempo
-- dice el motivo, el plazo que había y lo mínimo del envío; si Dynamo no encontró la
-- transferencia, lo dice; anulado por otra cosa, solo «anulado».
do $$ declare c uuid; e uuid; tok uuid; r jsonb; begin
  insert into clientes (razon_social, cif) values ('Plazo Pasado SL', 'B35400354') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id, pago_token into e, tok;
  alter table envios disable trigger user; alter table envio_paradas disable trigger user;
  update envios set estado = 'cancelado', estado_pago_previo = 'pendiente', pago_pendiente_en = now() - interval '3 hours', pago_a_cuenta = 0, pago_avisado_en = null where id = e;
  delete from envio_paradas where envio_id = e;
  insert into envio_paradas (envio_id, orden, tipo, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso) values
    (e, 1, 'carga', 'Empresa Oculta SL', 'Calle Secreta 7', '41001', 'Sevilla', 'Sevilla', 'ES'),
    (e, 2, 'descarga', 'Destino Oculto SA', 'Avenida Reservada 9', '12550', 'Almassora', 'Castellón', 'ES');
  alter table envios enable trigger user; alter table envio_paradas enable trigger user;
  -- Anulado sin más (p. ej. lo canceló el cliente): solo «anulado».
  if pago_publico(tok) - 'referencia' <> '{"resultado": "anulado"}'::jsonb then raise exception 'FALLO 354 · un anulado normal enseña más que «anulado»: %', pago_publico(tok); end if;
  -- Anulado por no pagar a tiempo: motivo «plazo» y el plazo que había (ya pasado).
  perform registrar_hito(e, 'incidencia', null, null, jsonb_build_object('motivo_cancelacion', 'Anulado sin pago: no se recibió el pago a tiempo', 'por', 'sistema'), 'servidor');
  set local role anon;
  r := pago_publico(tok);
  reset role;
  if r ->> 'resultado' <> 'anulado' or r ->> 'motivo' <> 'plazo' or (r ->> 'pago_limite')::timestamptz >= now() then
    raise exception 'FALLO 354 · la página de pago no dice que el plazo pasó: %', r; end if;
  -- Con lo mínimo para situarse (cliente, importe y paradas sin calle ni empresa), sin la cuenta ni horas previstas.
  if r ->> 'cliente' is null or (r ->> 'total')::numeric <> 1210 or jsonb_array_length(r -> 'paradas') < 2 or r ? 'transferencia'
     or r -> 'paradas' -> 0 ->> 'prevista' is not null or r -> 'paradas' -> 1 ->> 'poblacion' <> 'Almassora'
     or r::text ~* 'oculta|oculto|secreta|reservada|importe_transportista|: 800' then
    raise exception 'FALLO 354 · un envío con el plazo pasado no trae lo mínimo, o enseña de más: %', r; end if;
  -- Dynamo no encontró la transferencia avisada: motivo «transferencia».
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id, pago_token into e, tok;
  alter table envios disable trigger user;
  update envios set estado = 'cancelado', estado_pago_previo = 'pendiente', pago_pendiente_en = now() - interval '3 hours' where id = e;
  alter table envios enable trigger user;
  perform registrar_hito(e, 'incidencia', null, null, jsonb_build_object('motivo_cancelacion', 'Anulado sin pago: no nos consta la transferencia (no aparece en el banco)', 'por', 'dynamo'), 'app');
  r := pago_publico(tok);
  if r ->> 'motivo' <> 'transferencia' then raise exception 'FALLO 354 · la página de pago no dice que no consta la transferencia: %', r; end if;
  raise notice 'OK 354 · página de pago con el plazo pasado: dice el motivo, el plazo y lo mínimo del envío, sin nada con lo que pagar';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 355 · DESHACER A 60 SEGUNDOS Y AVISOS DE SEGURIDAD AL MOMENTO (usuario, 2026-11-25). El plazo
-- único es 60 s: lo que dura el contador de un cambio y lo que espera un email normal. Los de
-- seguridad (acceso desde un dispositivo nuevo, «No he sido yo», código de firma) no esperan.
do $$ declare c uuid; e uuid; x uuid; t timestamptz; v record;
  u_adm uuid := current_setting('prueba.u_admin')::uuid; begin
  if (select valor::text from parametros where clave = 'emails_espera_segundos') <> '60' then
    raise exception 'FALLO 355 · el plazo para deshacer no es de 60 segundos: %', (select valor from parametros where clave = 'emails_espera_segundos'); end if;
  if has_function_privilege('authenticated', 'email_sin_espera(text)', 'execute') or has_function_privilege('anon', 'email_sin_espera(text)', 'execute') then
    raise exception 'FALLO 355 · email_sin_espera se puede llamar por la API'; end if;
  -- Un email normal espera ~60 s; los de seguridad salen ya.
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html) values ('p355:normal', 'cuenta_activada', 'a@ejemplo.com', 'x', 'x') returning enviar_desde into t;
  if t < now() + interval '59 seconds' or t > now() + interval '61 seconds' then raise exception 'FALLO 355 · un email normal no espera 60 s: %', t - now(); end if;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html) values ('p355:acceso', 'acceso_nuevo', 'a@ejemplo.com', 'x', 'x') returning enviar_desde into t;
  if t > now() then raise exception 'FALLO 355 · el aviso de acceso desde un dispositivo nuevo espera: %', t - now(); end if;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html) values ('p355:noyo', 'acceso_no_he_sido_yo', 'a@ejemplo.com', 'x', 'x') returning enviar_desde into t;
  if t > now() then raise exception 'FALLO 355 · el aviso de «No he sido yo» espera: %', t - now(); end if;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html, estado) values ('p355:codigo', 'codigo_firma', 'a@ejemplo.com', 'x', 'x', 'enviado') returning enviar_desde into t;
  if t > now() then raise exception 'FALLO 355 · el código de firma queda apuntado con espera: %', t - now(); end if;
  delete from emails_enviados where clave like 'p355:%';
  -- El contador de un cambio hecho por una persona dura 60 s.
  insert into clientes (razon_social, cif) values ('Sesenta Segundos SL', 'B35500355') returning id into c;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id into e;
  select * into v from envio_cambios where envio_id = e and estado = 'abierto';
  if v.id is null or v.vence_en < now() + interval '59 seconds' or v.vence_en > now() + interval '61 seconds' then
    raise exception 'FALLO 355 · el contador de un envío recién creado no dura 60 s: %', v.vence_en - now(); end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from envio_cambios where envio_id = e;
  raise notice 'OK 355 · deshacer a 60 s (contador y emails) y los avisos de seguridad salen al momento';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 356 · DESHACER EN INCIDENCIAS Y PENALIZACIONES (usuario, 2026-11-25: «E INCLUYE: incidencias,
-- penalizaciones — 60 segundos»). Abrir una incidencia o cambiarle el estado, y cambiar el estado
-- de una penalización, abren un cambio de 60 s cuando lo hace una persona; al deshacerlo, la fila
-- vuelve atrás y sus emails y avisos no salen. Solo quien lo hizo o Dynamo; pasado el plazo, no.
do $$ declare c uuid; e uuid; i uuid; i2 uuid; p uuid; j jsonb; n int; v record;
  u_adm uuid := current_setting('prueba.u_admin')::uuid; u_cli uuid := current_setting('prueba.u_cli_b')::uuid; begin
  if has_function_privilege('anon', 'deshacer_cambio(text, uuid)', 'execute') or has_function_privilege('anon', 'cambios_deshacer_pendientes(text)', 'execute')
     or has_function_privilege('authenticated', 'cambio_deshacer_abrir(text, uuid, text, jsonb)', 'execute')
     or not has_function_privilege('authenticated', 'deshacer_cambio(text, uuid)', 'execute') then
    raise exception 'FALLO 356 · los permisos de deshacer no son los debidos'; end if;
  if not (select relrowsecurity from pg_class where oid = 'public.cambios_deshacer'::regclass) then raise exception 'FALLO 356 · cambios_deshacer sin RLS'; end if;
  if position('cambios_deshacer' in pg_get_functiondef('public.enviar_emails_pendientes()'::regprocedure)) = 0 then
    raise exception 'FALLO 356 · la cola de emails no limpia los cambios de incidencias y penalizaciones'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into clientes (razon_social, cif) values ('Deshacer Incidencias SL', 'B35600356') returning id into c;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta)
    values (c, 13.30, 20, 1000, 800, current_date + 5, current_date + 6) returning id into e;
  -- Sin persona detrás (un proceso automático): no abre cambio.
  insert into incidencias (envio_id, tipo_id, titulo, detalle) values (e, (select id from tipos_incidencia limit 1), 'Automática 356', 'Sin persona') returning id into i;
  if exists (select 1 from cambios_deshacer where fila_id = i) then raise exception 'FALLO 356 · un proceso automático abre un cambio'; end if;

  -- (a) Dynamo abre una incidencia: cambio «creada» de 60 s.
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  insert into incidencias (envio_id, tipo_id, titulo, detalle) values (e, (select id from tipos_incidencia limit 1), 'Palet roto 356', 'Detalle') returning id into i;
  select * into v from cambios_deshacer where tabla = 'incidencias' and fila_id = i and estado = 'abierto';
  if v.id is null or v.tipo <> 'creada' or v.usuario_id <> u_adm or v.vence_en < now() + interval '59 seconds' or v.vence_en > now() + interval '61 seconds' then
    raise exception 'FALLO 356 · abrir una incidencia no deja su cambio de 60 s: %', to_jsonb(v); end if;
  insert into emails_enviados (clave, tipo, destinatario, asunto, cuerpo_html) values ('p356_abierta:' || i, 'incidencia_abierta', 'a@ejemplo.com', 'x', 'x');
  select count(*) into n from cambios_deshacer_pendientes('incidencias') x where x.fila_id = i and x.emails >= 1 and x.puede_anular;
  if n <> 1 then raise exception 'FALLO 356 · el contador de la incidencia recién abierta no sale'; end if;
  -- Otro usuario ni lo ve ni lo deshace.
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  if exists (select 1 from cambios_deshacer_pendientes('incidencias') x where x.fila_id = i) then raise exception 'FALLO 356 · otro usuario ve el contador de un cambio ajeno'; end if;
  begin perform deshacer_cambio('incidencias', i); raise exception 'FALLO 356 · otro usuario deshace un cambio ajeno';
  exception when insufficient_privilege then null; end;
  -- Dynamo lo deshace: queda retirada y no sale nada.
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  j := deshacer_cambio('incidencias', i);
  if j ->> 'resultado' <> 'deshecho' or j ->> 'tipo' <> 'creada' or (select estado from incidencias where id = i) <> 'cancelado' then
    raise exception 'FALLO 356 · deshacer una incidencia recién abierta no la deja retirada: % / %', j, (select estado from incidencias where id = i); end if;
  if exists (select 1 from emails_enviados where position(i::text in clave) > 0 and estado = 'pendiente') then raise exception 'FALLO 356 · queda un email por salir de la incidencia deshecha'; end if;
  if exists (select 1 from avisos a where a.envio_id = e and a.enlace = '/panel/incidencias' and position('Palet roto 356' in coalesce(a.texto, '')) > 0) then
    raise exception 'FALLO 356 · queda un aviso de la incidencia deshecha'; end if;
  if (select estado from cambios_deshacer where id = v.id) <> 'anulado' or exists (select 1 from cambios_deshacer where fila_id = i and estado = 'abierto') then
    raise exception 'FALLO 356 · el cambio no queda anulado, o deshacer abre otro'; end if;
  if deshacer_cambio('incidencias', i) ->> 'resultado' <> 'nada' then raise exception 'FALLO 356 · se puede deshacer dos veces'; end if;

  -- (b) Resolver una incidencia y deshacerlo: vuelve a abierta, sin resolución.
  insert into incidencias (envio_id, tipo_id, titulo, detalle) values (e, (select id from tipos_incidencia limit 1), 'Retraso 356', 'Detalle') returning id into i2;
  update cambios_deshacer set estado = 'cerrado' where fila_id = i2 and estado = 'abierto';
  update incidencias set estado = 'resuelto', resolucion = 'Arreglado' where id = i2;
  select * into v from cambios_deshacer where fila_id = i2 and estado = 'abierto';
  if v.tipo <> 'estado' or v.antes ->> 'estado' <> 'abierto' then raise exception 'FALLO 356 · resolver una incidencia no guarda el estado de antes: %', to_jsonb(v); end if;
  j := deshacer_cambio('incidencias', i2);
  select estado::text as estado, resolucion, resuelto_en into v from incidencias where id = i2;
  if j ->> 'resultado' <> 'deshecho' or v.estado <> 'abierto' or v.resolucion is not null or v.resuelto_en is not null then
    raise exception 'FALLO 356 · deshacer la resolución no deja la incidencia como estaba: % / %', j, to_jsonb(v); end if;
  -- Pasado el plazo ya no se deshace.
  update incidencias set estado = 'resuelto', resolucion = 'Arreglado' where id = i2;
  update cambios_deshacer set vence_en = now() - interval '1 minute' where fila_id = i2 and estado = 'abierto';
  if deshacer_cambio('incidencias', i2) ->> 'resultado' <> 'ya_salio' or (select estado from incidencias where id = i2) <> 'resuelto' then
    raise exception 'FALLO 356 · se deshace un cambio con el plazo pasado'; end if;

  -- (c) Penalización: guardarla no abre cambio; confirmarla sí, y deshacerlo la deja sin confirmar.
  insert into penalizaciones (envio_id, tipo_id, importe_cliente) values (e, (select id from tipos_penalizacion limit 1), 50) returning id into p;
  if exists (select 1 from cambios_deshacer where fila_id = p) then raise exception 'FALLO 356 · guardar una penalización sin confirmar abre un cambio'; end if;
  update penalizaciones set estado = 'confirmada' where id = p;
  select * into v from cambios_deshacer where tabla = 'penalizaciones' and fila_id = p and estado = 'abierto';
  if v.id is null or v.antes ->> 'estado' <> 'pendiente_confirmar' then raise exception 'FALLO 356 · confirmar una penalización no abre su cambio: %', to_jsonb(v); end if;
  if not exists (select 1 from cambios_deshacer_pendientes('penalizaciones') x where x.fila_id = p) then raise exception 'FALLO 356 · el contador de la penalización confirmada no sale'; end if;
  j := deshacer_cambio('penalizaciones', p);
  if j ->> 'resultado' <> 'deshecho' or (select estado from penalizaciones where id = p) <> 'pendiente_confirmar' then
    raise exception 'FALLO 356 · deshacer la confirmación no deja la penalización sin confirmar: %', j; end if;
  if exists (select 1 from emails_enviados where position(p::text in clave) > 0 and estado = 'pendiente') then raise exception 'FALLO 356 · queda un email por salir de la penalización deshecha'; end if;
  if exists (select 1 from avisos a where a.envio_id = e and a.enlace = '/panel/penalizaciones') then raise exception 'FALLO 356 · queda un aviso de la penalización deshecha'; end if;
  -- Una tabla que no es de aquí: nada.
  if deshacer_cambio('envios', e) ->> 'resultado' <> 'nada' then raise exception 'FALLO 356 · deshacer_cambio acepta otras tablas'; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from envio_cambios where envio_id = e;
  raise notice 'OK 356 · deshacer en incidencias y penalizaciones: cambio de 60 s con persona detrás, vuelve atrás sin emails ni avisos, solo quien lo hizo o Dynamo y nunca con el plazo pasado';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 357 · SITIOS → BREVO (usuario, 2026-11-25: «que esos mails de sitios, de todos los sitios, se
-- suban a Brevo… lista 04-SITIOS-DYNAMO»). La base de datos dice qué emails de sitios tocan
-- (contactos del sitio y emails de avisos, uno por email), deja fuera almacenes de Dynamo,
-- borrados y direcciones de prueba, no repite lo ya subido, vuelve a subir lo que cambia y
-- reintenta los fallos tres veces. Solo el servidor; nace apagado.
do $$ declare c uuid; s1 uuid; s2 uuid; s3 uuid; n int; v record; j jsonb;
  u_adm uuid := current_setting('prueba.u_admin')::uuid; u_cli uuid := current_setting('prueba.u_cli_b')::uuid; begin
  if (select valor::text from parametros where clave = 'brevo_sitios_activo') <> 'false' then raise exception 'FALLO 357 · la subida a Brevo no nace apagada'; end if;
  if (select valor #>> '{}' from parametros where clave = 'brevo_sitios_lista') <> '04-SITIOS-DYNAMO' then raise exception 'FALLO 357 · la lista de Brevo no es 04-SITIOS-DYNAMO'; end if;
  if has_function_privilege('authenticated', 'brevo_sitios_pendientes(integer)', 'execute') or has_function_privilege('authenticated', 'brevo_sitios_candidatos()', 'execute')
     or has_function_privilege('authenticated', 'brevo_sitios_marcar(jsonb)', 'execute') or has_function_privilege('anon', 'brevo_sitios_resumen()', 'execute')
     or has_function_privilege('authenticated', 'brevo_sitios_avisar()', 'execute') then
    raise exception 'FALLO 357 · las funciones de Brevo se pueden llamar sin ser el servidor'; end if;
  if not (select relrowsecurity from pg_class where oid = 'public.brevo_subidas'::regclass) then raise exception 'FALLO 357 · brevo_subidas sin RLS'; end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if not exists (select 1 from cron.job where jobname = 'dynamo-brevo-sitios') then raise exception 'FALLO 357 · falta la tarea diaria de Brevo'; end if;
  end if;
  perform set_config('request.jwt.claim.sub', '', false);
  insert into clientes (razon_social, cif) values ('Sitios a Brevo SL', 'B35700357') returning id into c;
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso, emails_avisos)
    values (c, 'Aceros 357', 'Calle Uno 1', '41001', 'Sevilla', 'Sevilla', 'ES', array['Avisos357@Aceros357.com', 'prueba@aceros357.invalid']) returning id into s1;
  insert into contactos (sitio_id, nombre, cargo, telefono, email) values (s1, 'Marta Ruiz', 'Jefa de almacén', '+34954000357', 'marta@aceros357.com');
  -- El mismo email como persona y como aviso: una sola fila, la de la persona.
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso, emails_avisos)
    values (c, 'Naves 357', 'Calle Dos 2', '28001', 'Madrid', 'Madrid', 'ES', array['marta@aceros357.com']) returning id into s2;
  -- Un sitio borrado no sube.
  insert into sitios (cliente_id, nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso, emails_avisos, borrado, borrado_en)
    values (c, 'Borrado 357', 'Calle Tres 3', '46001', 'Valencia', 'Valencia', 'ES', array['borrado@aceros357.com'], true, now()) returning id into s3;

  select count(*) into n from brevo_sitios_candidatos() x where x.email like '%aceros357%';
  if n <> 2 then raise exception 'FALLO 357 · esperaba 2 emails de sitios (la persona y el de avisos) y hay %: %', n,
    (select string_agg(x.email, ', ') from brevo_sitios_candidatos() x where x.email like '%aceros357%'); end if;
  select * into v from brevo_sitios_candidatos() x where x.email = 'marta@aceros357.com';
  if v.nombre <> 'Marta Ruiz' or v.empresa <> 'Aceros 357' or v.cargo <> 'Jefa de almacén' or v.provincia <> 'Sevilla' or v.sitio_id <> s1 then
    raise exception 'FALLO 357 · la persona de contacto no sube con sus datos y los de su sitio: %', to_jsonb(v); end if;
  if not exists (select 1 from brevo_sitios_candidatos() x where x.email = 'avisos357@aceros357.com' and x.nombre is null and x.empresa = 'Aceros 357') then
    raise exception 'FALLO 357 · el email de avisos no sube en minúsculas con los datos del sitio'; end if;
  if exists (select 1 from brevo_sitios_candidatos() x where x.email ~ 'invalid|borrado@' or x.email like '%@' || split_part(lower(parametro('dynamo_email') #>> '{}'), '@', 2)) then
    raise exception 'FALLO 357 · sube una dirección de prueba, de un sitio borrado o del dominio de Dynamo'; end if;

  -- Un usuario cualquiera no puede apuntar resultados; el servidor sí.
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  set local role authenticated;
  begin perform brevo_sitios_marcar('[]'::jsonb); raise exception 'FALLO 357 · un usuario apunta subidas a Brevo';
  exception when insufficient_privilege then null; end;
  begin perform brevo_sitios_resumen(); raise exception 'FALLO 357 · un cliente ve el resumen de Brevo';
  exception when insufficient_privilege then null; end;
  if (select count(*) from brevo_subidas) <> 0 then raise exception 'FALLO 357 · un cliente ve la tabla de subidas'; end if;
  reset role;
  perform set_config('request.jwt.claim.sub', '', false);

  -- Subida: lo subido no vuelve a salir; lo que cambia de datos, sí.
  select jsonb_agg(jsonb_build_object('email', x.email, 'sitio_id', x.sitio_id, 'huella', x.huella, 'estado', 'subido')) into j
    from brevo_sitios_pendientes(500) x where x.email like '%aceros357%';
  if brevo_sitios_marcar(j) <> 2 then raise exception 'FALLO 357 · no se apuntan las dos subidas'; end if;
  if exists (select 1 from brevo_sitios_pendientes(500) x where x.email like '%aceros357%') then raise exception 'FALLO 357 · un email ya subido vuelve a salir'; end if;
  update contactos set cargo = 'Directora de logística' where email = 'marta@aceros357.com';
  if not exists (select 1 from brevo_sitios_pendientes(500) x where x.email = 'marta@aceros357.com') then raise exception 'FALLO 357 · al cambiar sus datos no vuelve a subir'; end if;
  -- Fallo: se reintenta al día siguiente, tres veces como mucho.
  perform brevo_sitios_marcar(jsonb_build_array(jsonb_build_object('email', 'marta@aceros357.com', 'sitio_id', s1, 'huella', 'x', 'estado', 'error', 'error', 'Brevo 400')));
  if exists (select 1 from brevo_sitios_pendientes(500) x where x.email = 'marta@aceros357.com') then raise exception 'FALLO 357 · un fallo se reintenta al momento'; end if;
  update brevo_subidas set subido_en = now() - interval '1 day' where email = 'marta@aceros357.com';
  if not exists (select 1 from brevo_sitios_pendientes(500) x where x.email = 'marta@aceros357.com') then raise exception 'FALLO 357 · un fallo no se reintenta al día siguiente'; end if;
  update brevo_subidas set intentos = 3 where email = 'marta@aceros357.com';
  if exists (select 1 from brevo_sitios_pendientes(500) x where x.email = 'marta@aceros357.com') then raise exception 'FALLO 357 · un fallo se reintenta más de tres veces'; end if;

  -- El resumen, para Dynamo.
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  j := brevo_sitios_resumen();
  if (j ->> 'activo')::boolean or j ->> 'lista' <> '04-SITIOS-DYNAMO' or (j ->> 'subidos')::int < 1 or (j ->> 'errores')::int < 1
     or jsonb_array_length(j -> 'ultimos_errores') < 1 then raise exception 'FALLO 357 · el resumen de Brevo no cuadra: %', j; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  -- Apagado, la tarea diaria no llama a nadie.
  if brevo_sitios_avisar() then raise exception 'FALLO 357 · apagado, la tarea diaria avisa al servidor'; end if;
  delete from brevo_subidas where email like '%aceros357%';
  raise notice 'OK 357 · sitios → Brevo: uno por email con sus datos, fuera pruebas, borrados y Dynamo, sin repetir, resube lo que cambia, reintenta 3 veces, solo el servidor y nace apagado';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 358 · EMAIL «LÍNEA DE CRÉDITO CONCEDIDA»: NO NOMBRA LOS DÍAS DE PAGO (usuario, 2026-11-25:
-- «quita eso de 120 días»). Se sigue diciendo «a vencimiento» y, si es de CESCE, que la respalda.
do $$ declare v_cli uuid; v_man numeric; v_ces numeric; v_plazo int; r record; begin
  select cliente_id into v_cli from usuarios where id = current_setting('prueba.u_cli_b')::uuid;
  select riesgo_manual_euros, riesgo_cesce_euros, plazo_pago_dias into v_man, v_ces, v_plazo from clientes where id = v_cli;
  update clientes set riesgo_manual_euros = null, riesgo_cesce_euros = 0, plazo_pago_dias = 120 where id = v_cli;
  update clientes set riesgo_cesce_euros = 5000 where id = v_cli;
  select * into r from emails_enviados where clave like 'credito_cambio:' || v_cli || ':%' order by clave desc limit 1;
  if r.id is null or r.asunto <> 'Línea de crédito concedida · Dynamo' then raise exception 'FALLO 358 · no sale el email de línea concedida: %', r.asunto; end if;
  if position('respaldada por CESCE' in r.cuerpo_html) = 0
     or position('se pagan <strong>a vencimiento</strong>, sin pago por adelantado' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 358 · el email de línea concedida no dice lo acordado: %', r.cuerpo_html; end if;
  if position('120' in r.cuerpo_html) > 0 or r.cuerpo_html ~ '\(a \d+ días\)' then
    raise exception 'FALLO 358 · el email de línea concedida sigue nombrando los días de pago: %', r.cuerpo_html; end if;
  update clientes set riesgo_manual_euros = v_man, riesgo_cesce_euros = v_ces, plazo_pago_dias = v_plazo where id = v_cli;
  raise notice 'OK 358 · email de línea de crédito concedida: a vencimiento, sin nombrar los días de pago';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 359 · SITIOS → BREVO: LA LISTA PARA REVISAR ANTES DE SUBIR (usuario, 2026-11-25: «OK, reviso,
-- pásamela»). El equipo de Dynamo ve, uno a uno, los que van a subir y por qué; nadie más.
do $$ declare j jsonb; f jsonb; s1 uuid;
  u_adm uuid := current_setting('prueba.u_admin')::uuid; u_cli uuid := current_setting('prueba.u_cli_b')::uuid; begin
  if has_function_privilege('anon', 'brevo_sitios_revisar()', 'execute') then raise exception 'FALLO 359 · la lista para revisar se puede pedir sin sesión'; end if;
  perform set_config('request.jwt.claim.sub', u_cli::text, false);
  begin perform brevo_sitios_revisar(); raise exception 'FALLO 359 · un cliente ve la lista de emails que suben a Brevo';
  exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  j := brevo_sitios_revisar();
  select x into f from jsonb_array_elements(j) x where x ->> 'email' = 'marta@aceros357.com';
  if f is null or f ->> 'motivo' <> 'nuevo' or f ->> 'nombre' <> 'Marta Ruiz' or f ->> 'empresa' <> 'Aceros 357' or f ->> 'poblacion' <> 'Sevilla' then
    raise exception 'FALLO 359 · la lista para revisar no trae la persona nueva con sus datos: %', f; end if;
  if exists (select 1 from jsonb_array_elements(j) x where x ->> 'email' ~ 'invalid|borrado@') then raise exception 'FALLO 359 · la lista para revisar enseña direcciones que no suben'; end if;
  if exists (select 1 from jsonb_array_elements(j) x where x ? 'telefono' or x ? 'cif' or x ? 'huella') then raise exception 'FALLO 359 · la lista para revisar trae más datos de los que se enseñan'; end if;
  -- Ya subida y con datos cambiados: «cambiado». Con fallo de ayer: «reintento». Subida y al día: no sale.
  select sitio_id into s1 from brevo_sitios_candidatos() x where x.email = 'marta@aceros357.com';
  perform set_config('request.jwt.claim.sub', '', false);
  perform brevo_sitios_marcar(jsonb_build_array(jsonb_build_object('email', 'marta@aceros357.com', 'sitio_id', s1, 'huella', 'otra', 'estado', 'subido')));
  perform set_config('request.jwt.claim.sub', u_adm::text, false);
  if (select x ->> 'motivo' from jsonb_array_elements(brevo_sitios_revisar()) x where x ->> 'email' = 'marta@aceros357.com') is distinct from 'cambiado' then
    raise exception 'FALLO 359 · un email ya subido con datos nuevos no sale como «cambiado»'; end if;
  update brevo_subidas set estado = 'error', intentos = 1, subido_en = now() - interval '1 day' where email = 'marta@aceros357.com';
  if (select x ->> 'motivo' from jsonb_array_elements(brevo_sitios_revisar()) x where x ->> 'email' = 'marta@aceros357.com') is distinct from 'reintento' then
    raise exception 'FALLO 359 · un email que falló ayer no sale como «reintento»'; end if;
  update brevo_subidas set estado = 'subido', huella = (select huella from brevo_sitios_candidatos() x where x.email = 'marta@aceros357.com') where email = 'marta@aceros357.com';
  if exists (select 1 from jsonb_array_elements(brevo_sitios_revisar()) x where x ->> 'email' = 'marta@aceros357.com') then
    raise exception 'FALLO 359 · un email ya subido y sin cambios sigue en la lista para revisar'; end if;
  delete from brevo_subidas where email like '%aceros357%';
  perform set_config('request.jwt.claim.sub', '', false);
  raise notice 'OK 359 · sitios → Brevo: lista para revisar antes de subir, solo para Dynamo, con el motivo de cada uno';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 360 · TRANSFERENCIA AVISADA: DYNAMO RECIBE SU PROPIO EMAIL, AL MOMENTO (usuario, 2026-11-25:
-- «ese aviso debería llegar a admin para saber rápido en el banco si nos pagó»). Con el importe
-- con IVA, el concepto y el cliente en el asunto y dentro; el del cliente sigue saliendo.
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare e uuid; cli uuid := current_setting('prueba.cliente')::uuid; adm uuid := current_setting('prueba.u_admin')::uuid; lun date;
  r record; v_gx text; v_dyn text := parametro('dynamo_email') #>> '{}'; v_total text; begin
  lun := (now() at time zone 'Europe/Madrid')::date + (8 - extract(isodow from (now() at time zone 'Europe/Madrid')::date)::int) + 7;
  insert into envios (cliente_id, metros_lineales, toneladas, importe_cliente, importe_transportista, fecha_carga_desde, fecha_carga_hasta, creado_por)
    values (cli, 13.30, 20, 900, 700, lun, lun + 1, adm) returning id, referencia_gx into e, v_gx;
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 1, 'carga', '41001', 'Sevilla', 'ES');
  insert into envio_paradas (envio_id, orden, tipo, codigo_postal, poblacion, pais_codigo_iso) values (e, 2, 'descarga', '28821', 'Coslada', 'ES');
  update envios set estado_pago_previo = 'pendiente', pago_motivo = 'Pedido por Dynamo', pago_pendiente_en = now(), estado_revision_precio = 'no_requiere' where id = e;
  update envios set estado = 'programado' where id = e;
  select euros_texto(i.total) into v_total from pago_envio_importes(e) i;
  if has_function_privilege('authenticated', 'fn_email_pago_avisado_dynamo(uuid, boolean)', 'execute') then raise exception 'FALLO 360 · cualquiera puede mandar el email de validar cobro'; end if;
  if (fn_pago_avisar(e, true)) ->> 'resultado' <> 'ok' then raise exception 'FALLO 360 · no se apunta el aviso de la transferencia'; end if;
  select * into r from emails_enviados where envio_id = e and tipo = 'pago_avisado_dynamo';
  if r.id is null then raise exception 'FALLO 360 · Dynamo no recibe su email de «validar cobro»'; end if;
  if r.destinatario <> v_dyn then raise exception 'FALLO 360 · el email de validar cobro no va al buzón de Dynamo: %', r.destinatario; end if;
  if r.asunto not like 'Validar cobro · #' || v_gx || ' · ' || v_total || ' · %' then raise exception 'FALLO 360 · el asunto no dice envío, importe y cliente: %', r.asunto; end if;
  if position('PRO-' || v_gx in r.cuerpo_html) = 0 or position(v_total || ' (IVA incluido)' in r.cuerpo_html) = 0
     or position('/panel/envios?ver=' || e in r.cuerpo_html) = 0 or position('desde el enlace de pago' in r.cuerpo_html) = 0 then
    raise exception 'FALLO 360 · al email de validar cobro le falta el concepto, el importe, el botón o de dónde vino: %', r.cuerpo_html; end if;
  if r.enviar_desde > now() + interval '2 seconds' then raise exception 'FALLO 360 · el email de validar cobro espera en vez de salir al momento (%)', r.enviar_desde - now(); end if;
  -- El del cliente sigue saliendo (con su minuto de espera, como todos).
  if not exists (select 1 from emails_enviados where envio_id = e and tipo = 'pago_avisado') then raise exception 'FALLO 360 · el cliente se queda sin su email de «la estamos validando»'; end if;
  -- Avisar dos veces no manda dos.
  perform fn_pago_avisar(e, false);
  if (select count(*) from emails_enviados where envio_id = e and tipo = 'pago_avisado_dynamo') <> 1 then raise exception 'FALLO 360 · el email de validar cobro se repite'; end if;
  raise notice 'OK 360 · transferencia avisada: Dynamo recibe al momento su email de «validar cobro» con envío, importe con IVA, concepto y cliente';
end $$;
select set_config('request.jwt.claim.sub', '', false);

-- 361 · WHATSAPP, PARTE 1 (usuario, 2026-11-25): conversaciones guardadas enteras, quién escribe
-- por su teléfono, solo el equipo las ve, contestar solo dentro de las 24 h de Meta, permiso de
-- cada usuario para los avisos y limpieza (texto 24 meses, archivos 6).
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare r jsonb; v_conv uuid; v_msg uuid; v_cli uuid := current_setting('prueba.u_cli')::uuid; v_tel text; n int; begin
  -- Formato WhatsApp.
  if tel_whatsapp('600 11 12 22') <> '+34600111222' or tel_whatsapp('+34 600-111-222') <> '+34600111222'
     or tel_whatsapp('0033612345678') <> '+33612345678' or tel_whatsapp('') is not null then
    raise exception 'FALLO 361 · el teléfono no se pasa bien al formato de WhatsApp'; end if;
  -- Nadie de fuera llama a lo del servidor ni lee las tablas.
  if has_function_privilege('authenticated', 'whatsapp_registrar_entrada(jsonb)', 'execute') or has_function_privilege('anon', 'whatsapp_preparar_respuesta(uuid, text)', 'execute')
     or has_function_privilege('authenticated', 'whatsapp_marcar_enviado(uuid, text, text)', 'execute') or has_function_privilege('authenticated', 'whatsapp_archivos_caducados(integer)', 'execute') then
    raise exception 'FALLO 361 · las funciones de WhatsApp del servidor se pueden llamar desde fuera'; end if;
  if not (select relrowsecurity from pg_class where oid = 'public.whatsapp_mensajes'::regclass) then raise exception 'FALLO 361 · whatsapp_mensajes sin RLS'; end if;
  if (select public from storage.buckets where id = 'whatsapp') then raise exception 'FALLO 361 · el almacén de WhatsApp es público'; end if;
  -- Llega un mensaje de un usuario cliente: se le reconoce por su móvil, escriba su ficha como lo escriba.
  perform set_config('prueba.wa_tel_antes', coalesce((select telefono from usuarios where id = v_cli), ''), false);
  update usuarios set telefono = '600361361' where id = v_cli;
  select count(*) into n from avisos where tipo = 'whatsapp';
  r := whatsapp_registrar_entrada(jsonb_build_object('telefono', '34600361361', 'nombre', 'Cliente 361', 'wa_id', 'wamid.361a', 'tipo', 'texto', 'texto', '¿Mi camión ya ha salido?', 'cuando', extract(epoch from now())::bigint));
  if r ->> 'resultado' <> 'ok' or r ->> 'quien' <> 'cliente' then raise exception 'FALLO 361 · no se reconoce al cliente por su móvil: %', r; end if;
  v_conv := (r ->> 'conversacion_id')::uuid;
  if (select usuario_id from whatsapp_conversaciones where id = v_conv) <> v_cli or (select empresa_cliente_id from whatsapp_conversaciones where id = v_conv) is null then
    raise exception 'FALLO 361 · la conversación no queda unida al usuario y a su empresa'; end if;
  -- Meta repite el aviso: no se guarda dos veces.
  if whatsapp_registrar_entrada(jsonb_build_object('telefono', '34600361361', 'wa_id', 'wamid.361a', 'tipo', 'texto', 'texto', 'otra vez')) ->> 'resultado' <> 'repetido' then
    raise exception 'FALLO 361 · el mismo mensaje de Meta se guarda dos veces'; end if;
  perform whatsapp_registrar_entrada(jsonb_build_object('telefono', '+34600361361', 'wa_id', 'wamid.361b', 'tipo', 'imagen', 'meta_archivo_id', 'm361', 'archivo_tipo', 'image/jpeg'));
  if (select sin_leer from whatsapp_conversaciones where id = v_conv) <> 2 or (select ultimo_texto from whatsapp_conversaciones where id = v_conv) not like '%Foto%' then
    raise exception 'FALLO 361 · la conversación no cuenta los sin leer o no enseña la foto como último mensaje'; end if;
  if (select count(*) from avisos where tipo = 'whatsapp') <> n + 1 then raise exception 'FALLO 361 · la campana avisa de cada mensaje (debe ser solo el primero sin leer)'; end if;
  if not exists (select 1 from whatsapp_archivos_por_bajar(50) x where x.meta_archivo_id = 'm361') then raise exception 'FALLO 361 · la foto no sale como archivo por bajar de Meta'; end if;
  -- Un número que no es de nadie: desconocido.
  if whatsapp_registrar_entrada(jsonb_build_object('telefono', '34699000361', 'wa_id', 'wamid.361c', 'tipo', 'texto', 'texto', 'Hola')) ->> 'quien' <> 'desconocido' then
    raise exception 'FALLO 361 · un número sin ficha no sale como desconocido'; end if;
  perform set_config('prueba.wa_conv', v_conv::text, false);
end $$;
-- Un cliente no ve nada ni contesta.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  if exists (select 1 from whatsapp_conversaciones) or exists (select 1 from whatsapp_mensajes) then raise exception 'FALLO 361 · un cliente ve las conversaciones de WhatsApp'; end if;
  begin perform whatsapp_preparar_respuesta(current_setting('prueba.wa_conv')::uuid, 'hola'); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 361 · un cliente contesta en la bandeja de WhatsApp'; end if;
end $$;
-- El equipo: contesta dentro de las 24 h; fuera, no (regla de Meta).
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare r jsonb; v_conv uuid := current_setting('prueba.wa_conv')::uuid; begin
  if not exists (select 1 from whatsapp_conversaciones where id = v_conv) then raise exception 'FALLO 361 · el equipo no ve la conversación'; end if;
  r := whatsapp_preparar_respuesta(v_conv, 'Sí, ha salido a las 8:10.');
  if r ->> 'resultado' <> 'ok' or r ->> 'telefono' <> '+34600361361' then raise exception 'FALLO 361 · el equipo no puede contestar dentro de las 24 h: %', r; end if;
  if (select sin_leer from whatsapp_conversaciones where id = v_conv) <> 0 then raise exception 'FALLO 361 · contestar no marca la conversación como leída'; end if;
  perform set_config('prueba.wa_msg', r ->> 'mensaje_id', false);
  if whatsapp_preparar_respuesta(v_conv, '   ') ->> 'resultado' <> 'vacio' then raise exception 'FALLO 361 · se manda una respuesta vacía'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare v_conv uuid := current_setting('prueba.wa_conv')::uuid; v_msg uuid := current_setting('prueba.wa_msg')::uuid; r jsonb; begin
  -- Meta acepta el mensaje y avisa: entregado y leído, solo hacia delante; un fallo se apunta.
  perform whatsapp_marcar_enviado(v_msg, 'wamid.361out', null);
  if (select estado from whatsapp_mensajes where id = v_msg) <> 'enviado' then raise exception 'FALLO 361 · el mensaje aceptado por Meta no queda enviado'; end if;
  perform whatsapp_registrar_estado('wamid.361out', 'leido', null, null);
  if whatsapp_registrar_estado('wamid.361out', 'entregado', null, null) then raise exception 'FALLO 361 · el estado de un mensaje va hacia atrás (leído → entregado)'; end if;
  if (select estado from whatsapp_mensajes where id = v_msg) <> 'leido' then raise exception 'FALLO 361 · no se apunta que la persona lo leyó'; end if;
  -- Pasadas 24 h desde su último mensaje: ya no se contesta con texto libre.
  update whatsapp_conversaciones set ultima_entrada_en = now() - interval '25 hours' where id = v_conv;
  perform set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
  set local role authenticated;
  r := whatsapp_preparar_respuesta(v_conv, 'Te escribo tarde');
  reset role;
  if r ->> 'resultado' <> 'fuera_de_plazo' then raise exception 'FALLO 361 · se deja contestar con texto libre pasadas las 24 h: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  -- Limpieza: el texto de más de 24 meses se borra; el archivo de más de 6 meses sale para borrar.
  update whatsapp_mensajes set creado_en = now() - interval '25 months' where wa_id = 'wamid.361a';
  update whatsapp_mensajes set archivo_ruta = 'c/361/foto.jpg', archivo_bytes = 1000, creado_en = now() - interval '7 months' where wa_id = 'wamid.361b';
  perform whatsapp_limpiar();
  if exists (select 1 from whatsapp_mensajes where wa_id = 'wamid.361a') then raise exception 'FALLO 361 · el texto de más de 24 meses no se borra'; end if;
  if not exists (select 1 from whatsapp_mensajes where wa_id = 'wamid.361b') then raise exception 'FALLO 361 · se borra un mensaje con archivo aún guardado'; end if;
  if not exists (select 1 from whatsapp_archivos_caducados(500) x where x.archivo_ruta = 'c/361/foto.jpg') then raise exception 'FALLO 361 · la foto de más de 6 meses no sale para borrar'; end if;
  perform whatsapp_archivos_borrados(array[(select id from whatsapp_mensajes where wa_id = 'wamid.361b')]);
  if (select archivo_ruta from whatsapp_mensajes where wa_id = 'wamid.361b') is not null then raise exception 'FALLO 361 · no se apunta que el archivo ya se borró'; end if;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if not exists (select 1 from cron.job where jobname = 'dynamo-whatsapp-limpiar') then raise exception 'FALLO 361 · falta la tarea diaria de limpieza de WhatsApp'; end if;
  end if;
end $$;
-- Permiso del usuario para los avisos: hace falta un móvil; queda la fecha como prueba.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare r jsonb; begin
  r := mi_avisos_whatsapp(true);
  if r ->> 'resultado' <> 'ok' or r ->> 'telefono' <> '+34600361361' then raise exception 'FALLO 361 · el usuario no puede dar su permiso para los avisos por WhatsApp: %', r; end if;
end $$;
reset role;
do $$ declare v_cli uuid := current_setting('prueba.u_cli')::uuid; r jsonb; begin
  if not (select avisos_whatsapp and avisos_whatsapp_en is not null and avisos_whatsapp_preguntado_en is not null from usuarios where id = v_cli) then
    raise exception 'FALLO 361 · el permiso no queda apuntado con su fecha'; end if;
  update usuarios set telefono = null, avisos_whatsapp = false where id = v_cli;
  perform set_config('request.jwt.claim.sub', v_cli::text, false);
  set local role authenticated;
  r := mi_avisos_whatsapp(true);
  reset role;
  if r ->> 'resultado' <> 'sin_movil' then raise exception 'FALLO 361 · se da el permiso de WhatsApp sin móvil: %', r; end if;
  perform set_config('request.jwt.claim.sub', '', false);
  delete from whatsapp_conversaciones where telefono in ('+34600361361', '+34699000361');
  delete from avisos where tipo = 'whatsapp';
  update usuarios set avisos_whatsapp_en = null, avisos_whatsapp_preguntado_en = null, telefono = nullif(current_setting('prueba.wa_tel_antes'), '') where id = v_cli;
  raise notice 'OK 361 · WhatsApp: se guarda todo, se reconoce a quien escribe, solo el equipo lo ve y contesta dentro de las 24 h, permiso con móvil y fecha, y limpieza 24/6 meses';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);

-- 362 · WHATSAPP: REENVÍO AL MÓVIL DE DYNAMO, «TOMO YO» Y CONTESTAR CITANDO (usuario, 2026-11-25):
-- lo que escribe la gente se reenvía al móvil de Dynamo (según el modo); desde ese móvil, responder
-- citando le contesta a quien escribió (dentro de sus 24 h), los botones toman o devuelven la
-- conversación, y el móvil de Dynamo no cuenta como «sin leer».
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare r jsonb; v_cli uuid; v_mov uuid; v_relay uuid; n int; v_aviso int;
  e jsonb := jsonb_build_object('cuando', extract(epoch from now())::bigint);
begin
  if has_function_privilege('authenticated', 'whatsapp_tras_entrada(uuid)', 'execute') or has_function_privilege('anon', 'whatsapp_tomar(uuid, boolean)', 'execute') then
    raise exception 'FALLO 362 · las funciones del reenvío se pueden llamar desde fuera'; end if;
  perform set_config('prueba.wa362', (select jsonb_object_agg(clave, valor)::text from parametros where clave in ('whatsapp_activo', 'whatsapp_movil_dynamo', 'whatsapp_reenvio_modo', 'whatsapp_reenviar_desconocidos')), false);
  update parametros set valor = '"611 362 362"' where clave = 'whatsapp_movil_dynamo';
  update parametros set valor = '"todo"' where clave = 'whatsapp_reenvio_modo';
  -- Apagado: no se reenvía nada.
  update parametros set valor = 'false' where clave = 'whatsapp_activo';
  r := whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362a', 'tipo', 'texto', 'texto', 'Hola, ¿precio a Lisboa?'));
  if whatsapp_tras_entrada((r ->> 'mensaje_id')::uuid) ->> 'accion' <> 'nada' then raise exception 'FALLO 362 · con WhatsApp apagado se reenvía'; end if;
  update parametros set valor = 'true' where clave = 'whatsapp_activo';
  -- Encendido: se reenvía al móvil de Dynamo, unido al original, con los datos de quién escribe.
  r := whatsapp_tras_entrada((r ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'reenviar' or r ->> 'telefono' <> '+34611362362' or (r ->> 'ventana')::boolean or r ->> 'texto' not like '%Lisboa%' or r ->> 'texto' not like '%desconocido%' then
    raise exception 'FALLO 362 · el mensaje no se reenvía bien al móvil de Dynamo: %', r; end if;
  v_cli := (r ->> 'conversacion')::uuid; v_relay := (r ->> 'mensaje_id')::uuid;
  if (select reenvio_de from whatsapp_mensajes where id = v_relay) is distinct from (select id from whatsapp_mensajes where wa_id = 'wamid.362a') then
    raise exception 'FALLO 362 · el reenvío no queda unido al mensaje original'; end if;
  perform whatsapp_marcar_enviado(v_relay, 'wamid.362relay', null);
  v_mov := (select conversacion_id from whatsapp_mensajes where id = v_relay);
  -- El móvil de Dynamo contesta citando el reenvío: va a quien escribió y la conversación pasa a ser suya.
  select count(*) into v_aviso from avisos where tipo = 'whatsapp';
  r := whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362b', 'tipo', 'texto', 'texto', 'Hola, sí: 650 € a Lisboa.', 'cita_wa_id', 'wamid.362relay'));
  if (select sin_leer from whatsapp_conversaciones where id = v_mov) <> 0 or (select count(*) from avisos where tipo = 'whatsapp') <> v_aviso then
    raise exception 'FALLO 362 · lo que escribe el móvil de Dynamo cuenta como sin leer o avisa en la campana'; end if;
  r := whatsapp_tras_entrada((r ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'responder' or r ->> 'telefono' <> '+34699362000' or r ->> 'texto' <> 'Hola, sí: 650 € a Lisboa.' or r #>> '{confirmar,wa_id}' <> 'wamid.362b' then
    raise exception 'FALLO 362 · la respuesta citando no va a quien escribió: %', r; end if;
  if not exists (select 1 from whatsapp_mensajes where id = (r ->> 'mensaje_id')::uuid and conversacion_id = v_cli and sentido = 'salida' and desde_movil and estado = 'pendiente' and origen = 'persona')
     or (select tomada_desde from whatsapp_conversaciones where id = v_cli) is distinct from 'movil' then
    raise exception 'FALLO 362 · la respuesta desde el móvil no queda en la conversación o no la toma'; end if;
  -- Sin citar, justo después: a la última reenviada.
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362c', 'tipo', 'texto', 'texto', 'Te lo mando por email.')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'responder' or r ->> 'telefono' <> '+34699362000' then raise exception 'FALLO 362 · sin citar no va a la última conversación reenviada: %', r; end if;
  -- Botones: «Que conteste Claude» la devuelve; «Tomo yo» la toma.
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362d', 'tipo', 'boton', 'texto', 'Que conteste Claude', 'boton_id', 'claude:' || v_cli)) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'avisar' or (select tomada_en from whatsapp_conversaciones where id = v_cli) is not null then raise exception 'FALLO 362 · «Que conteste Claude» no la devuelve: %', r; end if;
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362e', 'tipo', 'boton', 'texto', 'Tomo yo', 'boton_id', 'tomo:' || v_cli)) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'reaccion' or r ->> 'wa_id' <> 'wamid.362e' or (select tomada_en from whatsapp_conversaciones where id = v_cli) is null then raise exception 'FALLO 362 · «Tomo yo» no la toma: %', r; end if;
  -- «Claude» escrito citando el reenvío también la devuelve.
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362f', 'tipo', 'texto', 'texto', 'Claude', 'cita_wa_id', 'wamid.362relay')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'avisar' or (select tomada_en from whatsapp_conversaciones where id = v_cli) is not null then raise exception 'FALLO 362 · «Claude» citando no la devuelve: %', r; end if;
  -- Citar algo que no es un reenvío: se pregunta a quién va.
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362g', 'tipo', 'texto', 'texto', 'ok', 'cita_wa_id', 'wamid.no-existe')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'avisar' or r ->> 'texto' not like 'No sé a qué conversación%' then raise exception 'FALLO 362 · citar algo que no es un reenvío no pregunta a quién va: %', r; end if;
  -- Pasadas 24 h desde su último mensaje: no se le manda (Meta pide plantilla) y se avisa al móvil.
  update whatsapp_conversaciones set ultima_entrada_en = now() - interval '25 hours' where id = v_cli;
  select count(*) into n from whatsapp_mensajes where conversacion_id = v_cli;
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362h', 'tipo', 'texto', 'texto', '¿Sigues ahí?', 'cita_wa_id', 'wamid.362relay')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'avisar' or r ->> 'texto' not like '%más de 24 h%' or (select count(*) from whatsapp_mensajes where conversacion_id = v_cli) <> n then
    raise exception 'FALLO 362 · pasadas 24 h se intenta escribir con texto libre: %', r; end if;
  -- El móvil de Dynamo ya ha escrito: los reenvíos van sin plantilla (ventana abierta).
  if not (whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362i', 'tipo', 'texto', 'texto', 'Gracias')) ->> 'mensaje_id')::uuid) ->> 'ventana')::boolean then
    raise exception 'FALLO 362 · con el móvil de Dynamo escribiendo hoy, el reenvío pide plantilla'; end if;
  -- Sin citar y pasados 15 minutos del último reenvío: se pregunta.
  update whatsapp_mensajes set creado_en = now() - interval '20 minutes' where conversacion_id = v_mov and reenvio_de is not null;
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34611362362', 'wa_id', 'wamid.362j', 'tipo', 'texto', 'texto', 'Buenos días')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'avisar' then raise exception 'FALLO 362 · sin citar y pasado un rato, la respuesta se manda a alguien: %', r; end if;
  -- Modo «importante»: solo si piden una persona, es urgente o la lleva una persona; las reacciones nunca.
  update parametros set valor = '"importante"' where clave = 'whatsapp_reenvio_modo';
  update parametros set valor = 'false' where clave = 'whatsapp_reenviar_desconocidos';
  if whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362k', 'tipo', 'texto', 'texto', 'Vale')) ->> 'mensaje_id')::uuid) ->> 'accion' <> 'nada' then
    raise exception 'FALLO 362 · en el modo importante se reenvía un «Vale»'; end if;
  if whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362l', 'tipo', 'texto', 'texto', '¿Me podéis LLAMAR? Es urgente')) ->> 'mensaje_id')::uuid) ->> 'accion' <> 'reenviar' then
    raise exception 'FALLO 362 · en el modo importante no se reenvía «llamar, urgente»'; end if;
  update whatsapp_conversaciones set tomada_en = now(), tomada_desde = 'panel' where id = v_cli;
  r := whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362m', 'tipo', 'texto', 'texto', 'Vale')) ->> 'mensaje_id')::uuid);
  if r ->> 'accion' <> 'reenviar' or not (r ->> 'tomada')::boolean then raise exception 'FALLO 362 · en el modo importante no se reenvía lo de una conversación que lleva una persona: %', r; end if;
  if whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362n', 'tipo', 'reaccion', 'texto', '👍')) ->> 'mensaje_id')::uuid) ->> 'accion' <> 'nada' then
    raise exception 'FALLO 362 · se reenvían las reacciones'; end if;
  update parametros set valor = '"nada"' where clave = 'whatsapp_reenvio_modo';
  if whatsapp_tras_entrada((whatsapp_registrar_entrada(e || jsonb_build_object('telefono', '34699362000', 'wa_id', 'wamid.362o', 'tipo', 'texto', 'texto', 'Urgente')) ->> 'mensaje_id')::uuid) ->> 'accion' <> 'nada' then
    raise exception 'FALLO 362 · en el modo «nada» se reenvía'; end if;
  perform set_config('prueba.wa362_conv', v_cli::text, false);
end $$;
-- «Tomo yo» desde el panel: el equipo sí; un cliente, no.
select set_config('request.jwt.claim.sub', current_setting('prueba.u_admin'), false);
set role authenticated;
do $$ declare v uuid := current_setting('prueba.wa362_conv')::uuid; begin
  perform whatsapp_tomar(v, false);
  if (select tomada_en from whatsapp_conversaciones where id = v) is not null then raise exception 'FALLO 362 · «Que conteste Claude» del panel no la devuelve'; end if;
  perform whatsapp_tomar(v, true);
  if (select tomada_desde from whatsapp_conversaciones where id = v) is distinct from 'panel' then raise exception 'FALLO 362 · «Tomo yo» del panel no la toma'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', current_setting('prueba.u_cli'), false);
set role authenticated;
do $$ declare ok boolean := false; begin
  begin perform whatsapp_tomar(current_setting('prueba.wa362_conv')::uuid, true); exception when insufficient_privilege then ok := true; end;
  if not ok then raise exception 'FALLO 362 · un cliente toma una conversación de WhatsApp'; end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
do $$ declare p jsonb := current_setting('prueba.wa362')::jsonb; k text; begin
  delete from whatsapp_conversaciones where telefono in ('+34699362000', '+34611362362');
  delete from avisos where tipo = 'whatsapp';
  for k in select jsonb_object_keys(p) loop update parametros set valor = p -> k where clave = k; end loop;
  raise notice 'OK 362 · WhatsApp: reenvío al móvil de Dynamo según el modo, responder citando le llega a quien escribió (en sus 24 h), «Tomo yo» y «Que conteste Claude»';
end $$;
reset role;
select set_config('request.jwt.claim.sub', '', false);
